window.WCARDS={"lessons":[{"c":"W00","w":0,"d":0,"t":"Band 7.0+ Topic Lexicon Bank (8 Core Domains)"},{"c":"W1D1","w":1,"d":1,"t":"Band Descriptors & Viết Introduction"},{"c":"W1D2","w":1,"d":2,"t":"Phân Tích Bài Mẫu (Band 5 vs 7)"},{"c":"W1D3","w":1,"d":3,"t":"Task 1 Introduction & Overview"},{"c":"W1D4","w":1,"d":4,"t":"Diagnostic Test — Đánh Giá Level Thật"},{"c":"W2D1","w":2,"d":1,"t":"Describing Trends (Line Graph)"},{"c":"W2D2","w":2,"d":2,"t":"Comparing Data (Bar Chart)"},{"c":"W2D3","w":2,"d":3,"t":"Describing Proportions (Pie Chart)"},{"c":"W2D4","w":2,"d":4,"t":"Writing Complete Task 1 (Table)"},{"c":"W3D1","w":3,"d":1,"t":"TEES Paragraph Structure"},{"c":"W3D2","w":3,"d":2,"t":"Linking Devices — Từ Basic Lên Academic"},{"c":"W3D3","w":3,"d":3,"t":"Writing Body Paragraphs with Examples"},{"c":"W3D4","w":3,"d":4,"t":"Phase 1 Assessment"},{"c":"W4D1","w":4,"d":1,"t":"Task 2 Essay Structure"},{"c":"W4D2","w":4,"d":2,"t":"Opinion Essay — Agree/Disagree"},{"c":"W4D3","w":4,"d":3,"t":"Writing Conclusions"},{"c":"W4D4","w":4,"d":4,"t":"Full Opinion Essay Practice"},{"c":"W5D1","w":5,"d":1,"t":"Discussion Essay — Both Views"},{"c":"W5D2","w":5,"d":2,"t":"Academic Collocations (50 phrases)"},{"c":"W5D3","w":5,"d":3,"t":"Paraphrasing Techniques (Advanced)"},{"c":"W5D4","w":5,"d":4,"t":"Full Discussion Essay Practice"},{"c":"W6D1","w":6,"d":1,"t":"Problem-Solution Essay"},{"c":"W6D2","w":6,"d":2,"t":"Avoiding Repetition (Synonyms + Reference)"},{"c":"W6D3","w":6,"d":3,"t":"Phase 2 Assessment"},{"c":"W7D1","w":7,"d":1,"t":"Complex Sentences"},{"c":"W7D2","w":7,"d":2,"t":"Common Grammar Errors (Error Log Drill)"},{"c":"W7D3","w":7,"d":3,"t":"Sentence Variety + Academic Tone"},{"c":"W8D1","w":8,"d":1,"t":"Two-Part Question Essay"},{"c":"W8D2","w":8,"d":2,"t":"Task 1 Advanced — Process Diagram & Map Description"},{"c":"W8D3","w":8,"d":3,"t":"Full Test Simulation #1"},{"c":"W8D4","w":8,"d":4,"t":"Advantages & Disadvantages Essay (Outweigh)"},{"c":"W9D1","w":9,"d":1,"t":"Error Analysis + Weak Point Drill"},{"c":"W9D2","w":9,"d":2,"t":"Phase 3 Assessment — 2 Full Tests"},{"c":"W10D1","w":10,"d":1,"t":"Band 7 Checklist + Targeted Drills"},{"c":"W10D2","w":10,"d":2,"t":"Full Test Simulation #4-5 — Phase 4 Midpoint Assessment"},{"c":"W11D1","w":11,"d":1,"t":"High-Intensity Mock Exams — Endurance & Model Answer Phrases"},{"c":"W12D1","w":12,"d":1,"t":"Final Assessment + Exam Strategy"}],"weeks":{"0":"Core Topic Lexicon & Idea Banks","1":"Band Descriptors & Introduction","2":"Task 1 Data & Trends","3":"Body Paragraphs & TEES","4":"Task 2 Essay Structure & Opinion","5":"Discussion Essay & Lexical Resource","6":"Problem-Solution & Cohesion","7":"Complex Sentences & Grammar Mastery","8":"Two-Part Essay, Advanced Task 1 & Outweigh","9":"Error Analysis & Mock Tests","10":"Band 7 Checklist & Targeted Drills","11":"High-Intensity Mock Exams","12":"Final Assessment & Exam Strategy"},"cards":[{"id":"W00-S-01","l":0,"t":"S","st":"Structure","s":3,"tags":["topic-lexicon","education"],"f":"<p>3 cụm từ học thuật nâng cấp cho topic Education: học vẹt → ? / giáo dục toàn diện → ? / đào tạo nghề → ?</p>","a":"","b":"<div class=\"sec\"><ol><li>học vẹt / học thuộc lòng → <b>rote memorisation</b></li><li>giáo dục / phát triển toàn diện → <b>holistic development</b></li><li>đào tạo nghề nghiệp thực hành → <b>vocational training</b></li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Rather than relying on <b>rote memorisation</b>, curricula should prioritise <b>holistic development</b> and <b>vocational training</b>.\"</p></div>","p":1},{"id":"W00-S-02","l":0,"t":"S","st":"Structure","s":3,"tags":["topic-lexicon","crime"],"f":"<p>3 cụm từ học thuật nâng cấp cho topic Crime: án tù giam → ? / tỷ lệ tái phạm → ? / tác dụng răn đe → ?</p>","a":"","b":"<div class=\"sec\"><ol><li>án phạt tù giam → <b>custodial sentences</b></li><li>tỷ lệ tái phạm tội → <b>recidivism rates</b></li><li>tác dụng răn đe, ngăn ngừa → <b>deterrent effect</b></li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Harsher <b>custodial sentences</b> often fail to produce a meaningful <b>deterrent effect</b> or curb <b>recidivism rates</b>.\"</p></div>","p":1},{"id":"W00-S-03","l":0,"t":"S","st":"Structure","s":3,"tags":["topic-lexicon","economy"],"f":"<p>3 cụm từ học thuật nâng cấp cho topic Economy: khoảng cách giàu nghèo → ? / cơ hội thăng tiến xã hội → ? / thuế luỹ tiến → ?</p>","a":"","b":"<div class=\"sec\"><ol><li>khoảng cách giàu nghèo → <b>wealth disparity</b> / <b>income inequality</b></li><li>cơ hội thăng tiến xã hội → <b>upward social mobility</b></li><li>thuế thu nhập luỹ tiến → <b>progressive taxation</b></li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"<b>Progressive taxation</b> mitigates <b>wealth disparity</b> and promotes <b>upward social mobility</b>.\"</p></div>","p":1},{"id":"W00-P-01","l":0,"t":"P","st":"Phrase","s":3,"tags":["collocation","education"],"f":"<p>Modern educational curricula should nurture ______ (sự phát triển toàn diện) of children rather than academic test scores alone.</p>","a":"<b>holistic development</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Extracurricular activities are crucial because they foster the holistic development of students.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"comprehensive growth\" | \"all-round development\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Education essays — giải thích lợi ích của thể thao/nghệ thuật/kỹ năng mềm.</p></div>","p":1},{"id":"W00-P-02","l":0,"t":"P","st":"Phrase","s":3,"tags":["collocation","education"],"f":"<p>Providing practical ______ (đào tạo nghề nghiệp) is essential to reduce youth unemployment.</p>","a":"<b>vocational training</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Governments should subsidise vocational training programmes for students who do not attend university.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"career-oriented education\" | \"technical apprenticeships\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Education / Employment essays.</p></div>","p":1},{"id":"W00-P-03","l":0,"t":"P","st":"Phrase","s":3,"tags":["collocation","environment"],"f":"<p>Transitioning rapidly to renewable energy is imperative to avert an ______ (thảm hoạ sinh thái).</p>","a":"<b>ecological catastrophe</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Unchecked deforestation could precipitate an irreversible ecological catastrophe.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"environmental disaster\" | \"ecological crisis\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Environment / Climate change essays — mô tả hậu quả tồi tệ nhất.</p></div>","p":1},{"id":"W00-P-04","l":0,"t":"P","st":"Phrase","s":3,"tags":["collocation","environment"],"f":"<p>Massive industrial expansion in developing regions accelerates ______ (sự suy giảm đa dạng sinh học).</p>","a":"<b>biodiversity loss</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Habitat destruction represents the single largest driver of catastrophic biodiversity loss.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"loss of wildlife species\" | \"ecosystem depletion\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Environment / Wildlife conservation essays.</p></div>","p":1},{"id":"W00-P-05","l":0,"t":"P","st":"Phrase","s":3,"tags":["collocation","technology"],"f":"<p>The rapid ______ (sự tự động hoá các công việc lặp lại) threatens low-skilled employment.</p>","a":"<b>automation of routine tasks</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"While the automation of routine tasks elevates efficiency, it displaces manual workers.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"mechanisation of repetitive duties\" | \"automated labour\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Technology / AI / Future of work essays.</p></div>","p":1},{"id":"W00-P-06","l":0,"t":"P","st":"Phrase","s":3,"tags":["collocation","technology"],"f":"<p>Unequal access to digital infrastructure exacerbates the ______ (khoảng cách công nghệ số giữa giàu và nghèo).</p>","a":"<b>digital divide</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Subsidising internet connectivity in remote areas is vital to bridge the digital divide.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"technological disparity\" | \"digital inequality\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Technology / Education / Social equity essays.</p></div>","p":1},{"id":"W00-P-07","l":0,"t":"P","st":"Phrase","s":3,"tags":["collocation","crime"],"f":"<p>Lengthy prison terms fail to lower ______ (tỷ lệ tái phạm tội) without psychological rehabilitation.</p>","a":"<b>recidivism rates</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Vocational instruction in prisons has been shown to dramatically decrease recidivism rates.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"re-offending rates\" | \"repeat crime statistics\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Crime / Prison / Rehabilitation essays.</p></div>","p":1},{"id":"W00-P-08","l":0,"t":"P","st":"Phrase","s":3,"tags":["collocation","crime"],"f":"<p>Capital punishment does not exert a proven ______ (tác dụng răn đe / ngăn ngừa tội phạm) compared to life imprisonment.</p>","a":"<b>deterrent effect</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Strict law enforcement creates a powerful deterrent effect against violent crime.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"preventive impact\" | \"deterring influence\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Crime &amp; Punishment essays.</p></div>","p":1},{"id":"W00-P-09","l":0,"t":"P","st":"Phrase","s":3,"tags":["collocation","economy"],"f":"<p>The rapid rise of the ______ (nền kinh tế việc làm tự do / thời vụ) deprives workers of traditional pensions and sick leave.</p>","a":"<b>gig economy</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Independent contractors in the gig economy often experience intense financial instability.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"freelance labour market\" | \"on-demand employment\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Employment / Work culture essays.</p></div>","p":1},{"id":"W00-P-10","l":0,"t":"P","st":"Phrase","s":3,"tags":["collocation","economy"],"f":"<p>Unchecked capitalism has widened the ______ (khoảng cách giàu nghèo / bất bình đẳng của cải) to historic highs.</p>","a":"<b>wealth disparity</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Extreme wealth disparity threatens social harmony and economic stability.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"income inequality\" | \"economic chasm\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Economy / Social inequality essays.</p></div>","p":1},{"id":"W00-P-11","l":0,"t":"P","st":"Phrase","s":3,"tags":["collocation","health"],"f":"<p>Reorienting budget priorities towards ______ (y tế dự phòng / phòng ngừa bệnh tật) saves substantial state funds.</p>","a":"<b>preventive healthcare</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Investing in preventive healthcare through nutrition campaigns diminishes hospital overcrowding.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"proactive health measures\" | \"disease prevention\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Health / Government budget allocation essays.</p></div>","p":1},{"id":"W00-P-12","l":0,"t":"P","st":"Phrase","s":3,"tags":["collocation","health"],"f":"<p>Unwholesome fast-food consumption is directly linked to ______ (các bệnh mãn tính không lây) like heart disease.</p>","a":"<b>chronic non-communicable diseases</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Chronic non-communicable diseases represent the leading cause of premature mortality worldwide.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"long-term lifestyle illnesses\" | \"chronic health conditions\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Health / Diet / Sedentary lifestyle essays.</p></div>","p":1},{"id":"W00-P-13","l":0,"t":"P","st":"Phrase","s":3,"tags":["collocation","society"],"f":"<p>Rapid Westernisation risks triggering total ______ (sự đồng hoá văn hoá) among indigenous minorities.</p>","a":"<b>cultural assimilation</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Immersion into urban life often leads to the gradual cultural assimilation of immigrant communities.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"cultural homogenization\" | \"erosion of native traditions\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Culture / Globalization / Heritage essays.</p></div>","p":1},{"id":"W00-P-14","l":0,"t":"P","st":"Phrase","s":3,"tags":["collocation","society"],"f":"<p>Intercultural festivals are essential to reinforce ______ (sự gắn kết / hoà hợp xã hội) in multicultural cities.</p>","a":"<b>social cohesion</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Poverty and segregation weaken social cohesion and breed inter-community distrust.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"societal solidarity\" | \"communal harmony\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Society / Immigration / Community essays.</p></div>","p":1},{"id":"W00-P-15","l":0,"t":"P","st":"Phrase","s":3,"tags":["collocation","government"],"f":"<p>The judicious ______ (sự phân bổ nguồn lực tài chính / ngân sách) towards public transport fosters sustainable growth.</p>","a":"<b>allocation of fiscal resources</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The allocation of fiscal resources must prioritise critical sectors such as healthcare and schooling.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"distribution of state funds\" | \"budgetary allocation\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Government spending / Taxation essays.</p></div>","p":1},{"id":"W00-P-16","l":0,"t":"P","st":"Phrase","s":3,"tags":["collocation","government"],"f":"<p>A robust welfare system serves as a vital ______ (mạng lưới an sinh xã hội) during recessions.</p>","a":"<b>social safety net</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Providing unemployment benefits ensures that disadvantaged families retain a basic social safety net.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"state welfare buffer\" | \"social security framework\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Government / Poverty / Welfare essays.</p></div>","p":1},{"id":"W00-E-01","l":0,"t":"E","st":"Error","s":3,"tags":["mistake","collocation-topic","LR"],"f":"<p>Essay viết: <i>\"The government should give money to poor people to make life better.\"</i> — Nâng cấp lên Band 7.5+ LR thế nào?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Dùng từ vựng quá đơn giản và thông tục (\"give money\", \"poor people\", \"make life better\") → Band 5 LR.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Governments should expand the <b>social safety net</b> and allocate <b>targeted state subsidies</b> to promote <b>upward social mobility</b> among disadvantaged demographics.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Sử dụng các thuật ngữ kinh tế - xã hội chuyên ngành (social safety net, subsidies, upward mobility) để đạt tiêu chí Band 7+ Lexical Resource.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR — từ vựng nghèo nàn và thiếu tính học thuật.</p></div>","p":0},{"id":"W00-E-02","l":0,"t":"E","st":"Error","s":3,"tags":["mistake","collocation-topic","LR"],"f":"<p>Essay viết: <i>\"Put bad people in jail will stop other people from doing bad things.\"</i> — Nâng cấp lên Band 7.5+ LR thế nào?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Dùng từ ngữ trẻ con (\"bad people\", \"jail\", \"doing bad things\") → Band 5 LR.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Imposing rigorous <b>custodial sentences</b> serves as an effective <b>deterrent effect</b> against potential criminal offenders.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Chủ đề Pháp luật &amp; Tội phạm cần dùng đúng thuật ngữ: <i>custodial sentences</i> (thay cho jail), <i>deterrent effect</i> (thay cho stop doing bad things), <i>offenders</i> (thay cho bad people).</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR</p></div>","p":0},{"id":"W00-E-03","l":0,"t":"E","st":"Error","s":3,"tags":["mistake","collocation-topic","LR"],"f":"<p>Essay viết: <i>\"Nature is getting very dirty and animals are dying.\"</i> — Nâng cấp lên Band 7.5+ LR thế nào?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Diễn đạt thô sơ, cảm tính (\"nature getting dirty\", \"animals dying\") → Band 5 LR.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Industrial activities have exacerbated widespread <b>environmental degradation</b> and precipitated unprecedented <b>biodiversity loss</b>.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Dùng các cụm danh từ học thuật chính xác: <i>environmental degradation</i> (thay cho nature getting dirty) và <i>biodiversity loss</i> (thay cho animals dying).</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR</p></div>","p":0},{"id":"W1D1-S-01","l":1,"t":"S","st":"Structure","s":3,"tags":["formula","introduction"],"f":"<p>Task 2 Introduction = mấy câu? Công thức?</p>","a":"","b":"<div class=\"sec\"><p><b>2 câu:</b></p><ol><li><b>Câu 1: PARAPHRASE</b> đề bài (đổi ≥3 từ: verb + noun + cấu trúc)</li><li><b>Câu 2: NÊU QUAN ĐIỂM</b> + preview reasons (sẽ thành 2 body paragraphs)</li></ol></div><div class=\"sec\"><span class=\"lbl\">VD</span><ul><li>Câu 1: \"It is widely argued that [paraphrase đề].\"</li><li>Câu 2: \"I firmly believe that..., primarily due to [reason 1] and [reason 2].\"</li></ul><p><b>Độ dài:</b> 40-50 từ (KHÔNG quá 3 câu)</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Intro = 2 câu duy nhất. Câu 1 đổi từ, Câu 2 nêu ý kiến.\"</p></div>","p":1},{"id":"W1D1-S-02","l":1,"t":"S","st":"Structure","s":3,"tags":["criteria","scoring"],"f":"<p>IELTS Writing chấm theo mấy tiêu chí? Kể tên + tỉ trọng.</p>","a":"","b":"<div class=\"sec\"><p><b>4 tiêu chí, mỗi tiêu chí 25%:</b></p><ol><li><b>TA</b> — Task Achievement (trả lời đúng đề)</li><li><b>CC</b> — Coherence &amp; Cohesion (mạch lạc, liên kết)</li><li><b>LR</b> — Lexical Resource (từ vựng đa dạng)</li><li><b>GRA</b> — Grammatical Range &amp; Accuracy (ngữ pháp chính xác)</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Final = (TA + CC + LR + GRA) ÷ 4. Nếu (6 + 5.5 + 5 + 5.5) ÷ 4 = 5.5</p></div>","p":1},{"id":"W1D1-S-03","l":1,"t":"S","st":"Structure","s":2,"tags":["paraphrase","technique"],"f":"<p>Paraphrase đề bài cần đổi tối thiểu mấy từ? Đổi những gì?</p>","a":"","b":"<div class=\"sec\"><p><b>Đổi ≥3 từ:</b></p><ol><li><b>Verb</b> — \"makes life easier\" → \"has simplified daily life\"</li><li><b>Noun</b> — \"technology\" → \"technological advancements\"</li><li><b>Cấu trúc câu</b> — active → passive, hoặc đổi chủ ngữ</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Technology makes life easier\" → \"Technological advancements have simplified daily life\"</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Đổi 3 thứ: VERB + NOUN + CẤU TRÚC. Thiếu 1 = chưa đủ paraphrase.\"</p></div>","p":1},{"id":"W1D1-S-04","l":1,"t":"S","st":"Structure","s":2,"tags":["band-descriptors","comparison"],"f":"<p>Dấu hiệu nhận biết nhanh Band 5 vs Band 7 ở tiêu chí LR?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Band 5:</b> Lặp từ nhiều lần (\"important\" 5 lần), từ vựng đơn giản</li><li><b>Band 7:</b> Dùng <b>synonyms + collocations</b>, từ vựng đa dạng, academic</li></ul></div><div class=\"sec\"><span class=\"lbl\">VD</span><ul><li>Band 5: \"Technology is very important. Technology helps people.\"</li><li>Band 7: \"Technological advancements have played a <b>pivotal role</b>.\"</li></ul></div>","p":1},{"id":"W1D1-P-01","l":1,"t":"P","st":"Phrase","s":2,"tags":["paraphrase","introduction"],"f":"<p>Technology ______ (đã thay đổi căn bản) modern society.</p>","a":"<b>has fundamentally transformed</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Digital innovations have fundamentally transformed the way people live and work.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"has profoundly changed\" | \"has radically altered\" | \"has significantly reshaped\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Câu 1 introduction — khi paraphrase verb \"changed/affected\"</p></div>","p":1},{"id":"W1D1-P-02","l":1,"t":"P","st":"Phrase","s":2,"tags":["opinion","introduction"],"f":"<p>I ______ (tin chắc rằng) the benefits outweigh the drawbacks.</p>","a":"<b>am firmly convinced that</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"I am firmly convinced that technological advancements have been overwhelmingly beneficial.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"firmly believe that\" | \"strongly contend that\" | \"am of the opinion that\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Câu 2 introduction — khi nêu quan điểm (Task 2 mọi dạng đề)</p></div>","p":1},{"id":"W1D1-P-03","l":1,"t":"P","st":"Phrase","s":2,"tags":["paraphrase","trend"],"f":"<p>Working from home ______ (ngày càng phổ biến) in recent years.</p>","a":"<b>has become increasingly prevalent</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The trend of remote work has become increasingly prevalent since the pandemic.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"has grown substantially\" | \"has gained considerable momentum\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Câu 1 introduction — khi paraphrase \"becoming more common / increasing\"</p></div>","p":1},{"id":"W1D1-P-04","l":1,"t":"P","st":"Phrase","s":2,"tags":["paraphrase","introduction"],"f":"<p>The rapid advancement of online connectivity has ______ (thay đổi đáng kể) the way individuals interact.</p>","a":"<b>significantly altered</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Globalisation has significantly altered employment patterns in developing countries.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"dramatically changed\" | \"considerably modified\" | \"profoundly influenced\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Câu 1 introduction — khi paraphrase \"changed / affected / influenced\"</p></div>","p":1},{"id":"W1D1-P-05","l":1,"t":"P","st":"Phrase","s":2,"tags":["paraphrase","technology"],"f":"<p>______ (những tiến bộ công nghệ) have simplified daily life.</p>","a":"<b>Technological advancements</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Technological advancements have simplified daily life in countless ways.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"Digital innovations\" | \"Modern technologies\" | \"Technological breakthroughs\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Câu 1 introduction — khi paraphrase danh từ \"technology\"</p></div>","p":1},{"id":"W1D1-E-01","l":1,"t":"E","st":"Error","s":3,"tags":["mistake","introduction"],"f":"<p>Introduction viết: <i>\"I will discuss both views in this essay.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Không có opinion! Chỉ báo trước sẽ discuss nhưng không nêu quan điểm.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"I firmly believe that the advantages significantly outweigh the disadvantages.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Dù đề hỏi \"Discuss both views\", câu 2 introduction vẫn PHẢI nêu opinion rõ ràng.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA — thiếu position = Band 5 TA</p></div>","p":0},{"id":"W1D1-E-02","l":1,"t":"E","st":"Error","s":3,"tags":["mistake","paraphrase"],"f":"<p>Introduction viết nguyên câu đề bài: <i>\"Technology makes life easier.\"</i> — Mất điểm gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Copy nguyên đề = giám khảo thấy bạn không có vocab, không paraphrase được.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Technological advancements have simplified daily life.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Paraphrase ≥3 từ từ đề bài: đổi verb + noun + cấu trúc câu. KHÔNG BAO GIỜ copy nguyên.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR — lặp từ đề = Band 5 LR</p></div>","p":0},{"id":"W1D1-E-03","l":1,"t":"E","st":"Error","s":2,"tags":["mistake","introduction"],"f":"<p>Introduction viết 5-6 câu, chiếm 80 từ. — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Introduction quá dài = lấy mất chỗ cho body paragraphs (phần quan trọng nhất).</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Introduction chỉ 2-3 câu, 40-50 từ. Dành 80% cho body.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Introduction = 2 câu (paraphrase + opinion). Viết ngắn, vào thẳng vấn đề.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA — phân bổ từ không hợp lý</p></div>","p":0},{"id":"W1D2-S-01","l":2,"t":"S","st":"Structure","s":3,"tags":["formula","analysis"],"f":"<p>4 bước phân tích bài mẫu IELTS là gì?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>SCAN</b> — Đọc lướt → hiểu structure tổng thể (đếm paragraphs)</li><li><b>MARK</b> — Đánh dấu: [P]=Paraphrase, [C]=Collocation, [GRA]=Grammar, [LINK]=Linking, [EX]=Example</li><li><b>EXTRACT</b> — Ghi lại 5-8 techniques vào bảng (câu gốc + giải thích + cách áp dụng)</li><li><b>APPLY</b> — Viết 1 đoạn mới dùng ≥3 techniques đã trích</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Đọc essay Band 7 → đánh dấu \"collaborate seamlessly\" [C] → ghi vào bảng → dùng trong body paragraph bài mình</p></div>","p":1},{"id":"W1D2-S-02","l":2,"t":"S","st":"Structure","s":3,"tags":["formula","body-paragraph"],"f":"<p>TEES paragraph structure là gì? Mỗi chữ nghĩa gì?</p>","a":"","b":"<div class=\"sec\"><p><b>TEES = 1 body paragraph hoàn chỉnh (4-6 câu, ~80-100 từ):</b></p><ul><li><b>T</b> — Topic sentence: Nêu main idea (1 câu)</li><li><b>E</b> — Explanation: Giải thích tại sao (1-2 câu)</li><li><b>E</b> — Example: Ví dụ cụ thể — dùng tên, số liệu, quốc gia (1-2 câu)</li><li><b>S</b> — Summary: Kết nối lại thesis/topic (1 câu)</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>T: \"Technology enhances communication.\" → E: \"Digital platforms eliminate barriers...\" → E: \"For instance, Zoom...\" → S: \"Consequently, technology has made communication more accessible.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"1 paragraph = 1 idea. Nhồi 2 ý = Band 5. TEES = bắt buộc cho Band 7.\"</p></div>","p":1},{"id":"W1D2-S-03","l":2,"t":"S","st":"Structure","s":3,"tags":["formula","example"],"f":"<p>Công thức viết Specific Example (thay vì example chung chung)?</p>","a":"","b":"<div class=\"sec\"><p><b>Công thức:</b> [Tên cụ thể: tool/platform/country] + [has/have] + [verb mạnh] + [kết quả cụ thể]</p></div><div class=\"sec\"><span class=\"lbl\">VD</span><ul><li class=\"bad\">❌ \"Technology helps people communicate\" (chung chung)</li><li class=\"good\">✅ \"Video conferencing tools <b>such as Zoom</b> have become <b>indispensable</b> for remote collaboration in the <b>IT sector</b>.\"</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Luôn có TÊN (Zoom, Japan, Coursera) + KẾT QUẢ (streamlined, reduced, indispensable). Không tên = Band 5.\"</p></div>","p":1},{"id":"W1D2-S-04","l":2,"t":"S","st":"Structure","s":2,"tags":["linking","variety"],"f":"<p>Band 7 dùng linking devices gì thay cho \"Also, First, Second\" (Band 5)?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Giải thích:</b> \"Specifically,\" | \"The rationale behind this is that...\"</li><li><b>Thêm ý:</b> \"Furthermore,\" | \"Moreover,\" | \"In addition,\"</li><li><b>Kết quả:</b> \"Consequently,\" | \"As a result,\" | \"Therefore,\"</li><li><b>Tương phản:</b> \"Nevertheless,\" | \"However,\" | \"Conversely,\"</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Specifically, digital platforms have eliminated barriers. Consequently, technology has made communication more accessible.\"</p></div>","p":1},{"id":"W1D2-P-01","l":2,"t":"P","st":"Phrase","s":2,"tags":["collocation","body-paragraph"],"f":"<p>Distributed teams can ______ (hợp tác trơn tru) across time zones using video conferencing tools.</p>","a":"<b>collaborate seamlessly</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Video conferencing tools allow distributed teams to collaborate seamlessly across time zones.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"work together efficiently\" | \"cooperate effectively\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về technology/communication, dùng làm collocation trong Example</p></div>","p":1},{"id":"W1D2-P-02","l":2,"t":"P","st":"Phrase","s":2,"tags":["collocation","body-paragraph"],"f":"<p>Zoom and Microsoft Teams ______ (trở nên không thể thiếu) in the IT industry.</p>","a":"<b>have become indispensable</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Video conferencing tools such as Zoom have become indispensable in the modern workplace.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"have become essential\" | \"have proven invaluable\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph Example — thay cho \"very important\" (Band 5)</p></div>","p":1},{"id":"W1D2-P-03","l":2,"t":"P","st":"Phrase","s":2,"tags":["collocation","crime"],"f":"<p>Extending prison sentences is considered a means of ______ (ngăn chặn hoạt động phạm tội).</p>","a":"<b>deterring criminal activity</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Some argue that harsher punishments are the most effective means of deterring criminal activity.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"preventing illegal behaviour\" | \"reducing crime rates\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — topic Crime/Law. Dùng ở Topic sentence hoặc Explanation</p></div>","p":1},{"id":"W1D2-P-04","l":2,"t":"P","st":"Phrase","s":2,"tags":["collocation","ageing"],"f":"<p>Seasoned professionals possess decades of ______ (kiến thức tích lũy).</p>","a":"<b>accumulated knowledge</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Older employees bring accumulated knowledge that benefits the entire organisation.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"extensive expertise\" | \"deep institutional knowledge\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — topic Education/Employment/Ageing population</p></div>","p":1},{"id":"W1D2-P-05","l":2,"t":"P","st":"Phrase","s":2,"tags":["grammar","participle-clause"],"f":"<p>Digital platforms have eliminated geographical barriers, ______ (cho phép) individuals to maintain relationships.</p>","a":"<b>enabling</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Automation tools handle repetitive tasks, freeing employees to focus on creative responsibilities.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"allowing\" | \"permitting\" | \"empowering\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Nối 2 ý trong body paragraph — participle clause thay cho 2 câu đơn (tăng GRA)</p></div>","p":1},{"id":"W1D2-P-06","l":2,"t":"P","st":"Phrase","s":2,"tags":["collocation","workplace"],"f":"<p>CI/CD pipelines have ______ (tinh giản quy trình) workflows and increased output.</p>","a":"<b>streamlined</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Cloud-based platforms such as Slack and Zoom have streamlined remote collaboration in the IT sector.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"optimised\" | \"simplified\" | \"enhanced the efficiency of\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — thay cho \"made X easier\" (Band 5). Dùng với IT/workplace examples</p></div>","p":1},{"id":"W1D2-P-07","l":2,"t":"P","st":"Phrase","s":2,"tags":["linking","explanation"],"f":"<p>______ (lý do đằng sau quan điểm này) is that prolonged incarceration creates a psychological deterrent.</p>","a":"<b>The rationale behind this perspective</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The rationale behind this perspective is that higher salaries attract more qualified candidates.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"The reasoning behind this view\" | \"This perspective rests on the assumption that\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph Explanation (câu E trong TEES) — mở đầu giải thích tại sao</p></div>","p":1},{"id":"W1D2-E-01","l":2,"t":"E","st":"Error","s":3,"tags":["mistake","example"],"f":"<p>Body paragraph viết: <i>\"For example, technology is useful.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Ví dụ quá chung chung — không nêu cụ thể giúp GÌ, tool NÀO, cho AI.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"For instance, video conferencing tools such as Zoom have become indispensable for remote collaboration in the IT sector.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Specific example = [Tên cụ thể] + [has/have] + [kết quả]. Không bao giờ viết \"technology is useful\" chung chung.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + LR — thiếu evidence cụ thể + từ vựng nghèo</p></div>","p":0},{"id":"W1D2-E-02","l":2,"t":"E","st":"Error","s":3,"tags":["mistake","repetition"],"f":"<p>Bài viết dùng \"technology\" 8 lần và \"people\" 5 lần. Mất điểm tiêu chí nào?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Lặp từ quá nhiều = không thể hiện vốn từ vựng.</p></div><div class=\"sec\"><span class=\"lbl\">✅ Đúng</span><p>Dùng synonyms:</p><ul><li>\"technology\" → \"digital innovations\" / \"technological advancements\" / \"modern tools\"</li><li>\"people\" → \"individuals\" / \"citizens\" / \"users\"</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Mỗi từ chính (keyword) → chuẩn bị ≥2 synonyms trước khi viết. KHÔNG dùng cùng từ quá 2 lần.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR — lặp từ = Band 5 LR tối đa</p></div>","p":0},{"id":"W1D2-E-03","l":2,"t":"E","st":"Error","s":3,"tags":["mistake","body-paragraph"],"f":"<p>Body paragraph viết 4 ý khác nhau: <i>\"Technology helps communication. It improves education. It helps healthcare. It helps economy.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Nhồi 4 ý vào 1 paragraph → không ý nào được develop đầy đủ.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Chọn 1 ý duy nhất → develop bằng TEES (Topic → Explanation → Example → Summary).</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>1 paragraph = 1 main idea. Nếu có 2 ý → tách 2 paragraphs.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + CC — thiếu development + thiếu coherence</p></div>","p":0},{"id":"W1D2-E-04","l":2,"t":"E","st":"Error","s":2,"tags":["mistake","grammar"],"f":"<p>Bài viết toàn câu đơn: <i>\"Technology helps. It is important. People use it.\"</i> — Thiếu gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Chỉ simple sentences (S + V + O) → Band 5 GRA. Band 7 cần complex sentences.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Nối ý bằng participle clause: \"Technology has eliminated barriers, <b>enabling</b> individuals to communicate regardless of distance.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Mỗi body paragraph nên có ít nhất 1 complex sentence (participle clause, relative clause, hoặc conditional).</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA — thiếu grammatical range</p></div>","p":0},{"id":"W1D2-E-05","l":2,"t":"E","st":"Error","s":2,"tags":["mistake","linking"],"f":"<p>Bài viết chỉ dùng linking: \"Also\", \"First\", \"Second\", \"And\". — Thiếu gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Linking nghèo nàn → Band 5 CC. Band 7 cần đa dạng + tự nhiên.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"<b>Specifically,</b> digital platforms... <b>Consequently,</b> technology... <b>Furthermore,</b> innovations...\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Dùng ≥4 loại linking khác nhau: giải thích (Specifically), kết quả (Consequently), thêm ý (Furthermore), tương phản (Nevertheless).</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC — linking devices quá đơn giản</p></div>","p":0},{"id":"W1D3-S-01","l":3,"t":"S","st":"Structure","s":3,"tags":["formula","task1-introduction"],"f":"<p>Công thức Introduction Task 1 là gì? Khác Task 2 ở điểm nào?</p>","a":"","b":"<div class=\"sec\"><ul><li>Task 1 Introduction = <b>1 câu paraphrase</b> (~25-35 từ)</li><li>Công thức: The [chart type] + [verb paraphrase] + [nội dung paraphrase] + [time period]</li><li><b>Khác Task 2:</b> Task 1 = 1 câu, KHÔNG opinion. Task 2 = 2 câu, CÓ opinion.</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"The bar chart illustrates the figures for student enrolment at three universities over a ten-year period.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Task 1 = 1 câu. Task 2 = 2 câu. 1 vs 2, dễ nhớ!\"</p></div>","p":1},{"id":"W1D3-S-02","l":3,"t":"S","st":"Structure","s":3,"tags":["formula","task1-overview"],"f":"<p>Task 1 Overview viết thế nào? Có 3 quy tắc BẮT BUỘC nào?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Luôn bắt đầu</b> bằng \"Overall, ...\"</li><li>Nêu <b>2-3 xu hướng chính</b> (big picture only)</li><li><b>TUYỆT ĐỐI không</b> có số cụ thể</li></ol><ul><li>Thiếu overview → maximum Band 5!</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Overall, student numbers rose in all three universities, with University A seeing the most dramatic increase.\"</p></div>","p":1},{"id":"W1D3-S-03","l":3,"t":"S","st":"Structure","s":2,"tags":["chart-types","task1-introduction"],"f":"<p>Khi đề bài có 2+ nhóm/quốc gia, dùng verb nào thay \"shows\"?</p>","a":"","b":"<div class=\"sec\"><ul><li>Dùng <b>\"compares\"</b> — khi đề so sánh 2+ nhóm, quốc gia, hoặc categories</li><li>Dùng <b>\"illustrates\"</b> — mọi chart type (an toàn nhất)</li><li>Dùng <b>\"depicts\"</b> — line graph, process diagram</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"The bar chart compares the proportion of residents using public transport in three cities.\"</p></div>","p":1},{"id":"W1D3-S-04","l":3,"t":"S","st":"Structure","s":2,"tags":["trend-language","task1-body"],"f":"<p>Liệt kê verb mô tả xu hướng: tăng (3), giảm (3), ổn định (2)?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Tăng ↑:</b> rose / increased / grew</li><li><b>Giảm ↓:</b> fell / declined / dropped</li><li><b>Ổn định →:</b> remained stable / stayed constant</li><li><b>Dao động ↑↓:</b> fluctuated</li><li><b>Đỉnh:</b> peaked at / reached a peak</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"RIG — Rose, Increased, Grew\" cho tăng. \"FDD — Fell, Declined, Dropped\" cho giảm.</p></div>","p":1},{"id":"W1D3-P-01","l":3,"t":"P","st":"Phrase","s":2,"tags":["paraphrase","task1-introduction"],"f":"<p>The bar chart ______ (minh họa) the figures for student enrolment at three universities.</p>","a":"<b>illustrates</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The line graph illustrates the trends in unemployment rates across five countries.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"depicts\" | \"presents\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Introduction — paraphrase \"shows\"</p></div>","p":1},{"id":"W1D3-P-02","l":3,"t":"P","st":"Phrase","s":2,"tags":["paraphrase","task1-introduction"],"f":"<p>The pie chart shows the ______ (tỷ lệ) of energy generated from different sources.</p>","a":"<b>proportion</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"A significant proportion of the population relies on public transport for daily commuting.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"share\" | \"percentage\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Introduction — paraphrase \"percentage\", đặc biệt dùng cho pie chart</p></div>","p":1},{"id":"W1D3-P-03","l":3,"t":"P","st":"Phrase","s":2,"tags":["paraphrase","task1-introduction"],"f":"<p>The chart compares the ______ (số liệu) for international student enrolment in four countries.</p>","a":"<b>figures for</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The table provides figures for household expenditure across six categories.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"data on\" | \"statistics for\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Introduction — paraphrase \"number of\" hoặc \"amount of\"</p></div>","p":1},{"id":"W1D3-P-04","l":3,"t":"P","st":"Phrase","s":2,"tags":["trend-language","task1-overview"],"f":"<p>Overall, there was a ______ ______ (sự thay đổi lớn) in the energy mix over the thirty-year period.</p>","a":"<b>dramatic shift</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The data reveals a dramatic shift in consumer preferences towards online shopping.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"significant change\" | \"notable transformation\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Overview — khi pattern thay đổi lớn giữa 2 thời điểm</p></div>","p":1},{"id":"W1D3-P-05","l":3,"t":"P","st":"Phrase","s":2,"tags":["trend-language","task1-overview"],"f":"<p>The number of tourists ______ ______ (tăng đáng kể) over the period shown.</p>","a":"<b>rose considerably</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Household spending on technology rose considerably between 2010 and 2020.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"increased significantly\" | \"grew substantially\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Overview/Body — mô tả xu hướng tăng mạnh</p></div>","p":1},{"id":"W1D3-P-06","l":3,"t":"P","st":"Phrase","s":2,"tags":["trend-language","task1-overview"],"f":"<p>Fossil fuels saw a ______ ______ (giảm đáng kể) in their share of energy production.</p>","a":"<b>significant decline</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"There was a significant decline in the number of print newspaper readers after 2015.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"sharp decrease\" | \"substantial drop\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Overview/Body — mô tả xu hướng giảm rõ rệt</p></div>","p":1},{"id":"W1D3-E-01","l":3,"t":"E","st":"Error","s":3,"tags":["mistake","task1-overview"],"f":"<p><i>\"Overall, 500 students enrolled in 2010 and this rose to 800 by 2020.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Overview chứa số cụ thể (500, 800). Overview chỉ nêu xu hướng, KHÔNG bao giờ có số.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Overall, student enrolment rose significantly over the ten-year period.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Overview = big picture. Số cụ thể để dành cho body paragraphs.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA</p></div>","p":0},{"id":"W1D3-E-02","l":3,"t":"E","st":"Error","s":3,"tags":["mistake","task1-introduction"],"f":"<p><i>\"The chart shows the number of students enrolled in three universities. I believe this is a positive trend.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Task 1 KHÔNG BAO GIỜ có opinion cá nhân (\"I believe\"). Đây là lỗi nhầm Task 1 thành Task 2.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The chart illustrates the figures for student enrolment at three higher education institutions.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Task 1 = mô tả khách quan. Task 2 = có opinion. Không bao giờ trộn lẫn.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA</p></div>","p":0},{"id":"W1D3-E-03","l":3,"t":"E","st":"Error","s":3,"tags":["mistake","task1-introduction"],"f":"<p><i>\"The bar chart shows the number of international students studying at universities in four different countries between 2015 and 2022.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Copy nguyên đề bài, không paraphrase từ nào. Mất điểm LR vì không thể hiện vocabulary range.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The bar chart illustrates the figures for international student enrolment at universities in four nations over a seven-year period from 2015 to 2022.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Introduction Task 1 phải paraphrase ≥3 từ: verb + noun + time expression.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR</p></div>","p":0},{"id":"W1D3-E-04","l":3,"t":"E","st":"Error","s":2,"tags":["mistake","task1-overview"],"f":"<p><i>Bạn viết full Task 1 nhưng KHÔNG viết đoạn Overview.</i> — Hậu quả gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Thiếu overview = thiếu \"the key features\" → TA bị giới hạn ở Band 5 maximum.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Luôn viết Overview ngay sau Introduction, trước body paragraphs.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Overview là đoạn QUAN TRỌNG NHẤT trong Task 1. Thiếu overview = maximum Band 5.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA</p></div>","p":0},{"id":"W1D4-S-01","l":4,"t":"S","st":"Structure","s":3,"tags":["time-management","exam-strategy"],"f":"<p>IELTS Writing 60 phút: chia thời gian thế nào? Task nào quan trọng hơn?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Task 1:</b> 20 phút (33% điểm) — ≥150 từ</li><li><b>Task 2:</b> 40 phút (66% điểm) — ≥250 từ</li><li>Task 2 = <b>gấp đôi</b> điểm → LUÔN ưu tiên Task 2</li><li>Nếu hết giờ: thiếu Task 1 tốt hơn thiếu Task 2</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Task 1 chưa xong ở phút 20 → DỪNG, chuyển sang Task 2 ngay.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"20-40 phút = 1-2 tỉ lệ điểm. Task 2 = double points!\"</p></div>","p":1},{"id":"W1D4-S-02","l":4,"t":"S","st":"Structure","s":3,"tags":["time-management","task2"],"f":"<p>Task 2 (40 phút): chia thời gian chi tiết thế nào? Viết phần nào TRƯỚC?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>[5']</b> Đọc đề + xác định essay type</li><li><b>[5']</b> Lên outline (thesis + 2 reasons + examples)</li><li><b>[12']</b> Body Paragraph 1</li><li><b>[12']</b> Body Paragraph 2</li><li><b>[3']</b> Introduction + Conclusion</li><li><b>[3']</b> Đọc lại + sửa lỗi</li></ol><ul><li><b>Mẹo:</b> Viết <b>Body trước</b>, Intro + Conclusion sau!</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Outline 5' → Body 1 (12') → Body 2 (12') → Intro+Conclusion (3') → Check (3')</p></div>","p":1},{"id":"W1D4-S-03","l":4,"t":"S","st":"Structure","s":3,"tags":["error-checking","exam-strategy"],"f":"<p>3 phút cuối bài viết: kiểm tra 5 loại lỗi gì?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>S-V agreement:</b> Technology ha<b>s</b> changed (số ít = has/is/does)</li><li><b>Articles:</b> a/an/the/Ø — general = no article, specific = \"the\"</li><li><b>Spelling:</b> government ✅, <del>goverment</del> ❌</li><li><b>Verb tense:</b> Task 1 past data = past tense, Task 2 = present</li><li><b>Word form:</b> greatly develop<b>ed</b> ✅, <del>great develop</del> ❌</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Đọc lại từng câu → check 5 loại → sửa 3-5 lỗi nhỏ → tiết kiệm 0.5 band!</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"SA-SAV-W: Subject-Agreement, Articles, Spelling, And Verb tense, Word form\"</p></div>","p":1},{"id":"W1D4-S-04","l":4,"t":"S","st":"Structure","s":2,"tags":["word-count","exam-strategy"],"f":"<p>Số từ lý tưởng cho Task 1 và Task 2? Cách đếm từ nhanh?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Task 1:</b> 160-180 từ (tối thiểu 150)</li><li><b>Task 2:</b> 260-280 từ (tối thiểu 250)</li><li><b>Đếm nhanh:</b> ~25 từ/dòng viết tay → đếm số dòng × 25</li><li>Viết thiếu từ = bị trừ TA</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>10 dòng viết tay ≈ 250 từ → đủ Task 2.</p></div>","p":1},{"id":"W1D4-P-01","l":4,"t":"P","st":"Phrase","s":2,"tags":["trend-language","task1-body"],"f":"<p>The Science Museum ______ ______ ______ (tăng đáng kể) in visitor numbers over the period.</p>","a":"<b>experienced a significant rise</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Online shopping experienced a significant rise during the pandemic period.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"saw a considerable increase\" | \"witnessed a notable growth\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Overview/Body — mô tả xu hướng tăng rõ rệt, dùng noun phrase thay verb</p></div>","p":1},{"id":"W1D4-P-02","l":4,"t":"P","st":"Phrase","s":2,"tags":["trend-language","task1-body"],"f":"<p>All three museums ______ ______ ______ ______ (giảm mạnh đột ngột) in 2020.</p>","a":"<b>suffered a dramatic drop</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"International tourism suffered a dramatic drop due to travel restrictions in 2020.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"experienced a sharp decline\" | \"saw a steep fall\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — khi data giảm mạnh đột ngột (crisis, external event)</p></div>","p":1},{"id":"W1D4-P-03","l":4,"t":"P","st":"Phrase","s":2,"tags":["trend-language","task1-body"],"f":"<p>By 2022, visitor numbers had ______ ______ (phục hồi một phần) from the 2020 low.</p>","a":"<b>partially recovered</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The economy had partially recovered by the third quarter, though it remained below pre-crisis levels.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"rebounded slightly\" | \"made a partial recovery\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — khi data tăng lại sau giai đoạn giảm nhưng chưa về mức cũ</p></div>","p":1},{"id":"W1D4-P-04","l":4,"t":"P","st":"Phrase","s":2,"tags":["paraphrase","task2-introduction"],"f":"<p>It is frequently argued that modern technology has ______ ______ ______ ______ (tăng sự phức tạp) everyday life.</p>","a":"<b>increased the complexity of</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Globalisation has increased the complexity of supply chain management.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"added to the complexity of\" | \"made ... more intricate\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 2 Introduction — paraphrase \"made more complicated\"</p></div>","p":1},{"id":"W1D4-P-05","l":4,"t":"P","st":"Phrase","s":2,"tags":["collocation","task2-body"],"f":"<p>Technology has had a ______ ______ ______ (tác động biến đổi) communication and work.</p>","a":"<b>transformative effect on</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Artificial intelligence has had a transformative effect on the healthcare industry.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"profound impact on\" | \"far-reaching influence on\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 2 Body — khi viết về ảnh hưởng lớn, thay đổi sâu rộng</p></div>","p":1},{"id":"W1D4-P-06","l":4,"t":"P","st":"Phrase","s":2,"tags":["collocation","task2-body"],"f":"<p>These issues ______ ______ (bắt nguồn từ) how individuals manage technology rather than from technology itself.</p>","a":"<b>stem from</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Many environmental problems stem from unsustainable consumption patterns.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"originate from\" | \"are rooted in\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 2 Body — giải thích nguyên nhân, đặc biệt khi phản bác (counter-argument)</p></div>","p":1},{"id":"W1D4-E-01","l":4,"t":"E","st":"Error","s":3,"tags":["mistake","time-management"],"f":"<p><i>Bạn dành 35 phút cho Task 1 rồi chỉ còn 25 phút cho Task 2. Task 2 viết được 180 từ (thiếu 70 từ).</i> — Hậu quả gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Phân bổ thời gian sai. Task 2 = 66% điểm nhưng không đủ thời gian → viết thiếu từ + thiếu ý.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Task 1 = 20 phút. Task 2 = 40 phút. Nếu Task 1 chưa xong ở phút 20 → DỪNG.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Task 2 gấp đôi điểm Task 1. Luôn ưu tiên hoàn thành Task 2 trước.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA (cả 2 tasks)</p></div>","p":0},{"id":"W1D4-E-02","l":4,"t":"E","st":"Error","s":3,"tags":["mistake","grammar"],"f":"<p><i>\"Technology have changed the way people communicate and it make life easier.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>2 lỗi S-V agreement: \"Technology\" = số ít → \"have\" phải là \"has\"; \"it\" = số ít → \"make\" phải là \"makes\".</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Technology <b>has</b> changed the way people communicate and it <b>makes</b> life easier.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Chủ ngữ số ít (technology, it, education, government) → has/is/does/makes. Luôn check S-V agreement trong 3 phút cuối.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA</p></div>","p":0},{"id":"W1D4-E-03","l":4,"t":"E","st":"Error","s":3,"tags":["mistake","grammar"],"f":"<p><i>\"In 2020, the number of visitors increase to 500,000 and the goverment invest more money.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>3 lỗi: (1) \"increase\" → past tense vì data 2020 đã qua, (2) \"goverment\" → spelling sai, (3) \"invest\" → past tense.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"In 2020, the number of visitors <b>increased</b> to 500,000 and the <b>government</b> <b>invested</b> more money.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Task 1 mô tả data quá khứ → dùng past tense. Check spelling cho các từ hay sai: government, environment, developing.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA</p></div>","p":0},{"id":"W1D4-E-04","l":4,"t":"E","st":"Error","s":2,"tags":["mistake","essay-planning"],"f":"<p><i>Bạn bắt đầu viết Task 2 ngay không lên outline. Viết được 200 từ thì nhận ra 2 body paragraph nói cùng 1 ý.</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Không lên outline → 2 body paragraphs trùng ý → CC bị trừ nặng (thiếu logical organization).</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Dành 5 phút lên outline: thesis + Body 1 (reason 1 + example) + Body 2 (reason 2 + example). Mỗi body = 1 ý riêng.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>5 phút outline = tiết kiệm 10 phút viết lại. Outline chỉ cần note keywords, không cần viết đẹp.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC + TA</p></div>","p":0},{"id":"W2D1-S-01","l":5,"t":"S","st":"Structure","s":3,"tags":["formula","sentence-structure"],"f":"<p>2 cấu trúc câu chính để mô tả trends là gì? Phải dùng cả 2 vì sao?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Verb form:</b> Subject + VERB + ADVERB + from X to Y + time phrase</li></ol><p>→ \"Sales <b>rose sharply</b> from 200 to 800 between 2010 and 2020.\"</p><ol><li><b>Noun form:</b> There was + a/an + ADJECTIVE + NOUN + in Subject</li></ol><p>→ \"There was <b>a sharp rise</b> in sales, from 200 to 800.\"</p><ul><li>Phải dùng CẢ HAI → GRA variety (sentence structures). Chỉ dùng 1 loại = mất điểm GRA.</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Body paragraph tốt: 3 câu verb form + 2 câu noun form = variety ✅</p></div>","p":1},{"id":"W2D1-S-02","l":5,"t":"S","st":"Structure","s":3,"tags":["vocabulary","verb-noun"],"f":"<p>Chuyển đổi verb form → noun form: \"rose sharply\" → ? / \"declined significantly\" → ?</p>","a":"","b":"<div class=\"sec\"><ul><li>rose <b>sharply</b> → a <b>sharp</b> rise</li><li>increased <b>dramatically</b> → a <b>dramatic</b> increase</li><li>grew <b>steadily</b> → <b>steady</b> growth</li><li>fell <b>gradually</b> → a <b>gradual</b> fall</li><li>declined <b>significantly</b> → a <b>significant</b> decline</li><li>dropped <b>slightly</b> → a <b>slight</b> drop</li><li>⚠️ Adverb → Adjective: sharply→sharp, dramatically→dramatic, slightly→slight</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Sales rose sharply\" → \"There was a sharp rise in sales.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Verb form dùng ADVERB (sharply). Noun form dùng ADJECTIVE (sharp). Đừng nhầm: \"a sharply rise\" ❌</p></div>","p":1},{"id":"W2D1-S-03","l":5,"t":"S","st":"Structure","s":2,"tags":["vocabulary","adverb-degree"],"f":"<p>Xếp 6 adverbs theo mức độ thay đổi từ MẠNH → NHẸ: dramatically, steadily, slightly, significantly, marginally, gradually?</p>","a":"","b":"<div class=\"sec\"><ol><li>🔴 <b>dramatically / sharply</b> (&gt;50%)</li><li>🟡 <b>significantly / considerably</b> (20-50%)</li><li>🟢 <b>steadily / gradually</b> (đều đặn, ~10-20%)</li><li>⚪ <b>slightly / marginally</b> (&lt;10%)</li></ol><ul><li>Chọn adverb phải MATCH mức thay đổi thực tế trong data!</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Tăng từ 100 → 500 = \"rose <b>dramatically</b>\" ✅. Tăng từ 100 → 108 = \"rose <b>slightly</b>\" ✅</p></div>","p":1},{"id":"W2D1-S-04","l":5,"t":"S","st":"Structure","s":2,"tags":["vocabulary","trend-verbs"],"f":"<p>14 trend verbs: kể 5 TĂNG (nhẹ→mạnh) + 5 GIẢM (nhẹ→mạnh)?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>↑ Tăng:</b> rose &lt; increased &lt; grew &lt; climbed &lt; <b>surged</b></li><li><b>↓ Giảm:</b> dipped &lt; fell &lt; declined &lt; dropped &lt; <b>plummeted</b></li><li><b>→ Ổn định:</b> remained stable / stayed constant / levelled off</li><li><b>↑↓ Dao động:</b> fluctuated</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"+5% = rose\" vs \"+200% = surged\" / \"-3% = dipped\" vs \"-80% = plummeted\"</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Tăng nhớ \"RIGCS\" (Rose, Increased, Grew, Climbed, Surged). Giảm nhớ \"DFDP²\" (Dipped, Fell, Declined, Dropped, Plummeted)</p></div>","p":1},{"id":"W2D1-S-05","l":5,"t":"S","st":"Structure","s":2,"tags":["time-phrases","task1-body"],"f":"<p>Kể 6 time phrases dùng trong Task 1 body paragraphs?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>from X to Y</b> / <b>between X and Y</b> (khoảng thời gian)</li><li><b>over the period</b> / <b>over a [N]-year period</b> (toàn bộ)</li><li><b>during the first/last decade</b> (nửa đầu/cuối)</li><li><b>by [year]</b> (tính đến thời điểm)</li><li><b>throughout the period</b> (suốt khoảng thời gian)</li><li><b>in [year]</b> (năm cụ thể)</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Sales rose sharply <b>from 2010 to 2015</b>, <b>before declining gradually over the following five years</b>.\"</p></div>","p":1},{"id":"W2D1-P-01","l":5,"t":"P","st":"Phrase","s":2,"tags":["trend-verb","task1-body"],"f":"<p>House prices ______ (tăng vọt) by over 200% between 2010 and 2020.</p>","a":"<b>surged</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Demand for electric vehicles surged in the final quarter of the year.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"soared\" | \"skyrocketed\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — khi data tăng RẤT MẠNH (&gt;50%), mạnh hơn \"rose\" hoặc \"increased\"</p></div>","p":1},{"id":"W2D1-P-02","l":5,"t":"P","st":"Phrase","s":2,"tags":["trend-verb","task1-body"],"f":"<p>The number of print newspaper readers ______ (giảm thê thảm) from 5 million to under 500,000.</p>","a":"<b>plummeted</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Tourism revenue plummeted during the pandemic, falling to its lowest point in a decade.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"plunged\" | \"crashed\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — khi data giảm CỰC MẠNH (&gt;70%), mạnh hơn \"fell\" hoặc \"declined\"</p></div>","p":1},{"id":"W2D1-P-03","l":5,"t":"P","st":"Phrase","s":2,"tags":["trend-verb","task1-body"],"f":"<p>After peaking in 2015, sales ______ ______ (giảm nhẹ) to 470,000 the following year.</p>","a":"<b>dipped slightly</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Unemployment dipped slightly in March before rising again in the summer months.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"fell marginally\" | \"declined minimally\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — khi data giảm RẤT NHẸ (&lt;10%), nhẹ hơn \"fell\" hoặc \"dropped\"</p></div>","p":1},{"id":"W2D1-P-04","l":5,"t":"P","st":"Phrase","s":3,"tags":["noun-form","task1-body"],"f":"<p>There was ______ ______ ______ (sự tăng mạnh) in the number of online shoppers after 2015.</p>","a":"<b>a dramatic increase</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The country experienced a dramatic increase in renewable energy capacity over the decade.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"a sharp rise\" | \"a substantial growth\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — Noun form thay thế verb form để tạo GRA variety. Dùng adjective (dramatic) KHÔNG PHẢI adverb (dramatically)</p></div>","p":1},{"id":"W2D1-P-05","l":5,"t":"P","st":"Phrase","s":2,"tags":["peak-language","task1-body"],"f":"<p>Sales ______ ______ ______ (đạt đỉnh) approximately 500,000 in 2014.</p>","a":"<b>reached a peak of</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Global oil prices reached a peak of $140 per barrel in mid-2008.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"peaked at\" | \"hit a high of\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — khi mô tả data point CAO NHẤT trong line graph</p></div>","p":1},{"id":"W2D1-P-06","l":5,"t":"P","st":"Phrase","s":2,"tags":["peak-language","task1-body"],"f":"<p>The unemployment rate ______ ______ ______ (chạm đáy) just 3.2% in early 2020.</p>","a":"<b>bottomed out at</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"House prices bottomed out at £150,000 before beginning a gradual recovery.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"hit a low of\" | \"reached its lowest point at\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — khi mô tả data point THẤP NHẤT trong line graph</p></div>","p":1},{"id":"W2D1-P-07","l":5,"t":"P","st":"Phrase","s":2,"tags":["transition","task1-body"],"f":"<p>The figure continued to climb, reaching a peak of 500,000, ______ ______ (trước khi giảm) to 480,000 in 2017.</p>","a":"<b>before declining</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Exports grew rapidly in the first half of the year, before declining in the third quarter.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"before falling\" | \"after which it dropped\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — nối 2 trends trong cùng 1 câu (participle clause, tăng điểm GRA)</p></div>","p":1},{"id":"W2D1-E-01","l":5,"t":"E","st":"Error","s":3,"tags":["mistake","repetition"],"f":"<p><i>\"The number increased from 200 to 400. Then it increased again to 600. After that, it increased to 800.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Lặp \"increased\" 3 lần liên tiếp → LR cực thấp, Band 5 cách viết.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The number <b>rose sharply</b> from 200 to 400, before <b>climbing steadily</b> to 600. By 2020, the figure <b>had surged to</b> 800.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>KHÔNG lặp trend verb quá 2 lần trong toàn bài. Dùng ít nhất 4 verbs khác nhau + xen noun forms.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR + GRA</p></div>","p":0},{"id":"W2D1-E-02","l":5,"t":"E","st":"Error","s":3,"tags":["mistake","noun-form"],"f":"<p><i>\"There was a <b>sharply</b> rise in the number of tourists.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Dùng ADVERB (sharply) trước NOUN (rise). Noun form cần ADJECTIVE.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"There was a <b>sharp</b> rise in the number of tourists.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Verb form = adverb (rose <b>sharply</b>). Noun form = adjective (a <b>sharp</b> rise). Đừng trộn lẫn.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA</p></div>","p":0},{"id":"W2D1-E-03","l":5,"t":"E","st":"Error","s":3,"tags":["mistake","adverb-mismatch"],"f":"<p><i>\"The figure rose <b>dramatically</b> from 100 to 105 over the decade.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Dùng \"dramatically\" (tăng mạnh &gt;50%) nhưng thực tế chỉ tăng 5% → adverb KHÔNG match data.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The figure rose <b>slightly</b> from 100 to 105 over the decade.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Adverb phải MATCH mức thay đổi thực tế: &lt;10% = slightly/marginally, 20-50% = significantly, &gt;50% = dramatically.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + LR</p></div>","p":0},{"id":"W2D1-E-04","l":5,"t":"E","st":"Error","s":2,"tags":["mistake","listing"],"f":"<p><i>\"In 2010, it was 200. In 2012, it was 250. In 2014, it was 300. In 2016, it was 380. In 2018, it was 450.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Liệt kê TỪNG NĂM rời rạc, không mô tả trend tổng thể → Band 5 style, thiếu CC.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The figure <b>rose steadily</b> from 200 in 2010 to 450 by 2018, with the <b>most notable increase</b> occurring in the latter half of the period.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>KHÔNG liệt kê từng năm. Chọn 3-4 milestones (đầu, giữa, cuối, peak/low) + mô tả TREND giữa các mốc.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC + TA</p></div>","p":0},{"id":"W2D2-S-01","l":6,"t":"S","st":"Structure","s":3,"tags":["formula","contrast-connectors"],"f":"<p>Phân biệt vị trí của <b>while</b> vs <b>whereas</b> vs <b>in contrast</b> trong câu?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>While:</b> ĐẦU hoặc GIỮA câu → nối 2 mệnh đề TRONG 1 câu</li></ul><p>→ \"<b>While</b> A rose to 60%, B fell to 20%.\"</p><ul><li><b>Whereas:</b> CHỈ GIỮA câu → nối 2 mệnh đề TRONG 1 câu</li></ul><p>→ \"A rose to 60%, <b>whereas</b> B fell to 20%.\"</p><ul><li><b>In contrast:</b> ĐẦU CÂU MỚI → 2 câu riêng biệt</li></ul><p>→ \"A rose to 60%. <b>In contrast,</b> B fell to 20%.\"</p><ul><li>Band 7: xen kẽ cả 3 loại, KHÔNG chỉ dùng 1 loại</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"While housing dominated in Country A, the reverse was true for food, whereas transport was broadly similar.\"</p></div>","p":1},{"id":"W2D2-S-02","l":6,"t":"S","st":"Structure","s":3,"tags":["formula","grouping-strategy"],"f":"<p>Quy trình nhóm dữ liệu (grouping strategy) trước khi viết bar chart gồm mấy bước?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Nhìn data</b> → tìm pattern: categories nào giống nhau? Cái nào nổi bật?</li><li><b>Chia 2 nhóm</b> → Nhóm cao vs Nhóm thấp, hoặc Nhóm tăng vs Nhóm giảm</li><li><b>Body 1</b> = Nhóm nổi bật nhất (thường bắt đầu từ nhóm cao)</li><li><b>Body 2</b> = Nhóm còn lại + contrast với nhóm 1</li></ol><ul><li>⚠️ Nhóm phải có logic — không random</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Data: Housing 35%, Food 25%, Transport 20%, Entertainment 8% → Nhóm 1 (Housing+Food = chênh lệch rõ), Nhóm 2 (Transport+Entertainment = ít chênh lệch)</p></div>","p":1},{"id":"W2D2-S-03","l":6,"t":"S","st":"Structure","s":2,"tags":["formula","comparative"],"f":"<p>3 dạng so sánh chính trong bar chart là gì? Mỗi dạng cho 1 ví dụ.</p>","a":"","b":"<div class=\"sec\"><ol><li><b>So sánh hơn (2 items):</b> X was higher/lower than Y</li></ol><p>→ \"Country A <b>exceeded</b> Country B by 15 percentage points.\"</p><ol><li><b>So sánh nhất (3+ items):</b> X had the highest/lowest</li></ol><p>→ \"France <b>was by far the most visited</b> destination.\"</p><ol><li><b>So sánh bội số:</b> X was twice/three times as high as Y</li></ol><p>→ \"Spending on housing was <b>nearly double</b> that of food.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Bài tốt dùng cả 3 dạng trong 2 body paragraphs.</p></div>","p":1},{"id":"W2D2-S-04","l":6,"t":"S","st":"Structure","s":2,"tags":["formula","approximation"],"f":"<p>Khi nào DÙNG và khi nào KHÔNG DÙNG approximation (approximately, roughly, nearly)?</p>","a":"","b":"<div class=\"sec\"><ul><li class=\"good\">✅ <b>DÙNG khi:</b><div>Số lẻ/khó nhớ: 47.3% → \"nearly half\"</div><div>Số xấp xỉ: 198 → \"approximately 200\"</div><div>Muốn tự nhiên hơn: \"around 30%\"</div></li><li class=\"bad\">❌ <b>KHÔNG DÙNG khi:</b><div>Số tròn rõ ràng: 50%, 100, 200 → ghi chính xác</div><div>Đang nhấn mạnh exact figure: \"peaked at exactly 500\"</div></li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"47% of respondents...\" → \"<b>Nearly half</b> of respondents...\" ✅</p></div>","p":1},{"id":"W2D2-P-01","l":6,"t":"P","st":"Phrase","s":3,"tags":["multiplier","task1-body"],"f":"<p>Housing costs in City A were ______ ______ ______ ______ (gần gấp đôi) the figure for City B.</p>","a":"<b>nearly double</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The number of graduates in 2020 was nearly double that of the previous decade.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"almost twice as high as\" | \"close to double\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — khi 1 số liệu gấp ~2 lần số khác (1.7x–2.3x). Tự nhiên hơn \"two times more than\"</p></div>","p":1},{"id":"W2D2-P-02","l":6,"t":"P","st":"Phrase","s":2,"tags":["multiplier","task1-body"],"f":"<p>City X residents spent ______ ______ ______ ______ ______ (gấp 4 lần thời gian) commuting as their City Y counterparts.</p>","a":"<b>four times as long</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The US consumed approximately three times as much energy as Japan in 2019.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"quadruple the amount\" | \"four times more than\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — khi chênh lệch bội số rõ ràng (3x, 4x, 5x). Cấu trúc: X times as [adj] as Y</p></div>","p":1},{"id":"W2D2-P-03","l":6,"t":"P","st":"Phrase","s":2,"tags":["comparative","task1-body"],"f":"<p>France attracted 85 million tourists — ______ ______ ______ (nhiều hơn đáng kể) Spain's 68 million.</p>","a":"<b>significantly more than</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Government spending on healthcare was significantly more than the budget allocated to defence.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"considerably higher than\" | \"substantially greater than\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — so sánh 2 data points khi chênh lệch lớn nhưng không rõ bội số</p></div>","p":1},{"id":"W2D2-P-04","l":6,"t":"P","st":"Phrase","s":3,"tags":["contrast","task1-body"],"f":"<p>Country A allocated a larger share to housing. ______ ______ ______ ______ (ngược lại) for food, where Country B spent more.</p>","a":"<b>The reverse was true</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Men outnumbered women in engineering, but the reverse was true in nursing.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"the opposite was the case\" | \"the pattern was reversed\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — khi 2 categories có pattern NGƯỢC nhau giữa 2 nhóm. Rất tự nhiên + Band 7</p></div>","p":1},{"id":"W2D2-P-05","l":6,"t":"P","st":"Phrase","s":2,"tags":["grouping","task1-body"],"f":"<p>Transport expenditure was ______ ______ (gần tương tự) in both nations, standing at roughly 20% and 22% respectively.</p>","a":"<b>broadly similar</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The educational attainment levels were broadly similar across all three regions.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"roughly comparable\" | \"almost identical\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — khi 2+ data points gần bằng nhau → nhóm lại thay vì mô tả từng cái</p></div>","p":1},{"id":"W2D2-P-06","l":6,"t":"P","st":"Phrase","s":2,"tags":["approximation","task1-body"],"f":"<p>The difference between the two cities was ______ ______ ______ (sự chênh lệch không đáng kể) of just two percentage points.</p>","a":"<b>a negligible difference</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"There was a negligible difference in performance between the two groups.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"a marginal gap\" | \"a minimal disparity\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — khi 2 số gần bằng nhau, muốn nhấn mạnh chênh lệch KHÔNG đáng kể</p></div>","p":1},{"id":"W2D2-E-01","l":6,"t":"E","st":"Error","s":3,"tags":["mistake","listing"],"f":"<p><i>\"Country A was 35%. Country B was 18%. Country C was 25%. Country D was 22%.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Liệt kê TỪNG category 1 câu riêng, không nhóm, không so sánh → Band 5 style, thiếu CC + TA.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Countries C and D fell within a narrow range of 22%–25%, while Country A dominated at 35% — nearly double the figure for Country B (18%).\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>LUÔN nhóm data trước khi viết. Chia categories thành 2 nhóm (cao/thấp hoặc giống/khác) → viết 2 body paragraphs.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC + TA</p></div>","p":0},{"id":"W2D2-E-02","l":6,"t":"E","st":"Error","s":3,"tags":["mistake","multiplier"],"f":"<p><i>\"Housing spending in Country A (35%) was <b>three times higher than</b> Country B (18%).\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>35% ÷ 18% ≈ 1.9x → gấp ~2 lần, KHÔNG PHẢI 3 lần. Multiplier tính sai = mất điểm TA (inaccurate data).</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Housing spending in Country A (35%) was <b>nearly double</b> the figure for Country B (18%).\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>LUÔN tính bội số trước khi viết multiplier. Sai bội số = sai data = mất điểm TA nghiêm trọng.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA</p></div>","p":0},{"id":"W2D2-E-03","l":6,"t":"E","st":"Error","s":3,"tags":["mistake","contrast-connector"],"f":"<p><i>\"Country A spent 35% on housing. <b>While</b>, Country B only spent 18%.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"While\" nối 2 mệnh đề TRONG 1 câu, không đứng đầu câu mới với dấu chấm trước. Dùng sai = GRA error.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"<b>While</b> Country A spent 35% on housing, Country B only allocated 18%.\" (1 câu) HOẶC \"Country A spent 35% on housing. <b>In contrast,</b> Country B only spent 18%.\" (2 câu)</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>while/whereas = nối trong 1 câu (phẩy, không chấm). In contrast = đầu câu mới (chấm trước). Đừng nhầm.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA + CC</p></div>","p":0},{"id":"W2D2-E-04","l":6,"t":"E","st":"Error","s":2,"tags":["mistake","approximation"],"f":"<p><i>\"47% of people chose public transport, which is <b>around a third</b> of the total.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>47% ≈ \"nearly half\" (gần 50%), KHÔNG PHẢI \"around a third\" (≈33%). Approximation sai = inaccurate data.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"47% of people chose public transport, representing <b>nearly half</b> of the total.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Approximation phải HỢP LÝ: ~25%=a quarter, ~33%=a third, ~50%=nearly half, ~66%=two-thirds. Sai fraction = sai data.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + LR</p></div>","p":0},{"id":"W2D3-S-01","l":7,"t":"S","st":"Structure","s":3,"tags":["formula","sentence-structure"],"f":"<p>3 cấu trúc câu chính để mô tả proportions trong pie chart là gì?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>X + proportion verb + Y%:</b> \"Food <b>accounted for</b> 35% of spending.\"</li><li><b>Y% of total + was/went to + X:</b> \"Approximately <b>a third</b> of the budget <b>was allocated to</b> education.\"</li><li><b>X was... at Y%, with... expansion:</b> \"Food was the largest at 35%, <b>with housing making up</b> a further 25%.\"</li></ol><ul><li>Phải dùng CẢ 3 → GRA variety. Chỉ dùng cấu trúc 1 suốt bài = mất điểm GRA.</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Body paragraph tốt: 2 câu cấu trúc 1 + 1 câu cấu trúc 2 + 1 câu cấu trúc 3 = variety ✅</p></div>","p":1},{"id":"W2D3-S-02","l":7,"t":"S","st":"Structure","s":3,"tags":["vocabulary","proportion-verbs"],"f":"<p>Kể 5 proportion verbs/phrases thay thế \"was X%\"? Xếp theo mức formal.</p>","a":"","b":"<div class=\"sec\"><ul><li><b>accounted for</b> — phổ biến nhất, mọi mức %</li><li><b>made up</b> — tự nhiên, hơi informal hơn</li><li><b>comprised</b> — formal, hay dùng trong academic writing</li><li><b>represented</b> — neutral, dùng tốt với superlative</li><li><b>constituted</b> — formal nhất, dùng 1-2 lần/bài</li><li>Dùng ít nhất <b>3 verbs khác nhau</b> trong 1 bài Task 1</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Food <b>accounted for</b> 35%, while housing <b>comprised</b> a quarter. Healthcare <b>represented</b> the smallest share.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Nhớ \"AM-CRC\": Accounted for, Made up, Comprised, Represented, Constituted</p></div>","p":1},{"id":"W2D3-S-03","l":7,"t":"S","st":"Structure","s":2,"tags":["vocabulary","fractions"],"f":"<p>Chuyển đổi % sang fraction: ~25% = ? / ~33% = ? / ~50% = ? / ~67% = ? / ~75% = ?</p>","a":"","b":"<div class=\"sec\"><ul><li>~20% = <b>a fifth / one-fifth</b></li><li>~25% = <b>a quarter</b></li><li>~33% = <b>a third</b></li><li>~40% = <b>two-fifths</b></li><li>~50% = <b>half</b></li><li>~67% = <b>two-thirds</b></li><li>~75% = <b>three-quarters</b></li><li>Dùng hedging: \"<b>roughly</b> a quarter\" khi % không chính xác</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>24% → \"roughly <b>a quarter</b>\" ✅ / 37% → dùng \"37%\" (không ép thành fraction) ✅</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Chỉ dùng fraction khi % GẦN ĐÚNG. Xen kẽ fraction + % → Band 7 LR</p></div>","p":1},{"id":"W2D3-S-04","l":7,"t":"S","st":"Structure","s":2,"tags":["strategy","pie-chart"],"f":"<p>Single pie chart vs 2 pie charts: chiến lược chia body paragraphs khác nhau thế nào?</p>","a":"","b":"<div class=\"sec\"><p><b>1 pie chart</b> → nhóm theo SIZE:</p><ul><li>Body 1: Categories LỚN (&gt;20%) → mô tả chi tiết</li><li>Body 2: Categories NHỎ (&lt;20%) → mô tả tóm tắt</li></ul><p><b>2+ pie charts</b> → nhóm theo CHANGE:</p><ul><li>Body 1: Categories TĂNG (so sánh giữa charts)</li><li>Body 2: Categories GIẢM hoặc ỔN ĐỊNH</li><li class=\"good\">✅ Dùng trend language W2D1 + comparative W2D2</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>2 pie charts (2000 vs 2020): Body 1 — \"Renewables surged from 8% to 25%...\" Body 2 — \"Oil declined from 42% to 28%...\"</p></div>","p":1},{"id":"W2D3-S-05","l":7,"t":"S","st":"Structure","s":2,"tags":["vocabulary","majority-minority"],"f":"<p>Majority/minority language: 5 mức từ LỚN → NHỎ? Mỗi mức dùng cho % nào?</p>","a":"","b":"<div class=\"sec\"><ol><li>🔴 <b>&gt;60%:</b> the vast majority of, the overwhelming majority</li><li>🟠 <b>40-60%:</b> the majority of, a significant proportion of</li><li>🟡 <b>20-40%:</b> a considerable share, a notable proportion</li><li>🟢 <b>10-20%:</b> a relatively small proportion, a minor share</li><li>⚪ <b>&lt;10%:</b> a negligible proportion, a mere X%, a tiny fraction</li></ol><ul><li>⚠️ \"the majority\" = &gt;50%. KHÔNG dùng cho 30%!</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>65% → \"the vast majority\" ✅ / 30% → \"a considerable share\" ✅ / 3% → \"a mere 3%\" ✅</p></div>","p":1},{"id":"W2D3-P-01","l":7,"t":"P","st":"Phrase","s":3,"tags":["proportion-verb","task1-body"],"f":"<p>Food ______ ______ (chiếm) 35% of total household expenditure in 2022.</p>","a":"<b>accounted for</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Tourism accounted for approximately a quarter of the country's GDP.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"made up\" | \"represented\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — khi mô tả tỉ lệ % của 1 category trong pie chart. Phổ biến nhất, dùng cho mọi mức %</p></div>","p":1},{"id":"W2D3-P-02","l":7,"t":"P","st":"Phrase","s":2,"tags":["proportion-verb","task1-body"],"f":"<p>Transport ______ (cấu thành / chiếm) approximately 20% of the national budget.</p>","a":"<b>comprised</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Renewable energy comprised a mere 8% of total consumption in 2000.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"constituted\" | \"represented\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — thay thế \"accounted for\" để tạo LR variety. Formal hơn, phù hợp academic writing</p></div>","p":1},{"id":"W2D3-P-03","l":7,"t":"P","st":"Phrase","s":3,"tags":["fraction","task1-body"],"f":"<p>Education represented ______ ______ ______ (khoảng 1/3) of the government's total spending.</p>","a":"<b>roughly a third</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Nearly a third of respondents said they preferred working from home.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"approximately one-third\" | \"about 33%\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — dùng fraction thay % khi con số gần đúng (~33%). Xen kẽ fraction + % trong bài → Band 7 LR</p></div>","p":1},{"id":"W2D3-P-04","l":7,"t":"P","st":"Phrase","s":2,"tags":["majority-minority","task1-body"],"f":"<p>A ______ ______ (tỉ lệ không đáng kể) of the budget was allocated to entertainment, at just 3%.</p>","a":"<b>negligible proportion</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Nuclear energy constituted a negligible proportion of the energy mix at only 2%.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"a mere 3%\" | \"a tiny fraction\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — khi category chiếm &lt;10%. KHÔNG dùng cho category &gt;10%</p></div>","p":1},{"id":"W2D3-P-05","l":7,"t":"P","st":"Phrase","s":2,"tags":["ranking","task1-body"],"f":"<p>Food was the largest expense, ______ ______ (tiếp theo là) housing at 25%.</p>","a":"<b>followed by</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"China had the highest carbon emissions, followed by the United States and India.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"with housing in second place at 25%\" | \"while housing ranked second at 25%\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — khi xếp hạng categories từ lớn → nhỏ. Giúp nối các data points tự nhiên</p></div>","p":1},{"id":"W2D3-P-06","l":7,"t":"P","st":"Phrase","s":2,"tags":["grouping","task1-body"],"f":"<p>Housing and transport ______ (kết hợp lại) accounted for 45% of all spending.</p>","a":"<b>combined</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The three smallest categories combined represented less than a fifth of total revenue.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"together\" | \"collectively\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — nhóm 2+ categories lại để cho insight tổng thể → TA cao hơn vì phân tích thay vì chỉ liệt kê</p></div>","p":1},{"id":"W2D3-E-01","l":7,"t":"E","st":"Error","s":3,"tags":["mistake","repetition"],"f":"<p><i>\"Food was 35%. Housing was 25%. Transport was 20%. Education was 12%.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Lặp cấu trúc \"X was Y%\" 4 lần → LR cực thấp, Band 5 cách viết. Chỉ liệt kê, không phân tích.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Food <b>accounted for</b> the largest share at 35%, <b>followed by</b> housing, <b>which comprised</b> roughly <b>a quarter</b> of expenditure. Transport and education <b>made up</b> a further 32% <b>combined</b>.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>KHÔNG lặp \"was X%\" quá 1 lần. Dùng ít nhất 3 proportion verbs khác nhau + fractions + grouping.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR + CC</p></div>","p":0},{"id":"W2D3-E-02","l":7,"t":"E","st":"Error","s":3,"tags":["mistake","majority-misuse"],"f":"<p><i>\"The majority of spending went to food, at 30%.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"The majority\" nghĩa là &gt;50%, nhưng 30% KHÔNG phải majority → dùng sai vocabulary, mất accuracy.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"<b>A considerable share</b> of spending went to food, at 30%.\" hoặc \"Food <b>accounted for a notable proportion</b> at 30%.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>\"the majority\" = &gt;50%. 30-50% = \"a significant proportion\". 20-30% = \"a considerable share\". Chọn đúng mức!</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR + TA</p></div>","p":0},{"id":"W2D3-E-03","l":7,"t":"E","st":"Error","s":3,"tags":["mistake","fraction-mismatch"],"f":"<p><i>\"Healthcare represented roughly a quarter of the budget, at 17%.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"a quarter\" = 25%, nhưng 17% quá khác 25% → fraction KHÔNG match data. Người đọc sẽ confuse.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Healthcare represented <b>approximately a fifth</b> of the budget, at 17%.\" hoặc chỉ dùng \"17%\".</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Chỉ dùng fraction khi % GẦN ĐÚNG (±3-5%): 24% ≈ \"a quarter\" ✅, 17% ≈ \"a quarter\" ❌. Nếu không khớp → dùng % trực tiếp.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + LR</p></div>","p":0},{"id":"W2D3-E-04","l":7,"t":"E","st":"Error","s":2,"tags":["mistake","grammar"],"f":"<p><i>\"Food was the largest category, with food was 35% of spending.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Sau \"with\" phải dùng V-ing (participle), KHÔNG dùng \"was\" (finite verb). \"with X was\" ❌ grammar.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Food was the largest category, <b>with food representing</b> 35% of spending.\" hoặc \"..., <b>with 35% going to</b> food.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Cấu trúc \"with\" expansion: with + noun + V-ing. KHÔNG PHẢI with + noun + was/is. VD: \"with food <b>being</b>\" ✅, \"with food <b>was</b>\" ❌.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA</p></div>","p":0},{"id":"W2D4-S-01","l":8,"t":"S","st":"Structure","s":3,"tags":["formula","task1-structure"],"f":"<p>Complete Task 1 gồm mấy đoạn? Tên + word count mỗi đoạn?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Introduction</b> (25-35 từ) — 1 câu paraphrase đề</li><li><b>Overview</b> (35-45 từ) — 2-3 câu, \"Overall, ...\" + overall trends</li><li><b>Body 1</b> (45-55 từ) — Nhóm 1: data + số liệu + so sánh</li><li><b>Body 2</b> (45-55 từ) — Nhóm 2: data + số liệu + so sánh</li></ol><ul><li>Tổng: <b>150-190 từ</b>. KHÔNG có Conclusion.</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Intro (1 câu) → \"Overall, all five nations saw a decrease...\" → Body 1 (snapshot 1998) → Body 2 (changes by 2008)</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"I-O-B-B\" = Intro, Overview, Body, Body. Nhớ: Task 1 KHÔNG BAO GIỜ có Conclusion.</p></div>","p":1},{"id":"W2D4-S-02","l":8,"t":"S","st":"Structure","s":3,"tags":["overview","task1"],"f":"<p>Overview trong Task 1 phải tuân theo 2 quy tắc quan trọng nhất là gì?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>KHÔNG có số liệu cụ thể</b> — chỉ viết overall trends/patterns (VD: \"all countries saw a decrease\" ✅, \"France dropped from 30% to 25%\" ❌)</li><li><b>BẮT BUỘC phải có</b> — thiếu Overview = mất 1 band TA. Luôn bắt đầu bằng \"Overall, ...\"</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Overall, <b>all five nations</b> saw a decrease in spending. Spain <b>consistently devoted the highest share</b>, while Sweden <b>spent the least</b>.\"</p></div>","p":1},{"id":"W2D4-S-03","l":8,"t":"S","st":"Structure","s":3,"tags":["grouping","task1-body"],"f":"<p>3 cách nhóm data trong table là gì? Khi nào dùng cách nào?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Row-based</b> — mỗi hàng là 1 category có pattern riêng → Body 1: top rows, Body 2: bottom rows</li><li><b>Column-based</b> — mỗi cột là 1 time period → Body 1: giai đoạn 1, Body 2: giai đoạn 2</li><li><b>Pattern-based</b> (HAY DÙNG NHẤT) — chia data thành 2 nhóm theo pattern → Body 1: nhóm tăng, Body 2: nhóm giảm</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Table du khách 4 nước: France/Spain/Thailand (tăng) → Body 1; Egypt (giảm rồi hồi) → Body 2 = pattern-based ✅</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Luôn thử pattern-based trước. Hỏi: \"Data chia thành 2 nhóm rõ ràng không?\" — CÓ → pattern-based.</p></div>","p":1},{"id":"W2D4-S-04","l":8,"t":"S","st":"Structure","s":2,"tags":["key-features","task-achievement"],"f":"<p>5 tiêu chí chọn key features khi viết Task 1 là gì?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Highest</b> — số cao nhất</li><li><b>Lowest</b> — số thấp nhất</li><li><b>Biggest change</b> — thay đổi lớn nhất qua thời gian</li><li><b>Notable exception</b> — dữ liệu khác pattern chung</li><li><b>Overall patterns</b> — xu hướng chung</li></ol><ul><li>Chọn <b>5-6 data points</b>, KHÔNG liệt kê tất cả. Mỗi category mention ít nhất 1 lần.</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Table 5 nước → chọn: highest (Spain 35%), lowest (Sweden 18%), biggest fall (Spain -7), smallest fall (Sweden -5), overall (all decreased)</p></div>","p":1},{"id":"W2D4-S-05","l":8,"t":"S","st":"Structure","s":2,"tags":["time-management","task1"],"f":"<p>Phân bổ 20 phút cho Task 1 như thế nào?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Plan:</b> 3 phút — đọc đề, xác định pattern, đánh dấu key features</li><li><b>Intro + Overview:</b> 3 phút — 1 câu paraphrase + 2-3 câu overall</li><li><b>Body 1:</b> 6 phút — nhóm 1, 3-4 câu, ~50 từ</li><li><b>Body 2:</b> 6 phút — nhóm 2, 3-4 câu, ~50 từ</li><li><b>Check:</b> 2 phút — đếm từ (≥150?), có Overview?, spelling</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>0:00-3:00 Plan → 3:00-6:00 Intro+Overview → 6:00-12:00 Body 1 → 12:00-18:00 Body 2 → 18:00-20:00 Check</p></div>","p":1},{"id":"W2D4-P-01","l":8,"t":"P","st":"Phrase","s":2,"tags":["paraphrase","introduction","task1"],"f":"<p>The table ______ ______ ______ ______ (so sánh tỉ lệ) household income spent on food in five countries.</p>","a":"<b>compares the proportion of</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The chart compares the proportion of electricity generated from renewable sources in four nations.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"illustrates the percentage of\" | \"provides data on the share of\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Introduction — paraphrase \"shows the percentage of\" thành cụm tự nhiên hơn</p></div>","p":1},{"id":"W2D4-P-02","l":8,"t":"P","st":"Phrase","s":2,"tags":["paraphrase","introduction","task1"],"f":"<p>The table compares household income ______ ______ (được phân bổ cho) food and drink over a ten-year period.</p>","a":"<b>allocated to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"A significant portion of the national budget was allocated to infrastructure development.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"spent on\" | \"devoted to\" | \"directed towards\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Introduction — paraphrase \"spent on\" khi viết về chi tiêu, ngân sách</p></div>","p":1},{"id":"W2D4-P-03","l":8,"t":"P","st":"Phrase","s":2,"tags":["ranking","task1-body"],"f":"<p>Spain had the highest figure at 35%, ______ ______ ______ (theo sát bởi) France at 30%.</p>","a":"<b>followed closely by</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The USA had the largest number of visitors, followed closely by France and Spain.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"with France close behind at\" | \"trailed by France at\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — xếp hạng 2+ categories liên tiếp, cái thứ 2 gần sát cái thứ 1</p></div>","p":1},{"id":"W2D4-P-04","l":8,"t":"P","st":"Phrase","s":2,"tags":["comparison","task1-body"],"f":"<p>Germany and the UK allocated ______ ______ ______ (tỉ lệ gần tương tự) — 24% and 22% respectively.</p>","a":"<b>roughly similar proportions</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Men and women devoted roughly similar proportions of their income to entertainment.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"comparable shares\" | \"almost identical percentages\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — khi 2+ categories có số liệu gần giống nhau</p></div>","p":1},{"id":"W2D4-P-05","l":8,"t":"P","st":"Phrase","s":2,"tags":["trend","task1-body"],"f":"<p>Spain ______ ______ ______ ______ (tiếp tục giữ vị trí cao nhất) with 28% in 2008.</p>","a":"<b>remained at the top</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Despite a slight decrease, Japan remained at the top with the highest literacy rate.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"continued to lead\" | \"still ranked first\" | \"maintained its position as the highest\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — khi category giữ vị trí #1 qua nhiều thời kỳ dù số thay đổi</p></div>","p":1},{"id":"W2D4-P-06","l":8,"t":"P","st":"Phrase","s":3,"tags":["multiplier","task1-body"],"f":"<p>Engineering enrolment surged from 8,000 to 22,000, representing ______ ______ ______ (sự tăng gần gấp ba).</p>","a":"<b>a nearly threefold increase</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The country witnessed a nearly threefold increase in solar panel installations over the decade.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"almost tripling\" | \"increasing by approximately three times\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body — khi data tăng ~3 lần. Dùng \"twofold\" (×2), \"threefold\" (×3), \"fourfold\" (×4)</p></div>","p":1},{"id":"W2D4-E-01","l":8,"t":"E","st":"Error","s":3,"tags":["mistake","no-overview"],"f":"<p><i>\"The table shows spending in five countries. The UK spent 22% in 1998. France spent 30%. Germany spent 24%...\"</i> (bài viết đi thẳng vào số liệu sau Introduction) — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Không có đoạn Overview → nhảy thẳng từ Intro vào Body. Thiếu Overview = mất 1 band TA.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The table shows... <b>Overall, all five countries experienced a decline in food spending, with Spain consistently devoting the highest proportion.</b> In 1998, the UK spent 22%...\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Đoạn 2 LUÔN là Overview (bắt đầu bằng \"Overall, ...\"). Không bao giờ nhảy thẳng vào số liệu sau Introduction.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA (-1 band)</p></div>","p":0},{"id":"W2D4-E-02","l":8,"t":"E","st":"Error","s":3,"tags":["mistake","listing-data"],"f":"<p><i>\"The UK was 22%. France was 30%. Germany was 24%. Spain was 35%. Sweden was 18%.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Liệt kê TỪNG country + số liệu riêng lẻ, không nhóm, không so sánh → Band 5 style.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Spain had the highest figure at 35%, <b>followed closely by</b> France at 30%. Germany and the UK allocated <b>roughly similar proportions</b> — 24% and 22% respectively — <b>while</b> Sweden spent the least at just 18%.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>KHÔNG liệt kê. Nhóm data + so sánh (comparative, while/whereas, ranking language). 1 câu cover 2-3 categories.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC + LR</p></div>","p":0},{"id":"W2D4-E-03","l":8,"t":"E","st":"Error","s":3,"tags":["mistake","overview-numbers"],"f":"<p><i>\"Overall, the UK decreased from 22% to 17%, France decreased from 30% to 25%, and Spain decreased from 35% to 28%.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Overview chứa số liệu CỤ THỂ (22%, 17%, 30%...). Overview chỉ nêu xu hướng tổng quát, KHÔNG có số.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Overall, <b>all five nations</b> saw a decrease in the percentage of income spent on food. Spain <b>consistently devoted the highest share</b>, while Sweden <b>spent the least</b> in both years.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Overview = overall patterns ONLY. Để số liệu cụ thể cho Body paragraphs. Overview có số = mất điểm TA.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA</p></div>","p":0},{"id":"W2D4-E-04","l":8,"t":"E","st":"Error","s":2,"tags":["mistake","opinion-task1"],"f":"<p><i>\"In conclusion, I think Spain should reduce its spending on food because 35% is too high compared to other countries.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>(1) Có Conclusion — Task 1 KHÔNG cần kết luận. (2) Có opinion \"I think\" — Task 1 KHÔNG BAO GIỜ có ý kiến cá nhân. (3) Đưa ra recommendation \"should reduce\" — không phải việc của Task 1.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>KHÔNG viết đoạn này. Task 1 kết thúc sau Body 2. Chỉ mô tả data, KHÔNG đánh giá hay đề xuất.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Task 1 = MÔ TẢ data khách quan. KHÔNG có: Conclusion, opinion (I think), recommendation (should), evaluation (too high/too low).</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA (-1 band)</p></div>","p":0},{"id":"W3D1-S-01","l":9,"t":"S","st":"Structure","s":3,"tags":["formula","body-paragraph","tees"],"f":"<p>TEES paragraph structure gồm mấy phần? Kể tên + vai trò từng phần.</p>","a":"","b":"<div class=\"sec\"><ul><li><b>T</b> — Topic sentence (1 câu): nêu main idea + hướng lập luận</li><li><b>E</b> — Explanation (1-2 câu): giải thích tại sao / thế nào</li><li><b>E</b> — Example (1-2 câu): ví dụ cụ thể có tên riêng + kết quả</li><li><b>S</b> — Summary (1 câu): kết nối lại topic + chuyển ý</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>T: \"Technology has simplified communication.\" → E1: \"This is because...\" → E2: \"For instance, WhatsApp has...\" → S: \"It is therefore clear that...\"</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"1 paragraph = 1 idea. TEES = bắt buộc. Target 4-6 câu, 80-100 từ.\"</p></div>","p":1},{"id":"W3D1-S-02","l":9,"t":"S","st":"Structure","s":3,"tags":["formula","topic-sentence"],"f":"<p>Công thức viết Topic Sentence cho body paragraph Task 2?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>[Linking phrase]</b> (nếu Body 2+) + <b>[Main idea]</b> + <b>[Direction/Stance]</b></li><li>Linking: \"On the other hand,\" / \"Furthermore,\"</li><li>Main idea: ý chính của paragraph</li><li>Direction: đồng ý / phản đối / hướng lập luận</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"On the other hand, <b>excessive reliance</b> on technology can <b>undermine</b> traditional learning skills.\"</p></div>","p":1},{"id":"W3D1-S-03","l":9,"t":"S","st":"Structure","s":2,"tags":["formula","explanation"],"f":"<p>Kể 4 cụm mở đầu Explanation sentence trong TEES (E1).</p>","a":"","b":"<div class=\"sec\"><ol><li>\"<b>This is because...</b>\" (phổ biến nhất)</li><li>\"<b>The primary reason for this is that...</b>\"</li><li>\"<b>This can be attributed to...</b>\"</li><li>\"<b>This happens when...</b>\" / \"<b>This works by...</b>\"</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"The primary reason for this is that digital tools enable personalised learning.\"</p></div>","p":1},{"id":"W3D1-S-04","l":9,"t":"S","st":"Structure","s":2,"tags":["formula","summary"],"f":"<p>3 loại Summary sentence (S trong TEES)? Body 1 nên dùng loại nào?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Restate</b> — nói lại main idea khác cách: \"Therefore, it is evident that...\"</li><li><b>So what?</b> — tại sao quan trọng: \"As a result, students are better equipped...\"</li><li><b>Bridge</b> — chuyển ý sang Body 2: \"However, this is not without drawbacks.\"</li></ol><ul><li>Body 1 → dùng <b>Bridge</b> (chuyển ý tự nhiên)</li><li>Body 2 → dùng <b>Restate</b> hoặc <b>So what?</b> (kết sạch)</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Bridge: \"...technology has made connecting easier; <b>however, this convenience also comes with its own set of challenges.</b>\"</p></div>","p":1},{"id":"W3D1-S-05","l":9,"t":"S","st":"Structure","s":2,"tags":["rule","body-paragraph"],"f":"<p>Sự khác biệt chính giữa body paragraph Band 5 và Band 7?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Band 5:</b> 3-4 ý liệt kê, KHÔNG phát triển (40-50 từ)</li></ul><p>→ \"Technology is good. It helps people. It saves time.\"</p><ul><li><b>Band 7:</b> <b>1 ý</b> phát triển sâu theo TEES (80-100 từ)</li></ul><p>→ T + E (giải thích) + E (ví dụ cụ thể) + S (kết luận)</p></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Band 5: 4 câu × 4 ý khác nhau → CC thấp. Band 7: 4-6 câu × 1 ý sâu → CC cao.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Nhiều ý = Band 5. Một ý sâu = Band 7.\"</p></div>","p":1},{"id":"W3D1-P-01","l":9,"t":"P","st":"Phrase","s":2,"tags":["collocation","body-paragraph"],"f":"<p>Social media can have a ______ (tác hại sâu sắc) effect on young people's mental health.</p>","a":"<b>profoundly detrimental</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Air pollution has had a profoundly detrimental impact on public health in major cities.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"severely negative\" | \"deeply harmful\" | \"significantly damaging\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về tác động tiêu cực của 1 hiện tượng (health, environment, society)</p></div>","p":1},{"id":"W3D1-P-02","l":9,"t":"P","st":"Phrase","s":3,"tags":["collocation","example"],"f":"<p>International video calls would have been ______ (đắt đến mức không thể) just two decades ago.</p>","a":"<b>prohibitively expensive</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Higher education in many countries remains prohibitively expensive for low-income families.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"unaffordably costly\" | \"beyond the financial reach of most people\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph (Example/Explanation) — khi nói về chi phí là rào cản, so sánh quá khứ vs hiện tại</p></div>","p":1},{"id":"W3D1-P-03","l":9,"t":"P","st":"Phrase","s":2,"tags":["collocation","summary"],"f":"<p>______ (do đó, rõ ràng là) technology plays a crucial role in modern education.</p>","a":"<b>It is therefore clear that</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"It is therefore clear that stricter regulations are needed to reduce carbon emissions.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"It is therefore evident that\" | \"This clearly demonstrates that\" | \"It is thus apparent that\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Summary sentence (S trong TEES) — kết luận paragraph, dạng Restate hoặc So what?</p></div>","p":1},{"id":"W3D1-P-04","l":9,"t":"P","st":"Phrase","s":2,"tags":["collocation","explanation"],"f":"<p>The rise in obesity ______ (có thể quy cho) the widespread availability of fast food.</p>","a":"<b>can be attributed to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The improvement in literacy rates can be attributed to increased government investment in education.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"is largely due to\" | \"stems from\" | \"is primarily a result of\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Explanation sentence (E1 trong TEES) — giải thích nguyên nhân</p></div>","p":1},{"id":"W3D1-P-05","l":9,"t":"P","st":"Phrase","s":2,"tags":["collocation","body-paragraph"],"f":"<p>Abolishing tuition fees could place an ______ (gánh nặng không bền vững) on government budgets.</p>","a":"<b>unsustainable burden</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Rapid urbanisation has placed an unsustainable burden on existing infrastructure.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"excessive strain\" | \"overwhelming pressure\" | \"unmanageable demand\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về hậu quả tiêu cực lên tài chính / tài nguyên</p></div>","p":1},{"id":"W3D1-E-01","l":9,"t":"E","st":"Error","s":3,"tags":["mistake","body-paragraph"],"f":"<p><i>\"Technology is good. It helps people. It saves time. It is everywhere.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>4 ý khác nhau trong 1 paragraph, không ý nào được phát triển → CC thấp.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Chọn 1 ý (ví dụ: saves time) → phát triển sâu: T (saves time) → E (because...) → E (For instance, Zoom...) → S (Therefore...).</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>1 paragraph = 1 idea. Nhiều ý = tách thành nhiều paragraphs, mỗi paragraph phát triển TEES.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC + TA</p></div>","p":0},{"id":"W3D1-E-02","l":9,"t":"E","st":"Error","s":3,"tags":["mistake","example"],"f":"<p><i>\"For example, many people use technology every day.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Ví dụ quá chung chung — không có tên cụ thể, không có kết quả → không thuyết phục.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"For instance, <b>Duolingo</b> has helped over 500 million users learn languages for free, demonstrating how technology can democratise education.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Example = [Tên cụ thể] + [has/have V-ed] + [kết quả]. Không có tên riêng = Band 5.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + LR</p></div>","p":0},{"id":"W3D1-E-03","l":9,"t":"E","st":"Error","s":3,"tags":["mistake","topic-sentence"],"f":"<p><i>\"Technology is important.\"</i> dùng làm Topic sentence — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Quá mơ hồ — examiner không biết paragraph sẽ nói gì → CC thấp. Thiếu direction/stance.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Technology has <b>revolutionised</b> access to healthcare in remote areas.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Topic sentence phải có [Main idea cụ thể] + [Direction/stance]. Examiner đọc câu đầu = biết paragraph nói gì.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC</p></div>","p":0},{"id":"W3D1-E-04","l":9,"t":"E","st":"Error","s":2,"tags":["mistake","summary"],"f":"<p><i>Một paragraph kết thúc bằng Example rồi nhảy thẳng sang paragraph mới, không có Summary.</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Paragraph bỏ lửng — không có kết luận → CC thấp. Reader không biết ý đã xong chưa.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Thêm Summary: \"Therefore, it is clear that technology has greatly improved communication.\" hoặc Bridge: \"However, this convenience also raises concerns.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Mỗi body paragraph PHẢI có Summary sentence (S trong TEES) — restate, so what, hoặc bridge.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC</p></div>","p":0},{"id":"W3D2-S-01","l":10,"t":"S","st":"Structure","s":3,"tags":["linking","framework","coherence"],"f":"<p>3 cấp linking trong IELTS Writing là gì? Band 7 cần dùng thế nào?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Cấp 1 — Trong câu:</b> relative clauses (which, where), participle clauses (-ing, -ed)</li><li><b>Cấp 2 — Giữa câu:</b> cohesive devices (Furthermore, However, Consequently)</li><li><b>Cấp 3 — Giữa đoạn:</b> transitions (On the other hand, Turning to)</li><li>Band 7 = <b>mix cả 3 cấp</b>. Band 5 = chỉ dùng cấp 2.</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>1 TEES paragraph 5 câu → 2-3 linking cấp 2, 1-2 cấp 1, 1 reference device</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Band 5 = chỉ biết Furthermore. Band 7 = Furthermore + which + this trend.\"</p></div>","p":1},{"id":"W3D2-S-02","l":10,"t":"S","st":"Structure","s":2,"tags":["linking","function-groups","vocabulary"],"f":"<p>Kể 6 nhóm chức năng linking devices. Mỗi nhóm cho 1 từ academic thay thế từ basic.</p>","a":"","b":"<div class=\"sec\"><div class=\"tw\"><table><thead><tr><th>Nhóm</th><th>Basic</th><th>Academic</th></tr></thead><tbody><tr><td>Adding</td><td>and</td><td><b>Furthermore</b></td></tr><tr><td>Contrast</td><td>but</td><td><b>However</b></td></tr><tr><td>Cause/Effect</td><td>because</td><td><b>Consequently</b></td></tr><tr><td>Example</td><td>for example</td><td><b>For instance</b></td></tr><tr><td>Concession</td><td>although</td><td><b>Despite</b></td></tr><tr><td>Sequence</td><td>first</td><td><b>To begin with</b></td></tr></tbody></table></div></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Technology helps students. Furthermore, it empowers educators.\" (Adding)</p></div>","p":1},{"id":"W3D2-S-03","l":10,"t":"S","st":"Structure","s":3,"tags":["linking","reference-device","coherence"],"f":"<p>\"this + noun summary\" là gì? Tại sao cần dùng trong IELTS Writing?</p>","a":"","b":"<div class=\"sec\"><ul><li>Thay vì lặp noun → dùng <b>this/these/such + noun tóm tắt</b></li><li>Giúp tránh lặp từ + tăng cohesion (CC Band 7)</li><li>Rule: noun chính không xuất hiện quá <b>2 lần</b> / paragraph → lần 3 dùng reference device</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Governments invest in renewable energy. <b>Such initiatives</b> demonstrate commitment to sustainability.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Noun summary phải đúng nghĩa: 'this trend' ≠ 'this problem' — chọn noun phù hợp context.\"</p></div>","p":1},{"id":"W3D2-S-04","l":10,"t":"S","st":"Structure","s":3,"tags":["linking","overuse","band-score"],"f":"<p>Tại sao dùng NHIỀU linking words vẫn bị Band 6 CC? Quy tắc linking tự nhiên là gì?</p>","a":"","b":"<div class=\"sec\"><ul><li>Band 6: <b>lạm dụng</b> — \"Furthermore,... Moreover,... In addition,...\" (mọi câu đều bắt đầu bằng linking)</li><li>Band 7: dùng <b>đúng chỗ, đúng loại</b> — 2-3 linking giữa câu / paragraph là đủ</li><li>Câu còn lại nối bằng: pronoun reference, relative clause, hoặc meaning tự nhiên</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>5 câu TEES → chỉ 2-3 câu có linking word giữa câu, câu khác dùng \"which\", \"this trend\"</p></div>","p":1},{"id":"W3D2-P-01","l":10,"t":"P","st":"Phrase","s":2,"tags":["linking","cause-effect","body-paragraph"],"f":"<p>There are compelling reasons to support this policy. ______ (lý do chính là) well-funded transport networks reduce traffic congestion.</p>","a":"<b>The primary justification is that</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The primary justification is that access to clean water directly reduces infant mortality rates.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"The primary reason for this is that\" | \"This can be attributed to the fact that\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — E1 (Explanation) trong TEES, khi giải thích nguyên nhân chính</p></div>","p":1},{"id":"W3D2-P-02","l":10,"t":"P","st":"Phrase","s":2,"tags":["linking","example","body-paragraph"],"f":"<p>Many countries have successfully reduced carbon emissions. ______ (một ví dụ điển hình là) Sweden, where renewable energy now accounts for over 50% of total consumption.</p>","a":"<b>A case in point is</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"A case in point is Singapore, where the government's substantial investment in its MRT system has resulted in one of the most efficient urban transit networks globally.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"This is exemplified by\" | \"A notable example is\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — E2 (Example) trong TEES, khi đưa ví dụ cụ thể thay vì \"For example\"</p></div>","p":1},{"id":"W3D2-P-03","l":10,"t":"P","st":"Phrase","s":3,"tags":["linking","concession","body-paragraph"],"f":"<p>______ (thừa nhận rằng), there are dissenting voices; however, the evidence overwhelmingly supports this position.</p>","a":"<b>Admittedly</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Admittedly, online education lacks face-to-face interaction; however, it provides unparalleled flexibility for working professionals.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"While it is true that...\" | \"It must be acknowledged that...\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi thừa nhận ý đối lập trước khi phản bác (concession technique)</p></div>","p":1},{"id":"W3D2-P-04","l":10,"t":"P","st":"Phrase","s":2,"tags":["linking","participle","grammar"],"f":"<p>Reliable bus and rail services decrease dependence on private vehicles, ______ (từ đó giảm) both fuel consumption and road maintenance costs.</p>","a":"<b>thereby reducing</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The new policy restricts single-use plastics, thereby reducing ocean pollution by an estimated 30%.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"thus lowering\" | \"which in turn reduces\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — nối kết quả vào cuối câu bằng participle clause (GRA Band 7)</p></div>","p":1},{"id":"W3D2-P-05","l":10,"t":"P","st":"Phrase","s":2,"tags":["linking","reference-device","coherence"],"f":"<p>Many companies now allow remote work. ______ (xu hướng này) has reduced commuting stress and improved work-life balance.</p>","a":"<b>This trend</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Governments worldwide are investing in renewable energy. This shift reflects growing awareness of climate change.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"This development\" | \"This phenomenon\" | \"Such a change\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Mọi vị trí — thay thế việc lặp noun, đặc biệt ở câu Summary (S) trong TEES</p></div>","p":1},{"id":"W3D2-P-06","l":10,"t":"P","st":"Phrase","s":2,"tags":["linking","transition","paragraph"],"f":"<p>[Kết thúc Body 1 về economic benefits] ______ (chuyển sang) the social implications, this trend has also affected community cohesion.</p>","a":"<b>Turning to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Turning to the environmental impact, deforestation has accelerated at an alarming rate over the past decade.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"With regard to\" | \"Another key consideration is\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Đầu Body 2 — linking giữa đoạn (Cấp 3), chuyển sang khía cạnh mới</p></div>","p":1},{"id":"W3D2-E-01","l":10,"t":"E","st":"Error","s":3,"tags":["mistake","linking","overuse"],"f":"<p><i>\"Furthermore, technology helps students learn. Moreover, it improves communication. In addition, it creates jobs. Additionally, it boosts the economy.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>4 câu liên tiếp đều mở đầu bằng linking word nhóm Adding → lạm dụng, đọc giả tạo, máy móc.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Technology helps students learn more effectively. Moreover, it has improved workplace communication, <b>which</b> in turn has boosted economic productivity. <b>This digital transformation</b> has also created entirely new job categories.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Không bắt đầu mọi câu bằng linking word — xen kẽ cấp 1 (which, -ing) và reference device (this + noun).</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC</p></div>","p":0},{"id":"W3D2-E-02","l":10,"t":"E","st":"Error","s":3,"tags":["mistake","fragment","grammar"],"f":"<p><i>\"Crime is increasing. Because police can't control it.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"Because...\" đứng một mình = sentence fragment (không phải câu hoàn chỉnh).</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Crime rates have risen sharply, <b>primarily due to</b> insufficient policing resources.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>\"Because\" không đứng đầu câu riêng — phải nối vào câu trước hoặc dùng \"due to / as a result of\" thay thế.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA + CC</p></div>","p":0},{"id":"W3D2-E-03","l":10,"t":"E","st":"Error","s":2,"tags":["mistake","repetition","coherence"],"f":"<p><i>\"Technology helps students. Technology also helps teachers. Technology makes life easier.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Lặp \"Technology\" 3 lần liên tiếp → thiếu cohesion, đọc rời rạc.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Technology helps students and educators alike. <b>Moreover</b>, <b>it</b> has empowered parents to monitor their children's progress <b>through</b> dedicated platforms.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Noun chính không lặp quá 2 lần / paragraph → dùng pronoun (it/they) hoặc \"this + noun summary\" (this innovation, such tools).</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC + LR</p></div>","p":0},{"id":"W3D2-E-04","l":10,"t":"E","st":"Error","s":2,"tags":["mistake","linking","contrast"],"f":"<p><i>\"Some people agree. But other people disagree.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>2 câu đơn giản + \"But\" ở đầu câu = Band 5 (thiếu sentence variety, linking quá cơ bản).</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"<b>While</b> proponents argue that this policy reduces inequality, <b>opponents contend that</b> it stifles individual freedom.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Dùng \"While/Whereas\" gộp 2 ý ngược chiều vào 1 câu → complex sentence = CC + GRA Band 7.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC + GRA</p></div>","p":0},{"id":"W3D3-S-01","l":11,"t":"S","st":"Structure","s":3,"tags":["example-types","task2"],"f":"<p>IELTS Writing có 3 loại example. Kể tên theo thứ tự ưu tiên + khi nào dùng loại nào?</p>","a":"","b":"<div class=\"sec\"><ul><li>🥇 <b>Specific / Real-world</b> (ưu tiên nhất): dùng tên cụ thể (Zoom, Singapore, WHO) → mọi loại essay</li><li>🥈 <b>Hypothetical</b>: \"If a student were to...\" → khi topic trừu tượng, không biết real example</li><li>🥉 <b>Personal experience</b>: \"In my own experience...\" → chỉ khi đề hỏi personal opinion, KHÔNG dùng cho Discussion essay</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Specific: \"For instance, <b>Zoom</b> has enabled remote teams to collaborate seamlessly across time zones.\"</p></div>","p":1},{"id":"W3D3-S-02","l":11,"t":"S","st":"Structure","s":3,"tags":["formula","example"],"f":"<p>Example Formula nâng cấp (Band 7) gồm mấy câu? Viết công thức từng câu.</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Câu 1 — Example:</b> [Signal phrase] + [Specific name] + [has/have + V-ed] + [result/impact]</li><li><b>Câu 2 — Extension:</b> [Extension phrase] + [deeper impact / so what?]</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Câu 1: \"For instance, <b>Google Classroom</b> has enabled teachers in 150+ countries to deliver lessons remotely.\" → Câu 2: \"This has subsequently <b>narrowed the educational divide</b> between urban and rural institutions.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Band 5 = 0 câu example. Band 6 = 1 câu. Band 7 = 2 câu (example + extension).\"</p></div>","p":1},{"id":"W3D3-S-03","l":11,"t":"S","st":"Structure","s":3,"tags":["tees","example-position"],"f":"<p>Trong TEES paragraph, example nằm ở vị trí nào? Example phải thoả điều kiện gì?</p>","a":"","b":"<div class=\"sec\"><ul><li>Vị trí: <b>E2</b> — sau Explanation (E1), trước Summary (S)</li><li>Điều kiện: Example phải <b>support/minh hoạ</b> cho Explanation → không đứng lẻ</li><li>Thứ tự đúng: T → E1 (giải thích) → E2 (example minh hoạ E1) → S (kết luận)</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>E1: \"Smartphones are designed to capture attention...\" → E2: \"A 2021 Meta study found that 30% of teen girls felt worse on Instagram.\" ✅</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Explanation TRƯỚC, Example SAU — giải thích xong mới minh hoạ.\"</p></div>","p":1},{"id":"W3D3-S-04","l":11,"t":"S","st":"Structure","s":2,"tags":["signal-phrase","extension-phrase"],"f":"<p>Kể 3 signal phrases mở đầu example + 3 extension phrases phát triển example.</p>","a":"","b":"<div class=\"sec\"><p><b>Signal phrases (mở example):</b></p><ol><li>For instance, ...</li><li>A case in point is [noun phrase]</li><li>This is exemplified by [noun phrase]</li></ol><p><b>Extension phrases (phát triển):</b></p><ol><li>This demonstrates that ...</li><li>As a result, ...</li><li>, thereby + V-ing ...</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Signal: \"<b>A case in point is</b> Finland's education system...\" → Extension: \"<b>This demonstrates that</b> project-based learning can outperform traditional testing.\"</p></div>","p":1},{"id":"W3D3-P-01","l":11,"t":"P","st":"Phrase","s":2,"tags":["signal-phrase","example"],"f":"<p>______ (một ví dụ điển hình là) Singapore's Mass Rapid Transit system, which carries over three million passengers daily.</p>","a":"<b>A case in point is</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"A case in point is Finland's education system, which eliminated standardised testing in favour of project-based learning.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"A notable example of this is\" | \"This is exemplified by\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — E2 position, khi giới thiệu specific example (Loại 1)</p></div>","p":1},{"id":"W3D3-P-02","l":11,"t":"P","st":"Phrase","s":2,"tags":["signal-phrase","example"],"f":"<p>______ (điều này được minh hoạ bởi) Beijing's Air Quality Action Plan, which reduced PM2.5 concentrations by 35%.</p>","a":"<b>This is exemplified by</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"This is exemplified by Denmark's welfare model, which allocates approximately 10% of GDP to publicly funded healthcare.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"A case in point is\" | \"A notable example of this is\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — E2 position, khi example minh hoạ trực tiếp cho explanation trước đó</p></div>","p":1},{"id":"W3D3-P-03","l":11,"t":"P","st":"Phrase","s":3,"tags":["extension","example"],"f":"<p>A 2021 internal study by Meta revealed that over 30% of teenage girls felt worse about their bodies on Instagram. ______ (điều này chứng minh rằng) social media companies are aware of the harm their platforms inflict.</p>","a":"<b>This demonstrates that</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Japan's Radio Taiso programme has contributed to the country's high life expectancy. This demonstrates that simple public health initiatives can have profound long-term effects.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"This suggests that\" | \"This indicates that\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — Extension sentence sau E2, phát triển example thành insight sâu hơn</p></div>","p":1},{"id":"W3D3-P-04","l":11,"t":"P","st":"Phrase","s":2,"tags":["extension","body-paragraph"],"f":"<p>Google Classroom has enabled teachers in over 150 countries to deliver lessons remotely, ______ (từ đó dẫn đến) a narrowing of the educational divide between urban and rural areas.</p>","a":"<b>which has subsequently led to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The Paris Agreement committed 196 nations to reducing carbon emissions, which has subsequently led to a measurable decline in global coal consumption.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"thereby + V-ing\" | \"as a result of which\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — Extension nối trong cùng câu (relative clause), thay vì tách 2 câu</p></div>","p":1},{"id":"W3D3-P-05","l":11,"t":"P","st":"Phrase","s":2,"tags":["collocation","body-paragraph"],"f":"<p>The constant ______ (làn sóng liên tục) of digital notifications has eroded people's ability to concentrate on a single task.</p>","a":"<b>barrage of</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Students face a constant barrage of social media alerts during study hours, significantly reducing their productivity.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"flood of\" | \"stream of\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi mô tả negative impact của technology/information overload</p></div>","p":1},{"id":"W3D3-P-06","l":11,"t":"P","st":"Phrase","s":2,"tags":["collocation","body-paragraph"],"f":"<p>Preventable diseases ______ (ảnh hưởng không tương xứng đến) the poorest segments of society, further entrenching the cycle of poverty.</p>","a":"<b>disproportionately affect</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Climate change disproportionately affects developing nations, which have contributed least to global emissions.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"have an outsized impact on\" | \"predominantly impact\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi bàn về inequality, health, environment — chỉ ra nhóm bị ảnh hưởng nhiều hơn</p></div>","p":1},{"id":"W3D3-E-01","l":11,"t":"E","st":"Error","s":3,"tags":["mistake","example"],"f":"<p><i>\"For example, technology is useful for students.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Đây là general statement, KHÔNG phải example. Không có tên cụ thể, không có data, ai cũng viết được.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"For instance, <b>Google Classroom</b> has enabled teachers in over 150 countries to deliver lessons remotely, which has significantly narrowed the educational gap between urban and rural areas.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Example = [Tên cụ thể] + [has/have + V-ed] + [result]. Không có tên cụ thể = không phải example.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + LR</p></div>","p":0},{"id":"W3D3-E-02","l":11,"t":"E","st":"Error","s":3,"tags":["mistake","tees-order"],"f":"<p><i>\"[T] Social media harms teenagers. [E2] For instance, Meta's study found 30% of girls felt worse. [E1] This is because algorithms promote idealised content. [S] Therefore, social media is harmful.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Thứ tự sai — đưa Example (E2) trước Explanation (E1). Reader chưa hiểu WHY đã thấy evidence.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>[T] → [E1] \"This is because algorithms promote idealised content...\" → [E2] \"For instance, Meta's study found...\" → [S]</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Trong TEES: Explanation (E1) luôn TRƯỚC Example (E2). Giải thích xong mới minh hoạ.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC</p></div>","p":0},{"id":"W3D3-E-03","l":11,"t":"E","st":"Error","s":2,"tags":["mistake","example"],"f":"<p><i>\"For instance, Zoom has enabled remote collaboration.\"</i> — câu này đúng ngữ pháp, nhưng thiếu gì để đạt Band 7?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Chỉ có 1 câu example, không có extension. Band 6 viết thế này — Band 7 cần phát triển thêm.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"For instance, Zoom has enabled remote teams to collaborate seamlessly across time zones. <b>This has subsequently reduced the need for business travel</b>, saving companies millions in annual expenses.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Band 7 example = 2 câu (Example + Extension). 1 câu = Band 6 — chưa fully developed.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA</p></div>","p":0},{"id":"W3D3-E-04","l":11,"t":"E","st":"Error","s":2,"tags":["mistake","example-relevance"],"f":"<p><i>\"[E1] Social media algorithms promote idealised content. [E2] For example, WhatsApp has over 2 billion users worldwide.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Example (WhatsApp users) KHÔNG liên quan đến Explanation (algorithms + idealised content). Example đứng lẻ, không minh hoạ cho E1.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"[E1] ...algorithms promote idealised content. [E2] For instance, <b>a 2021 Meta study</b> found that <b>Instagram's algorithm prioritised appearance-focused posts</b>, causing 30% of teen girls to feel worse about their bodies.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Example phải SUPPORT Explanation trước đó. Cùng topic chưa đủ — phải cùng ARGUMENT.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC + TA</p></div>","p":0},{"id":"W3D4-S-01","l":12,"t":"S","st":"Structure","s":3,"tags":["formula","assessment","quality-check"],"f":"<p>Phase 1 Assessment gồm mấy phần? Thời gian mỗi phần?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Part A:</b> Full Task 1 — 20 phút (line graph/bar chart, 150-190 từ, 4 đoạn)</li><li><b>Nghỉ:</b> 5 phút</li><li><b>Part B:</b> 2 TEES Body Paragraphs — 25 phút (opinion topic, ~80-100 từ/paragraph)</li><li><b>Tổng:</b> 45 phút viết + 5 phút nghỉ</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Part A: Task 1 line graph (Intro → Overview → Body 1 → Body 2) + Part B: 2 body paragraphs (Paragraph 1: main argument + Paragraph 2: concession)</p></div>","p":1},{"id":"W3D4-S-02","l":12,"t":"S","st":"Structure","s":3,"tags":["formula","task1","quality-check"],"f":"<p>Task 1 Quality Checklist — 4 tiêu chí cần kiểm tra sau khi viết là gì?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>TA:</b> Paraphrase đề? Có Overview (KHÔNG số)? 5-6 key features? ≥150 từ? KHÔNG opinion?</li><li><b>CC:</b> 4 đoạn rõ? Grouping logic (pattern-based)? Transition giữa Body 1 và 2?</li><li><b>LR:</b> ≥4 trend verbs? ≥1 noun form? Comparative/proportion? Không lặp từ?</li><li><b>GRA:</b> Verb + noun form variety? ≥1 complex structure (participle/relative)? Tenses đúng?</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Thiếu Overview → TA -1 band. Chỉ dùng \"increased/decreased\" → LR Band 5.</p></div>","p":1},{"id":"W3D4-S-03","l":12,"t":"S","st":"Structure","s":3,"tags":["formula","task2","quality-check"],"f":"<p>Task 2 Body Paragraph Quality Checklist — liệt kê 4 tiêu chí cần check.</p>","a":"","b":"<div class=\"sec\"><ul><li><b>TA:</b> 1 idea/paragraph? Specific example? Example supports explanation?</li><li><b>CC:</b> TEES đủ (T-E-E-S)? Academic linking? Không overuse? Reference devices?</li><li><b>LR:</b> Academic vocab? Collocations đúng? Paraphrase (không lặp)?</li><li><b>GRA:</b> Complex sentences (relative, participle)? Conditional/concession? Grammar chính xác?</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Liệt kê 3-4 ý không phát triển = Band 5 TA. Dùng \"and/but/because\" suốt = Band 5 CC.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"1 idea sâu = Band 7. 4 ý nông = Band 5.\"</p></div>","p":1},{"id":"W3D4-S-04","l":12,"t":"S","st":"Structure","s":2,"tags":["formula","assessment","phase1"],"f":"<p>4 điều kiện PASS Phase 1 để vào Phase 2 là gì? Cần đạt mấy điều kiện?</p>","a":"","b":"<div class=\"sec\"><p>Cần đạt <b>≥3 trong 4</b> điều kiện:</p><ol><li>Task 1: Viết đủ 4 đoạn, có Overview, ≥150 từ</li><li>Body paragraph: Viết theo TEES, có specific example</li><li>Linking: Dùng ≥3 academic linking devices tự nhiên</li><li>AI feedback: Average band ≥5.0 cho cả Part A + Part B</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Nếu Task 1 có Overview + TEES body + academic linking nhưng AI feedback = 4.5 → vẫn PASS (3/4 ✅)</p></div>","p":1},{"id":"W3D4-P-01","l":12,"t":"P","st":"Phrase","s":2,"tags":["collocation","task1-body","trend"],"f":"<p>The Theme Park was initially the most popular destination, ______ (thu hút) 2.5 million visitors in 2005.</p>","a":"<b>attracting</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The new shopping mall opened in 2019, attracting over 10,000 customers on its first day.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"drawing\" | \"receiving\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 body paragraph — khi mô tả số lượng ban đầu bằng participle clause (GRA Band 7)</p></div>","p":1},{"id":"W3D4-P-02","l":12,"t":"P","st":"Phrase","s":3,"tags":["collocation","task1-body","contrast"],"f":"<p>The City Museum ______ (đi theo hướng ngược lại), climbing steadily from 1.2 million to 2.4 million.</p>","a":"<b>followed an opposite trajectory</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"While urban populations expanded, rural areas followed an opposite trajectory, experiencing consistent decline.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"took the reverse path\" | \"showed the opposite trend\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 body — khi 2 categories có xu hướng ngược nhau hoàn toàn</p></div>","p":1},{"id":"W3D4-P-03","l":12,"t":"P","st":"Phrase","s":3,"tags":["collocation","task2-body","argument"],"f":"<p>One significant reason why longer prison sentences may not reduce crime is that they ______ (không giải quyết được nguyên nhân gốc) of criminal behaviour.</p>","a":"<b>fail to address the root causes</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Critics argue that standardised testing fails to address the root causes of educational inequality.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"do not tackle the underlying factors\" | \"overlook the fundamental reasons\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 2 body — Topic sentence khi disagree, chỉ ra giải pháp không hiệu quả</p></div>","p":1},{"id":"W3D4-P-04","l":12,"t":"P","st":"Phrase","s":2,"tags":["collocation","task2-body","concession"],"f":"<p>______ (Phải thừa nhận rằng), harsher sentencing can serve as a deterrent for certain types of crime.</p>","a":"<b>Admittedly</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Admittedly, online education offers greater flexibility for working professionals.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"It must be acknowledged that\" | \"Granted,\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 2 body — mở đầu concession paragraph (thừa nhận quan điểm đối lập trước khi phản bác)</p></div>","p":1},{"id":"W3D4-P-05","l":12,"t":"P","st":"Phrase","s":3,"tags":["collocation","task2-body","example"],"f":"<p>Norway has adopted a rehabilitation-focused approach, and the country ______ (tự hào có) one of the lowest reoffending rates in the world.</p>","a":"<b>boasts</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Singapore boasts one of the most efficient public transportation systems globally.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"has achieved\" | \"maintains\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 2 body — Example sentence khi nêu thành tựu/kết quả tích cực của một quốc gia/tổ chức</p></div>","p":1},{"id":"W3D4-E-01","l":12,"t":"E","st":"Error","s":3,"tags":["mistake","task1","overview"],"f":"<p><i>\"Overall, France had 30% in 1998 and Spain had 35% in 1998.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Overview chứa số liệu cụ thể (30%, 35%). Overview chỉ nêu xu hướng chung, KHÔNG có số.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Overall, all five nations saw a decrease in the percentage of income spent on food and drink over the decade.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Overview = xu hướng chung + ranking + ngoại lệ. KHÔNG BAO GIỜ có số cụ thể.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA</p></div>","p":0},{"id":"W3D4-E-02","l":12,"t":"E","st":"Error","s":3,"tags":["mistake","task2","body-paragraph"],"f":"<p><i>\"There are many reasons why crime is increasing. Firstly, poverty is a problem. Secondly, education is lacking. Thirdly, drugs are everywhere.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Liệt kê 3 ý (poverty, education, drugs) mà không phát triển ý nào. Mỗi ý chỉ 1 câu. Không có example hay explanation chi tiết.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Chọn 1 ý (VD: poverty) → viết TEES: Topic (poverty causes crime) → Explanation (why/how) → Example (specific country/data) → Summary (therefore...).</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>1 paragraph = 1 idea phát triển sâu (TEES). KHÔNG liệt kê 3-4 ý nông.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + CC</p></div>","p":0},{"id":"W3D4-E-03","l":12,"t":"E","st":"Error","s":2,"tags":["mistake","task1","body"],"f":"<p><i>\"The number of visitors to City Museum increased. The number of visitors to Theme Park decreased. The number of visitors to Historic Castle decreased.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>(1) Lặp cấu trúc \"The number of visitors to X increased/decreased\" 3 lần. (2) Không có grouping — liệt kê từng category riêng lẻ. (3) Không có số liệu cụ thể.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Nhóm theo pattern: \"The City Museum followed an opposite trajectory, climbing steadily from 1.2 to 2.4 million. Meanwhile, the Theme Park saw a dramatic reversal, dropping to just 1.5 million by 2020.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Task 1 Body = grouping (pattern-based) + variety (trend verbs + noun forms) + số liệu cụ thể. KHÔNG liệt kê theo từng category.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC + LR</p></div>","p":0},{"id":"W4D1-S-01","l":13,"t":"S","st":"Structure","s":3,"tags":["essay-structure","academic-writing"],"f":"<p>Bố cục 4 đoạn chuẩn của Task 2 essay gồm những phần nào, số câu và số lượng từ mục tiêu tương ứng?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Introduction</b> (~40-50 từ, ~15%): 2 câu (Paraphrase + Thesis)</li><li><b>Body 1</b> (~80-100 từ, ~35%): 4-6 câu (TEES structure)</li><li><b>Body 2</b> (~80-100 từ, ~35%): 4-6 câu (TEES structure)</li><li><b>Conclusion</b> (~30-40 từ, ~15%): 2-3 câu (Restate thesis + Summarise reasons)</li><li><b>Tổng cộng:</b> 250-280 từ (Body paragraphs chiếm ~70% dung lượng)</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Một bài viết đạt chuẩn Band 7.0+ thường dài từ 260-270 từ phân bổ đều vào 4 đoạn như trên để đảm bảo phát triển ý sâu và kiểm soát tốt thời gian/lỗi sai.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Body = 70% essay. Viết thân bài sâu hơn là mở bài/kết bài dài dòng.\"</p></div>","p":1},{"id":"W4D1-S-02","l":13,"t":"S","st":"Structure","s":3,"tags":["essay-structure","coherence-cohesion"],"f":"<p>Quy tắc nhất quán (Consistency rule) giữa Introduction và Conclusion trong Task 2 essay là gì? Tại sao nó quan trọng?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Quy tắc:</b> Lập trường (Position/Stance) thể hiện ở phần Thesis Statement (Introduction) phải <b>đồng nhất hoàn toàn</b> với lập trường ở phần Restate Opinion (Conclusion).</li><li><b>Lý do:</b> Giúp đạt tiêu chí Task Achievement (TA) Band 7: <i>\"presents a clear position throughout the response\"</i> (thể hiện một lập trường rõ ràng xuyên suốt bài viết). Nếu hai đoạn này mâu thuẫn hoặc không đồng nhất, điểm TA sẽ bị giảm xuống Band 5 hoặc 6.</li></ul></div><div class=\"sec\"><span class=\"lbl\">VD</span><ul><li>Intro: <i>I strongly agree...</i> → Conclusion: <i>I firmly believe that... is essential.</i> (Đồng nhất) ✅</li><li>Intro: <i>I agree that X is beneficial...</i> → Conclusion: <i>However, X causes more harm than good.</i> (Mâu thuẫn) ❌</li></ul></div>","p":1},{"id":"W4D1-S-03","l":13,"t":"S","st":"Structure","s":2,"tags":["planning","essay-structure"],"f":"<p>Nêu quy trình 5 bước Planning trong 5 phút đầu tiên trước khi viết bài Task 2.</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Đọc đề 2 lần (30s):</b> Lần 1 hiểu topic chung, lần 2 xác định chính xác loại đề dựa vào instruction ở câu cuối.</li><li><b>Xác định Position (30s):</b> Lập trường của bạn là gì (Agree, Disagree, hay Partially)? Phác thảo nhanh câu Thesis draft.</li><li><b>Brainstorm 2 Main Ideas (2 phút):</b> Chọn ra 2 ý lớn, rõ ràng và KHÁC NHAU để đưa vào Body 1 và Body 2.</li><li><b>Nghĩ Examples cụ thể (1.5 phút):</b> Chuẩn bị sẵn tên riêng (tổ chức, quốc gia, nghiên cứu) và kết quả cụ thể cho mỗi ý chính.</li><li><b>Phác thảo Essay Blueprint (30s):</b> Ghi chú nhanh sơ đồ dàn bài ra nháp để bám sát khi viết.</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Dành 5 phút lập dàn ý giúp tiết kiệm thời gian chỉnh sửa và tránh bị lạc đề (off-topic) khi đang viết dở bài.</p></div>","p":1},{"id":"W4D1-S-04","l":13,"t":"S","st":"Structure","s":3,"tags":["idea-generation","brainstorming","band7"],"f":"<p>3 công cụ sinh ý tưởng (Idea Generation Frameworks) khi bị bí ý cho Task 2 essay là gì?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Khung PESTLE (Đa chiều):</b> Soi chiếu qua 6 góc độ: Political, Economic, Social, Technological, Legal, Environmental. Chọn 2 góc độ cho 2 Body paragraphs.</li><li><b>Khung Stakeholder Analysis (Đối tượng):</b> Xét tác động từ cấp độ: Individual → Family → Business/School → Government/Society.</li><li><b>Chuỗi Nhân Quả 3 Bước (Cause-Effect Chain):</b> Hành động <i>(Action)</i> → Hệ quả trực tiếp <i>(Direct Effect)</i> → Tác động xã hội sâu sắc <i>(Ultimate Impact)</i>.</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Thay vì bí ý, chọn Body 1 góc độ Economic (tiết kiệm chi phí), Body 2 góc độ Environmental (giảm phát thải) → bài viết đa chiều, đạt Band 7.5+ TR.</p></div>","p":1},{"id":"W4D1-S-05","l":13,"t":"S","st":"Structure","s":2,"tags":["idea-generation","cause-effect","band7"],"f":"<p>Kỹ thuật Chuỗi Nhân Quả 3 Bước (3-Step Cause-and-Effect Chain) nâng cấp ý tưởng từ Band 5 lên Band 7 thế nào?</p>","a":"","b":"<div class=\"sec\"><ul><li>Luôn tự hỏi: <i>\"Điều này dẫn tới hệ quả gì tiếp theo?\"</i></li><li><b>Công thức:</b> Action → Direct Effect → Ultimate Impact</li><li><b>So sánh:</b><div><i>Ý tưởng nông (Band 5):</i> \"Playing video games is bad because it wastes time.\"</div><div><i>Chuỗi sâu (Band 7.5):</i> Excessive screen time <i>(Action)</i> → induces sedentary behaviour and sleep disruption <i>(Direct Effect)</i> → which severely impairs academic focus and heightens chronic mental fatigue <i>(Ultimate Impact)</i>.</div></li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Chuỗi 3 bước biến một luận điểm sơ sài thành một đoạn Explanation sâu sắc chuẩn TEES.</p></div>","p":1},{"id":"W4D1-P-01","l":13,"t":"P","st":"Phrase","s":2,"tags":["collocation","environmental-protection"],"f":"<p>Environmental education at school can ______ (hình thành thói quen bền vững suốt đời) for children.</p>","a":"<b>shape lifelong sustainable habits</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Early exposure to ecological concepts can shape lifelong sustainable habits in young learners.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"instil sustainable behaviours\" | \"form long-term green habits\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Dùng trong Introduction hoặc Body khi viết về các chủ đề giáo dục, môi trường, hành vi của trẻ em.</p></div>","p":1},{"id":"W4D1-P-02","l":13,"t":"P","st":"Phrase","s":2,"tags":["collocation","education"],"f":"<p>Early school programmes help children become ______ (công dân có nhận thức/hiểu biết).</p>","a":"<b>informed citizens</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Teaching children about environmental issues creates informed citizens capable of making responsible decisions.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"well-informed members of society\" | \"knowledgeable individuals\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Dùng trong Body hoặc Conclusion để nói về kết quả lâu dài của giáo dục đối với xã hội.</p></div>","p":1},{"id":"W4D1-P-03","l":13,"t":"P","st":"Phrase","s":2,"tags":["academic-phrase","habits"],"f":"<p>Habits formed during childhood tend to ______ (kéo dài/tồn tại đến khi trưởng thành).</p>","a":"<b>persist into adulthood</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Dietary preferences established in early youth often persist into adulthood.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"remain throughout one's life\" | \"continue into mature years\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Dùng để giải thích cơ chế (Explanation) tại sao một hành động giáo dục ở trường lại có hiệu quả lâu dài.</p></div>","p":1},{"id":"W4D1-P-04","l":13,"t":"P","st":"Phrase","s":3,"tags":["collocation","education-equality"],"f":"<p>Formal education provides ______ (sự tiếp cận bình đẳng với chương trình học có cấu trúc) regardless of a child's ______ (hoàn cảnh kinh tế xã hội).</p>","a":"<b>equal access to structured curricula</b> | <b>socioeconomic backgrounds</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"State schools ensure that all children, regardless of their socioeconomic backgrounds, have equal access to structured curricula.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"fair access to organised study plans\" | \"financial and social status\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Dùng trong Body paragraph khi phân tích lợi ích của trường học so với việc giáo dục tại nhà hoặc qua mạng internet.</p></div>","p":1},{"id":"W4D1-P-05","l":13,"t":"P","st":"Phrase","s":2,"tags":["collocation","society"],"f":"<p>Schools can ______ (đóng vai trò then chốt) in protecting our planet.</p>","a":"<b>play a pivotal role</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Local governments play a pivotal role in maintaining public health standards.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"play a crucial role\" | \"play a vital part\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Thường dùng trong Introduction/Thesis statement hoặc Conclusion để khẳng định tầm quan trọng của một chủ thể đối với vấn đề.</p></div>","p":1},{"id":"W4D1-E-01","l":13,"t":"E","st":"Error","s":3,"tags":["mistake","essay-structure"],"f":"<p><i>Viết 3 đoạn thân bài (Body paragraphs) ngắn thay vì viết 2 đoạn thân bài sâu.</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Việc chia nhỏ thành 3 đoạn thân bài thường làm cho các luận điểm bị nông, thiếu ví dụ và phân tích sâu (underdeveloped), làm giảm điểm Task Achievement (TA) và Coherence &amp; Cohesion (CC).</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Nên viết đúng <b>2 đoạn thân bài sâu</b>, phát triển đầy đủ theo cấu trúc TEES (~80-100 từ/đoạn).</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>2 body paragraphs sâu và chặt chẽ luôn tốt hơn 3 body paragraphs ngắn và hời hợt.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + CC</p></div>","p":0},{"id":"W4D1-E-02","l":13,"t":"E","st":"Error","s":2,"tags":["mistake","introduction"],"f":"<p><i>Viết đoạn Introduction quá dài (80-90 từ) với nhiều câu dẫn dắt chung chung trước khi nêu Thesis.</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Introduction quá dài làm lãng phí thời gian quý báu (đáng lẽ phải dành cho thân bài) và làm lu mờ câu Thesis statement chính.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Chỉ viết Introduction <b>tối đa 2 câu (~40-50 từ)</b>: Câu 1 paraphrase đề bài, Câu 2 nêu trực tiếp Thesis statement (quan điểm của bạn + 2 lý do khái quát).</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Introduction chỉ làm nhiệm vụ mở cánh cửa vào bài viết; phần chấm điểm chính nằm ở Body.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC (Coherence) + quản lý thời gian thi thực tế.</p></div>","p":0},{"id":"W4D1-E-03","l":13,"t":"E","st":"Error","s":3,"tags":["mistake","planning"],"f":"<p><i>Không lập dàn ý (plan) trước khi viết, dẫn đến việc Body 1 và Body 2 bị trùng ý hoặc lập luận quanh co.</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Bắt đầu viết ngay mà không lập dàn ý khiến người viết dễ bị \"bí\" ý giữa chừng hoặc viết 2 đoạn thân bài nhưng thực chất chỉ là 2 cách diễn đạt khác nhau của cùng một ý tưởng, gây lặp ý và rời rạc.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Luôn dành <b>5 phút đầu tiên</b> để lập dàn ý (Essay Blueprint): ghi rõ Position, Idea 1 + Example 1, Idea 2 + Example 2.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Tốc độ viết sẽ nhanh hơn và cấu trúc sẽ mạch lạc hơn 3 lần nếu có một bản đồ dàn ý rõ ràng trước khi đặt bút viết.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC + TA</p></div>","p":0},{"id":"W4D2-S-01","l":14,"t":"S","st":"Structure","s":3,"tags":["formula","thesis-statement"],"f":"<p>Công thức viết Thesis Statement cho dạng Strong Opinion (đồng ý hoặc phản đối hoàn toàn) là gì?</p>","a":"","b":"<div class=\"sec\"><p><code>I [firmly/strongly] [agree/disagree] with this statement because [reason 1] and [reason 2].</code></p></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"I firmly agree with this view because public transport reduces carbon emissions and alleviates urban congestion more effectively than road expansion.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Phải nêu rõ cả <b>position</b> (agree/disagree) và <b>2 reasons</b> (tương ứng với 2 đoạn body) ngay trong 1 câu thesis.</p></div>","p":1},{"id":"W4D2-S-02","l":14,"t":"S","st":"Structure","s":3,"tags":["formula","thesis-statement"],"f":"<p>Công thức viết Thesis Statement cho dạng Balanced Opinion (đồng ý một phần / có concession) là gì?</p>","a":"","b":"<div class=\"sec\"><p><code>While I acknowledge that [opposing side], I [ultimately/fundamentally] believe that [your position] because [reason 1] and [reason 2].</code></p></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"While I acknowledge that road infrastructure has its merits, I ultimately believe that prioritising public transport investment is more beneficial because it addresses both environmental concerns and urban mobility challenges.\"</p></div>","p":1},{"id":"W4D2-S-03","l":14,"t":"S","st":"Structure","s":2,"tags":["concession","formula"],"f":"<p>3 công thức viết câu nhượng bộ (Concession) để chuẩn bị phản bác/nêu ý chính là gì?</p>","a":"","b":"<div class=\"sec\"><ul><li><code>While it is true that [opposing argument], [counter-argument/your position].</code></li><li><code>Admittedly, [opposing point]. However, [your stronger argument].</code></li><li><code>Some might argue that [opposing view]. Nevertheless, [evidence against].</code></li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"While it is true that free education places a heavy burden on the state budget, the long-term economic benefits of a highly skilled workforce are far greater.\"</p></div>","p":1},{"id":"W4D2-P-01","l":14,"t":"P","st":"Phrase","s":3,"tags":["collocation","mental-health"],"f":"<p>Social media has a ______ (ảnh hưởng cực kỳ bất lợi) on young people's mental health.</p>","a":"<b>profoundly detrimental effect</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Academic pressure and lack of sleep can have a profoundly detrimental effect on a student's development.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"highly negative impact\" | \"severely adverse influence\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Dùng trong Body paragraph khi viết về tác hại của một xu hướng/thói quen xấu.</p></div>","p":1},{"id":"W4D2-P-02","l":14,"t":"P","st":"Phrase","s":2,"tags":["collocation","social-media"],"f":"<p>Teenagers are constantly exposed to ______ (những hình ảnh được cắt tỉa kỹ lưỡng và thường không thực tế) of life.</p>","a":"<b>carefully curated and often unrealistic portrayals</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Many people suffer from low self-esteem due to the carefully curated and often unrealistic portrayals of success on Instagram.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"idealised and artificial depictions\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Dùng khi viết về chủ đề Social Media, Advertising hoặc Media.</p></div>","p":1},{"id":"W4D2-P-03","l":14,"t":"P","st":"Phrase","s":2,"tags":["collocation","finance"],"f":"<p>Abolishing tuition fees would place an ______ (gánh nặng tài chính không thể chống đỡ nổi) on the government.</p>","a":"<b>unsustainable financial burden</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Providing free healthcare for all citizens could impose an unsustainable financial burden on developing nations.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"excessive fiscal strain\" | \"unsustainable budget deficit\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Dùng khi bàn về việc chính phủ chi tiêu hoặc tài trợ cho dịch vụ công (Arts, Healthcare, Education).</p></div>","p":1},{"id":"W4D2-P-04","l":14,"t":"P","st":"Phrase","s":2,"tags":["collocation","finance"],"f":"<p>Free university education would require ______ (sự gia tăng đáng kể trong thuế).</p>","a":"<b>substantial increases in taxation</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"To fund new infrastructure projects, the government had to implement substantial increases in taxation.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"significant tax hikes\" | \"heavy tax burdens\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Dùng khi viết về giải pháp tài chính của chính phủ.</p></div>","p":1},{"id":"W4D2-P-05","l":14,"t":"P","st":"Phrase","s":2,"tags":["collocation","government"],"f":"<p>The government should focus on ______ (truyền tải nguồn vốn ngân sách) into essential public services.</p>","a":"<b>channelling government funds</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Channelling government funds into renewable energy projects is crucial for combating climate change.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"allocating state budget\" | \"directing public expenditure\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Dùng khi đưa ra giải pháp/khuyến nghị hành động cho chính phủ.</p></div>","p":1},{"id":"W4D2-P-06","l":14,"t":"P","st":"Phrase","s":3,"tags":["collocation","society"],"f":"<p>Investing in education is crucial for ensuring ______ (sự phát triển xã hội công bằng).</p>","a":"<b>equitable societal development</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Access to clean water and sanitation is fundamental to achieving equitable societal development.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"fair social progression\" | \"balanced development of society\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Dùng trong câu Summary hoặc Conclusion khi bàn về lợi ích lâu dài của chính sách xã hội.</p></div>","p":1},{"id":"W4D2-E-01","l":14,"t":"E","st":"Error","s":3,"tags":["mistake","thesis-statement"],"f":"<p><i>“In this essay, I will discuss both sides of the argument and then give my opinion.”</i> (cho đề Opinion Agree/Disagree) — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Không đưa ra position (lập trường) rõ ràng ngay ở Introduction. Đây là lỗi chí mạng khiến điểm TA bị giới hạn ở Band 5-6.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"I firmly agree with this view because public transport reduces carbon emissions and alleviates urban congestion.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Với đề Opinion, Thesis statement phải chỉ rõ lập trường (agree/disagree/partially agree) kèm theo lý do, KHÔNG được viết nước đôi hứa hẹn thảo luận chung chung.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA</p></div>","p":0},{"id":"W4D2-E-02","l":14,"t":"E","st":"Error","s":3,"tags":["mistake","consistency"],"f":"<p>Introduction viết: <i>“I firmly agree that the government should fund the arts.”</i> nhưng Conclusion lại viết: <i>“However, health and education are more important, so arts funding should be limited.”</i> — Lỗi gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Vi phạm <b>Consistency Rule</b> (mâu thuẫn lập trường giữa mở bài và kết bài).</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Cả mở bài và kết bài phải cùng đồng ý (hoặc cùng phản đối). Nếu muốn viết cả hai khía cạnh, phải dùng <b>balanced thesis</b> ở mở bài ngay từ đầu.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Position phải nhất quán từ đầu đến cuối bài (throughout the response).</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + CC</p></div>","p":0},{"id":"W4D2-E-03","l":14,"t":"E","st":"Error","s":2,"tags":["mistake","concession"],"f":"<p><i>“Admittedly, free education has some drawbacks, but I agree with it.”</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Phần nhượng bộ quá chung chung (drawbacks) và phần bác bỏ/lập trường (but I agree with it) quá cụ thể/không tương xứng, thiếu chiều sâu lập luận.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"While it is true that free university education places a heavy burden on the state budget, I ultimately believe it is necessary because it fosters long-term economic growth.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Mệnh đề Concession (<code>While...</code>) và mệnh đề chính phải cân đối: cụ thể hóa cả lý do nhượng bộ và lý do ủng hộ.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + CC</p></div>","p":0},{"id":"W4D3-S-01","l":15,"t":"S","st":"Structure","s":3,"tags":["formula","conclusion"],"f":"<p>Công thức viết Conclusion cho Opinion Essay gồm mấy câu? Viết công thức.</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Câu 1:</b> \"In conclusion, \" + restate opinion (paraphrase từ thesis)</li><li><b>Câu 2:</b> \"This is primarily because \" + summarise 2 reasons (gộp 1 câu)</li><li><b>(Optional) Câu 3:</b> Final thought — prediction hoặc recommendation</li><li><b>Tổng: 2-3 câu, ~30-40 từ, KHÔNG thêm ý mới</b></li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"In conclusion, it is evident that social media poses serious risks to the younger generation. This is primarily because its impact on psychological well-being and educational outcomes cannot be overlooked.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Restate + Summarise = Done. Không develop, không evidence mới.\"</p></div>","p":1},{"id":"W4D3-S-02","l":15,"t":"S","st":"Structure","s":3,"tags":["paraphrase","restate","conclusion"],"f":"<p>Khi restate thesis trong conclusion, có 3 kỹ thuật nào?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Đổi chủ ngữ:</b> \"I firmly agree\" → \"It is evident that\"</li><li><b>Đổi từ vựng:</b> \"negative impact\" → \"poses serious risks\"</li><li><b>Đổi cấu trúc câu:</b> \"I agree because A and B\" → \"It is clear that..., given both A and B\"</li></ol></div><div class=\"sec\"><span class=\"lbl\">VD</span><p>Intro: \"I firmly agree that social media has a profoundly negative impact\"</p><p>→ Conclusion: \"It is evident that social media poses serious risks\"</p></div>","p":1},{"id":"W4D3-S-03","l":15,"t":"S","st":"Structure","s":2,"tags":["checklist","mirror","conclusion"],"f":"<p>Sau khi viết xong essay, hỏi 3 câu gì để kiểm tra Introduction ↔ Conclusion mirror?</p>","a":"","b":"<div class=\"sec\"><ol><li class=\"good\">✅ <b>Cùng position?</b> Intro agree → Conclusion vẫn agree?</li><li class=\"good\">✅ <b>Cùng 2 reasons?</b> 2 reasons trong conclusion khớp 2 reasons trong intro?</li><li class=\"good\">✅ <b>Khác từ ngữ?</b> Không copy nguyên câu từ intro?</li></ol></div><div class=\"sec\"><span class=\"lbl\">VD</span><p>Intro: \"I firmly agree... damages mental health... undermines academic performance\"</p><p>→ Conclusion: \"...poses serious risks... psychological well-being... educational outcomes\"</p><p>→ ✅ cùng position, ✅ cùng reasons, ✅ khác từ</p></div>","p":1},{"id":"W4D3-S-04","l":15,"t":"S","st":"Structure","s":2,"tags":["final-thought","conclusion"],"f":"<p>Final thought technique trong conclusion có mấy loại? Kể tên + cho công thức.</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Prediction:</b> \"Without [action], [negative consequence] is likely to [continue/worsen]\"</li><li><b>Recommendation:</b> \"It is therefore essential/imperative that [stakeholders] [action]\"</li></ol></div><div class=\"sec\"><span class=\"lbl\">VD</span><ul><li>Prediction: \"Without appropriate regulation, this problem is likely to intensify.\"</li><li>Recommendation: \"It is therefore essential that governments implement stricter policies.\"</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Final thought = OPTIONAL. Chỉ thêm khi tự nhiên + còn dư từ. Không ép = không thêm.\"</p></div>","p":1},{"id":"W4D3-P-01","l":15,"t":"P","st":"Phrase","s":3,"tags":["restate","conclusion"],"f":"<p>In conclusion, ______ (rõ ràng rằng) social media poses serious risks to the younger generation.</p>","a":"<b>it is evident that</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"In conclusion, it is evident that investing in public transport yields greater long-term advantages.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"it is clear that\" | \"the evidence clearly shows that\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Conclusion — câu đầu tiên, thay thế \"I firmly agree/disagree\" từ intro</p></div>","p":1},{"id":"W4D3-P-02","l":15,"t":"P","st":"Phrase","s":3,"tags":["restate","conclusion"],"f":"<p>In conclusion, ______ (bằng chứng cho thấy rõ ràng rằng) this perspective is flawed.</p>","a":"<b>the evidence clearly demonstrates that</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"In conclusion, the evidence clearly demonstrates that longer prison sentences do not reduce crime effectively.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"the evidence suggests that\" | \"the evidence clearly refutes the claim that\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Conclusion — restate opinion khi disagree, mạnh hơn \"it is clear that\"</p></div>","p":1},{"id":"W4D3-P-03","l":15,"t":"P","st":"Phrase","s":3,"tags":["summarise","conclusion"],"f":"<p>______ (Điều này chủ yếu là vì) its impact on psychological well-being and educational outcomes is substantial.</p>","a":"<b>This is primarily because</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"This is primarily because the cognitive benefits of early learning, combined with the professional opportunities it creates, far outweigh any drawbacks.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"This is largely due to\" | \"The combination of... makes this position clear\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Conclusion — câu thứ 2, gộp 2 reasons thành 1 câu</p></div>","p":1},{"id":"W4D3-P-04","l":15,"t":"P","st":"Phrase","s":2,"tags":["paraphrase","conclusion"],"f":"<p>Despite the ______ (những hệ quả tài chính đáng kể), providing free education would deliver substantial long-term returns.</p>","a":"<b>considerable fiscal implications</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The considerable fiscal implications of this policy must be weighed against its social benefits.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"significant financial burden\" | \"substantial economic costs\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Conclusion — paraphrase \"financial burden\" / \"costs\" ở mức academic hơn</p></div>","p":1},{"id":"W4D3-P-05","l":15,"t":"P","st":"Phrase","s":2,"tags":["final-thought","conclusion"],"f":"<p>Without appropriate regulation, this problem ______ (có khả năng sẽ trầm trọng hơn).</p>","a":"<b>is likely to intensify</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Without immediate intervention, income inequality is likely to intensify in developing nations.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"is expected to worsen\" | \"will inevitably escalate\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Conclusion — final thought (prediction), chỉ dùng khi phù hợp + còn dư từ</p></div>","p":1},{"id":"W4D3-E-01","l":15,"t":"E","st":"Error","s":3,"tags":["mistake","conclusion","copy"],"f":"<p><i>Intro: \"I firmly agree that social media has a negative impact on young people.\"</i></p><p><i>Conclusion: \"I firmly agree that social media has a negative impact on young people.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Copy nguyên xi Introduction — không paraphrase gì cả → mất điểm LR (lặp từ vựng + cấu trúc).</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"In conclusion, it is evident that social media poses serious risks to the younger generation.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Conclusion phải PARAPHRASE thesis — đổi ≥3 từ + đổi cấu trúc câu. Giữ position, đổi ngôn ngữ.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR + CC</p></div>","p":0},{"id":"W4D3-E-02","l":15,"t":"E","st":"Error","s":3,"tags":["mistake","conclusion","new-idea"],"f":"<p><i>\"In conclusion, I agree that social media is harmful. Additionally, technology also affects people's physical health due to sedentary lifestyles.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Thêm ý mới (\"physical health\", \"sedentary lifestyles\") chưa từng nhắc trong body paragraphs → conclusion phải KẾT LUẬN, không phải INTRODUCE.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"In conclusion, it is evident that social media poses serious risks. This is primarily because its impact on psychological well-being and educational outcomes cannot be overlooked.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Conclusion chỉ được restate + summarise. MỌI ý trong conclusion phải đã xuất hiện trong Introduction hoặc Body.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC + TA</p></div>","p":0},{"id":"W4D3-E-03","l":15,"t":"E","st":"Error","s":2,"tags":["mistake","conclusion","length"],"f":"<p><i>[Conclusion dài 5 câu, ~70 từ, develop thêm ví dụ và giải thích]</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Conclusion quá dài (&gt;50 từ) — lãng phí thời gian và từ mà lẽ ra nên dành cho body paragraphs. Conclusion không phải nơi develop ideas.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Giới hạn conclusion 2-3 câu, ~30-40 từ. Restate + Summarise = đủ.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Conclusion = đoạn NGẮN NHẤT trong essay (~15%). Dài &gt;50 từ = đang develop thay vì kết luận → mất CC.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC</p></div>","p":0},{"id":"W4D4-S-01","l":16,"t":"S","st":"Structure","s":3,"tags":["time-management","workflow"],"f":"<p>Chia thời gian 40 phút viết Task 2 essay như thế nào? Nêu 6 bước + thời gian.</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Plan</b> — 5 phút (đọc đề → loại đề → position → 2 ideas → 2 examples)</li><li><b>Introduction</b> — 5 phút (paraphrase + thesis, ~40-50 từ)</li><li><b>Body 1</b> — 12 phút (TEES, ~80-100 từ)</li><li><b>Body 2</b> — 12 phút (TEES, ~80-100 từ)</li><li><b>Conclusion</b> — 3 phút (restate + summarise, ~30-40 từ)</li><li><b>Check</b> — 3 phút (S-V, articles, tense, word count)</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>5' + 5' + 12' + 12' + 3' + 3' = 40 phút. Body chiếm 24/40 phút = 60% thời gian.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"5-5-12-12-3-3. Body = 24 phút, phần còn lại chia đều.\"</p></div>","p":1},{"id":"W4D4-S-02","l":16,"t":"S","st":"Structure","s":3,"tags":["checklist","pre-writing"],"f":"<p>Pre-Writing Checklist gồm 5 câu hỏi gì? (Hỏi bản thân trước khi bắt đầu viết essay)</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Loại đề?</b> — Opinion / Discussion / Problem-Solution / Two-Part / Adv-Disadv</li><li><b>Position?</b> — Agree / Disagree / Partially agree — phải RÕ RÀNG</li><li><b>2 main ideas?</b> — 2 ý KHÁC NHAU, đủ develop 80-100 từ mỗi ý</li><li><b>2 examples?</b> — Tên cụ thể + kết quả</li><li><b>Thesis draft?</b> — 1 câu: [position] + [reason 1] + [reason 2]</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Nếu chưa trả lời được cả 5 → dành thêm 1-2 phút plan, ĐỪNG viết khi chưa rõ.</p></div>","p":1},{"id":"W4D4-S-03","l":16,"t":"S","st":"Structure","s":3,"tags":["checklist","post-writing"],"f":"<p>Post-Writing Checklist: 3 phút cuối kiểm tra 5 lỗi gì?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Subject-Verb Agreement</b> — \\\"The government have\\\" → \\\"has\\\"</li><li><b>Articles</b> — uncountable + general = no article; specific = \\\"the\\\"</li><li><b>Tense consistency</b> — present cho arguments, past cho examples</li><li><b>Word count</b> — ≥250 từ? Nếu thiếu: thêm 1 câu Explanation vào body ngắn</li><li><b>Intro ↔ Conclusion</b> — cùng position? cùng reasons? khác từ?</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Đọc lại 1 lần duy nhất, chỉ sửa lỗi nhỏ. KHÔNG viết lại cả đoạn.</p></div>","p":1},{"id":"W4D4-S-04","l":16,"t":"S","st":"Structure","s":2,"tags":["word-count","strategy"],"f":"<p>Bao nhiêu từ là lý tưởng cho Task 2 essay? Viết dưới bao nhiêu bị trừ điểm?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>&lt;250 từ:</b> ❌ Penalty — bị trừ điểm TA</li><li><b>250-260 từ:</b> ✅ Đủ — nếu nội dung chất lượng</li><li><b>260-280 từ:</b> ✅ <b>Lý tưởng</b> — đủ depth, không dài dòng</li><li><b>&gt;300 từ:</b> ⚠️ Rủi ro — nhiều cơ hội mắc lỗi + hết thời gian check</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Intro 45 + Body 1 90 + Body 2 90 + Conclusion 35 = 260 từ ✅</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"260-280 = sweet spot. Viết dài hơn 300 = tự hại mình.\"</p></div>","p":1},{"id":"W4D4-P-01","l":16,"t":"P","st":"Phrase","s":3,"tags":["collocation","body-paragraph"],"f":"<p>The allocation of government funding between education and defence is a ______ (vấn đề gây tranh cãi).</p>","a":"<b>contentious issue</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Whether to prioritise economic growth or environmental protection remains a contentious issue in many countries.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"controversial topic\" | \"widely debated matter\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Introduction — paraphrase đề bài, nâng cấp từ \"important topic\"</p></div>","p":1},{"id":"W4D4-P-02","l":16,"t":"P","st":"Phrase","s":3,"tags":["collocation","body-paragraph"],"f":"<p>When governments allocate resources to education, they ______ (trang bị cho công dân) the skills necessary to contribute productively.</p>","a":"<b>equip citizens with</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Vocational training programmes equip citizens with practical skills for the modern workforce.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"provide citizens with\" | \"furnish individuals with\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi nói về education/training benefits</p></div>","p":1},{"id":"W4D4-P-03","l":16,"t":"P","st":"Phrase","s":2,"tags":["collocation","body-paragraph"],"f":"<p>Education spending ______ (thúc đẩy sự bình đẳng xã hội) by ensuring access to opportunities.</p>","a":"<b>fosters greater social equity</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Universal healthcare fosters greater social equity by removing financial barriers to medical treatment.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"promotes social equality\" | \"advances social inclusion\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về lợi ích xã hội của một policy</p></div>","p":1},{"id":"W4D4-P-04","l":16,"t":"P","st":"Phrase","s":2,"tags":["collocation","body-paragraph"],"f":"<p>The creative industries generate considerable revenue, making it one of the ______ (các ngành kinh tế phát triển nhanh nhất).</p>","a":"<b>fastest-growing economic sectors</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Renewable energy has become one of the fastest-growing economic sectors in the developing world.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"most rapidly expanding industries\" | \"leading growth sectors\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi nêu ví dụ về ngành/lĩnh vực phát triển</p></div>","p":1},{"id":"W4D4-P-05","l":16,"t":"P","st":"Phrase","s":3,"tags":["collocation","conclusion"],"f":"<p>______ (Bằng chứng cho thấy rằng) arts funding is far from wasteful.</p>","a":"<b>The evidence demonstrates that</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The evidence demonstrates that early childhood education significantly improves long-term academic outcomes.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"The evidence clearly indicates that\" | \"Research has shown that\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Conclusion — restate opinion dạng impersonal, thay cho \"I believe\"</p></div>","p":1},{"id":"W4D4-P-06","l":16,"t":"P","st":"Phrase","s":2,"tags":["collocation","body-paragraph"],"f":"<p>South Korea's strategic investment in cultural industries significantly enhanced the nation's ______ (sức mạnh mềm) on the world stage.</p>","a":"<b>soft power</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Japan's animation industry has significantly enhanced its soft power and international cultural influence.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"cultural influence\" | \"international standing\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về arts, culture, national image</p></div>","p":1},{"id":"W4D4-E-01","l":16,"t":"E","st":"Error","s":3,"tags":["mistake","essay-structure"],"f":"<p><i>[Essay chỉ có 150 từ, 3 đoạn, Body mỗi đoạn 40-50 từ, không có specific examples]</i> — Band mấy? Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Body paragraphs quá ngắn (40-50 từ) = underdeveloped arguments. Thiếu examples = general, không thuyết phục. 150 từ = bị penalty under length.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Mỗi body 80-100 từ, TEES đầy đủ, ít nhất 1 specific example (tên + kết quả). Tổng ≥250 từ.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Body = 70% essay (~180 từ cho 2 body). Mỗi body phải có TEES đầy đủ. &lt;250 từ = bị trừ điểm TA.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + CC</p></div>","p":0},{"id":"W4D4-E-02","l":16,"t":"E","st":"Error","s":3,"tags":["mistake","example"],"f":"<p><i>\"For example, many people go to university and then get good salary.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Example chung chung — \"many people\" không cụ thể, không có tên, không có số liệu → Band 5 example.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"For instance, South Korea's dramatic increase in education spending during the 1980s transformed the nation into one of Asia's leading technological powerhouses, with GDP per capita rising from $2,000 to over $30,000.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Example = [Tên cụ thể] + [hành động/sự kiện] + [kết quả đo lường được]. \"Many people\" KHÔNG BAO GIỜ là good example.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + LR</p></div>","p":0},{"id":"W4D4-E-03","l":16,"t":"E","st":"Error","s":3,"tags":["mistake","grammar"],"f":"<p><i>\"Education help people to get good jobs. Government spend a lot of money.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Subject-Verb Agreement — \"Education\" (số ít) + \"help\" (thiếu -s); \"Government\" (số ít) + \"spend\" (thiếu -s).</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Education <b>helps</b> people to secure employment.\" / \"The government <b>spends</b> a considerable amount on...\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Chủ ngữ số ít (Education, Government, Technology, Society) luôn đi với verb có -s/-es ở thì Present Simple. Kiểm tra EVERY sentence khi post-check.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA</p></div>","p":0},{"id":"W4D4-E-04","l":16,"t":"E","st":"Error","s":2,"tags":["mistake","time-management"],"f":"<p><i>[Viết hết 38 phút cho Introduction + 2 Body paragraphs, không còn thời gian viết Conclusion]</i> — Nên làm gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Tiếp tục hoàn thiện Body 2 → hết giờ → nộp bài không có Conclusion.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span><b>DỪNG body ngay lập tức</b> → viết Conclusion 2 câu (restate + summarise) trong 2 phút → nộp.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Thiếu Conclusion mất nhiều điểm CC hơn Body ngắn. LUÔN dành ít nhất 3 phút cuối cho Conclusion. Nếu sắp hết giờ → ưu tiên Conclusion.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC</p></div>","p":0},{"id":"W5D1-S-01","l":17,"t":"S","st":"Structure","s":3,"tags":["essay-structure","discussion"],"f":"<p>Discussion essay structure gồm mấy đoạn? Nội dung từng đoạn là gì?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Introduction</b> (~40-50 từ): Paraphrase đề (acknowledge 2 views) + Thesis lean nhẹ</li><li><b>Body 1</b> (~80-100 từ): View A — trình bày khách quan theo TEES</li><li><b>Body 2</b> (~80-100 từ): View B — trình bày khách quan theo TEES</li><li><b>Conclusion</b> (~30-40 từ): Acknowledge cả 2 + nêu opinion RÕ RÀNG</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Intro (acknowledge traditional vs modern) → Body 1 (View A: traditional) → Body 2 (View B: modern) → Conclusion (lean View B)</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"A-B-O\" — Acknowledge → Both views → Opinion cuối</p></div>","p":1},{"id":"W5D1-S-02","l":17,"t":"S","st":"Structure","s":3,"tags":["discussion","opinion","comparison"],"f":"<p>Discussion essay khác Opinion essay ở 3 điểm chính nào?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Thesis</b>: Opinion = chọn phía ngay (\"I strongly agree...\") → Discussion = acknowledge cả 2 trước (\"While both perspectives have merit, I believe...\")</li><li><b>Body</b>: Opinion = 2 body support cùng phía → Discussion = Body 1 = View A, Body 2 = View B</li><li><b>Balance</b>: Opinion = lệch OK → Discussion = PHẢI cân bằng (Body 1 ≈ Body 2)</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Opinion: \"I agree → reason 1 → reason 2\" vs Discussion: \"Both views → View A → View B → I lean View B\"</p></div>","p":1},{"id":"W5D1-S-03","l":17,"t":"S","st":"Structure","s":2,"tags":["balance-rule","discussion"],"f":"<p>Balance rule trong Discussion essay là gì? Chênh lệch tối đa bao nhiêu từ?</p>","a":"","b":"<div class=\"sec\"><ul><li>Body 1 và Body 2 <b>PHẢI gần bằng nhau</b> về độ dài</li><li>Chênh lệch tối đa: <b>~20 từ</b></li><li>Nếu 1 đoạn dưới <b>70 từ</b> → examiner coi là <b>underdeveloped</b></li><li>Body lệch → mất điểm TA vì không \"fully discuss\" cả 2 views</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Body 1 = 95 từ, Body 2 = 90 từ → ✅ OK. Body 1 = 120 từ, Body 2 = 50 từ → ❌ lệch, mất TA</p></div>","p":1},{"id":"W5D1-S-04","l":17,"t":"S","st":"Structure","s":2,"tags":["opinion-placement","discussion"],"f":"<p>Opinion đặt ở đâu trong Discussion essay? Chuẩn Band 7.5+ (Integrated Position) viết Body 2 thế nào?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>2 cách đặt opinion</b>:</li></ul><ol><li><i>Cách 1 (Neutral):</i> Intro (lean nhẹ) → Body 1 &amp; 2 (khách quan) → Conclusion (khẳng định). Đạt 6.5-7.0.<div><i>Cách 2 (Integrated - Band 7.5+):</i> Body 1 trình bày View A khách quan; <b>Body 2 lồng ghép quan điểm cá nhân</b> giải thích vì sao View B thuyết phục hơn (<i>\"I find the arguments in favour of View B far more compelling...\"</i>).</div></li></ol><ul><li>Đảm bảo yêu cầu Band 7 TR: <b>\"presents a clear position throughout\"</b>.</li><li>⚠️ Quy tắc sống còn: Lập trường từ Intro, Body 2 và Conclusion phải <b>HOÀN TOÀN NHẤT QUÁN</b>.</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Intro lean View B → Body 2 ủng hộ View B → Conclusion khẳng định View B ✅. Tuyệt đối không mâu thuẫn giữa các đoạn.</p></div>","p":1},{"id":"W5D1-P-01","l":17,"t":"P","st":"Phrase","s":3,"tags":["thesis","discussion"],"f":"<p>______ (mặc dù cả hai quan điểm đều có giá trị), I believe that modern approaches are more effective.</p>","a":"<b>While both perspectives have merit</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"While both perspectives have merit, I tend to agree that technology brings more benefits than drawbacks to education.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"Although there are valid arguments on both sides\" | \"While each viewpoint has its strengths\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Introduction — thesis sentence cho Discussion essay</p></div>","p":1},{"id":"W5D1-P-02","l":17,"t":"P","st":"Phrase","s":3,"tags":["view-attribution","body"],"f":"<p>______ (những người ủng hộ giáo dục truyền thống lập luận rằng) structured lectures provide a solid academic foundation.</p>","a":"<b>Advocates of traditional education argue that</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Advocates of stricter regulations argue that they are necessary to protect public health.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"Those who support... argue that...\" | \"Proponents of... maintain that...\" | \"Supporters of... contend that...\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body 1 — mở đầu View A trong Discussion essay</p></div>","p":1},{"id":"W5D1-P-03","l":17,"t":"P","st":"Phrase","s":3,"tags":["view-attribution","transition","body"],"f":"<p>______ (mặt khác, những người ủng hộ giáo dục hiện đại cho rằng) interactive methods better prepare students.</p>","a":"<b>On the other hand, proponents of modern education contend that</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"On the other hand, proponents of flexible working hours contend that employees are more productive when given autonomy.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"Conversely, opponents argue that...\" | \"However, an alternative viewpoint suggests that...\" | \"In contrast, supporters of... point out that...\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body 2 — mở đầu View B, chuyển từ View A sang View B</p></div>","p":1},{"id":"W5D1-P-04","l":17,"t":"P","st":"Phrase","s":2,"tags":["collocation","body"],"f":"<p>Traditional lectures and textbooks provide a solid academic foundation that has ______ (đã trải qua thử thách của thời gian).</p>","a":"<b>stood the test of time</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The apprenticeship model has stood the test of time as an effective method of skills transfer.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"has proven effective over the years\" | \"has demonstrated lasting value\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về phương pháp/hệ thống đã tồn tại lâu và vẫn hiệu quả</p></div>","p":1},{"id":"W5D1-P-05","l":17,"t":"P","st":"Phrase","s":2,"tags":["collocation","conclusion"],"f":"<p>I ______ (có xu hướng tin rằng) modern approaches are more beneficial overall.</p>","a":"<b>am inclined to believe that</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Having considered both arguments, I am inclined to believe that renewable energy is the more sustainable option.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"tend to believe that\" | \"am of the opinion that\" | \"lean towards the view that\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Conclusion — nêu opinion trong Discussion essay (giọng học thuật, không quá mạnh)</p></div>","p":1},{"id":"W5D1-P-06","l":17,"t":"P","st":"Phrase","s":2,"tags":["collocation","body"],"f":"<p>Modern methods appear to cultivate a broader, more ______ (bộ kỹ năng đa dạng, linh hoạt).</p>","a":"<b>versatile skill set</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Internship programmes help graduates develop a versatile skill set that employers value highly.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"well-rounded set of competencies\" | \"diverse range of abilities\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về lợi ích giáo dục, đào tạo, phát triển kỹ năng</p></div>","p":1},{"id":"W5D1-E-01","l":17,"t":"E","st":"Error","s":3,"tags":["mistake","thesis","discussion"],"f":"<p><i>\"I strongly agree that traditional education is better than modern education.\"</i> — dùng cho Discussion essay. Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Thesis viết như Opinion essay — chọn phía ngay, không acknowledge view kia. Discussion cần trình bày CẢ HAI views.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"While both traditional and modern education have strengths, I believe traditional methods remain more effective for building core knowledge.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Thesis Discussion = acknowledge cả 2 views trước → rồi mới lean. Dùng \"While both... I believe...\" — KHÔNG dùng \"I agree/disagree\".</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA</p></div>","p":0},{"id":"W5D1-E-02","l":17,"t":"E","st":"Error","s":3,"tags":["mistake","balance","discussion"],"f":"<p><i>Discussion essay có Body 1 = 120 từ, Body 2 = 45 từ.</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Body không cân bằng — View B chỉ 45 từ = underdeveloped. Examiner coi là không \"fully discuss\" cả 2 views.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Body 1 ≈ 80-100 từ, Body 2 ≈ 80-100 từ. Chênh lệch ≤ 20 từ.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Discussion essay = BALANCE bắt buộc. Body dưới 70 từ = underdeveloped. Chênh lệch &gt; 20 từ = lệch.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA</p></div>","p":0},{"id":"W5D1-E-03","l":17,"t":"E","st":"Error","s":3,"tags":["mistake","opinion","discussion"],"f":"<p><i>Discussion essay: Introduction lean View A, nhưng Conclusion lean View B.</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Opinion mâu thuẫn giữa intro và conclusion. Examiner thấy \"position is inconsistent\" → không rõ bạn nghiêng phía nào.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Intro lean View B + Conclusion lean View B → nhất quán. Hoặc cả hai cùng lean View A.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Opinion trong Discussion phải NHẤT QUÁN — intro và conclusion lean cùng 1 phía. Đọc lại cả 2 trước khi nộp.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + CC</p></div>","p":0},{"id":"W5D1-E-04","l":17,"t":"E","st":"Error","s":2,"tags":["mistake","discussion"],"f":"<p><i>\"I think that traditional education is the best approach. I also think modern education is equally effective.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Đồng ý cả 2 views = fence-sitting → examiner coi là \"no clear position\". Discussion yêu cầu cho opinion = CHỌN 1 phía mạnh hơn.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"While both approaches have clear merits, I believe that modern education is ultimately more effective because it develops a broader range of skills.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Acknowledge cả 2 ≠ agree cả 2. Phải CHỌN 1 phía lean — dùng \"more effective / more convincing / outweigh\" để thể hiện.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA</p></div>","p":0},{"id":"W5D2-S-01","l":18,"t":"S","st":"Structure","s":3,"tags":["collocation","band-descriptor"],"f":"<p>Band 7 LR descriptor yêu cầu gì về collocation? (trích nguyên văn)</p>","a":"","b":"<div class=\"sec\"><blockquote><i>\"uses less common lexical items with <b>some awareness of style and collocation</b>\"</i></blockquote><p>Hai yêu cầu:</p><ul><li><b>less common lexical items</b> → không dùng \"good/bad/important\" → dùng \"pivotal/detrimental/fundamental\"</li><li><b>awareness of collocation</b> → biết từ nào đi với từ nào tự nhiên</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"play a pivotal <b>role</b>\" (✅) vs \"do a pivotal role\" (❌)</p></div>","p":1},{"id":"W5D2-S-02","l":18,"t":"S","st":"Structure","s":2,"tags":["collocation","upgrade-technique"],"f":"<p>Quy trình 3 bước upgrade câu Band 5 → Band 7 bằng collocation là gì?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Xác định ý cốt lõi</b> (core meaning) của câu</li><li><b>Tìm collocation</b> phù hợp topic</li><li><b>Điều chỉnh câu</b> cho tự nhiên</li></ol></div><div class=\"sec\"><span class=\"lbl\">VD</span><ul><li>Band 5: \"The government should help people know about health problems.\"</li><li>Core: raise awareness + health issues</li><li>Band 7: \"The government should <b>raise awareness</b> about pressing health issues through <b>public health campaigns</b>.\"</li></ul></div>","p":1},{"id":"W5D2-S-03","l":18,"t":"S","st":"Structure","s":2,"tags":["collocation","memory-technique"],"f":"<p>3 bước học collocation đúng cách (không quên sau 2 ngày) là gì?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Group by topic</b> → chọn 1 topic → highlight 3-5 cái MỚI</li><li><b>Write sentences</b> → viết 1 câu IELTS cho mỗi collocation mới → cố kết hợp 2 collocations/câu</li><li><b>Anki review</b> → review cards mỗi ngày ~5 phút</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"GWA — Group, Write, Anki.\" KHÔNG học thuộc list, học qua ngữ cảnh.</p></div>","p":1},{"id":"W5D2-P-01","l":18,"t":"P","st":"Phrase","s":3,"tags":["collocation","education"],"f":"<p>Modern education should ______ (nuôi dưỡng tư duy phản biện) rather than rote memorisation.</p>","a":"<b>nurture critical thinking</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"By encouraging debate and discussion, teachers can nurture critical thinking skills in their students.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"foster analytical thinking\" | \"develop critical reasoning\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về giáo dục, phương pháp dạy học.</p></div>","p":1},{"id":"W5D2-P-02","l":18,"t":"P","st":"Phrase","s":3,"tags":["collocation","health"],"f":"<p>Air pollution ______ (gây ra mối đe doạ lớn) to public health, particularly in urban areas.</p>","a":"<b>poses a significant threat</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The spread of antibiotic-resistant bacteria poses a significant threat to global healthcare systems.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"presents a serious risk\" | \"constitutes a major danger\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi mô tả tác hại/nguy hiểm của một vấn đề (Health, Environment, Technology).</p></div>","p":1},{"id":"W5D2-P-03","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","environment"],"f":"<p>International cooperation is crucial for ______ (giảm thiểu biến đổi khí hậu).</p>","a":"<b>climate change mitigation</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Investing in renewable energy is one of the most effective strategies for climate change mitigation.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"combating global warming\" | \"addressing climate change\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về môi trường, giải pháp cho biến đổi khí hậu.</p></div>","p":1},{"id":"W5D2-P-04","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","society"],"f":"<p>______ (Bất bình đẳng thu nhập) remains a pressing issue in many developing countries.</p>","a":"<b>Income inequality</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Governments must implement progressive tax policies to address the widening income inequality between social classes.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"wealth disparity\" | \"economic imbalance\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về vấn đề xã hội, kinh tế, chính sách thuế.</p></div>","p":1},{"id":"W5D2-P-05","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","technology"],"f":"<p>The ______ (khoảng cách số) prevents disadvantaged communities from accessing online education.</p>","a":"<b>digital divide</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Bridging the digital divide requires significant investment in rural internet infrastructure.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"technology gap\" | \"digital inequality\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về công nghệ, bất bình đẳng trong tiếp cận kỹ thuật số.</p></div>","p":1},{"id":"W5D2-P-06","l":18,"t":"P","st":"Phrase","s":3,"tags":["collocation","health"],"f":"<p>Many office workers ______ (sống lối sống ít vận động), which increases the risk of chronic diseases.</p>","a":"<b>lead a sedentary lifestyle</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The growing number of people who lead a sedentary lifestyle has contributed to rising obesity rates worldwide.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"live an inactive life\" | \"maintain a physically passive lifestyle\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về sức khoẻ, lối sống hiện đại, tác hại của công nghệ.</p></div>","p":1},{"id":"W5D2-P-07","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","education"],"f":"<p>Technology can ______ (thu hẹp khoảng cách) between urban and rural education.</p>","a":"<b>bridge the gap</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Online learning platforms have the potential to bridge the gap between students in developed and developing nations.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"narrow the divide\" | \"close the disparity\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về giải pháp giảm bất bình đẳng (Education, Society, Technology).</p></div>","p":1},{"id":"W5D2-P-08","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","education"],"f":"<p>Students ______ (tiếp thu kiến thức) more effectively through interactive activities.</p>","a":"<b>acquire knowledge</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Experiential learning allows students to acquire knowledge more effectively than passive listening.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"gain knowledge\" | \"absorb information\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Education essays — nâng cấp từ \"learn things\".</p></div>","p":1},{"id":"W5D2-P-09","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","education"],"f":"<p>Studying in a foreign country helps young people ______ (mở rộng tầm nhìn).</p>","a":"<b>broaden their horizons</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"International exchange programmes encourage students to broaden their horizons and appreciate diverse cultures.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"expand their perspectives\" | \"widen their worldview\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Education / Travel / Culture essays.</p></div>","p":1},{"id":"W5D2-P-10","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","education"],"f":"<p>Many high school graduates choose to ______ (theo đuổi giáo dục đại học) to secure better employment.</p>","a":"<b>pursue higher education</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Financial assistance should be provided to disadvantaged students wishing to pursue higher education.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"enrol in tertiary education\" | \"attend university\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Education / Youth / Career essays.</p></div>","p":1},{"id":"W5D2-P-11","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","education"],"f":"<p>Arts and music curricula are essential because they ______ (thúc đẩy sự sáng tạo) in young learners.</p>","a":"<b>foster creativity</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"An open educational environment fosters creativity and encourages independent problem-solving.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"stimulate imagination\" | \"cultivate creative thinking\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Education / School curriculum essays.</p></div>","p":1},{"id":"W5D2-P-12","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","education"],"f":"<p>In an era of rapid technological shifts, ______ (học tập suốt đời) has become an absolute necessity.</p>","a":"<b>lifelong learning</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Governments should promote lifelong learning by subsidising adult vocational training schemes.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"continuous education\" | \"ongoing professional development\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Education / Employment / Modern society essays.</p></div>","p":1},{"id":"W5D2-P-13","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","health"],"f":"<p>Health authorities urge citizens to ______ (áp dụng chế độ ăn cân bằng) rich in nutrients.</p>","a":"<b>adopt a balanced diet</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Schools must teach children how to adopt a balanced diet to prevent childhood obesity.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"maintain a healthy nutritional regimen\" | \"follow a nutritious diet\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Health / Diet / Lifestyle essays.</p></div>","p":1},{"id":"W5D2-P-14","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","health"],"f":"<p>Investing in ______ (các biện pháp phòng ngừa) is far more cost-effective than treating illnesses.</p>","a":"<b>preventive measures</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Governments should allocate more funds to preventive measures such as vaccination programmes.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"proactive interventions\" | \"precautionary steps\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Healthcare / Government spending essays.</p></div>","p":1},{"id":"W5D2-P-15","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","health"],"f":"<p>Poor dietary habits and inactivity are primary drivers of ______ (các bệnh mãn tính).</p>","a":"<b>chronic diseases</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Non-communicable chronic diseases like diabetes place an enormous strain on public healthcare systems.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"long-term illnesses\" | \"persistent medical conditions\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Health / Lifestyle / Public expenditure essays.</p></div>","p":1},{"id":"W5D2-P-16","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","health"],"f":"<p>Breakthroughs in medical science have substantially increased human ______ (tuổi thọ trung bình).</p>","a":"<b>life expectancy</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"While global life expectancy has risen, ensuring a high quality of life in old age remains a challenge.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"average lifespan\" | \"longevity\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Health / Demographics / Ageing population essays.</p></div>","p":1},{"id":"W5D2-P-17","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","health"],"f":"<p>Well-designed ______ (các chiến dịch sức khoẻ cộng đồng) are vital to educate citizens on hygiene.</p>","a":"<b>public health campaigns</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Effective public health campaigns have successfully lowered smoking rates in many developed countries.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"health awareness initiatives\" | \"state health drives\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Health / Government role essays.</p></div>","p":1},{"id":"W5D2-P-18","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","environment"],"f":"<p>Stricter industrial regulations are imperative to curb ______ (lượng khí thải carbon).</p>","a":"<b>carbon emissions</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Taxing heavy polluters provides a financial incentive to diminish carbon emissions significantly.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"greenhouse gas emissions\" | \"carbon footprint\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Environment / Climate change / Energy essays.</p></div>","p":1},{"id":"W5D2-P-19","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","environment"],"f":"<p>Policies must align industrial growth with the principles of ______ (phát triển bền vững).</p>","a":"<b>sustainable development</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Sustainable development requires balancing immediate economic gains with long-term ecological preservation.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"environmentally sound growth\" | \"green progress\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Environment / Economy / Urban planning essays.</p></div>","p":1},{"id":"W5D2-P-20","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","environment"],"f":"<p>Phasing out fossil fuels in favour of ______ (các nguồn năng lượng tái tạo) is paramount.</p>","a":"<b>renewable energy sources</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Subsidising renewable energy sources such as solar and wind power will accelerate decarbonisation.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"clean energy alternatives\" | \"green energy solutions\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Energy / Environment / Technology essays.</p></div>","p":1},{"id":"W5D2-P-21","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","environment"],"f":"<p>Individuals can minimise their ______ (dấu chân sinh thái) by reducing single-use plastic consumption.</p>","a":"<b>ecological footprint</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Adopting public transit allows urban residents to dramatically diminish their ecological footprint.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"environmental impact\" | \"carbon footprint\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Individual responsibility vs Government in environment essays.</p></div>","p":1},{"id":"W5D2-P-22","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","environment"],"f":"<p>Rapid industrialisation without oversight precipitates severe ______ (suy thoái môi trường).</p>","a":"<b>environmental degradation</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Soil contamination and water pollution are alarming symptoms of widespread environmental degradation.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"ecological deterioration\" | \"environmental damage\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Environment / Industrialisation essays.</p></div>","p":1},{"id":"W5D2-P-23","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","environment"],"f":"<p>Deforestation in rainforests directly results in catastrophic ______ (sự suy giảm đa dạng sinh học).</p>","a":"<b>biodiversity loss</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Habitat destruction is the single most pressing driver of global biodiversity loss.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"species extinction\" | \"loss of wildlife species\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Environment / Conservation essays.</p></div>","p":1},{"id":"W5D2-P-24","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","technology"],"f":"<p>Unequal internet access exacerbates the ______ (khoảng cách số) between wealthy and impoverished areas.</p>","a":"<b>digital divide</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Providing free laptops to rural schools is essential to bridge the digital divide.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"technological disparity\" | \"digital inequality\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Technology / Education / Social inequality essays.</p></div>","p":1},{"id":"W5D2-P-25","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","technology"],"f":"<p>The widespread integration of ______ (trí tuệ nhân tạo) is reshaping modern employment.</p>","a":"<b>artificial intelligence</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Artificial intelligence algorithms can now diagnose diseases with accuracy comparable to human doctors.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"machine learning systems\" | \"automated cognitive systems\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Technology / AI / Future of work essays.</p></div>","p":1},{"id":"W5D2-P-26","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","technology"],"f":"<p>The commercial exploitation of user information has triggered profound concerns about ______ (quyền riêng tư dữ liệu).</p>","a":"<b>data privacy</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Governments must enforce rigorous legislation to safeguard individual data privacy online.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"information confidentiality\" | \"digital privacy\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Technology / Social media / Civil liberties essays.</p></div>","p":1},{"id":"W5D2-P-27","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","technology"],"f":"<p>Modern educational curricula must prioritise ______ (hiểu biết/năng lực kỹ thuật số) alongside literacy.</p>","a":"<b>digital literacy</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Equipping senior citizens with digital literacy empowers them to access vital online public services.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"technological competence\" | \"computer literacy\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Technology / Education / Ageing population essays.</p></div>","p":1},{"id":"W5D2-P-28","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","society"],"f":"<p>Widening income disparities can seriously erode ______ (sự gắn kết xã hội) and trust among citizens.</p>","a":"<b>social cohesion</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Community-led sports events and public festivals foster social cohesion in multicultural neighbourhoods.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"social harmony\" | \"societal solidarity\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Society / Inequality / Crime essays.</p></div>","p":1},{"id":"W5D2-P-29","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","society"],"f":"<p>Embracing ______ (sự đa dạng văn hoá) enriches the artistic and economic fabric of global cities.</p>","a":"<b>cultural diversity</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Workplace productivity often improves when teams draw strength from cultural diversity.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"multiculturalism\" | \"ethnic variety\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Globalization / Migration / Society essays.</p></div>","p":1},{"id":"W5D2-P-30","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","society"],"f":"<p>Dismantling the gender wage gap is fundamental to achieving genuine ______ (bình đẳng giới).</p>","a":"<b>gender equality</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Encouraging female enrolment in STEM disciplines is an effective measure towards gender equality.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"gender parity\" | \"equal opportunities for men and women\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Society / Employment / Rights essays.</p></div>","p":1},{"id":"W5D2-P-31","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","society"],"f":"<p>A declining birth rate combined with an ______ (dân số già hoá) places acute pressure on pension schemes.</p>","a":"<b>ageing population</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Societies facing an ageing population must reform retirement policies and expand geriatric healthcare.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"greying demographic\" | \"elderly population\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Demographics / Economy / Healthcare essays.</p></div>","p":1},{"id":"W5D2-P-32","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","society"],"f":"<p>Proactive community policing serves as a cornerstone of effective ______ (phòng chống tội phạm).</p>","a":"<b>crime prevention</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Investing in youth recreation centres yields better crime prevention outcomes than harsher punitive sentences.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"deterring criminal behaviour\" | \"crime deterrence\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Crime / Law enforcement / Social spending essays.</p></div>","p":1},{"id":"W5D2-E-01","l":18,"t":"E","st":"Error","s":3,"tags":["mistake","collocation"],"f":"<p><i>\"Pollution is very bad for people and we need to stop it.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Dùng từ chung chung \"very bad\" — đây là từ vựng Band 5, thiếu collocation học thuật.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Air pollution <b>poses a significant threat</b> to public health, and governments must implement stricter regulations to address it.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Tránh dùng \"very + adj đơn giản\" (very bad, very good, very important). Thay bằng collocation cụ thể theo topic.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR</p></div>","p":0},{"id":"W5D2-E-02","l":18,"t":"E","st":"Error","s":3,"tags":["mistake","collocation-context"],"f":"<p><i>\"The government should adopt a new technology to improve education.\"</i> — Collocation nào dùng sai context?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"adopt\" KHÔNG đi với \"technology\" trong tiếng Anh học thuật. \"Adopt\" dùng với policies, diets, approaches — KHÔNG dùng với technology.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The government should <b>embrace</b> / <b>implement</b> new technology to improve education.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Collocation PHẢI đúng context. Khi không chắc, dùng cách nói đơn giản hơn mà CHẮC CHẮN. Band 6 chắc chắn &gt; Band 7 sai.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR</p></div>","p":0},{"id":"W5D2-E-03","l":18,"t":"E","st":"Error","s":2,"tags":["mistake","collocation-context"],"f":"<p><i>\"Schools should raise a concern about the quality of teaching.\"</i> — Collocation nào dùng sai?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"raise a concern\" — sai collocation. Nói đúng là \"<b>raise</b> awareness\" hoặc \"<b>express</b> a concern\" / \"<b>raise</b> concerns\" (số nhiều, không có \"a\").</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Schools should <b>raise concerns</b> about the quality of teaching.\" hoặc \"Schools should <b>express concern</b> about the quality of teaching.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Mỗi collocation có pattern cố định — thay đổi 1 từ nhỏ (a/the, số ít/nhiều) cũng có thể sai.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR</p></div>","p":0},{"id":"W5D2-E-04","l":18,"t":"E","st":"Error","s":3,"tags":["mistake","band5-vocabulary"],"f":"<p><i>\"People should eat healthy food and exercise more to be healthy.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Lặp \"healthy\" 2 lần + dùng toàn từ chung chung (\"eat healthy food\", \"exercise more\") — thiếu collocations, giống Band 5.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Individuals should <b>adopt a balanced diet</b> and engage in regular physical activity to improve their overall <b>mental well-being</b> and prevent <b>chronic diseases</b>.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Mỗi câu cố gắng dùng ≥1 collocation. Tránh lặp từ — dùng synonym hoặc collocation thay thế.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR + GRA</p></div>","p":0},{"id":"W5D2-P-51","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","education"],"f":"<p>Schools should ______ ______ (nâng cao nhận thức) about environmental issues.</p>","a":"<b>raise awareness</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Schools should raise awareness about environmental issues through dedicated sustainability programmes.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"heighten awareness\" | \"promote awareness\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về giải pháp giáo dục/truyền thông cho một vấn đề (Education, Environment, Health).</p></div>","p":1},{"id":"W5D2-P-52","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","education"],"f":"<p>Students ______ ______ (tiếp thu kiến thức) more effectively through hands-on activities.</p>","a":"<b>acquire knowledge</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Learners acquire knowledge more effectively when they apply concepts in practical settings.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"gain knowledge\" | \"absorb information\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi bàn về phương pháp học tập, chất lượng giáo dục.</p></div>","p":1},{"id":"W5D2-P-53","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","education"],"f":"<p>Studying abroad helps students ______ ______ ______ (mở rộng tầm nhìn).</p>","a":"<b>broaden their horizons</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Exposure to different cultures allows young people to broaden their horizons and develop greater tolerance.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"expand their outlook\" | \"widen their perspective\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về lợi ích của du học, giao lưu văn hoá, trải nghiệm quốc tế.</p></div>","p":1},{"id":"W5D2-P-54","l":18,"t":"P","st":"Phrase","s":3,"tags":["collocation","education"],"f":"<p>Governments need to ______ ______ ______ (thực hiện cải cách giáo dục) to address skill gaps.</p>","a":"<b>implement educational reforms</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Countries that implement educational reforms early tend to close skills gaps more rapidly.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"introduce educational reforms\" | \"carry out curriculum reform\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph / Solutions — khi đề xuất giải pháp ở tầm chính sách cho giáo dục.</p></div>","p":1},{"id":"W5D2-P-55","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","education"],"f":"<p>Many young people ______ ______ ______ (theo đuổi giáo dục đại học) to improve career prospects.</p>","a":"<b>pursue higher education</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"A growing number of school-leavers choose to pursue higher education despite rising tuition costs.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"undertake university studies\" | \"enrol in tertiary education\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về lựa chọn sau trung học, học phí, giá trị bằng đại học.</p></div>","p":1},{"id":"W5D2-P-56","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","education"],"f":"<p>Parental involvement plays a key role in ______ ______ (thành tích học tập).</p>","a":"<b>academic achievement</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Socioeconomic background remains one of the strongest predictors of academic achievement.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"academic performance\" | \"scholastic attainment\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi bàn về yếu tố ảnh hưởng kết quả học tập.</p></div>","p":1},{"id":"W5D2-P-57","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","education"],"f":"<p>Arts education ______ ______ (thúc đẩy sáng tạo) and innovation.</p>","a":"<b>fosters creativity</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"A well-designed curriculum fosters creativity alongside technical competence.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"stimulates creativity\" | \"encourages innovation\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi bảo vệ vai trò của nghệ thuật, thể thao trong giáo dục.</p></div>","p":1},{"id":"W5D2-P-58","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","education"],"f":"<p>In a rapidly changing world, ______ ______ (học tập suốt đời) is essential.</p>","a":"<b>lifelong learning</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Automation makes lifelong learning a necessity rather than an option.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"continuous learning\" | \"ongoing education\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về thích nghi với thay đổi công nghệ, đào tạo lại nghề.</p></div>","p":1},{"id":"W5D2-P-59","l":18,"t":"P","st":"Phrase","s":3,"tags":["collocation","health"],"f":"<p>Social media can negatively affect ______ ______ (sức khoẻ tinh thần) among teenagers.</p>","a":"<b>mental well-being</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Regular physical activity has a measurable impact on mental well-being.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"psychological well-being\" | \"emotional health\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về sức khoẻ tâm thần, mạng xã hội, áp lực học đường.</p></div>","p":1},{"id":"W5D2-P-60","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","health"],"f":"<p>Health campaigns encourage people to ______ ______ ______ ______ (áp dụng chế độ ăn cân bằng).</p>","a":"<b>adopt a balanced diet</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Schools can encourage children to adopt a balanced diet from an early age.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"maintain a balanced diet\" | \"follow a nutritious diet\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về dinh dưỡng, béo phì, giáo dục sức khoẻ.</p></div>","p":1},{"id":"W5D2-P-61","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","health"],"f":"<p>Investing in ______ ______ (biện pháp phòng ngừa) can reduce healthcare costs.</p>","a":"<b>preventive measures</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Governments that prioritise preventive measures spend considerably less on acute care.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"preventative measures\" | \"proactive healthcare\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph / Solutions — khi đề xuất giải pháp y tế dự phòng.</p></div>","p":1},{"id":"W5D2-P-62","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","health"],"f":"<p>Poor lifestyle choices contribute to the rise of ______ ______ (bệnh mãn tính).</p>","a":"<b>chronic diseases</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The burden of chronic diseases is growing fastest in low-income countries.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"chronic illnesses\" | \"long-term conditions\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về nguyên nhân bệnh tật, chi phí y tế dài hạn.</p></div>","p":1},{"id":"W5D2-P-63","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","health"],"f":"<p>Improving ______ ______ (cung cấp dịch vụ y tế) in rural areas remains a challenge.</p>","a":"<b>healthcare provision</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Unequal healthcare provision between urban and rural regions remains a persistent problem.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"healthcare delivery\" | \"medical services\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về bất bình đẳng y tế, chính sách công.</p></div>","p":1},{"id":"W5D2-P-64","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","health"],"f":"<p>______ ______ (thiếu hoạt động thể chất) is a leading risk factor for cardiovascular disease.</p>","a":"<b>Physical inactivity</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Physical inactivity has been described as a silent pandemic of the modern era.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"a lack of physical activity\" | \"sedentary behaviour\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về nguyên nhân bệnh tật, thói quen sinh hoạt.</p></div>","p":1},{"id":"W5D2-P-65","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","health"],"f":"<p>Advances in medicine have significantly increased ______ ______ (tuổi thọ trung bình).</p>","a":"<b>life expectancy</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Rising life expectancy places new demands on pension and care systems.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"average lifespan\" | \"longevity\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về dân số già, tiến bộ y học, chi phí hưu trí.</p></div>","p":1},{"id":"W5D2-P-66","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","health"],"f":"<p>______ ______ ______ (chiến dịch sức khoẻ cộng đồng) play a vital role in disease prevention.</p>","a":"<b>Public health campaigns</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Public health campaigns were instrumental in reducing smoking rates across many countries.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"public health initiatives\" | \"awareness campaigns\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph / Solutions — khi đề xuất giải pháp nâng cao nhận thức sức khoẻ.</p></div>","p":1},{"id":"W5D2-P-67","l":18,"t":"P","st":"Phrase","s":3,"tags":["collocation","environment"],"f":"<p>Governments must take action to reduce ______ ______ (khí thải carbon).</p>","a":"<b>carbon emissions</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Cutting carbon emissions requires coordinated action across transport, industry and energy.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"carbon output\" | \"greenhouse gas emissions\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về biến đổi khí hậu, năng lượng, giao thông.</p></div>","p":1},{"id":"W5D2-P-68","l":18,"t":"P","st":"Phrase","s":3,"tags":["collocation","environment"],"f":"<p>______ ______ (phát triển bền vững) balances economic growth with environmental protection.</p>","a":"<b>Sustainable development</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Sustainable development aims to meet present needs without compromising future generations.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"sustainable growth\" | \"environmentally responsible development\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về cân bằng kinh tế và môi trường, chính sách dài hạn.</p></div>","p":1},{"id":"W5D2-P-69","l":18,"t":"P","st":"Phrase","s":3,"tags":["collocation","environment"],"f":"<p>Investing in ______ ______ ______ (nguồn năng lượng tái tạo) is essential for combating climate change.</p>","a":"<b>renewable energy sources</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Transitioning to renewable energy sources reduces long-term dependence on fossil fuels.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"clean energy sources\" | \"sustainable energy\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph / Solutions — khi đề xuất giải pháp năng lượng.</p></div>","p":1},{"id":"W5D2-P-70","l":18,"t":"P","st":"Phrase","s":3,"tags":["collocation","environment"],"f":"<p>Individuals should reduce their ______ ______ (dấu chân sinh thái) by consuming less.</p>","a":"<b>ecological footprint</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Urban populations tend to have a larger ecological footprint than rural communities.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"environmental footprint\" | \"carbon footprint\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về trách nhiệm cá nhân với môi trường.</p></div>","p":1},{"id":"W5D2-P-71","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","environment"],"f":"<p>Overexploitation of ______ ______ (tài nguyên thiên nhiên) leads to environmental degradation.</p>","a":"<b>natural resources</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Rapid industrialisation has placed immense pressure on natural resources.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"environmental resources\" | \"raw materials\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về khai thác quá mức, tăng trưởng công nghiệp.</p></div>","p":1},{"id":"W5D2-P-72","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","environment"],"f":"<p>Deforestation is a major cause of ______ ______ (suy thoái môi trường).</p>","a":"<b>environmental degradation</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Unregulated mining has accelerated environmental degradation in many regions.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"environmental damage\" | \"ecological deterioration\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi mô tả hậu quả của hoạt động con người.</p></div>","p":1},{"id":"W5D2-P-73","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","environment"],"f":"<p>Effective ______ ______ (quản lý chất thải) systems can reduce landfill pollution.</p>","a":"<b>waste management</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Improved waste management is one of the most cost-effective environmental policies.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"waste disposal\" | \"refuse management\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph / Solutions — khi đề xuất giải pháp ô nhiễm, tái chế.</p></div>","p":1},{"id":"W5D2-P-74","l":18,"t":"P","st":"Phrase","s":3,"tags":["collocation","environment"],"f":"<p>Urbanisation contributes to ______ ______ (mất đa dạng sinh học) in natural habitats.</p>","a":"<b>biodiversity loss</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Habitat destruction is the single largest driver of biodiversity loss worldwide.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"loss of biodiversity\" | \"decline in species diversity\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về bảo tồn, mở rộng đô thị, nông nghiệp.</p></div>","p":1},{"id":"W5D2-P-75","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","environment"],"f":"<p>______ ______ (nỗ lực bảo tồn) have helped endangered species recover.</p>","a":"<b>Conservation efforts</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Sustained conservation efforts have brought several species back from the brink of extinction.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"preservation efforts\" | \"protection measures\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về bảo vệ động vật, khu bảo tồn, thành công của chính sách.</p></div>","p":1},{"id":"W5D2-P-76","l":18,"t":"P","st":"Phrase","s":3,"tags":["collocation","technology"],"f":"<p>______ ______ (trí tuệ nhân tạo) is transforming industries worldwide.</p>","a":"<b>Artificial intelligence</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Artificial intelligence is reshaping everything from diagnostics to customer service.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"machine intelligence\" | \"AI systems\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về tự động hoá, việc làm, đổi mới công nghệ.</p></div>","p":1},{"id":"W5D2-P-77","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","technology"],"f":"<p>Concerns about ______ ______ (quyền riêng tư dữ liệu) have increased with the growth of social media.</p>","a":"<b>data privacy</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Regulators are struggling to keep pace with evolving data privacy challenges.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"data protection\" | \"information privacy\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về quyền cá nhân, luật công nghệ, mạng xã hội.</p></div>","p":1},{"id":"W5D2-P-78","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","technology"],"f":"<p>______ ______ (tiến bộ công nghệ) has revolutionised the way people communicate.</p>","a":"<b>Technological advancement</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Technological advancement has compressed decades of change into a few short years.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"technological progress\" | \"technological innovation\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi mở đầu đoạn về thay đổi công nghệ.</p></div>","p":1},{"id":"W5D2-P-79","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","technology"],"f":"<p>______ ______ ______ (nền tảng mạng xã hội) can spread misinformation rapidly.</p>","a":"<b>Social media platforms</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Social media platforms have become primary sources of news for younger generations.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"social networking sites\" | \"online platforms\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về truyền thông, tin giả, ảnh hưởng giới trẻ.</p></div>","p":1},{"id":"W5D2-P-80","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","technology"],"f":"<p>______ ______ (kết nối trực tuyến) enables remote work and distance learning.</p>","a":"<b>Online connectivity</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Reliable online connectivity is now as essential as electricity for many households.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"internet access\" | \"digital connectivity\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về làm việc từ xa, học trực tuyến, hạ tầng số.</p></div>","p":1},{"id":"W5D2-P-81","l":18,"t":"P","st":"Phrase","s":3,"tags":["collocation","technology"],"f":"<p>Businesses face growing ______ ______ (mối đe doạ an ninh mạng) in the digital age.</p>","a":"<b>cybersecurity threats</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Cybersecurity threats now target healthcare and utility providers, not just banks.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"cyber threats\" | \"online security risks\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về rủi ro công nghệ, tội phạm mạng.</p></div>","p":1},{"id":"W5D2-P-82","l":18,"t":"P","st":"Phrase","s":3,"tags":["collocation","technology"],"f":"<p>The ______ ______ ______ (tự động hoá công việc) may lead to job displacement in certain sectors.</p>","a":"<b>automation of tasks</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The automation of tasks has eliminated some roles while creating entirely new ones.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"task automation\" | \"workplace automation\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về thất nghiệp do công nghệ, đào tạo lại kỹ năng.</p></div>","p":1},{"id":"W5D2-P-83","l":18,"t":"P","st":"Phrase","s":3,"tags":["collocation","technology"],"f":"<p>Schools should prioritise ______ ______ (hiểu biết kỹ thuật số) alongside traditional subjects.</p>","a":"<b>digital literacy</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Digital literacy is now as fundamental as numeracy for full participation in society.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"digital skills\" | \"technological competence\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về kỹ năng cần thiết, cải cách giáo dục.</p></div>","p":1},{"id":"W5D2-P-84","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","technology"],"f":"<p>______ ______ (quá tải thông tin) can hinder effective decision-making.</p>","a":"<b>Information overload</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Information overload makes it harder to distinguish reliable sources from unreliable ones.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"information saturation\" | \"data overload\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về tác động tiêu cực của công nghệ, sự tập trung.</p></div>","p":1},{"id":"W5D2-P-85","l":18,"t":"P","st":"Phrase","s":3,"tags":["collocation","society"],"f":"<p>Cultural events promote ______ ______ (gắn kết xã hội) within communities.</p>","a":"<b>social cohesion</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Shared public spaces play a quiet but vital role in maintaining social cohesion.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"social solidarity\" | \"community bonds\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về cộng đồng, đa văn hoá, ổn định xã hội.</p></div>","p":1},{"id":"W5D2-P-86","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","society"],"f":"<p>______ ______ (đa dạng văn hoá) enriches society and fosters innovation.</p>","a":"<b>Cultural diversity</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Cultural diversity brings a wider range of perspectives to problem-solving.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"multiculturalism\" | \"cultural plurality\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về nhập cư, toàn cầu hoá, bản sắc.</p></div>","p":1},{"id":"W5D2-P-87","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","society"],"f":"<p>Achieving ______ ______ (bình đẳng giới) requires systemic changes in education and employment.</p>","a":"<b>gender equality</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Gender equality in the workplace correlates strongly with overall economic productivity.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"gender parity\" | \"equal opportunities\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về quyền phụ nữ, việc làm, giáo dục.</p></div>","p":1},{"id":"W5D2-P-88","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","society"],"f":"<p>______ ______ (di cư đô thị) puts pressure on housing and public services.</p>","a":"<b>Urban migration</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Rapid urban migration has outpaced infrastructure development in many megacities.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"rural-to-urban migration\" | \"urbanisation\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về đô thị hoá, nhà ở, hạ tầng.</p></div>","p":1},{"id":"W5D2-P-89","l":18,"t":"P","st":"Phrase","s":3,"tags":["collocation","society"],"f":"<p>An ______ ______ (dân số già hoá) poses challenges for healthcare and pension systems.</p>","a":"<b>ageing population</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"An ageing population places a double burden on a shrinking workforce.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"greying population\" | \"demographic ageing\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về nhân khẩu học, lương hưu, chăm sóc sức khoẻ.</p></div>","p":1},{"id":"W5D2-P-90","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","society"],"f":"<p>Community policing is an effective approach to ______ ______ (phòng chống tội phạm).</p>","a":"<b>crime prevention</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Investment in youth services is one of the most effective forms of crime prevention.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"crime reduction\" | \"tackling crime\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về an ninh, hình phạt, tái hoà nhập.</p></div>","p":1},{"id":"W5D2-P-91","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","society"],"f":"<p>Investment in education drives long-term ______ ______ (phát triển kinh tế).</p>","a":"<b>economic development</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Sustained economic development depends on a well-educated workforce.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"economic growth\" | \"economic progress\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về đầu tư, việc làm, chính sách phát triển.</p></div>","p":1},{"id":"W5D2-P-92","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","society"],"f":"<p>______ ______ (sự tham gia cộng đồng) is essential for the success of local initiatives.</p>","a":"<b>Community engagement</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Community engagement often determines whether a public project succeeds or stalls.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"civic participation\" | \"public involvement\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về vai trò công dân, chính sách địa phương.</p></div>","p":1},{"id":"W5D2-P-93","l":18,"t":"P","st":"Phrase","s":2,"tags":["collocation","society"],"f":"<p>Access to green spaces significantly improves ______ ______ ______ (chất lượng cuộc sống).</p>","a":"<b>quality of life</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Beyond income, factors such as safety and green space shape overall quality of life.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"standard of living\" | \"living standards\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về đô thị, sức khoẻ cộng đồng, phúc lợi.</p></div>","p":1},{"id":"W5D3-S-01","l":19,"t":"S","st":"Structure","s":3,"tags":["paraphrase","technique"],"f":"<p>4 kỹ thuật paraphrase nâng cao là gì? Xếp theo độ khó.</p>","a":"","b":"<div class=\"sec\"><ol><li><b>T1 — Synonym Replacement</b> ★☆☆: Đổi từ chính bằng synonym phù hợp context</li><li><b>T2 — Word Form Change</b> ★★☆: Đổi noun↔verb↔adj↔adv → thay đổi cấu trúc câu</li><li><b>T3 — Clause Restructuring</b> ★★★: Active↔passive, đổi thứ tự clause, gộp/tách câu</li><li><b>T4 — Combination</b> ★★★: Kết hợp 2-3 techniques → paraphrase mạnh nhất</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Many people move to cities\" → T4: \"<b>Urban migration</b> has become increasingly <b>prevalent</b> in recent decades.\" (T1+T2+T3)</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"S-W-C-Combo\" — Synonym → Word form → Clause → Combo. Càng lên cao càng mạnh.</p></div>","p":1},{"id":"W5D3-S-02","l":19,"t":"S","st":"Structure","s":2,"tags":["paraphrase","word-form"],"f":"<p>Technique 2 — Word Form Change hoạt động thế nào? Cho ví dụ.</p>","a":"","b":"<div class=\"sec\"><ul><li>Đổi <b>loại từ</b> (noun↔verb↔adj↔adv) → câu thay đổi cấu trúc mà giữ nghĩa</li><li>Thường biến SVO → <b>noun phrase</b> (academic hơn)</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Children <b>develop</b> quickly when they play.\" → \"The rapid <b>development</b> of children is facilitated by play.\" (verb→noun)</p></div>","p":1},{"id":"W5D3-S-03","l":19,"t":"S","st":"Structure","s":2,"tags":["paraphrase","clause-restructuring"],"f":"<p>Technique 3 — Clause Restructuring có mấy cách? Kể tên.</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Active → Passive</b>: Đổi chủ ngữ, nhấn mạnh object</li><li><b>Clause reorder</b>: Đưa subordinate clause lên trước</li><li><b>Sentence split/merge</b>: Tách 1 câu dài → 2 ngắn, hoặc gộp 2 → 1</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"The government should ban smoking.\" → \"Smoking should be <b>prohibited</b> by authorities.\" (active→passive + T1)</p></div>","p":1},{"id":"W5D3-S-04","l":19,"t":"S","st":"Structure","s":3,"tags":["paraphrase","tees","summary"],"f":"<p>Câu Summary (S) trong TEES phải paraphrase thế nào so với Topic sentence (T)?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>KHÔNG copy</b> Topic sentence — phải paraphrase bằng synonym + word form + restructure</li><li>Đổi ít nhất <b>từ vựng + cấu trúc</b> (T1 + T2 hoặc T3)</li></ul></div><div class=\"sec\"><span class=\"lbl\">VD</span><ul><li><b>T:</b> \"Public transport reduces traffic congestion.\"</li><li><b>S:</b> \"Consequently, efficient transit systems can significantly <b>alleviate</b> urban <b>gridlock</b>.\"</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Nếu S đọc giống T → Band 5. S đọc khác T nhưng cùng ý → Band 7.</p></div>","p":1},{"id":"W5D3-P-01","l":19,"t":"P","st":"Phrase","s":2,"tags":["paraphrase","synonym","introduction"],"f":"<p>The most effective approach to crime prevention is ______ (chủ đề gây nhiều tranh luận).</p>","a":"<b>a subject of considerable debate</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Whether university education should be free remains a subject of considerable debate among policymakers.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"a contentious issue\" | \"a widely debated topic\" | \"a matter of ongoing discussion\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Introduction — câu 1 paraphrase đề bài, mở đầu bài Discussion/Opinion</p></div>","p":1},{"id":"W5D3-P-02","l":19,"t":"P","st":"Phrase","s":2,"tags":["paraphrase","synonym","introduction"],"f":"<p>The steadily growing proportion of senior citizens has ______ (gây ra tranh luận về) its societal implications.</p>","a":"<b>sparked debate over</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The rapid expansion of social media has sparked debate over its impact on mental well-being.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"generated discussion about\" | \"raised questions regarding\" | \"prompted concerns about\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Introduction — khi paraphrase đề bài có 2 quan điểm đối lập</p></div>","p":1},{"id":"W5D3-P-03","l":19,"t":"P","st":"Phrase","s":3,"tags":["paraphrase","synonym","body"],"f":"<p>Academic qualifications remain ______ (đóng vai trò quan trọng trong việc) enhancing career prospects.</p>","a":"<b>instrumental in</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Parental involvement is instrumental in shaping a child's attitude towards education.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"pivotal in\" | \"essential for\" | \"crucial to\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi nói về vai trò/tầm quan trọng của 1 yếu tố</p></div>","p":1},{"id":"W5D3-P-04","l":19,"t":"P","st":"Phrase","s":2,"tags":["paraphrase","synonym","general"],"f":"<p>______ (ngày càng nhiều) individuals are choosing to work remotely.</p>","a":"<b>An increasing number of</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"An increasing number of young people pursue higher education to improve career prospects.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"A growing proportion of\" | \"A rising number of\" | \"A considerable number of\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Bất kỳ đâu — thay thế \"more and more\" (Band 5) → academic hơn</p></div>","p":1},{"id":"W5D3-P-05","l":19,"t":"P","st":"Phrase","s":2,"tags":["paraphrase","synonym","general"],"f":"<p>Excessive screen time is ______ (có hại cho) children's cognitive development.</p>","a":"<b>detrimental to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Physical inactivity is detrimental to both mental well-being and long-term health outcomes.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"harmful to\" | \"damaging to\" | \"injurious to\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — thay thế \"bad for\" (Band 5) → Band 7 paraphrase</p></div>","p":1},{"id":"W5D3-P-06","l":19,"t":"P","st":"Phrase","s":2,"tags":["paraphrase","synonym","cause-effect"],"f":"<p>Rapid urbanisation has ______ (dẫn đến) significant environmental challenges.</p>","a":"<b>given rise to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The automation of tasks has given rise to growing concerns about widespread job displacement.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"led to\" | \"resulted in\" | \"contributed to\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — diễn tả nguyên nhân-kết quả, thay thế \"cause\" (Band 5)</p></div>","p":1},{"id":"W5D3-E-01","l":19,"t":"E","st":"Error","s":3,"tags":["mistake","paraphrase","synonym"],"f":"<p><i>\"Many people have a <b>career</b> in farming.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"Career\" = sự nghiệp dài hạn, có lộ trình thăng tiến — không phù hợp với farming (thường là job/livelihood).</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Many people <b>earn a livelihood</b> through farming.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Synonym PHẢI phù hợp context — không phải mọi synonym đều thay thế được. Khi không chắc → giữ từ gốc.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR</p></div>","p":0},{"id":"W5D3-E-02","l":19,"t":"E","st":"Error","s":3,"tags":["mistake","paraphrase","over-paraphrase"],"f":"<p>Original: <i>\"Children should play more.\"</i> → Paraphrase: <i>\"The juvenile population ought to engage in <b>excessive</b> recreational pursuits.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"Excessive\" = quá mức, mang nghĩa tiêu cực — nghĩa gốc là \"play MORE\" (tích cực), không phải \"play EXCESSIVELY\" (tiêu cực). Đổi quá nhiều → sai nghĩa.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Young learners should be afforded greater opportunities for recreational activities.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Đổi tối đa 60-70% từ. Luôn kiểm tra: nghĩa có bị méo không? Core meaning phải giữ nguyên.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + LR</p></div>","p":0},{"id":"W5D3-E-03","l":19,"t":"E","st":"Error","s":2,"tags":["mistake","paraphrase","word-order"],"f":"<p>Original: <i>\"Education is important for children.\"</i> → Paraphrase: <i>\"For children, education is important.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Chỉ đảo thứ tự từ — không đổi từ vựng hay cấu trúc nào. Examiner coi như KHÔNG paraphrase.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Formal schooling plays an <b>essential</b> role in the <b>development</b> of young learners.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Paraphrase phải đổi ít nhất TỪ VỰNG + CẤU TRÚC (T1 + T2 hoặc T3). Chỉ đảo thứ tự = 0 điểm paraphrase.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR</p></div>","p":0},{"id":"W5D3-E-04","l":19,"t":"E","st":"Error","s":2,"tags":["mistake","paraphrase","over-complex"],"f":"<p>Original: <i>\"Kids should play outside.\"</i> → Paraphrase: <i>\"The prepubescent demographic ought to partake in al fresco locomotor activities.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Quá phức tạp, mất tự nhiên hoàn toàn. Band descriptor nói \"less common lexical items\" — không phải \"obscure and unnatural vocabulary\".</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Children should be encouraged to engage in outdoor physical activities.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Band 7 = chính xác + tự nhiên, KHÔNG PHẢI phức tạp. Dùng từ bạn KIỂM SOÁT ĐƯỢC.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR + CC</p></div>","p":0},{"id":"W5D4-S-01","l":20,"t":"S","st":"Structure","s":3,"tags":["workflow","discussion","time-management"],"f":"<p>Discussion essay chia 40 phút thế nào? Khác Opinion ở bước nào?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Plan</b> (5'): Đọc đề → xác định 2 views → opinion lean → 1 idea + 1 example cho MỖI view</li><li><b>Intro</b> (5'): Paraphrase đề (T1+T2+T3) + thesis lean</li><li><b>Body 1 — View A</b> (12'): TEES, \"Those who support... argue...\"</li><li><b>Body 2 — View B</b> (12'): TEES, \"On the other hand,...\"</li><li><b>Conclusion</b> (3'): Opinion RÕ RÀNG + summary cả 2 views</li><li><b>Check</b> (3'): <b>Balance check</b> (Body 1 ≈ Body 2) + grammar + collocation count ≥5</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Khác Opinion ở Plan (2 views thay vì 1 position) và Check (thêm balance check)</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"P-I-AB-C-Ch\" — Plan → Intro → viewA → viewB → Conclusion → Check</p></div>","p":1},{"id":"W5D4-S-02","l":20,"t":"S","st":"Structure","s":3,"tags":["checklist","pre-writing","discussion"],"f":"<p>Pre-writing checklist cho Discussion essay gồm 5 câu hỏi gì?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Loại đề?</b> → Discussion (\"Discuss both views and give your opinion\")</li><li><b>2 views là gì?</b> → View A = [rõ ràng], View B = [rõ ràng]</li><li><b>Opinion lean về phía nào?</b> → Chọn 1 phía, dù nhẹ</li><li><b>1 idea + 1 example cho MỖI view?</b> → 2 ideas, 2 examples</li><li><b>Thesis draft?</b> → \"While both... I believe... because...\"</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Đề health → View A: individual responsibility, View B: government responsibility → Lean B → Ideas: personal choices vs systemic policies → Thesis draft</p></div>","p":1},{"id":"W5D4-S-03","l":20,"t":"S","st":"Structure","s":2,"tags":["scoring","discussion"],"f":"<p>3 lỗi Discussion essay mất điểm nặng nhất là gì?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Chỉ viết 1 view</b> (viết như Opinion) → TA giảm 1-2 band</li><li><b>Thiếu opinion</b> → TA giảm: \"no clear position\"</li><li><b>Body lệch</b> (VD: View A = 120 từ, View B = 40 từ) → TA giảm: \"one view underdeveloped\"</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Band 5 essay chỉ viết \"studying is important\" + \"playing is good\" = 2 views nhưng mỗi view chỉ 40-50 từ → underdeveloped → TA 5.0</p></div>","p":1},{"id":"W5D4-P-01","l":20,"t":"P","st":"Phrase","s":2,"tags":["collocation","introduction"],"f":"<p>Whether maintaining a healthy lifestyle is an individual duty or requires governmental intervention has become ______ (một chủ đề gây tranh cãi đáng kể).</p>","a":"<b>a subject of considerable debate</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The impact of social media on young people has become a subject of considerable debate among educators and parents.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"a contentious issue\" | \"a widely debated topic\" | \"a matter of ongoing discussion\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Introduction — câu 1, khi mở đề Discussion essay</p></div>","p":1},{"id":"W5D4-P-02","l":20,"t":"P","st":"Phrase","s":3,"tags":["collocation","health","body"],"f":"<p>Governments can implement ______ (các biện pháp phòng ngừa) that benefit entire populations.</p>","a":"<b>preventive measures</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Investing in preventive measures such as vaccination programmes is more cost-effective than treating chronic diseases.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"precautionary steps\" | \"proactive strategies\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về Health, Government policy, Public health</p></div>","p":1},{"id":"W5D4-P-03","l":20,"t":"P","st":"Phrase","s":2,"tags":["collocation","health","body"],"f":"<p>When individuals choose to ______ (áp dụng chế độ ăn cân bằng), they reduce their risk of chronic diseases.</p>","a":"<b>adopt a balanced diet</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Public health campaigns encourage citizens to adopt a balanced diet and engage in regular physical activity.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"maintain a healthy diet\" | \"follow a nutritious eating plan\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về Health, Lifestyle, Individual responsibility</p></div>","p":1},{"id":"W5D4-P-04","l":20,"t":"P","st":"Phrase","s":2,"tags":["collocation","body","conclusion"],"f":"<p>This evidence suggests that educational investment can ______ (mang lại những lợi ích đáng kể).</p>","a":"<b>yield substantial benefits</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Renewable energy sources yield substantial benefits for both the environment and the economy.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"produce significant advantages\" | \"generate considerable returns\" | \"deliver meaningful outcomes\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Summary sentence (S trong TEES) hoặc Conclusion — khi tổng kết lợi ích</p></div>","p":1},{"id":"W5D4-P-05","l":20,"t":"P","st":"Phrase","s":2,"tags":["example","body"],"f":"<p>______ (một ví dụ thuyết phục) is the United Kingdom's sugar tax, which led to a 28.8% reduction in sugar content.</p>","a":"<b>A compelling example</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"A compelling example of successful environmental policy is Denmark's investment in wind energy, which now supplies over 40% of national electricity.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"A notable example\" | \"A striking illustration\" | \"A clear demonstration\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — mở đầu Example sentence (E trong TEES)</p></div>","p":1},{"id":"W5D4-P-06","l":20,"t":"P","st":"Phrase","s":2,"tags":["collocation","health","body"],"f":"<p>Systemic factors, including unequal ______ (cung cấp dịch vụ y tế), often lie beyond individual control.</p>","a":"<b>healthcare provision</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Improving healthcare provision in rural areas remains a priority for developing nations.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"access to medical services\" | \"health service delivery\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về Health, Government, Social inequality</p></div>","p":1},{"id":"W5D4-P-07","l":20,"t":"P","st":"Phrase","s":3,"tags":["paraphrase","introduction"],"f":"<p>Paraphrase \"governments should do more to promote public health\" bằng T1+T2+T3:</p><p>→ \"greater ______ (sự can thiệp của chính phủ)\" [T2: governments→governmental]</p>","a":"<b>governmental intervention</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Whether greater governmental intervention is needed to address income inequality remains a contentious issue.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"state involvement\" | \"government-led action\" | \"public policy intervention\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Introduction — khi paraphrase đề bài có \"government should...\" (đổi noun→adjective + nominalize verb)</p></div>","p":1},{"id":"W5D4-E-01","l":20,"t":"E","st":"Error","s":3,"tags":["mistake","discussion","vocabulary"],"f":"<p><i>Band 5 Discussion essay lặp \"children\" 7 lần, \"study\" 5 lần trong 170 từ.</i> — Mất điểm gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Lặp từ quá nhiều = \"limited range of vocabulary\" → LR Band 5.0. Examiner đếm word repetition.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Thay thế bằng paraphrase: \"children\" → \"the younger generation\" / \"young learners\" / \"young people\". \"study\" → \"academic pursuits\" / \"acquiring knowledge\" / \"formal education\".</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Mỗi từ chính KHÔNG lặp quá 2 lần trong toàn essay. Dùng 4 kỹ thuật paraphrase (W5D3) để tránh lặp.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR</p></div>","p":0},{"id":"W5D4-E-02","l":20,"t":"E","st":"Error","s":3,"tags":["mistake","discussion","example"],"f":"<p><i>Band 5: \"Many parents want their children to study more.\"</i> — Dùng làm example trong body. Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Example chung chung — \"many parents\" = ai? Không có tên cụ thể, không có số liệu → examiner coi là \"lack of supporting evidence\".</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"For instance, Japan's culture of mindful eating and regular physical movement has contributed to the nation having one of the highest life expectancy rates globally.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Example = [Tên cụ thể (quốc gia/tổ chức/nghiên cứu)] + [kết quả có số liệu hoặc outcome rõ ràng]. \"Many people/countries\" = KHÔNG phải example.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA</p></div>","p":0},{"id":"W5D4-E-03","l":20,"t":"E","st":"Error","s":3,"tags":["mistake","discussion","conclusion"],"f":"<p><i>\"In conclusion, I think children should both study and play.\"</i> — Dùng cho Discussion essay. Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Opinion mơ hồ (fence-sitting) — \"both study and play\" = không lean phía nào. Thiếu lý do. Quá ngắn (1 câu).</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"In conclusion, although dedicating time to study undeniably supports academic achievement, I believe that prioritising play and recreation is equally important. This is primarily because a childhood that balances learning with enjoyment fosters creativity and mental well-being.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Conclusion Discussion = restate opinion (LEAN 1 phía) + summarise lý do. KHÔNG viết \"both X and Y\" mà không lean. Ít nhất 2 câu, 30-40 từ.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + CC</p></div>","p":0},{"id":"W5D4-E-04","l":20,"t":"E","st":"Error","s":2,"tags":["mistake","grammar"],"f":"<p><i>\"Education help children to be successful. Playing make them happy.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Subject-Verb Agreement — \"Education\" (uncountable, singular) + \"help\" → phải là \"helps\". \"Playing\" (gerund, singular) + \"make\" → phải là \"makes\".</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Education <b>helps</b> children to be successful.\" / \"Playing <b>makes</b> them happy.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Uncountable nouns (education, technology, pollution) và gerunds (playing, studying, working) = SINGULAR → verb thêm -s/-es. Check S-V agreement ở bước Check 3 phút cuối.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA</p></div>","p":0},{"id":"W6D1-S-01","l":21,"t":"S","st":"Structure","s":3,"tags":["essay-type","recognition"],"f":"<p>3 essay types đã học — nhận diện thế nào trong 10 giây?</p>","a":"","b":"<div class=\"sec\"><ul><li>Thấy <b>\"agree or disagree\"</b> → <b>Opinion</b></li><li>Thấy <b>\"discuss both views\"</b> → <b>Discussion</b></li><li>Thấy <b>\"problems/causes + solutions/measures\"</b> → <b>Problem-Solution</b></li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"What problems does this cause? What solutions can you suggest?\" → Problem-Solution</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Nhìn câu CUỐI của đề — instruction nằm ở đó.</p></div>","p":1},{"id":"W6D1-S-02","l":21,"t":"S","st":"Structure","s":3,"tags":["essay-structure","problem-solution"],"f":"<p>Problem-Solution essay dùng Block structure — 4 đoạn gồm gì?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Introduction</b>: Paraphrase đề + thesis (nêu hướng, KHÔNG chọn phe)</li><li><b>Body 1 — ALL Problems</b>: Problem 1 + Problem 2 (explanation + impact)</li><li><b>Body 2 — ALL Solutions</b>: Solution 1 + Solution 2 (mechanism + why effective)</li><li><b>Conclusion</b>: Summarise + final recommendation</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Body 1 = pollution + congestion → Body 2 = public transport + congestion charge</p></div>","p":1},{"id":"W6D1-S-03","l":21,"t":"S","st":"Structure","s":2,"tags":["paragraph-structure","problem"],"f":"<p>Problem paragraph cần 4 phần nào?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Statement</b> — nêu problem rõ ràng (1 câu)</li><li><b>Explanation</b> — tại sao nó là problem (1-2 câu)</li><li><b>Impact</b> — ảnh hưởng đến ai/gì (1 câu)</li><li><b>Example</b> — ví dụ cụ thể (1 câu)</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Air pollution (statement) → vehicle emissions release CO₂ (explanation) → respiratory diseases (impact) → London £5 billion annually (example)</p></div>","p":1},{"id":"W6D1-S-04","l":21,"t":"S","st":"Structure","s":2,"tags":["paragraph-structure","solution"],"f":"<p>Solution paragraph cần 4 phần nào?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Statement</b> — nêu solution (1 câu)</li><li><b>Mechanism</b> — hoạt động thế nào (1-2 câu)</li><li><b>Why effective</b> — tại sao hiệu quả (1 câu)</li><li><b>Evidence</b> — ví dụ/bằng chứng (1 câu)</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Invest in public transport (statement) → expanding metro + affordable buses (mechanism) → reduces car dependency (why) → Tokyo's rail = low pollution (evidence)</p></div>","p":1},{"id":"W6D1-P-01","l":21,"t":"P","st":"Phrase","s":3,"tags":["thesis","problem-solution"],"f":"<p>This essay will ______ (xem xét các vấn đề chính) and ______ (đề xuất giải pháp thực tế).</p>","a":"<b>examine the key problems</b> ... <b>propose practical solutions</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"This essay will examine the key problems arising from rapid urbanisation and propose practical solutions to mitigate its effects.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"analyse the main issues... suggest effective strategies\" | \"outline the primary difficulties... recommend feasible solutions\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Introduction — thesis câu 2 cho Problem-Solution essay</p></div>","p":1},{"id":"W6D1-P-02","l":21,"t":"P","st":"Phrase","s":2,"tags":["problem-opener","body-paragraph"],"f":"<p>______ (Một trong những vấn đề cấp bách nhất) is the severe air pollution generated by vehicle emissions.</p>","a":"<b>One of the most pressing problems</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"One of the most pressing problems caused by deforestation is the loss of biodiversity in tropical regions.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"The primary issue arising from this trend is...\" | \"A significant challenge caused by [X] is...\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body 1 — mở đầu problem đầu tiên</p></div>","p":1},{"id":"W6D1-P-03","l":21,"t":"P","st":"Phrase","s":2,"tags":["transition","problem-to-solution"],"f":"<p>______ (Để giải quyết vấn đề này), governments should invest heavily in public transportation.</p>","a":"<b>To address this issue</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"To address this issue, schools could implement anti-bullying programmes with trained counsellors.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"A practical solution would be to...\" | \"This problem can be mitigated by...\" | \"One effective measure is to...\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body 2 — mở đầu solution, linking từ problem sang</p></div>","p":1},{"id":"W6D1-P-04","l":21,"t":"P","st":"Phrase","s":2,"tags":["collocation","environment"],"f":"<p>Exhaust fumes from cars contribute to ______ (chất lượng không khí xấu đi) in urban areas.</p>","a":"<b>deteriorating air quality</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Industrial emissions have led to deteriorating air quality across major Chinese cities.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"declining air quality\" | \"worsening atmospheric conditions\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về environment/pollution problems</p></div>","p":1},{"id":"W6D1-P-05","l":21,"t":"P","st":"Phrase","s":2,"tags":["collocation","urbanisation"],"f":"<p>The exodus of young people has resulted in ______ (sự suy thoái kinh tế) of entire villages.</p>","a":"<b>economic deterioration</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Years of underinvestment have caused the economic deterioration of former industrial towns.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"economic decline\" | \"financial degradation\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về economic problems/rural issues</p></div>","p":1},{"id":"W6D1-P-06","l":21,"t":"P","st":"Phrase","s":2,"tags":["collocation","traffic"],"f":"<p>As the number of cars continues to rise, commuters face ______ (thời gian đi lại kéo dài) and substantial ______ (tổn thất kinh tế).</p>","a":"<b>lengthy commute times</b> ... <b>economic losses</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Traffic congestion in Jakarta causes lengthy commute times, with workers spending up to four hours daily on the road.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"prolonged travel times\" | \"significant financial costs\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về traffic/congestion impact</p></div>","p":1},{"id":"W6D1-E-01","l":21,"t":"E","st":"Error","s":3,"tags":["mistake","thesis"],"f":"<p><i>\"I strongly agree that pollution is a serious problem.\"</i> — Viết cho Problem-Solution essay. Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Viết thesis như Opinion essay — chọn phe \"agree/disagree\". Problem-Solution KHÔNG cần chọn phe.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"This essay will examine the key problems caused by pollution and propose practical solutions.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Problem-Solution thesis = nêu vấn đề + hướng giải quyết. KHÔNG viết \"I agree/disagree\".</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA</p></div>","p":0},{"id":"W6D1-E-02","l":21,"t":"E","st":"Error","s":3,"tags":["mistake","solution"],"f":"<p><i>\"The government should do something to solve this problem.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Solution quá chung chung — không nêu cụ thể giải pháp gì, hoạt động thế nào.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The government should invest in expanding metro systems and introducing affordable bus routes, which would reduce residents' dependency on private vehicles.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Solution phải có MECHANISM (hoạt động thế nào) + WHY (tại sao hiệu quả). Không chung chung.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + LR</p></div>","p":0},{"id":"W6D1-E-03","l":21,"t":"E","st":"Error","s":2,"tags":["mistake","structure"],"f":"<p><i>Body 1 viết về pollution (problem) + solution cho pollution. Body 2 viết về congestion (problem) + solution cho congestion.</i> — Đây là structure nào? Có vấn đề gì nếu đang target Band 6.0?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Đây là Chain structure — phù hợp Band 7.0+ nhưng khó kiểm soát cho Band 6.0. Dễ mất balance giữa 2 body.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Dùng Block cho Band 6.0: Body 1 = ALL problems → Body 2 = ALL solutions.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Band 5.5-6.0 nên dùng Block (dễ quản lý). Chain phù hợp Band 7.0+.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC</p></div>","p":0},{"id":"W6D1-E-04","l":21,"t":"E","st":"Error","s":3,"tags":["mistake","content"],"f":"<p><i>Body 1 nêu problems: (1) air pollution, (2) traffic congestion. Body 2 nêu solutions: (1) stricter school discipline, (2) higher taxes on cigarettes.</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Problems và solutions KHÔNG tương ứng nhau. Pollution/congestion cần solutions về transport/emissions, không phải school discipline hay cigarette tax.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Problem: pollution → Solution: public transport. Problem: congestion → Solution: congestion charges.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Mỗi Problem phải có Solution tương ứng. Vẽ đường nối: P1→S1, P2→S2.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + CC</p></div>","p":0},{"id":"W6D2-S-01","l":22,"t":"S","st":"Structure","s":3,"tags":["avoiding-repetition","lr"],"f":"<p>5 kỹ thuật Avoiding Repetition là gì?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Synonym substitution</b> — đổi từ đồng nghĩa (students → learners)</li><li><b>Pronoun reference</b> — dùng he/she/they/it thay noun</li><li><b>Demonstrative reference</b> — this/that/these/those/such + summary noun</li><li><b>Superordinate / Hypernym</b> — từ chung thay nhóm cụ thể (cars, buses → vehicles)</li><li><b>Ellipsis + Summary noun</b> — lược bỏ + tóm tắt (this issue, this challenge)</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Students face pressure. These learners struggle. They experience anxiety. This issue needs attention.\" → 4 techniques trong 4 câu</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Sy-Pro-De-Su-El\" — Synonym, Pronoun, Demonstrative, Superordinate, Ellipsis</p></div>","p":1},{"id":"W6D2-S-02","l":22,"t":"S","st":"Structure","s":3,"tags":["referencing-rotation","lr"],"f":"<p>Referencing Rotation Pattern — thứ tự xoay vòng 4 bước khi nhắc lại 1 noun nhiều lần?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Lần 1:</b> Full noun (tên đầy đủ) — \"University students...\"</li><li><b>Lần 2:</b> Synonym — \"These learners...\"</li><li><b>Lần 3:</b> Pronoun — \"They...\"</li><li><b>Lần 4:</b> Demonstrative + summary noun — \"This issue...\"</li><li><b>Lần 5:</b> Quay lại full noun hoặc synonym mới</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"University students face pressure. These learners are expected to balance coursework. They may experience anxiety. This issue requires urgent attention. Young people in higher education need support.\"</p></div>","p":1},{"id":"W6D2-S-03","l":22,"t":"S","st":"Structure","s":2,"tags":["band-descriptors","lr"],"f":"<p>LR Band 5 vs Band 7 khác nhau thế nào về repetition?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Band 5:</b> \"limited range of vocabulary, with <b>noticeable repetition</b>\"</li><li><b>Band 7:</b> \"sufficient range to allow <b>flexibility and precision</b>, uses <b>less common items</b>\"</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Band 5: \"students\" 10 lần trong 1 đoạn → Band 7: \"students\" 1 lần + 4 thay thế (learners, they, young people, the younger generation)</p></div>","p":1},{"id":"W6D2-S-04","l":22,"t":"S","st":"Structure","s":2,"tags":["summary-nouns","lr"],"f":"<p>Summary nouns bank — kể ≥6 cặp thay thế (từ gốc → summary nouns)?</p>","a":"","b":"<div class=\"sec\"><div class=\"tw\"><table><thead><tr><th>Từ gốc</th><th>Summary nouns</th></tr></thead><tbody><tr><td>problem</td><td>this <b>issue</b> / this <b>challenge</b></td></tr><tr><td>solution</td><td>this <b>approach</b> / this <b>measure</b> / this <b>strategy</b></td></tr><tr><td>trend</td><td>this <b>phenomenon</b> / this <b>pattern</b></td></tr><tr><td>opinion</td><td>this <b>viewpoint</b> / this <b>perspective</b></td></tr><tr><td>change</td><td>this <b>shift</b> / this <b>transformation</b></td></tr><tr><td>result</td><td>this <b>outcome</b> / this <b>consequence</b></td></tr><tr><td>increase</td><td>this <b>rise</b> / this <b>surge</b></td></tr><tr><td>decrease</td><td>this <b>decline</b> / this <b>reduction</b></td></tr></tbody></table></div></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Pollution is rising rapidly. This <b>phenomenon</b> is particularly concerning in developing nations.\"</p></div>","p":1},{"id":"W6D2-P-01","l":22,"t":"P","st":"Phrase","s":3,"tags":["demonstrative-reference","summary-noun"],"f":"<p>Pollution is increasing rapidly. ______ (xu hướng này) is particularly concerning in developing nations.</p>","a":"<b>This trend</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Crime rates rose sharply in urban areas. This trend has prompted calls for stricter policing.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"This pattern\" | \"This tendency\" | \"This phenomenon\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — câu 2+ khi cần nhắc lại ý vừa nêu mà không lặp từ</p></div>","p":1},{"id":"W6D2-P-02","l":22,"t":"P","st":"Phrase","s":3,"tags":["demonstrative-reference","summary-noun"],"f":"<p>Governments introduced new education reforms. ______ (những biện pháp như vậy) aim to improve educational outcomes.</p>","a":"<b>Such measures</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Authorities imposed congestion charges in city centres. Such measures have proven effective in reducing traffic volume.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"These measures\" | \"These initiatives\" | \"Such policies\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi nhắc lại solutions/policies đã nêu ở câu trước</p></div>","p":1},{"id":"W6D2-P-03","l":22,"t":"P","st":"Phrase","s":2,"tags":["superordinate","avoiding-repetition"],"f":"<p>Cars, buses, and motorcycles contribute to air pollution. These ______ (phương tiện) should be regulated more strictly.</p>","a":"<b>vehicles</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Facebook, Instagram, and TikTok have transformed communication. These <b>platforms</b> now influence public opinion significantly.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>(tuỳ context) \"devices\" | \"qualifications\" | \"crops\" | \"professionals\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — sau khi liệt kê nhiều items cụ thể, dùng từ chung (category word) để tránh lặp</p></div>","p":1},{"id":"W6D2-P-04","l":22,"t":"P","st":"Phrase","s":2,"tags":["summary-noun","ellipsis"],"f":"<p>Many students drop out of school because they cannot afford tuition fees. ______ (vấn đề này) could be addressed by government scholarships.</p>","a":"<b>This issue</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Air quality in cities has deteriorated significantly over the past decade. This decline is largely attributed to vehicle emissions.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"This challenge\" | \"This difficulty\" | \"This problem\" (nhưng hạn chế dùng \"problem\" nếu đã dùng rồi)</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi tóm tắt cả ý dài ở câu trước bằng 1 summary noun</p></div>","p":1},{"id":"W6D2-P-05","l":22,"t":"P","st":"Phrase","s":3,"tags":["pronoun-reference","avoiding-repetition"],"f":"<p>Many young people are relocating to urban areas. ______ (họ) seek better employment and educational opportunities.</p>","a":"<b>They</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The government should invest in public transport. It could allocate more funding to expand metro systems.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>(tuỳ noun) \"he/she\" | \"it\" | \"them\" | \"their\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Câu liền kề — khi antecedent (noun gốc) RÕ RÀNG, chỉ 1 đối tượng duy nhất</p></div>","p":1},{"id":"W6D2-P-06","l":22,"t":"P","st":"Phrase","s":2,"tags":["synonym-substitution","avoiding-repetition"],"f":"<p>Kể ≥4 synonyms thay thế \"students\" trong 1 essay:</p>","a":"<ul><li><b>learners</b></li><li><b>young people</b></li><li><b>those enrolled in education</b></li><li><b>the younger generation</b></li><li><b>individuals in higher education</b></li></ul>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"University students face enormous pressure. These learners are expected to balance coursework. They may experience anxiety. Ultimately, young people in higher education need better support.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>(tuỳ context) \"pupils\" (primary only) | \"undergraduates\" (university only)</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Throughout essay — xoay vòng theo Referencing Rotation Pattern</p></div>","p":1},{"id":"W6D2-E-01","l":22,"t":"E","st":"Error","s":3,"tags":["mistake","demonstrative-reference"],"f":"<p><i>\"Pollution is increasing rapidly. This is dangerous for public health.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"This\" đứng một mình (bare demonstrative) — không rõ \"this\" chỉ gì: pollution? increasing? rapidly?</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Pollution is increasing rapidly. <b>This trend</b> is dangerous for public health.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>\"This/That\" luôn đi kèm summary noun (this trend, this issue, this situation). KHÔNG bao giờ dùng \"this\" đứng một mình.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC + LR</p></div>","p":0},{"id":"W6D2-E-02","l":22,"t":"E","st":"Error","s":3,"tags":["mistake","pronoun-reference"],"f":"<p><i>\"Teachers and students often disagree about homework policies. They should find a compromise.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"They\" unclear antecedent — \"they\" chỉ teachers hay students? Người đọc không biết.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Teachers and students often disagree about homework policies. <b>Both groups</b> should find a compromise.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Pronoun phải có clear antecedent — nếu câu trước có ≥2 nouns, KHÔNG dùng pronoun, dùng summary phrase thay thế.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC</p></div>","p":0},{"id":"W6D2-E-03","l":22,"t":"E","st":"Error","s":2,"tags":["mistake","synonym-substitution"],"f":"<p><i>\"University students should study harder. Pupils need to improve their grades.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"Pupils\" = primary school students. Dùng thay \"university students\" = sai context, thay đổi nghĩa.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"University students should study harder. <b>Learners at the tertiary level</b> need to improve their grades.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Synonym phải cùng context — kiểm tra: synonym có chỉ CÙNG ĐỐI TƯỢNG không? Nếu nghi ngờ, dùng pronoun hoặc demonstrative an toàn hơn.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR</p></div>","p":0},{"id":"W6D2-E-04","l":22,"t":"E","st":"Error","s":2,"tags":["mistake","sentence-pattern"],"f":"<p><i>\"It is important to study. It is necessary to exercise. It is essential to sleep well.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Lặp cấu trúc câu \"It is [adj] to [verb]\" 3 lần liên tiếp — sentence pattern repetition.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Studying is crucial. <b>In addition</b>, regular exercise <b>helps</b> maintain fitness. <b>Furthermore</b>, adequate sleep <b>contributes to</b> overall well-being.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Đa dạng cấu trúc câu — không dùng cùng 1 sentence pattern quá 2 lần liên tiếp. Mỗi câu nên có subject + verb pattern khác nhau.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA</p></div>","p":0},{"id":"W6D2-E-05","l":22,"t":"E","st":"Error","s":3,"tags":["mistake","word-repetition"],"f":"<p><i>\"The environment is important. People should protect the environment because the environment provides clean air.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"environment\" lặp 3 lần trong 2 câu — Band 5 \"noticeable repetition\".</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"<b>The natural environment</b> is essential for human survival. People should protect <b>these vital ecosystems</b> because <b>they</b> provide clean air.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Mỗi noun quan trọng chỉ xuất hiện TỐI ĐA 2 lần trong 1 đoạn (~100 từ). Dùng Referencing Rotation: full noun → synonym → pronoun → demonstrative.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR</p></div>","p":0},{"id":"W6D3-S-01","l":23,"t":"S","st":"Structure","s":3,"tags":["assessment","workflow"],"f":"<p>Assessment workflow 45 phút — 6 bước theo thứ tự nào?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Read prompt</b> (2') — đọc đề 2 lần, gạch chân instruction</li><li><b>Identify type</b> (1') — Opinion / Discussion / P-S</li><li><b>Plan</b> (5') — thesis + body 1 idea + body 2 idea + conclusion</li><li><b>Write</b> (30') — Intro 5' + Body 1 10' + Body 2 10' + Conclusion 5'</li><li><b>Check repetition</b> (4') — đếm từ lặp, bare \"this\", collocation count</li><li><b>Proofread</b> (3') — S-V agreement, articles, tenses</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Phút 38-42 = check repetition: \"students\" lặp 4 lần → thay: learners, they, young people</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"R-I-P-W-C-P\" = Read → Identify → Plan → Write → Check → Proofread</p></div>","p":1},{"id":"W6D3-S-02","l":23,"t":"S","st":"Structure","s":3,"tags":["assessment","minimum-requirements"],"f":"<p>Band 5.5-6.0 cần đạt tối thiểu mấy yêu cầu? Kể 5 yêu cầu quan trọng nhất.</p>","a":"","b":"<div class=\"sec\"><p>10 yêu cầu — phải đạt TẤT CẢ. Top 5:</p><ol><li>Nhận diện <b>ĐÚNG essay type</b></li><li><b>4 đoạn</b> rõ ràng (Intro + Body + Body + Conclusion)</li><li><b>≥3 collocations</b> academic</li><li><b>Paraphrase đề</b> thành công (không copy nguyên văn)</li><li><b>250-280 từ</b> + hoàn thành trong 45 phút</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Sai type (viết Opinion khi đề Discussion) = mất 1+ band TA ngay lập tức</p></div>","p":1},{"id":"W6D3-S-03","l":23,"t":"S","st":"Structure","s":2,"tags":["essay-type","thesis-comparison"],"f":"<p>Thesis cho 3 essay types khác nhau thế nào?</p>","a":"","b":"<div class=\"sec\"><div class=\"tw\"><table><thead><tr><th>Type</th><th>Thesis pattern</th></tr></thead><tbody><tr><td><b>Opinion</b></td><td>Chọn phe: \"I strongly agree that...\"</td></tr><tr><td><b>Discussion</b></td><td>Acknowledge 2 views: \"While both have merit, I believe...\"</td></tr><tr><td><b>Problem-Solution</b></td><td>KHÔNG chọn phe: \"This essay will examine... and propose...\"</td></tr></tbody></table></div></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Đề \"Discuss both views\" → thesis: \"While some advocate for sports facilities, I believe a comprehensive approach is more effective.\"</p></div>","p":1},{"id":"W6D3-S-04","l":23,"t":"S","st":"Structure","s":2,"tags":["assessment","repetition-check"],"f":"<p>Bước \"Check repetition\" (4 phút) trong assessment — cần kiểm tra 3 thứ gì?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Đếm từ lặp:</b> Content word nào xuất hiện &gt;2 lần? → thay synonym/pronoun/demonstrative</li><li><b>Bare demonstrative:</b> Có \"This is...\" / \"That is...\" đứng một mình? → thêm summary noun (\"This trend...\")</li><li><b>Collocation count:</b> Đã dùng ≥5 collocations chưa? → nếu thiếu, thay từ đơn bằng collocation</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"health\" xuất hiện 5 lần → thay: well-being, physical fitness, public welfare</p></div>","p":1},{"id":"W6D3-P-01","l":23,"t":"P","st":"Phrase","s":2,"tags":["collocation","health"],"f":"<p>Improved access to athletic facilities can significantly reduce the ______ (tỷ lệ mắc bệnh) of obesity and ______ (bệnh tim mạch).</p>","a":"<b>prevalence</b> ... <b>cardiovascular disease</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Regular physical activity has been shown to reduce the prevalence of cardiovascular disease in middle-aged adults.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"incidence of obesity\" | \"rates of heart disease\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về health benefits / public health problems</p></div>","p":1},{"id":"W6D3-P-02","l":23,"t":"P","st":"Phrase","s":2,"tags":["collocation","health"],"f":"<p>Japan's comprehensive strategy has contributed to the nation achieving the highest ______ (tuổi thọ trung bình) globally.</p>","a":"<b>life expectancy</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Improvements in healthcare and nutrition have led to a steady rise in life expectancy across developed nations.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"average lifespan\" | \"longevity rates\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về health outcomes / country examples</p></div>","p":1},{"id":"W6D3-P-03","l":23,"t":"P","st":"Phrase","s":2,"tags":["collocation","health"],"f":"<p>Issues such as ______ (rối loạn sức khỏe tâm thần), poor ______ (thói quen ăn uống), and substance abuse require different interventions.</p>","a":"<b>mental health disorders</b> ... <b>dietary habits</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Addressing mental health disorders requires investment in counselling services, not just physical infrastructure.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"psychological well-being issues\" | \"eating patterns / nutritional habits\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về public health beyond exercise</p></div>","p":1},{"id":"W6D3-P-04","l":23,"t":"P","st":"Phrase","s":3,"tags":["academic-phrase","argument"],"f":"<p>______ (Bằng chứng như vậy) suggests that a ______ (cách tiếp cận đa chiều) is considerably more effective than focusing solely on exercise.</p>","a":"<b>Such evidence</b> ... <b>multifaceted approach</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Such evidence suggests that a multifaceted approach to education reform yields better results than any single policy change.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"This demonstrates that\" | \"a comprehensive/holistic strategy\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — Summary sentence (S trong TEES), khi kết luận từ evidence</p></div>","p":1},{"id":"W6D3-P-05","l":23,"t":"P","st":"Phrase","s":2,"tags":["conclusion","discussion"],"f":"<p>I am convinced that this measure alone is ______ (không đầy đủ). Governments should adopt a ______ (chiến lược toàn diện) that integrates multiple interventions.</p>","a":"<b>inadequate</b> ... <b>holistic strategy</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"While technology aids learning, it is inadequate as a standalone solution; schools should adopt a holistic strategy combining digital tools with traditional teaching.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"insufficient on its own\" | \"a comprehensive approach / an integrated strategy\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Conclusion — khi bày tỏ opinion rằng 1 giải pháp đơn lẻ chưa đủ</p></div>","p":1},{"id":"W6D3-P-06","l":23,"t":"P","st":"Phrase","s":2,"tags":["academic-phrase","introduction"],"f":"<p>There is ______ (cuộc tranh luận đáng kể) about whether expanding sports infrastructure is the most ______ (cách tiếp cận hiệu quả) to enhancing public well-being.</p>","a":"<b>considerable debate</b> ... <b>effective approach</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"There is considerable debate about whether stricter regulations are the most effective approach to reducing carbon emissions.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"ongoing discussion / significant controversy\" | \"efficient method / viable strategy\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Introduction — câu 1, mở đề Discussion essay</p></div>","p":1},{"id":"W6D3-E-01","l":23,"t":"E","st":"Error","s":3,"tags":["mistake","essay-type"],"f":"<p><i>Đề: \"Discuss both these views and give your own opinion.\" → Viết: \"I strongly agree that sports facilities improve public health.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Viết thesis như Opinion essay (chọn phe) cho đề Discussion. Discussion yêu cầu trình bày CẢ HAI views trước khi cho opinion.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"While some advocate for more sports facilities, I believe a comprehensive approach incorporating multiple health interventions is essential.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Đọc instruction cuối đề: \"Discuss both views\" → PHẢI discuss 2 views balanced. Chọn phe ngay = sai type = -1 band TA.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA</p></div>","p":0},{"id":"W6D3-E-02","l":23,"t":"E","st":"Error","s":3,"tags":["mistake","repetition"],"f":"<p><i>\"Public health is important. The government should improve public health. Many people have poor public health because of lack of exercise. Public health programmes can solve this.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"Public health\" lặp 4 lần trong 4 câu liên tiếp → Band 5 LR: \"noticeable repetition.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Public health is a growing concern. The government should enhance <b>the well-being of citizens</b>. Many people suffer from preventable illnesses due to sedentary lifestyles. Comprehensive <b>wellness programmes</b> can address <b>this issue</b>.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Content word KHÔNG lặp &gt;2 lần. Dùng xoay vòng: full noun → synonym → pronoun → demonstrative + summary noun.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR</p></div>","p":0},{"id":"W6D3-E-03","l":23,"t":"E","st":"Error","s":2,"tags":["mistake","collocation"],"f":"<p><i>\"Sports facilities can make people's health become better and reduce the number of fat people.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Dùng từ đơn giản (make...better, fat people) thay vì academic collocations → Band 5 LR: \"limited range.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Sports facilities can <b>significantly improve physical fitness</b> and <b>reduce the prevalence of obesity</b> among the general population.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Thay \"basic word + basic word\" bằng academic collocation. \"make better\" → \"significantly improve\"; \"fat people\" → \"prevalence of obesity.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR</p></div>","p":0},{"id":"W6D3-E-04","l":23,"t":"E","st":"Error","s":2,"tags":["mistake","paraphrase"],"f":"<p><i>Đề: \"the best way to improve public health is by increasing the number of sports facilities\" → Intro: \"the best way to improve public health is by increasing the number of sports facilities.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Copy đề nguyên văn vào introduction — Band 5 TA: examiner đánh giá paraphrase ability, copy = 0 điểm paraphrase.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The most effective approach to <b>enhancing public well-being</b> is through the <b>expansion of athletic infrastructure</b>.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Introduction câu 1 PHẢI paraphrase đề: đổi từ khoá (improve → enhance, public health → public well-being, sports facilities → athletic infrastructure) + đổi cấu trúc câu.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + LR</p></div>","p":0},{"id":"W7D1-S-01","l":24,"t":"S","st":"Structure","s":3,"tags":["grammar","complex-sentence","clause-types"],"f":"<p>4 loại complex clause phổ biến nhất trong IELTS Writing là gì?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Relative clauses</b> — who/which/that/where — thêm thông tin cho danh từ</li><li><b>Conditional clauses</b> — If + condition → result — nêu điều kiện</li><li><b>Concessive clauses</b> — although/despite/while — thừa nhận 1 phía, nhấn phía còn lại</li><li><b>Participle clauses</b> — V-ing / V-ed / Having + V3 — rút gọn câu, nâng tone</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Students <b>who</b> study abroad gain valuable experience. / <b>Although</b> social media poses risks, it enables global communication. / <b>If</b> governments invest more, citizens <b>will</b> benefit. / <b>Having considered</b> both sides, the benefits are clear.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"R-C-C-P\" — Relative, Conditional, Concessive, Participle — 4 vũ khí GRA.</p></div>","p":1},{"id":"W7D1-S-02","l":24,"t":"S","st":"Structure","s":3,"tags":["grammar","relative-clause","comma-rule"],"f":"<p>Phân biệt <b>defining</b> vs <b>non-defining</b> relative clause? Quy tắc comma?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Defining</b> (bắt buộc — bỏ → sai nghĩa): KHÔNG comma, dùng who/which/<b>that</b></li><li><b>Non-defining</b> (bổ sung — bỏ → vẫn hiểu): CÓ comma, dùng who/which — <b>KHÔNG dùng \"that\"</b></li></ul></div><div class=\"sec\"><span class=\"lbl\">VD</span><ul><li>Defining: Students <b>who receive scholarships</b> are more likely to graduate.</li><li>Non-defining: Technology<b>,</b> <b>which has advanced rapidly,</b> has transformed the workplace.</li></ul></div>","p":1},{"id":"W7D1-S-03","l":24,"t":"S","st":"Structure","s":3,"tags":["grammar","conditional","tense"],"f":"<p>Conditional <b>Type 1</b> vs <b>Type 2</b> — công thức + khi nào dùng trong IELTS?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Type 1</b> (Real/Possible): If + <b>present simple</b>, + <b>will</b> + V → đề xuất solution khả thi</li><li><b>Type 2</b> (Unreal/Hypothetical): If + <b>past simple</b>, + <b>would</b> + V → argument giả định, counter-argument</li></ul></div><div class=\"sec\"><span class=\"lbl\">VD</span><ul><li>Type 1: If governments <b>invest</b> in education, citizens <b>will have</b> better prospects.</li><li>Type 2: If education <b>were</b> free, more people <b>would pursue</b> degrees.</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Type 1 = \"có thể xảy ra\" → dùng cho solutions. Type 2 = \"giá mà\" → dùng cho counter-arguments.</p></div>","p":1},{"id":"W7D1-S-04","l":24,"t":"S","st":"Structure","s":2,"tags":["grammar","paragraph-balance","sentence-variety"],"f":"<p>\"2+1 Rule\" trong body paragraph là gì? Tại sao simple sentences vẫn cần?</p>","a":"","b":"<div class=\"sec\"><ul><li>Mỗi body paragraph: ≥ <b>2 complex</b> sentences + <b>1 simple</b> sentence</li><li>Simple sentences tạo <b>emphasis/impact</b> — \"Education transforms lives.\" mạnh HƠN câu complex dài</li><li>Nhồi toàn complex → khó đọc, không tự nhiên</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>[CONC] Although online education has limitations... [REL] Students who enrol in online programmes... [SIMPLE] <b>The results speak for themselves.</b> [COND] If universities continue to invest...</p></div>","p":1},{"id":"W7D1-P-01","l":24,"t":"P","st":"Phrase","s":2,"tags":["collocation","role-function","body-paragraph"],"f":"<p>Technology ______ (đóng vai trò không thể thiếu) in both professional and personal contexts.</p>","a":"<b>plays an indispensable role</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Public transportation plays an indispensable role in reducing urban congestion.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"serves a crucial function\" | \"is of paramount importance\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi nêu tầm quan trọng của một yếu tố</p></div>","p":1},{"id":"W7D1-P-02","l":24,"t":"P","st":"Phrase","s":2,"tags":["collocation","accessibility","education"],"f":"<p>Students can access world-class education ______ (bất kể rào cản địa lý).</p>","a":"<b>regardless of geographical barriers</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Telemedicine allows patients to receive consultations regardless of geographical barriers.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"irrespective of location\" | \"without geographical limitations\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về education, technology, accessibility</p></div>","p":1},{"id":"W7D1-P-03","l":24,"t":"P","st":"Phrase","s":3,"tags":["collocation","comparison","opinion"],"f":"<p>The long-term economic benefits ______ (vượt xa) the initial costs.</p>","a":"<b>far outweigh</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The advantages of renewable energy far outweigh the short-term financial investment required.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"significantly exceed\" | \"greatly surpass\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph + Conclusion — khi so sánh benefits vs drawbacks/costs trong Opinion essay</p></div>","p":1},{"id":"W7D1-P-04","l":24,"t":"P","st":"Phrase","s":2,"tags":["collocation","crime","body-paragraph"],"f":"<p>Longer prison sentences may ______ (đóng vai trò răn đe) for potential offenders.</p>","a":"<b>serve as a deterrent</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Heavy fines serve as a deterrent for companies that violate environmental regulations.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"act as a disincentive\" | \"function as a preventive measure\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về crime, punishment, law enforcement</p></div>","p":1},{"id":"W7D1-P-05","l":24,"t":"P","st":"Phrase","s":3,"tags":["collocation","cause-analysis","body-paragraph"],"f":"<p>This approach alone is insufficient to address the ______ (nguyên nhân gốc rễ) of criminal behaviour.</p>","a":"<b>root causes</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"To effectively reduce poverty, governments must address the root causes, including unequal access to education.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"underlying factors\" | \"fundamental reasons\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi phân tích nguyên nhân sâu xa trong Problem-Solution hoặc Opinion essay</p></div>","p":1},{"id":"W7D1-P-06","l":24,"t":"P","st":"Phrase","s":2,"tags":["collocation","rehabilitation","crime"],"f":"<p>Former offenders would be far more likely to ______ (tái hoà nhập xã hội) as productive citizens.</p>","a":"<b>reintegrate into society</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Vocational training programmes help released prisoners reintegrate into society and find stable employment.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"rejoin the community\" | \"become contributing members of society\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về crime, rehabilitation, social issues</p></div>","p":1},{"id":"W7D1-P-07","l":24,"t":"P","st":"Phrase","s":2,"tags":["collocation","technology","balance"],"f":"<p>Citizens would be better equipped to ______ (tận dụng tiềm năng) of technology while ______ (giảm thiểu) its adverse effects.</p>","a":"<b>harness [something's] potential</b> ... <b>mitigating</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Education empowers individuals to harness the potential of digital tools while mitigating the risks of misinformation.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"capitalise on the benefits\" | \"leverage the advantages\" (cho harness) — \"reducing\" | \"minimising\" (cho mitigating)</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph + Conclusion — khi viết về technology, balance giữa benefits và risks</p></div>","p":1},{"id":"W7D1-E-01","l":24,"t":"E","st":"Error","s":3,"tags":["mistake","relative-clause","that-which"],"f":"<p><i>\"Technology, that has advanced rapidly, has transformed the workplace.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Non-defining relative clause (có comma) dùng \"that\" — sai quy tắc.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Technology, <b>which</b> has advanced rapidly, has transformed the workplace.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Non-defining relative clause (có comma) → dùng <b>who/which</b>, KHÔNG BAO GIỜ dùng \"that\".</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA</p></div>","p":0},{"id":"W7D1-E-02","l":24,"t":"E","st":"Error","s":3,"tags":["mistake","conditional","tense"],"f":"<p><i>\"If governments will invest more in education, citizens will have better jobs.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>If-clause dùng \"will\" — sai tense. Conditional Type 1: if-clause = present simple, KHÔNG dùng \"will\".</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"If governments <b>invest</b> more in education, citizens will have better jobs.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>If-clause KHÔNG BAO GIỜ dùng \"will\" — dùng present simple (Type 1) hoặc past simple (Type 2).</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA</p></div>","p":0},{"id":"W7D1-E-03","l":24,"t":"E","st":"Error","s":3,"tags":["mistake","concessive","despite-although"],"f":"<p><i>\"Despite technology creates some risks, its benefits are significant.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"Despite\" + clause (S + V) — sai cấu trúc. \"Despite\" chỉ đi với noun phrase.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Despite <b>the risks created by</b> technology, its benefits are significant.\" HOẶC \"<b>Although</b> technology creates some risks, its benefits are significant.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Despite/In spite of + <b>noun phrase</b> (KHÔNG có S + V). Although/Even though + <b>clause</b> (có S + V).</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA</p></div>","p":0},{"id":"W7D1-E-04","l":24,"t":"E","st":"Error","s":3,"tags":["mistake","fragment","dependent-clause"],"f":"<p><i>\"Although technology is useful.\"</i> (kết thúc luôn, không có câu tiếp) — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Fragment — dependent clause (Although...) đứng một mình, thiếu main clause. Câu chưa hoàn chỉnh.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Although technology is useful, <b>it also poses certain risks to privacy.</b>\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Dependent clause (Although/If/While/Who...) PHẢI có main clause đi kèm — nếu không = fragment = GRA giảm nặng.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA</p></div>","p":0},{"id":"W7D1-E-05","l":24,"t":"E","st":"Error","s":2,"tags":["mistake","participle-clause","dangling-modifier"],"f":"<p><i>\"Walking down the street, the building caught my attention.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Dangling participle — subject của \"walking\" (người đi) khác subject của main clause (\"the building\"). Building không thể walk.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Walking down the street, <b>I</b> noticed the building.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Subject của participle clause PHẢI TRÙNG với subject của main clause. Nếu khác → dangling modifier → câu vô nghĩa.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA</p></div>","p":0},{"id":"W7D2-S-01","l":25,"t":"S","st":"Structure","s":3,"tags":["error-classification","grammar"],"f":"<p>10 lỗi GRA phổ biến nhất của Band 5 được chia thành 3 nhóm nào? Mỗi nhóm gồm những lỗi gì?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Sentence-level</b> (cấu trúc câu): Run-on, Comma splice</li><li><b>Word-level</b> (từ vựng + hình thái): S-V Agreement, Articles, Countable/Uncountable, Prepositions, Word Form</li><li><b>Discourse-level</b> (mạch văn): Tense inconsistency, Redundancy, Pronoun reference</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Technology is useful, it helps people\" = Comma splice = Sentence-level error</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"SWD — Sentence, Word, Discourse — từ to → nhỏ → toàn cục\"</p></div>","p":1},{"id":"W7D2-S-02","l":25,"t":"S","st":"Structure","s":3,"tags":["impact-ranking","grammar"],"f":"<p>Top 3 lỗi GRA mất điểm NHIỀU nhất (kéo Band xuống thấp nhất)?</p>","a":"","b":"<div class=\"sec\"><ol><li>🔴 <b>Run-on / Fragment</b> → \"impedes communication\" → Band 4-5</li><li>🔴 <b>Subject-Verb Agreement</b> → \"noticeable errors\" → Band 5</li><li>🟡 <b>Tense Inconsistency</b> → \"errors in tense usage\" → Band 5-5.5</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Technology is useful it helps people\" (run-on) → examiner KHÔNG hiểu → Band 4-5</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"RST — Run-on, Subject-verb, Tense — sửa 3 cái này trước = nhảy Band\"</p></div>","p":1},{"id":"W7D2-S-03","l":25,"t":"S","st":"Structure","s":2,"tags":["error-log","self-check"],"f":"<p>Self-Error Log gồm những cột nào? Khi nào cần \"drill riêng\" cho 1 lỗi?</p>","a":"","b":"<div class=\"sec\"><ul><li>5 cột: <b>Lỗi</b> | <b>Câu sai</b> | <b>Câu đúng</b> | <b>Rule</b> | <b>Lặp lại (lần thứ)</b></li><li>Lỗi lặp <b>≥3 lần</b> = cần drill riêng</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Nếu mắc \"S-V Agreement\" 3 lần trong 3 essays khác nhau → cần drill 10 câu S-V riêng</p></div>","p":1},{"id":"W7D2-S-04","l":25,"t":"S","st":"Structure","s":2,"tags":["uncountable-nouns","grammar"],"f":"<p>Kể 8 uncountable nouns phổ biến mà Band 5 hay thêm \"-s\" sai?</p>","a":"","b":"<div class=\"sec\"><ul><li>information, advice, equipment, research</li><li>knowledge, evidence, furniture, luggage</li></ul></div><div class=\"sec\"><p class=\"bad\"><span class=\"lbl\">VD</span>❌ \"informations\" → ✅ \"information\" / \"pieces of information\"</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"IAER KEFL — 8 từ KHÔNG BAO GIỜ có -s\"</p></div>","p":1},{"id":"W7D2-P-01","l":25,"t":"P","st":"Phrase","s":2,"tags":["preposition","collocation"],"f":"<p>The success of this policy ______ (phụ thuộc vào) several economic factors.</p>","a":"<b>depends on</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Whether students succeed at university depends on the quality of their secondary education.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"is contingent upon\" | \"hinges on\" | \"is determined by\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi nêu điều kiện/yếu tố ảnh hưởng</p></div>","p":1},{"id":"W7D2-P-02","l":25,"t":"P","st":"Phrase","s":2,"tags":["preposition","collocation"],"f":"<p>Rapid urbanisation has had a significant ______ (ảnh hưởng đến) the environment.</p>","a":"<b>impact on</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Social media has had a profound impact on the way young people communicate.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"influence on\" | \"effect on\" | \"bearing on\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi mô tả tác động của X lên Y</p></div>","p":1},{"id":"W7D2-P-03","l":25,"t":"P","st":"Phrase","s":2,"tags":["preposition","collocation"],"f":"<p>Excessive screen time can ______ (dẫn đến) deteriorating mental health among adolescents.</p>","a":"<b>result in</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"A lack of investment in public transport may result in increased traffic congestion.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"lead to\" | \"give rise to\" | \"contribute to\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi nêu hệ quả/kết quả</p></div>","p":1},{"id":"W7D2-P-04","l":25,"t":"P","st":"Phrase","s":2,"tags":["word-form","grammar"],"f":"<p>Technology has a ______ (đáng kể) impact on modern education. (adj hay adv?)</p>","a":"<b>significant</b> (adjective — đứng trước noun)","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The government's decision had a significant influence on public opinion.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"considerable\" | \"substantial\" | \"profound\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — trước noun (impact, effect, role, influence)</p></div>","p":1},{"id":"W7D2-P-05","l":25,"t":"P","st":"Phrase","s":2,"tags":["article","grammar"],"f":"<p>______ education is important for everyone. (\"The education\" hay \"Education\"?)</p>","a":"∅ <b>Education</b> (NO article — general/abstract concept)","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"∅ Technology has transformed the way people work.\" (general) vs \"<b>The</b> technology used in hospitals must be reliable.\" (specific)</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>Rule: abstract/general = NO article | specific/known = \"the\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Mọi câu — đặc biệt Topic sentence khi nói về concept chung</p></div>","p":1},{"id":"W7D2-E-01","l":25,"t":"E","st":"Error","s":3,"tags":["mistake","run-on"],"f":"<p><i>\"Technology is useful, it helps people learn new things.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Comma splice — dùng comma nối 2 independent clauses.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Technology is useful <b>because</b> it helps people learn new things.\" / \"Technology is useful<b>;</b> it helps people learn new things.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>2 independent clauses cần: conjunction (because/and/but), semicolon, hoặc period — KHÔNG dùng comma.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA + CC</p></div>","p":0},{"id":"W7D2-E-02","l":25,"t":"E","st":"Error","s":3,"tags":["mistake","subject-verb"],"f":"<p><i>\"The number of students have increased significantly.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"The number of\" = singular → verb phải singular.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The number of students <b>has</b> increased significantly.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>\"The number of\" = singular (has/is). \"A number of\" = plural (have/are).</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA</p></div>","p":0},{"id":"W7D2-E-03","l":25,"t":"E","st":"Error","s":3,"tags":["mistake","tense"],"f":"<p><i>\"The chart showed that population increases between 2000 and 2010.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>2000-2010 = quá khứ → phải dùng past tense, không phải present.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The chart showed that population <b>increased</b> between 2000 and 2010.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Task 1: data trong quá khứ → past tense. Task 2: arguments chung → present tense.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA</p></div>","p":0},{"id":"W7D2-E-04","l":25,"t":"E","st":"Error","s":2,"tags":["mistake","preposition"],"f":"<p><i>\"The outcome of this initiative depends of several factors.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"depends of\" — sai preposition.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The outcome of this initiative <b>depends on</b> several factors.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>depend ON, result IN, contribute TO, impact ON — học cố định, không dịch từ tiếng Việt.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA + LR</p></div>","p":0},{"id":"W7D2-E-05","l":25,"t":"E","st":"Error","s":2,"tags":["mistake","word-form"],"f":"<p><i>\"Air pollution has a significantly impact on public health.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"significantly\" = adverb → không đứng trước noun. Cần adjective.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Air pollution has a <b>significant</b> impact on public health.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Trước NOUN → adjective. Sau VERB → adverb. (significant impact ✅, increased significantly ✅)</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA</p></div>","p":0},{"id":"W7D2-E-06","l":25,"t":"E","st":"Error","s":2,"tags":["mistake","redundancy"],"f":"<p><i>\"The reason for the increase is because more people moved to cities.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"reason\" + \"because\" = redundant (cả hai đều chỉ nguyên nhân).</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The reason for the increase is <b>that</b> more people moved to cities.\" / \"This is <b>because</b> more people moved to cities.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>\"The reason is THAT...\" hoặc \"This is BECAUSE...\" — KHÔNG kết hợp cả hai.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA + LR</p></div>","p":0},{"id":"W7D3-S-01","l":26,"t":"S","st":"Structure","s":3,"tags":["sentence-variety","distribution"],"f":"<p>6 loại sentence structure cần dùng trong IELTS essay? Band 7 nên phân bổ % thế nào?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Simple</b> (S+V+O) — 20-25%</li><li><b>Compound</b> (conj: and/but/so/yet) — 20-25%</li><li><b>Complex</b> (relative/conditional/concessive) — 40-50%</li><li><b>Cleft</b> (\"It is X that...\") — }</li><li><b>Inversion</b> (\"Not only does...\") — } 10-15%</li><li><b>Passive</b> (\"It is widely believed...\") — }</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Essay 250 từ (~13 câu): ~3 simple + 3 compound + 6 complex + 1-2 advanced</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Band 5 = 70% simple. Band 7 = Complex chiếm gần NỬA.\"</p></div>","p":1},{"id":"W7D3-S-02","l":26,"t":"S","st":"Structure","s":3,"tags":["academic-tone","rules"],"f":"<p>5 quy tắc Academic Tone trong IELTS Writing?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>No contractions</b> — don't → do not, can't → cannot</li><li><b>No informal language</b> — kids → children, a lot of → a considerable number of</li><li><b>Hedging</b> — \"IS the best\" → \"could be considered one of the most effective\"</li><li><b>No personal anecdotes</b> — \"My friend...\" → \"Research indicates...\"</li><li><b>Nominalisation</b> — \"People move\" → \"The migration\"</li></ol></div><div class=\"sec\"><p class=\"bad\"><span class=\"lbl\">VD</span>❌ \"I think kids nowadays don't study hard\" → ✅ \"It is widely observed that young people in contemporary society tend to exhibit lower levels of academic commitment\"</p></div>","p":1},{"id":"W7D3-S-03","l":26,"t":"S","st":"Structure","s":2,"tags":["cleft-sentence","emphasis"],"f":"<p>Cleft sentence — công thức + khi nào dùng?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Công thức:</b> <b>It is/was [X] that [clause]</b></li><li><b>Dùng khi:</b> Muốn nhấn mạnh 1 yếu tố cụ thể</li><li><b>Vị trí:</b> Topic sentence hoặc conclusion</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Education plays the most crucial role.\" → \"<b>It is</b> education <b>that</b> plays the most crucial role.\"</p></div>","p":1},{"id":"W7D3-S-04","l":26,"t":"S","st":"Structure","s":2,"tags":["inversion","formal-tone"],"f":"<p>3 patterns inversion phổ biến nhất trong IELTS Writing?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Not only</b> + aux + S + V, <b>but</b> S <b>also</b> V</li><li><b>Rarely / Seldom</b> + aux + S + V</li><li><b>Only by</b> + gerund + <b>can</b> + S + V</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Not only <b>does</b> technology improve communication, <b>but it also</b> enhances productivity.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Dùng 1-2 lần/essay. Quá nhiều = unnatural.</p></div>","p":1},{"id":"W7D3-P-01","l":26,"t":"P","st":"Phrase","s":3,"tags":["hedging","academic-tone"],"f":"<p>Technology ______ (có thể được coi là) one of the most effective solutions to environmental challenges.</p>","a":"<b>could be considered</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Investment in renewable energy could be considered the most sustainable approach to reducing carbon emissions.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"may be regarded as\" | \"might be seen as\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body/conclusion — khi đưa ra đánh giá, tránh nói quá tuyệt đối</p></div>","p":1},{"id":"W7D3-P-02","l":26,"t":"P","st":"Phrase","s":3,"tags":["hedging","passive"],"f":"<p>______ (Nhiều người thừa nhận rằng) education is of paramount importance for socioeconomic mobility.</p>","a":"<b>It is widely acknowledged that</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"It is widely acknowledged that access to healthcare significantly influences quality of life.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"It is generally recognised that\" | \"It is commonly accepted that\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Topic sentence hoặc opening — thay thế \"Everyone knows that\" / \"I think\"</p></div>","p":1},{"id":"W7D3-P-03","l":26,"t":"P","st":"Phrase","s":2,"tags":["hedging","modal"],"f":"<p>Well-funded public transit systems ______ (có xu hướng) reduce the volume of private vehicles on roads.</p>","a":"<b>tend to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Countries with higher education budgets tend to achieve greater economic growth.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"are inclined to\" | \"have a tendency to\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi nêu xu hướng chung thay vì khẳng định tuyệt đối</p></div>","p":1},{"id":"W7D3-P-04","l":26,"t":"P","st":"Phrase","s":2,"tags":["nominalisation","academic-tone"],"f":"<p>______ (Sự di cư) to urban centres in search of employment opportunities has further highlighted the skills gap.</p>","a":"<b>The migration</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The migration of rural populations to cities has placed considerable strain on urban infrastructure.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"The movement\" | \"The relocation\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — biến verb thành noun phrase để nâng academic tone</p></div>","p":1},{"id":"W7D3-P-05","l":26,"t":"P","st":"Phrase","s":2,"tags":["formal-alternative","emphasis"],"f":"<p>Education is ______ (cực kỳ quan trọng) for national development.</p>","a":"<b>of paramount importance</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Access to clean water is of paramount importance for public health in developing nations.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"of critical significance\" | \"vitally important\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body/conclusion — thay thế \"very important\" (informal)</p></div>","p":1},{"id":"W7D3-P-06","l":26,"t":"P","st":"Phrase","s":2,"tags":["formal-alternative","quantifier"],"f":"<p>______ (Rất nhiều) children in developing countries are unable to access quality education.</p>","a":"<b>A considerable number of</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"A considerable number of employees have reported increased productivity when working remotely.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"A significant proportion of\" | \"Numerous\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Mọi nơi trong essay — thay thế \"a lot of / lots of / many\" (informal)</p></div>","p":1},{"id":"W7D3-E-01","l":26,"t":"E","st":"Error","s":3,"tags":["mistake","contraction"],"f":"<p><i>\"The government shouldn't ignore this problem because it can't be solved without intervention.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Dùng contractions (shouldn't, can't) — informal, không phù hợp academic writing.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The government <b>should not</b> ignore this problem because it <b>cannot</b> be solved without intervention.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>IELTS Writing = academic register → KHÔNG BAO GIỜ dùng contractions (don't, can't, won't, it's...).</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR + GRA</p></div>","p":0},{"id":"W7D3-E-02","l":26,"t":"E","st":"Error","s":3,"tags":["mistake","informal-language"],"f":"<p><i>\"Nowadays, a lot of kids don't have access to good education because of bad government policies.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Informal language: \"a lot of\" (→ a considerable number of), \"kids\" (→ children), \"good\" (→ quality), \"bad\" (→ ineffective/inadequate), \"nowadays\" (→ in contemporary society), contraction \"don't\" (→ do not).</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"In contemporary society, a considerable number of children do not have access to quality education owing to inadequate government policies.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Thay TẤT CẢ informal words bằng formal equivalents. Mỗi từ informal = mất điểm LR.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR</p></div>","p":0},{"id":"W7D3-E-03","l":26,"t":"E","st":"Error","s":2,"tags":["mistake","personal-anecdote"],"f":"<p><i>\"I think education is very important. In my country, my friend dropped out of school and now he can't find a good job.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Personal anecdote (\"my friend\") + personal opinion không hedge (\"I think\") + contraction (\"can't\"). IELTS Writing ≠ personal story.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"It is widely recognised that education is of paramount importance. Research indicates that individuals who do not complete formal schooling face significantly reduced employment prospects.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>KHÔNG dùng personal stories/examples (my friend, my country, I saw...) → thay bằng \"Research indicates\", \"Evidence suggests\", \"In many nations\".</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + LR</p></div>","p":0},{"id":"W7D3-E-04","l":26,"t":"E","st":"Error","s":2,"tags":["mistake","hedging"],"f":"<p><i>\"Technology IS the best solution to all environmental problems. Everyone KNOWS this is true.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Quá tuyệt đối — \"IS the best\", \"all problems\", \"Everyone KNOWS\" → không có hedging, thiếu nuance. Academic writing KHÔNG khẳng định 100%.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Technology <b>could be considered</b> one of the most effective solutions to <b>many</b> environmental challenges. <b>It is widely acknowledged</b> that this is <b>largely</b> the case.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Dùng hedging (may/might/could/tend to/it appears that) → thể hiện academic caution. Tránh \"all/every/always/never/the best/the worst\".</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + LR</p></div>","p":0},{"id":"W8D1-S-01","l":27,"t":"S","st":"Structure","s":3,"tags":["essay-type","two-part","identification"],"f":"<p>Cách nhận diện đề <b>Two-Part Question</b>? Phân biệt với Discussion Essay?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Two-Part</b>: 2 câu hỏi <b>RIÊNG BIỆT</b> → đếm <b>2 dấu \"?\"</b> trong đề</li><li><b>Discussion</b>: 1 topic, 2 sides → \"Discuss both views\" (chỉ 1 dấu \"?\")</li><li>Two-Part: Body 1 = Answer Q1, Body 2 = Answer Q2 (2 chủ đề ĐỘC LẬP)</li><li>Discussion: Body 1 = View A, Body 2 = View B (1 chủ đề, 2 góc nhìn)</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Why is this happening? Is this positive or negative?\" = Two-Part (2 \"?\"). \"Discuss both views and give your opinion.\" = Discussion (1 \"?\").</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Đếm dấu \"?\" — 2 dấu hỏi = Two-Part.</p></div>","p":1},{"id":"W8D1-S-02","l":27,"t":"S","st":"Structure","s":3,"tags":["essay-structure","two-part","blueprint"],"f":"<p>Cấu trúc <b>4 đoạn chuẩn</b> cho Two-Part Question Essay? Mỗi phần bao nhiêu từ?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Introduction</b> (~30-40 từ, 2 câu): Paraphrase đề + Preview 2 phần sẽ trả lời</li><li><b>Body 1</b> (~80-100 từ): Trả lời Q1 — TEES structure</li><li><b>Body 2</b> (~80-100 từ): Trả lời Q2 — TEES structure</li><li><b>Conclusion</b> (~20-30 từ, 1-2 câu): Tóm tắt cả 2 phần</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Intro = paraphrase + \"This essay will examine [Q1] and [Q2].\" → Body 1 (causes ~90 từ) → Body 2 (solutions ~90 từ) → Conclusion = summary. Tổng: ~250-280 từ.</p></div>","p":1},{"id":"W8D1-S-03","l":27,"t":"S","st":"Structure","s":3,"tags":["task-achievement","half-answer-trap","two-part"],"f":"<p>\"Half-Answer Trap\" là gì? Kể <b>3 dạng</b> và Band Impact?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Half-Answer Trap</b> = chỉ trả lời đầy đủ <b>1 trong 2 câu hỏi</b> → TA giảm ít nhất 1 band</li><li>3 dạng:</li></ul><ol><li><b>Complete Skip</b> — quên câu 2 hoàn toàn → TA Band 4-5<div><b>Token Answer</b> — câu 2 chỉ 2 dòng (30 từ) → TA Band 5</div><div><b>Merged Answer</b> — trộn 2 câu hỏi vào nhau, không phân biệt rõ → TA Band 5-6</div></li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Body 1 = 180 từ, Body 2 = 30 từ = Token Answer → TA Band 5.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>3-Step Check trước khi viết: ① Đếm \"?\" ② Gạch chân 2 câu ③ Ghi Q1 = ___, Q2 = ___</p></div>","p":1},{"id":"W8D1-S-04","l":27,"t":"S","st":"Structure","s":3,"tags":["equal-weight","word-balance","two-part"],"f":"<p>\"Equal Weight\" technique — mỗi body bao nhiêu từ? Chênh lệch tối đa? Kỹ thuật giữ balance?</p>","a":"","b":"<div class=\"sec\"><ul><li>Mỗi body: <b>~80-100 từ</b></li><li>Chênh lệch tối đa: <b>~20 từ</b></li><li>4 kỹ thuật:</li></ul><ol><li><b>Planning trước</b> — brainstorm 2-3 ý mỗi câu → chọn 1-2 ý mạnh nhất<div><b>Đếm từ khi viết</b> — ước lượng: 1 dòng ≈ 10-12 từ</div><div><b>Quality &gt; Quantity</b> — 1-2 ý phát triển SÂU hơn 5 ý liệt kê</div><div><b>TEES for both</b> — tự động ≈ 80-100 từ mỗi đoạn</div></li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>90 từ vs 85 từ = ✅ Balanced. 150 từ vs 50 từ = ❌ TA Band 5-6.</p></div>","p":1},{"id":"W8D1-P-01","l":27,"t":"P","st":"Phrase","s":3,"tags":["collocation","cause-analysis","topic-sentence"],"f":"<p>The escalating levels of stress ______ (có thể được quy cho) several key factors.</p>","a":"<b>can be primarily attributed to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The decline in reading habits can be primarily attributed to the widespread use of social media.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"can be largely attributed to\" | \"stem primarily from\" | \"are chiefly the result of\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph (Topic sentence) — khi phân tích nguyên nhân trong Two-Part / Problem-Solution essay</p></div>","p":1},{"id":"W8D1-P-02","l":27,"t":"P","st":"Phrase","s":2,"tags":["collocation","work-pressure","body-paragraph"],"f":"<p>Employees are often ______ (bị kỳ vọng làm việc nhiều giờ) while simultaneously meeting demanding targets.</p>","a":"<b>expected to work extended hours</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"In many Asian economies, teachers are expected to work extended hours grading assignments and attending meetings.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"required to put in long hours\" | \"compelled to work overtime\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về work-life balance, stress, employment issues</p></div>","p":1},{"id":"W8D1-P-03","l":27,"t":"P","st":"Phrase","s":3,"tags":["collocation","transition","two-part"],"f":"<p>______ (Chuyển sang giải pháp), both governments and individuals can take concrete steps.</p>","a":"<b>Turning to possible solutions</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Turning to the effects on their home countries, this trend produces both negative and positive consequences.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"With regard to possible solutions\" | \"Regarding measures to address this issue\" | \"As for whether this is a positive development\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body 2 (Topic sentence) — transition giữa 2 body paragraphs trong Two-Part essay. KHÔNG dùng \"Secondly\" cho mục đích này.</p></div>","p":1},{"id":"W8D1-P-04","l":27,"t":"P","st":"Phrase","s":2,"tags":["collocation","career","paraphrase"],"f":"<p>A growing number of young professionals are opting to ______ (theo đuổi sự nghiệp ở nước ngoài).</p>","a":"<b>pursue careers overseas</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Many skilled workers pursue careers overseas in search of better salaries and professional development.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"seek employment abroad\" | \"work in foreign countries\" | \"build careers in other nations\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Introduction / Body paragraph — paraphrase \"work abroad\" / \"go to other countries for work\"</p></div>","p":1},{"id":"W8D1-P-05","l":27,"t":"P","st":"Phrase","s":2,"tags":["collocation","brain-drain","effects"],"f":"<p>The departure of skilled workers ______ (tạo nên hiện tượng chảy máu chất xám đáng kể).</p>","a":"<b>constitutes a significant \"brain drain\"</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The emigration of doctors and engineers constitutes a significant brain drain, undermining the country's healthcare and infrastructure.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"represents a major loss of talent\" | \"leads to a significant outflow of skilled workers\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về migration, globalisation, effects on developing countries</p></div>","p":1},{"id":"W8D1-P-06","l":27,"t":"P","st":"Phrase","s":2,"tags":["collocation","education","flexibility"],"f":"<p>Home education allows parents to ______ (điều chỉnh chương trình) to their child's individual learning pace.</p>","a":"<b>tailor the curriculum</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Progressive schools tailor the curriculum to accommodate students with different learning styles and abilities.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"customise the syllabus\" | \"adapt the learning programme\" | \"personalise the educational content\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về education, home schooling, personalised learning</p></div>","p":1},{"id":"W8D1-P-07","l":27,"t":"P","st":"Phrase","s":2,"tags":["collocation","conclusion","offset"],"f":"<p>While the immediate loss of human capital is concerning, the financial contributions of the diaspora ______ (bù đắp một phần) this disadvantage.</p>","a":"<b>partially offset</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The economic benefits of tourism partially offset the environmental damage caused by overdevelopment.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"partly compensate for\" | \"go some way towards mitigating\" | \"somewhat counterbalance\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph / Conclusion — khi cân nhắc 2 mặt (negative + positive) trong Two-Part hoặc Discussion essay</p></div>","p":1},{"id":"W8D1-E-01","l":27,"t":"E","st":"Error","s":3,"tags":["mistake","half-answer","task-achievement"],"f":"<p><i>\"Nowadays, many people are stressed. I will write about the causes and solutions of stress.\"</i> (Introduction) — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>(1) Copy gần nguyên đề — không paraphrase. (2) \"I will write about\" — quá đơn giản, không academic. (3) \"causes and solutions of stress\" — sai collocation (\"solutions <b>to</b> stress\", không phải \"of\").</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"An increasing number of individuals across the globe are experiencing heightened levels of stress. This essay will explore the primary <b>factors contributing to</b> this trend <b>as well as</b> several practical <b>measures</b> that could be implemented to alleviate the problem.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Introduction Two-Part = paraphrase đề (đổi ≥3 từ) + preview CẢ 2 phần bằng academic language. KHÔNG copy đề nguyên văn.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR + TA</p></div>","p":0},{"id":"W8D1-E-02","l":27,"t":"E","st":"Error","s":3,"tags":["mistake","listing","development"],"f":"<p><i>\"There are many causes. First, work. Second, school. Third, money. Fourth, family. Fifth, health.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Liệt kê 5 ý NÔNG — không có explanation, không có example, không phát triển ý nào.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Chọn 1-2 ý → phát triển SÂU bằng TEES: \"The primary cause is work-related pressure. In today's competitive economy, employees are expected to work extended hours, often exceeding 50 hours per week. A WHO survey confirmed that over 60% of workers report chronic overwork.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Band 7 = \"presents, extends and supports main ideas\" — 1-2 ý SÂU (explain + example + impact) luôn tốt hơn 5 ý NÔNG.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA</p></div>","p":0},{"id":"W8D1-E-03","l":27,"t":"E","st":"Error","s":3,"tags":["mistake","firstly-secondly","linking-device"],"f":"<p><i>\"Firstly, there are many causes of stress. ... Secondly, there are solutions.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Dùng \"Firstly/Secondly\" để chuyển giữa 2 câu hỏi KHÁC NHAU — sai cấp linking device.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The main causes of stress relate to... <b>Turning to possible solutions</b>, a combination of government and individual action could...\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>\"Firstly/Secondly\" chỉ dùng để liệt kê ý TRONG 1 paragraph (First reason..., Second reason...). Chuyển giữa 2 câu hỏi → dùng transition phrases: \"Turning to...\", \"With regard to...\", \"As for...\".</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC</p></div>","p":0},{"id":"W8D1-E-04","l":27,"t":"E","st":"Error","s":3,"tags":["mistake","two-part-vs-discussion","essay-type"],"f":"<p>Đề: <i>\"What are the causes of stress? What solutions can you suggest?\"</i> — Thí sinh viết: Body 1 = causes, Body 2 = solutions NỐI TIẾP TỪ causes (viết theo chuỗi). Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Nhầm Two-Part thành Problem-Solution — viết theo chuỗi logic (cause → effect → solution) thay vì 2 câu trả lời ĐỘC LẬP.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Body 1 trả lời Q1 (causes) <b>hoàn chỉnh</b> với TEES riêng. Body 2 trả lời Q2 (solutions) <b>hoàn chỉnh</b> với TEES riêng. Mỗi phần tự đứng được.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Two-Part = 2 câu hỏi ĐỘC LẬP, mỗi body có TEES riêng. Problem-Solution = 1 chuỗi liên kết (cause → effect → solution). Phân biệt: đếm dấu \"?\" trong đề.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA</p></div>","p":0},{"id":"W8D1-E-05","l":27,"t":"E","st":"Error","s":2,"tags":["mistake","conclusion","new-idea"],"f":"<p><i>\"In conclusion, stress has many causes and we should try to reduce it. I hope people will be less stressed in the future.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>(1) Quá chung chung — không tóm tắt cụ thể 2 phần đã viết. (2) \"I hope people will be less stressed\" — thêm ý mới ở conclusion.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"In conclusion, while the primary cause of rising stress levels is the <b>demanding nature</b> of modern work life, this issue can be <b>effectively addressed</b> through a combination of <b>government regulation</b> and <b>individual coping strategies</b>.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Conclusion = tóm tắt CỤ THỂ cả 2 phần đã viết. KHÔNG thêm ý mới — examiner coi ý mới ở conclusion là \"chưa develop\" → CC giảm.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + CC</p></div>","p":0},{"id":"W8D2-S-01","l":28,"t":"S","st":"Structure","s":3,"tags":["process","data-chart","comparison"],"f":"<p>Process diagram khác Data Chart (line/bar/pie) ở những điểm nào? Kể ít nhất 4 khác biệt.</p>","a":"","b":"<div class=\"sec\"><div class=\"tw\"><table><thead><tr><th>Tiêu chí</th><th>Data Chart</th><th>Process</th></tr></thead><tbody><tr><td><b>Mô tả gì</b></td><td>Trends + Comparisons</td><td>Steps + Stages</td></tr><tr><td><b>Ngôn ngữ</b></td><td>increased, decreased, the highest</td><td>passive voice + sequencing markers</td></tr><tr><td><b>Voice</b></td><td>Active hoặc Passive</td><td><b>Passive BẮT BUỘC</b> (man-made)</td></tr><tr><td><b>Số liệu</b></td><td>Có (%, numbers, years)</td><td>Không</td></tr><tr><td><b>Linking</b></td><td>whereas, by contrast</td><td>First, Then, Subsequently, Finally</td></tr></tbody></table></div></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Data: \"Sales <b>increased</b> by 20%.\" → Process: \"The powder <b>is heated</b> to 1400°C.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Data = ĐỌC SỐ LIỆU + SO SÁNH. Process = MÔ TẢ QUY TRÌNH từ đầu đến cuối. 3 bộ từ vựng hoàn toàn khác.</p></div>","p":1},{"id":"W8D2-S-02","l":28,"t":"S","st":"Structure","s":3,"tags":["process","voice-rule","natural-vs-manmade"],"f":"<p>Natural Process vs Man-made Process — khác nhau thế nào về <b>voice</b> (active/passive)?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Man-made process</b> (cement, recycling, food processing):</li></ul><p>→ Passive voice <b>BẮT BUỘC 100%</b>: <i>\"The beans <b>are roasted</b>\"</i> — focus vào sản phẩm, không phải con người</p><ul><li><b>Natural process</b> (water cycle, life cycle, erosion):</li></ul><p>→ <b>Active voice CHÍNH</b> + passive xen kẽ: <i>\"Water <b>evaporates</b>\"</i>, <i>\"Eggs <b>are laid</b> on leaves\"</i></p><p>→ Mix cả 2 = Band 7 GRA (chứng tỏ grammatical range)</p></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Man-made: <del>\"Workers grind the cement\"</del> → \"The cement <b>is ground</b> into powder.\" Natural: \"The tadpole <b>develops</b> legs\" (active ✅) + \"Eggs <b>are laid</b> by the female\" (passive ✅).</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Man-made = passive 100%. Natural = active chính + passive xen kẽ.</p></div>","p":1},{"id":"W8D2-S-03","l":28,"t":"S","st":"Structure","s":3,"tags":["process","essay-structure","formula"],"f":"<p>Cấu trúc 4 đoạn cho <b>Process Description</b>? Mỗi phần viết gì?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Introduction</b> (~1 câu): Paraphrase đề — <i>\"The diagram illustrates the process by which [product] is [produced].\"</i></li><li><b>Overview</b> (~2 câu): Bao nhiêu stages? Linear hay cyclical? — <i>\"Overall, the production involves [N] main stages, beginning with [X] and ending with [Y].\"</i></li><li><b>Body 1</b> (~4-5 câu): First half of stages (Stage 1 → N/2)</li><li><b>Body 2</b> (~4-5 câu): Second half of stages (Stage N/2+1 → cuối)</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Intro+Overview có thể gộp 1 đoạn hoặc tách 2 đoạn — cả 2 đều được. Nhưng <b>PHẢI CÓ overview</b> — thiếu overview → TA giảm 1 band.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Nhớ: Intro = paraphrase, Overview = đếm stages + linear/cyclical, Body = chia đôi stages.</p></div>","p":1},{"id":"W8D2-S-04","l":28,"t":"S","st":"Structure","s":3,"tags":["map","tense-rule","historical-vs-proposed"],"f":"<p>2 dạng Map trong IELTS Task 1? Mỗi dạng dùng <b>tense</b> gì?</p>","a":"","b":"<div class=\"sec\"><div class=\"tw\"><table><thead><tr><th>Dạng</th><th>Tense</th><th>Ví dụ</th></tr></thead><tbody><tr><td><b>Historical Map</b> (1980 vs 2020)</td><td><b>Past Simple Passive</b></td><td><i>\"A hospital <b>was built</b>. Farmland <b>was replaced</b> by housing.\"</i></td></tr><tr><td><b>Historical</b> (1980 vs now)</td><td><b>Past Simple + Present Perfect</b></td><td><i>\"In 1980, it <b>was</b> farmland. <b>Since then</b>, it <b>has been transformed</b>.\"</i></td></tr><tr><td><b>Proposed Development</b></td><td><b>Future / Modal verbs</b></td><td><i>\"A school <b>will be built</b>. The park <b>is set to be</b> expanded.\"</i></td></tr></tbody></table></div></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Sai tense: <del>\"In 1990, a school is built\"</del> → Đúng: \"In 1990, a school <b>was built</b>\" (1990 = quá khứ → past tense).</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Nhìn NĂM trong đề: cả 2 quá khứ → past simple. Có \"now\" → thêm present perfect. \"Proposed/planned\" → future.</p></div>","p":1},{"id":"W8D2-S-05","l":28,"t":"S","st":"Structure","s":2,"tags":["map","select-dont-list","grouping"],"f":"<p>Nguyên tắc \"Select, Don't List\" cho Map? Cách chọn features nào để mô tả?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Nguyên tắc</b>: Chọn <b>4-5 thay đổi LỚN NHẤT</b> → bỏ qua chi tiết nhỏ</li><li><b>Ưu tiên chọn:</b></li></ul><ol><li>Thay đổi <b>DRAMATIC</b> — xây mới/phá dỡ hoàn toàn<div>Thay đổi <b>DIỆN TÍCH LỚN</b> — khu đất lớn chuyển đổi</div><div>Features <b>KHÔNG thay đổi</b> — đề cập ngắn gọn (1 câu)</div><div>Chi tiết nhỏ → <b>BỎ QUA</b></div></li></ol><ul><li><b>2 chiến thuật tổ chức</b>: Group by <b>TIME</b> (phổ biến cho historical: Body 1 = Map 1, Body 2 = Map 2) hoặc Group by <b>AREA</b> (phổ biến cho proposed: Body 1 = Bắc, Body 2 = Nam)</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Map 12 features → chọn: farmland→housing (dramatic), new motorway (dramatic), factory→museum (conversion), river unchanged (no change). Bỏ: thêm 1 bus stop (quá nhỏ).</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Historical 2 maps → group by TIME. Proposed 1 map → group by AREA.</p></div>","p":1},{"id":"W8D2-P-01","l":28,"t":"P","st":"Phrase","s":2,"tags":["process","introduction","paraphrase"],"f":"<p>The diagram ______ (minh họa quy trình mà) cement ______ (được sản xuất) from raw materials.</p>","a":"<b>illustrates the process by which ... is manufactured</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The diagram <b>illustrates the process by which</b> olive oil <b>is produced</b>, from the initial cultivation to the final packaging stage.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"shows how [X] is [produced/processed/recycled]\" | \"depicts the stages involved in the production of [X]\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Câu đầu tiên (Introduction) của mọi process description — paraphrase đề.</p></div>","p":1},{"id":"W8D2-P-02","l":28,"t":"P","st":"Phrase","s":2,"tags":["process","overview","formula"],"f":"<p>Overall, this is ______ (một quy trình tuyến tính gồm) eight ______ (các giai đoạn liên tiếp).</p>","a":"<b>a linear process comprising ... sequential stages</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Overall, this is <b>a linear process comprising</b> eight <b>sequential stages</b>, beginning with the growing of olives and culminating in the bottling of the finished product.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"involves [N] main stages\" | \"consists of [N] distinct steps\" | \"a cyclical process involving [N] stages\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Overview sentence — nêu tổng quan: đếm stages + linear/cyclical.</p></div>","p":1},{"id":"W8D2-P-03","l":28,"t":"P","st":"Phrase","s":2,"tags":["process","sequencing","advanced"],"f":"<p>The powder is ______ (sau đó) heated to 1400°C. ______ (Tiếp theo đó), the calcium powder is transferred to a grinder.</p>","a":"<b>subsequently ... Following this</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The powder is <b>subsequently</b> heated to 1400°C. <b>Following this</b>, the calcium powder is transferred to a grinder.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"In the subsequent stage\" | \"At the next stage\" | \"Thereafter\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraphs — nối các steps giữa (Tier 2 sequencing cho Band 6.5-7+). Mix với Tier 1 (Then, Next) để đa dạng.</p></div>","p":1},{"id":"W8D2-P-04","l":28,"t":"P","st":"Phrase","s":3,"tags":["process","sequencing","complex-grammar"],"f":"<p>______ the mixture ______ (đã được nung nóng), it ______ (được làm nguội) rapidly. [Viết dạng temporal clause]</p>","a":"<b>Once ... has been heated ... is cooled</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"<b>Once</b> the paste <b>has been prepared</b>, it <b>is pressed</b> to extract the liquid content.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"After [X] has been [pp]\" | \"When [X] has been [pp]\" | \"Having been [pp], [main clause]\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Complex grammar cho Band 7+ — nối 2 steps liền nhau, step trước là điều kiện của step sau.</p></div>","p":1},{"id":"W8D2-P-05","l":28,"t":"P","st":"Phrase","s":3,"tags":["process","participle-clause","complex-grammar"],"f":"<p>______ (Đã được nghiền thành các mảnh nhỏ), the limestone is mixed with clay. [Viết dạng participle clause]</p>","a":"<b>Having been crushed into small pieces</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"<b>Having been crushed into small pieces</b>, the limestone is mixed with clay and fed into a cylindrical heater.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"Once crushed, ...\" (reduced form) | \"After being crushed, ...\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Complex grammar Band 7+ — mở đầu câu bằng participle clause, nối 2 bước liền nhau thành 1 câu phức.</p></div>","p":1},{"id":"W8D2-P-06","l":28,"t":"P","st":"Phrase","s":2,"tags":["map","spatial-language","location"],"f":"<p>A new car park was constructed ______ (kề bên) the shopping centre.</p>","a":"<b>adjacent to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Adjacent to the main road, a primary school was constructed.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"next to\" | \"bordering\" | \"adjoining\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Map description — vị trí kề sát nhau.</p></div>","p":1},{"id":"W8D2-P-07","l":28,"t":"P","st":"Phrase","s":2,"tags":["map","spatial-language","location"],"f":"<p>The local library was relocated directly ______ (đối diện) the town hall.</p>","a":"<b>opposite</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"A modern sports complex now stands opposite the residential quarter.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"across from\" | \"on the opposite side of\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Map description — vị trí đối diện qua đường hoặc sông.</p></div>","p":1},{"id":"W8D2-P-08","l":28,"t":"P","st":"Phrase","s":2,"tags":["map","change-language","replacement"],"f":"<p>The farmland in the north ______ (đã bị thay thế bởi) a sprawling housing estate.</p>","a":"<b>was replaced by</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The old industrial harbour was replaced by a waterfront promenade.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"was superseded by\" | \"was demolished to make way for\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Map description (historical) — công trình mới thay thế công trình cũ.</p></div>","p":1},{"id":"W8D2-P-09","l":28,"t":"P","st":"Phrase","s":2,"tags":["map","change-language","transformation"],"f":"<p>The agricultural woodland ______ (đã nhường chỗ cho) commercial and residential development.</p>","a":"<b>gave way to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Much of the original green belt gave way to modern suburban housing.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"was cleared for\" | \"made room for\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Map description (historical) — khu đất tự nhiên bị biến thành khu xây dựng.</p></div>","p":1},{"id":"W8D2-P-10","l":28,"t":"P","st":"Phrase","s":2,"tags":["map","change-language","conversion"],"f":"<p>The disused textile factory ______ (đã được chuyển đổi thành) an interactive science museum.</p>","a":"<b>was converted into</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The nineteenth-century railway depot was converted into a bustling retail market.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"was transformed into\" | \"was repurposed into\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Map description — toà nhà cũ được cải tạo công năng.</p></div>","p":1},{"id":"W8D2-E-01","l":28,"t":"E","st":"Error","s":3,"tags":["mistake","process","active-voice"],"f":"<p>Process description viết: <i>\"Workers crush the limestone. They heat the mixture to 1400°C.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Dùng <b>active voice</b> — focus vào người làm (workers, they) thay vì quy trình.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The limestone <b>is crushed</b>. The mixture <b>is heated</b> to 1400°C.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Man-made process = <b>passive voice BẮT BUỘC 100%</b>. Focus vào ACTION + MATERIALS, không phải con người. Active voice cho man-made process = mất GRA marks.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA — sai voice cho task type = Band 5 GRA</p></div>","p":0},{"id":"W8D2-E-02","l":28,"t":"E","st":"Error","s":3,"tags":["mistake","process","map","overview"],"f":"<p>Bài Process/Map nhảy thẳng vào mô tả: <i>\"First, the limestone is crushed...\"</i> mà KHÔNG có Overview. — Mất điểm gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Thiếu Overview — examiner không thấy tổng quan → TA giảm 1 band ngay lập tức.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"<b>Overall</b>, cement production involves <b>five main stages</b>, from the crushing of raw materials to the final grinding.\" → rồi mới vào details.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Band Descriptors yêu cầu <i>\"presents a clear overview of main trends/differences\"</i> cho Band 7. Không overview = TA <b>Band 5 maximum</b>.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA — thiếu overview = giảm ít nhất 1 band</p></div>","p":0},{"id":"W8D2-E-03","l":28,"t":"E","st":"Error","s":3,"tags":["mistake","map","spatial-language"],"f":"<p>Map description viết: <i>\"There is a park. There is a school. There is a road.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Liệt kê features mà <b>KHÔNG mô tả vị trí</b> — examiner không hình dung được map.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"<b>To the north of</b> the river, a park <b>was established</b>. <b>Adjacent to</b> the park, a school <b>was constructed</b>. A main road <b>runs through the centre</b> of the area.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Map description <b>YÊU CẦU</b> spatial language (ít nhất 5 phrases). Thiếu spatial language = TA/CC giảm vì examiner không biết features ở đâu.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + CC — thiếu vị trí = mất tính mạch lạc</p></div>","p":0},{"id":"W8D2-E-04","l":28,"t":"E","st":"Error","s":3,"tags":["mistake","map","tense"],"f":"<p>Historical map (1990 vs 2015) viết: <i>\"In 1990, a school is built near the river.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Dùng <b>present tense</b> cho sự kiện <b>quá khứ</b> (1990).</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"In 1990, a school <b>was built</b> near the river.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Historical map (cả 2 thời điểm quá khứ) → <b>Past Simple Passive</b>. Có \"now\" → Past + Present Perfect. Proposed plan → Future/Modal. Vietnamese speakers hay sai vì tiếng Việt không chia thì.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA — sai tense cơ bản = GRA Band 5</p></div>","p":0},{"id":"W8D2-E-05","l":28,"t":"E","st":"Error","s":2,"tags":["mistake","process","paraphrase","technical-terms"],"f":"<p>Process description viết: <i>\"The powder is placed in a very hot heating device\"</i> thay vì dùng từ \"kiln\" có sẵn trên diagram. — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Cố <b>paraphrase thuật ngữ chuyên môn</b> (kiln → \"very hot heating device\") → mất chính xác, examiner biết bạn đang né từ.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The powder <b>is heated</b> in a <b>kiln</b> at 1400°C.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Paraphrase <b>câu prompt</b> (introduction) nhưng <b>KHÔNG paraphrase technical terms</b> từ diagram (kiln, centrifuge, penstock). Dùng ĐÚNG thuật ngữ mà diagram hiển thị.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR — né từ kỹ thuật = mất accuracy</p></div>","p":0},{"id":"W8D3-S-01","l":29,"t":"S","st":"Structure","s":3,"tags":["time-management","20-40-rule","exam-strategy"],"f":"<p>\"20-40 Rule\" là gì? Phân bổ thời gian cụ thể cho mỗi task?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Task 1: 20 phút</b> (tối đa 25 — KHÔNG ĐƯỢC hơn)</li><li><b>Task 2: 40 phút</b> (tối thiểu 35)</li><li><b>Tổng: 60 phút</b></li></ul><p><b>Chi tiết:</b></p><ul><li>Task 1: Đọc + Phân tích (2-3') → Viết (14-15') → Check (2-3')</li><li>Task 2: Đọc + Planning (5') → Viết (30') → Check (5')</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Task 2 = 66% trọng số → mỗi 0.5 band mất ở Task 2 = mất GẤP ĐÔI so với 0.5 band được ở Task 1. KHÔNG phá rule.</p></div>","p":1},{"id":"W8D3-S-02","l":29,"t":"S","st":"Structure","s":3,"tags":["time-management","task-weight","scoring"],"f":"<p>Task 1 và Task 2 chiếm bao nhiêu % trọng số? Nếu phải hy sinh, hy sinh task nào?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Task 1 = 33%</b> (1/3) — yêu cầu ≥ 150 từ</li><li><b>Task 2 = 66%</b> (2/3) — yêu cầu ≥ 250 từ</li></ul><p><b>Rule bất di bất dịch:</b> Task 2 PHẢI hoàn chỉnh (có Conclusion) + ≥ 250 từ. Hy sinh Task 1 nếu cần — KHÔNG BAO GIỜ hy sinh Task 2.</p></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Task 1 \"hoàn hảo\" (30') + Task 2 thiếu Conclusion (30') → Overall GIẢM ~0.5 band so với Task 1 \"đủ tốt\" (20') + Task 2 hoàn chỉnh (40').</p></div>","p":1},{"id":"W8D3-S-03","l":29,"t":"S","st":"Structure","s":3,"tags":["proofread","checklist","exam-strategy"],"f":"<p>5-Minute Proofread Checklist — thứ tự ưu tiên sửa lỗi khi còn 2-5 phút cuối?</p>","a":"","b":"<div class=\"sec\"><p>Sửa theo thứ tự <b>impact cao → thấp:</b></p><ol><li>🔴 <b>Subject-Verb Agreement</b> — tìm subject thật → verb khớp chưa? (1')</li><li>🔴 <b>Tense consistency</b> — tense khớp với data/map? nhất quán? (1')</li><li>🟡 <b>Articles (a/an/the)</b> — specific (the) vs general (Ø)? (1')</li><li>🟡 <b>Contractions</b> — \"don't\" → \"do not\", \"can't\" → \"cannot\" (30\")</li><li>🟢 <b>Spelling + Punctuation</b> — focus từ hay sai + dấu chấm cuối câu (30\")</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Đọc nhanh hơn bình thường — chỗ nào phải dừng lại = chỗ có lỗi. Không chắc → để nguyên, đừng over-correct.</p></div>","p":1},{"id":"W8D3-S-04","l":29,"t":"S","st":"Structure","s":3,"tags":["emergency","time-management","exam-strategy"],"f":"<p>Hết 20 phút mà Task 1 chưa xong — xử lý thế nào theo từng tình huống?</p>","a":"","b":"<div class=\"sec\"><div class=\"tw\"><table><thead><tr><th>Tình huống</th><th>Action</th></tr></thead><tbody><tr><td>Thiếu Conclusion Task 1</td><td><b>Bỏ</b> → chuyển Task 2 (Task 1 không bắt buộc conclusion)</td></tr><tr><td>Thiếu vài chi tiết Body 2</td><td>Viết nhanh 1-2 câu tóm gọn → chuyển</td></tr><tr><td>Mới ~100 từ</td><td>Viết thêm 50 từ (tổng ≥ 150) → chuyển. KHÔNG cố \"hoàn hảo\"</td></tr><tr><td>Chưa viết gì (quên!)</td><td>Viết Task 2 TRƯỚC → 15-18' cuối viết Task 1 nhanh</td></tr></tbody></table></div></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Task 2 PHẢI hoàn chỉnh. Hy sinh Task 1 nếu cần.</p></div>","p":1},{"id":"W8D3-S-05","l":29,"t":"S","st":"Structure","s":2,"tags":["band-descriptors","self-assessment","scoring"],"f":"<p>Công thức tính Overall Writing Band Score từ Task 1 và Task 2?</p>","a":"","b":"<div class=\"sec\"><ol><li>Chấm mỗi task theo <b>4 tiêu chí</b> (TA + CC + LR + GRA) → trung bình = Band score task đó</li><li><b>Overall = Task 1 × 1/3 + Task 2 × 2/3</b></li><li>Làm tròn lên/xuống đến <b>0.5 gần nhất</b></li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Task 1 = 6.0, Task 2 = 6.5 → Overall = (6.0 × 0.33) + (6.5 × 0.67) = 1.98 + 4.36 = 6.34 → <b>6.5</b></p></div>","p":1},{"id":"W8D3-S-06","l":29,"t":"S","st":"Structure","s":2,"tags":["best-practice","mindset","exam-strategy"],"f":"<p>Kể 4 \"Best Practices\" quan trọng nhất khi vào phòng thi IELTS Writing?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Luôn làm Task 1 trước</b> — dễ \"xong\" → tạo momentum cho Task 2</li><li><b>Planning 3-5 phút Task 2</b> trước khi viết — outline rõ → viết nhanh + đúng hướng</li><li><b>Đếm từ</b> sau mỗi task — ≥ 150 (T1) và ≥ 250 (T2) → tránh TA penalty</li><li><b>Dành 2-5 phút cuối proofread</b> — sửa article, tense, S-V → GRA tăng 0.5 band dễ dàng</li></ol><p><b>Mindset:</b> \"Viết XONG &gt; Viết HAY\" — bài hoàn chỉnh với vài lỗi nhỏ LUÔN score cao hơn bài hay nhưng thiếu Conclusion.</p></div>","p":1},{"id":"W8D3-P-01","l":29,"t":"P","st":"Phrase","s":3,"tags":["collocation","process","introduction"],"f":"<p>The diagram ______ (minh hoạ quy trình mà) instant noodles are manufactured.</p>","a":"<b>illustrates the process by which</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The diagram illustrates the process by which cement is produced, from the extraction of raw materials to the final packaging.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"shows the stages involved in\" | \"depicts the procedure by which\" | \"outlines the method by which\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Introduction — Task 1 Process diagram. Dùng \"by which\" + passive voice thay vì \"how\".</p></div>","p":1},{"id":"W8D3-P-02","l":29,"t":"P","st":"Phrase","s":3,"tags":["collocation","process","overview"],"f":"<p>Overall, the production process involves eight main stages, ______ (bắt đầu từ) flour storage ______ (và kết thúc ở) the distribution of the product.</p>","a":"<b>beginning with</b> ... <b>and culminating in</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Overall, the manufacturing process comprises six distinct phases, beginning with the harvesting of cocoa beans and culminating in the packaging of chocolate bars.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"starting with... and ending with\" | \"commencing with... and concluding with\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Overview — Task 1 Process. Dùng participle clause (beginning/culminating) = GRA Band 7.</p></div>","p":1},{"id":"W8D3-P-03","l":29,"t":"P","st":"Phrase","s":2,"tags":["collocation","process","sequencing"],"f":"<p>______ (Một khi mì đã được cắt), they are steamed at 100°C.</p>","a":"<b>Once the noodles have been cut</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Once the mixture has been thoroughly blended, it is poured into moulds and left to set.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"After the noodles have been cut\" | \"Following the cutting stage\" | \"Having been cut\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — Task 1 Process. Temporal clause nối 2 stages liền kề = CC + GRA Band 7.</p></div>","p":1},{"id":"W8D3-P-04","l":29,"t":"P","st":"Phrase","s":3,"tags":["collocation","inequality","paraphrase"],"f":"<p>The ______ (khoảng cách ngày càng lớn giữa) wealthy and disadvantaged individuals has become a pressing concern.</p>","a":"<b>widening disparity between</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The widening disparity between urban and rural communities has become a pressing social issue in developing nations.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"growing gap between\" | \"increasing divide between\" | \"escalating inequality between\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Introduction — paraphrase \"gap between rich and poor\" = LR Band 7.</p></div>","p":1},{"id":"W8D3-P-05","l":29,"t":"P","st":"Phrase","s":3,"tags":["collocation","cause-analysis","inequality"],"f":"<p>The wealth gap ______ (có thể chủ yếu do) disparities in educational access and the rapid advancement of technology.</p>","a":"<b>can be largely attributed to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The decline in biodiversity can be largely attributed to habitat destruction and industrial pollution.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"can be primarily attributed to\" | \"stems predominantly from\" | \"is chiefly the result of\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph (Topic sentence) — khi phân tích nguyên nhân. Passive structure = academic tone.</p></div>","p":1},{"id":"W8D3-P-06","l":29,"t":"P","st":"Phrase","s":2,"tags":["collocation","solution","taxation"],"f":"<p>Implementing ______ (hệ thống thuế luỹ tiến), whereby higher earners contribute a greater proportion, would generate revenue for social welfare.</p>","a":"<b>progressive taxation systems</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Governments should implement progressive taxation systems to redistribute wealth and fund essential public services.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"graduated income tax\" | \"proportional tax structures\" | \"tiered taxation policies\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi viết về government solutions, inequality, wealth redistribution.</p></div>","p":1},{"id":"W8D3-P-07","l":29,"t":"P","st":"Phrase","s":2,"tags":["collocation","example","nordic-model"],"f":"<p>Countries such as Denmark and Sweden have maintained relatively low levels of inequality through ______ (mạng lưới an sinh xã hội vững chắc) and ______ (dịch vụ công được trợ cấp nhiều).</p>","a":"<b>robust social safety nets</b> and <b>heavily subsidised public services</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The Nordic countries demonstrate that robust social safety nets, combined with heavily subsidised public services, can effectively reduce income inequality.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"comprehensive welfare systems\" | \"strong social protection programmes\" | \"generously funded public services\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi cần specific example cho government solutions / social policies. Nordic model = ví dụ kinh điển cho inequality essay.</p></div>","p":1},{"id":"W8D3-E-01","l":29,"t":"E","st":"Error","s":3,"tags":["mistake","time-management","vietnamese-trap"],"f":"<p>Thí sinh Việt dành 30 phút viết Task 1 \"hoàn hảo\", chỉ còn 30 phút cho Task 2 → thiếu Conclusion. Sai ở đâu? Hậu quả?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Phá \"20-40 Rule\" — dành quá nhiều thời gian cho Task 1 (33% trọng số) → hy sinh Task 2 (66% trọng số).</p></div><div class=\"sec\"><p><span class=\"lbl\">Hậu quả</span>Task 1 tốt hơn ~0.5 band nhưng Task 2 giảm ~1.0 band → Overall GIẢM ~0.5 band. Task 2 thiếu Conclusion = CC giảm — \"ideas are not concluded\".</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Task 1 \"đủ tốt\" (170 từ, có overview, có key features) trong 20 phút → dành 40 phút cho Task 2 hoàn chỉnh.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Mỗi 0.5 band tăng ở Task 2 = giá trị GẤP ĐÔI 0.5 band tăng ở Task 1.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + CC (Task 2)</p></div>","p":0},{"id":"W8D3-E-02","l":29,"t":"E","st":"Error","s":3,"tags":["mistake","no-planning","vietnamese-trap"],"f":"<p>Thí sinh đọc xong đề Task 2 → viết ngay không planning. Kết quả: viết lan man, Body 1 quá dài (150 từ), Body 2 chỉ 50 từ. Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Không planning = viết \"trôi theo ý\" → mất structure, Body không balanced, dễ lạc đề.</p></div><div class=\"sec\"><span class=\"lbl\">✅ Đúng</span><p>BẮT BUỘC 3-5 phút planning Task 2:</p><ol><li>Đọc đề 2 lần → gạch chân keywords</li><li>Xác định dạng essay — đếm dấu \"?\"</li><li>Brainstorm 2-3 ý mỗi câu (keywords, không viết câu)</li><li>Chọn 1-2 ý mạnh nhất + nghĩ example</li><li>Outline nhanh: Intro → B1 → B2 → Conc</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Planning 5 phút → save 10 phút viết. Không planning → dễ viết lệch, mất thời gian sửa.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + CC</p></div>","p":0},{"id":"W8D3-E-03","l":29,"t":"E","st":"Error","s":3,"tags":["mistake","no-conclusion","panic"],"f":"<p>Còn 5 phút, chưa viết Conclusion Task 2. Thí sinh panic, bỏ Conclusion. Sai ở đâu? Cách xử lý?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Bỏ Conclusion = essay chưa hoàn chỉnh → CC giảm ít nhất 0.5 band (\"ideas are not concluded\").</p></div><div class=\"sec\"><span class=\"lbl\">✅ Đúng</span><p>Viết <b>1 câu Conclusion nhanh</b> — chỉ cần 15-20 từ:</p><p>\"In conclusion, [summary Q1] and [summary Q2].\"</p></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"In conclusion, while structural factors such as unequal educational access are the primary drivers of the wealth gap, targeted government policies offer viable pathways to a more equitable society.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>KHÔNG thêm ý mới ở Conclusion. Chỉ tóm tắt 2 ý chính từ 2 body. 1 câu Conclusion &gt; không có Conclusion.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC</p></div>","p":0},{"id":"W8D3-E-04","l":29,"t":"E","st":"Error","s":2,"tags":["mistake","passive-voice","process"],"f":"<p>Task 1 Process (man-made): <i>\"Workers mix flour with water. Then workers cut the dough.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Dùng active voice cho man-made process → không phù hợp academic register. Process diagram mô tả QUY TRÌNH, không quan tâm \"ai làm\" (agent).</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The flour <b>is mixed</b> with water and oil. Subsequently, the dough <b>is cut</b> into noodle strands by a cutting machine.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Man-made process = <b>passive voice bắt buộc</b> (is stored, is mixed, are cut, are steamed). Không cần mention \"workers\" — focus vào quy trình, không phải người thực hiện.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA + TA</p></div>","p":0},{"id":"W8D3-E-05","l":29,"t":"E","st":"Error","s":2,"tags":["mistake","word-count","underdeveloped"],"f":"<p>Thí sinh viết Task 2 chỉ 200 từ (thiếu 50 từ so với yêu cầu). Hậu quả? Cách phòng tránh?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Task 2 &lt; 250 từ → bài bị đánh giá \"underdeveloped\" → TA giảm vì không đủ ideas/support.</p></div><div class=\"sec\"><p><span class=\"lbl\">Hậu quả</span>Giám khảo thấy bài ngắn → tự động đánh TA thấp hơn vì \"does not adequately develop ideas\". KHÔNG phải trừ điểm cơ học, mà đánh giá chất lượng nội dung.</p></div><div class=\"sec\"><span class=\"lbl\">Cách phòng tránh</span><ol><li><b>Đếm từ</b> sau khi viết — ước lượng: 1 dòng ≈ 10-12 từ</li><li>Nếu thiếu → thêm 1 example hoặc 1 câu explanation vào Body</li><li>Planning trước → đủ ý → đủ từ tự nhiên</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Task 1 ≥ 150 từ, Task 2 ≥ 250 từ. Viết 250-280 từ là tối ưu (không quá dài = ít lỗi hơn).</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA</p></div>","p":0},{"id":"W8D4-S-01","l":30,"t":"S","st":"Structure","s":3,"tags":["outweigh","essay-type","band-descriptors"],"f":"<p>Phân biệt yêu cầu Task Achievement giữa: <i>\"Discuss advantages and disadvantages\"</i> vs <i>\"Do the advantages outweigh the disadvantages?\"</i></p>","a":"","b":"<div class=\"sec\"><ol><li><b>\"Discuss advantages and disadvantages\"</b>:</li></ol><ul><li>Thân bài cân bằng <b>50/50</b> (Body 1 = Pros, Body 2 = Cons)<div>Giọng văn khách quan, KHÔNG cần đưa quan điểm cá nhân (trừ khi đề ghi rõ \"...and give your opinion\")</div></li></ul><ol><li><b>\"Do the advantages outweigh the disadvantages?\"</b>:</li></ol><ul><li><b>BẮT BUỘC</b> có quan điểm rõ ràng (Clear Position) từ Intro đến Conclusion<div>KHÔNG viết 50/50: Phải chứng minh <b>VÌ SAO</b> một bên có trọng số áp đảo bên kia (Weighing argument)</div><div>Body 1 = Phía yếu hơn (Concession), Body 2 = Phía vượt trội (Dominant)</div></li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Viết 50/50 cho đề outweigh = giám khảo trừ TA xuống Band 6.0 vì không giải quyết câu hỏi \"outweigh\".</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Thấy chữ \"outweigh\" = PHẢI CHỌN BÊN THẮNG THẾ và dùng tiêu chí so sánh (ngắn hạn vs dài hạn, khắc phục được vs vĩnh viễn).</p></div>","p":1},{"id":"W8D4-S-02","l":30,"t":"S","st":"Structure","s":3,"tags":["outweigh","weighing-criteria","band7"],"f":"<p>3 tiêu chí so sánh trọng số (Weighing Framework) để chứng minh A nặng hơn B trong dạng Outweigh là gì?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Time Horizon (Thời gian):</b></li></ol><ul><li>Bất lợi = <b>Short-term / Transient</b> (tạm thời, chi phí ban đầu)<div>Lợi ích = <b>Long-term &amp; Sustainable</b> (lâu dài, bền vững)</div></li></ul><ol><li><b>Solvability (Khả năng khắc phục):</b></li></ol><ul><li>Bất lợi = <b>Manageable / Readily mitigatable</b> (có thể xử lý bằng chính sách/công nghệ)<div>Lợi ích = <b>Fundamental &amp; Irreplaceable</b> (cốt lõi, không thể thay thế)</div></li></ul><ol><li><b>Scope &amp; Severity (Quy mô tác động):</b></li></ol><ul><li>Bất lợi = <b>Minor / Localised</b> (ảnh hưởng nhóm nhỏ hoặc bề mặt)<div>Lợi ích = <b>Societal / Universal</b> (mang lại giá trị cho toàn xã hội)</div></li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Mất việc do tự động hoá là ngắn hạn và giải quyết được qua đào tạo lại; nhưng tăng năng suất và cứu sống con người là lợi ích vĩnh viễn.</p></div>","p":1},{"id":"W8D4-S-03","l":30,"t":"S","st":"Structure","s":3,"tags":["outweigh","essay-structure","pivot-sentence"],"f":"<p>Bố cục 4 đoạn chuẩn cho dạng Outweigh Essay? Vai trò của \"Pivot sentence\" cuối Body 1 là gì?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Introduction</b> (~40-50 từ): Paraphrase đề + Thesis statement (nêu rõ bên thắng thế dựa trên tiêu chí trọng số)</li><li><b>Body 1 — Phía yếu hơn</b> (~80-90 từ): Nêu 1-2 điểm của phía yếu hơn + <b>Pivot sentence</b> ở cuối đoạn</li><li><b>Body 2 — Phía vượt trội</b> (~95-110 từ): 2 luận điểm mạnh nhất, phát triển sâu theo TEES, dùng từ vựng so sánh trọng số</li><li><b>Conclusion</b> (~35-45 từ): Khẳng định lại bên thắng thế và tóm lược lý do trọng số</li></ul><p><b>Vai trò Pivot sentence:</b> Câu kết của Body 1 dùng để chỉ ra rằng các nhược điểm này chỉ là tạm thời/có thể khắc phục được (<i>\"However, these shortcomings are largely manageable and far from insurmountable\"</i>), tạo bước đệm hoàn hảo sang Body 2.</p></div>","p":1},{"id":"W8D4-S-04","l":30,"t":"S","st":"Structure","s":2,"tags":["outweigh","thesis-formula"],"f":"<p>Công thức viết Thesis Statement chuẩn Band 7.5+ cho dạng Outweigh (khi Ưu điểm áp đảo Nhược điểm)?</p><p><b>Answer:</b> While I acknowledge that [Topic] entails certain drawbacks, most notably [Nhược điểm chính], I am firmly convinced that its benefits in terms of [Lợi ích 1] and [Lợi ích 2] are far more substantial and enduring.</p>","a":"","b":"<div class=\"sec\"><blockquote><i>\"While I acknowledge that [Topic] entails certain drawbacks, most notably [Nhược điểm chính], I am firmly convinced that its benefits in terms of [Lợi ích 1] and [Lợi ích 2] are far more substantial and enduring.\"</i></blockquote></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"While I acknowledge that remote work entails certain challenges regarding social isolation, I am firmly convinced that its benefits in terms of productivity and environmental sustainability are far more substantial and enduring.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Cấu trúc \"While I acknowledge [A], I am firmly convinced that [B]...\" vừa tạo câu phức Band 7+ GRA vừa thể hiện lập trường dứt khoát.</p></div>","p":1},{"id":"W8D4-P-01","l":30,"t":"P","st":"Phrase","s":3,"tags":["outweigh","comparison","collocation"],"f":"<p>The long-term environmental benefits ______ (vượt trội hơn hẳn) the initial installation costs.</p>","a":"<b>far outweigh</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The long-term economic dividends of renewable energy far outweigh the initial capital investments.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"heavily outweigh\" | \"vastly outstrip\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Thesis statement và Conclusion — khi khẳng định bên thắng thế.</p></div>","p":1},{"id":"W8D4-P-02","l":30,"t":"P","st":"Phrase","s":3,"tags":["outweigh","comparison","vocabulary"],"f":"<p>The enduring advantages of this policy ______ (lấn át/che mờ hoàn toàn) any transient drawbacks.</p>","a":"<b>vastly eclipse</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The educational gains of digital learning vastly eclipse the temporary difficulties of technical adaptation.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"completely overshadow\" | \"render insignificant\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Cuối Body 2 hoặc Conclusion — nhấn mạnh sức nặng áp đảo.</p></div>","p":1},{"id":"W8D4-P-03","l":30,"t":"P","st":"Phrase","s":2,"tags":["outweigh","comparison","idiom-academic"],"f":"<p>Minor technical glitches ______ (trở nên nhỏ bé/không đáng kể khi so với) the massive boost in productivity.</p>","a":"<b>pale in comparison to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"These administrative costs pale in comparison to the enormous societal savings.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"are dwarfed by\" | \"are negligible when compared with\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Thân bài hoặc câu pivot — làm giảm bớt sức nặng của phía yếu hơn.</p></div>","p":1},{"id":"W8D4-P-04","l":30,"t":"P","st":"Phrase","s":2,"tags":["outweigh","evaluative-adjective"],"f":"<p>The government should view these economic hurdles as ______ (những bất lợi tạm thời/ngắn hạn).</p>","a":"<b>transient drawbacks</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Supply chain disruptions are merely transient drawbacks rather than systemic failures.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"temporary shortcomings\" | \"short-lived disadvantages\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body 1 — mô tả phía yếu hơn để chứng minh nó không tồn tại mãi mãi.</p></div>","p":1},{"id":"W8D4-P-05","l":30,"t":"P","st":"Phrase","s":3,"tags":["outweigh","evaluative-adjective"],"f":"<p>Fortunately, issues regarding digital security are ______ (có thể giảm nhẹ/khắc phục dễ dàng) through robust protocols.</p>","a":"<b>readily mitigatable</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The risk of data breach is readily mitigatable through enhanced encryption methods.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"largely manageable\" | \"readily solvable\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Câu Pivot cuối Body 1 — chứng minh nhược điểm có thể xử lý được.</p></div>","p":1},{"id":"W8D4-P-06","l":30,"t":"P","st":"Phrase","s":2,"tags":["outweigh","evaluative-phrase"],"f":"<p>Although adapting to new systems is challenging, the barriers are ______ (hoàn toàn không phải không thể vượt qua).</p>","a":"<b>far from insurmountable</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"While retraining the workforce poses logistical difficulties, these hurdles are far from insurmountable.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"entirely manageable\" | \"readily overcome\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Câu chốt Body 1 — kết thúc phần phân tích phía yếu hơn để mở sang phía mạnh hơn.</p></div>","p":1},{"id":"W8D4-P-07","l":30,"t":"P","st":"Phrase","s":3,"tags":["outweigh","evaluative-adjective"],"f":"<p>Telecommuting offers ______ (những lợi thế lâu dài/bền vững) that enhance employee retention.</p>","a":"<b>enduring advantages</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Investing in early childhood education delivers enduring advantages for national prosperity.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"sustainable benefits\" | \"long-lasting dividends\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body 2 — mô tả các lợi ích mang tính dài hạn của phía thắng thế.</p></div>","p":1},{"id":"W8D4-P-08","l":30,"t":"P","st":"Phrase","s":2,"tags":["outweigh","advanced-noun"],"f":"<p>The digital transition yields massive ______ (lợi ích/thành quả mang tính cơ cấu) for enterprises.</p>","a":"<b>structural dividends</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Urban planning reforms have produced significant structural dividends in terms of public health.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"transformative benefits\" | \"systemic gains\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body 2 (Topic sentence hoặc Summary sentence) — nâng cấp từ \"big benefits\".</p></div>","p":1},{"id":"W8D4-E-01","l":30,"t":"E","st":"Error","s":3,"tags":["mistake","outweigh","half-answer"],"f":"<p>Gặp đề <i>\"Do advantages outweigh disadvantages?\"</i>, bài viết chia Body 1 = Pros, Body 2 = Cons với độ dài bằng nhau, kết bài nói \"Both exist\". — Mất điểm gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Viết 50/50 và không so sánh trọng số = <b>KHÔNG trả lời câu hỏi \"outweigh\"</b>.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Phải chọn một bên thắng thế rõ ràng, dùng tiêu chí so sánh (thời gian, khả năng khắc phục, quy mô) để chứng minh bên đó nặng hơn.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Thấy từ \"outweigh\" trong đề = BẮT BUỘC phải có lập trường (Position) và cân đo trọng số (Weighing).</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA — chỉ đạt tối đa Band 6.0 vì chưa giải quyết trọn vẹn yêu cầu đề bài.</p></div>","p":0},{"id":"W8D4-E-02","l":30,"t":"E","st":"Error","s":3,"tags":["mistake","outweigh","thesis"],"f":"<p>Introduction đề Outweigh viết: <i>\"In this essay, I will explore both the positive and negative aspects of this phenomenon.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Hoàn toàn thiếu <b>Thesis statement / Opinion</b>. Đề hỏi \"Cái nào nặng hơn?\", câu này chỉ hứa hẹn \"sẽ khám phá cả hai\".</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"While I acknowledge that this trend creates certain drawbacks, I firmly believe that its advantages are far more substantial and enduring.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Intro của Outweigh essay BẮT BUỘC phải tuyên bố rõ bên nào thắng thế ngay từ câu 2.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA — thiếu position rõ ràng xuyên suốt bài viết (Band 7 yêu cầu \"clear position throughout\").</p></div>","p":0},{"id":"W8D4-E-03","l":30,"t":"E","st":"Error","s":2,"tags":["mistake","outweigh","contradiction"],"f":"<p>Thí sinh chọn Advantages &gt; Disadvantages, nhưng Body 1 viết về nhược điểm cực kỳ thê thảm và không có cách khắc phục, sang Body 2 viết ưu điểm hời hợt. — Hậu quả gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Mâu thuẫn lập luận (Internal Contradiction). Nếu nhược điểm quá thảm khốc và không thể giải quyết, người đọc sẽ thấy vô lý khi bạn kết luận là ưu điểm lớn hơn!</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Phía yếu hơn (Body 1) phải được gán tính chất hạn định (transient, manageable, localized) và có câu pivot chỉ ra nó có thể giải quyết được. Body 2 (phía thắng thế) phải phát triển sâu hơn, đưa ra lợi ích nền tảng/lâu dài.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Phía thắng thế luôn phải có sức nặng lý lẽ và chiều sâu phát triển lớn hơn phía nhượng bộ.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + CC — lập luận thiếu nhất quán và thiếu thuyết phục.</p></div>","p":0},{"id":"W9D1-S-01","l":31,"t":"S","st":"Structure","s":3,"tags":["formula","error-analysis"],"f":"<p>Error Analysis Framework có mấy tầng? Kể tên + chức năng từng tầng.</p>","a":"","b":"<div class=\"sec\"><p><b>4 tầng:</b></p><ol><li><b>CLASSIFY</b> — Lỗi thuộc nhóm nào? (TA / CC / LR / GRA)</li><li><b>FREQUENCY</b> — Xuất hiện bao nhiêu lần? (isolated / pattern / systematic)</li><li><b>SEVERITY</b> — Ảnh hưởng band bao nhiêu? (minor / moderate / major)</li><li><b>PRIORITY</b> — Sửa lỗi nào TRƯỚC? (Frequency × Severity = priority matrix)</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Thiếu articles 4 lần = Systematic + Moderate = 🔴 <b>Urgent</b> → sửa TRƯỚC</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"CFSP — Classify, Frequency, Severity, Priority. Luôn sửa Systematic + Major/Moderate TRƯỚC.\"</p></div>","p":1},{"id":"W9D1-S-02","l":31,"t":"S","st":"Structure","s":3,"tags":["formula","error-analysis","priority"],"f":"<p>Priority Matrix: Frequency × Severity — khi nào là #1 PRIORITY (🔴🔴)?</p>","a":"","b":"<div class=\"sec\"><p><b>Ma trận ưu tiên:</b></p><ul><li>⬜ Ignore = Isolated + Minor</li><li>🟡 Note = Isolated + Moderate HOẶC Pattern + Minor</li><li>🟠 Drill = Isolated + Major HOẶC Pattern + Moderate HOẶC Systematic + Minor</li><li>🔴 Urgent = Pattern + Major HOẶC Systematic + Moderate</li><li>🔴🔴 <b>#1 PRIORITY</b> = <b>Systematic (4+ lần) + Major</b></li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"technology\" lặp 5 lần (Systematic) + Moderate (LR) = 🔴 Urgent</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"High Frequency + High Severity = sửa NGAY. Isolated + Minor = bỏ qua.\"</p></div>","p":1},{"id":"W9D1-S-03","l":31,"t":"S","st":"Structure","s":3,"tags":["formula","checklist","exam-strategy"],"f":"<p>Error Prevention Checklist có mấy bước? Kể tên + thời gian từng bước. (Tổng 3 phút)</p>","a":"","b":"<div class=\"sec\"><p><b>5 bước, tổng 3 phút trước khi nộp:</b></p><ol><li><b>WORD COUNT</b> (30s) — Task 1 ≥ 150? Task 2 ≥ 250?</li><li><b>TA CHECK</b> (30s) — Trả lời đủ parts? Overview (T1)? Opinion (Discussion)?</li><li><b>GRAMMAR SCAN</b> (1') — articles → S-V agreement → tense → word form</li><li><b>LR SCAN</b> (30s) — Từ lặp 3+? Đã paraphrase đề?</li><li><b>CC SCAN</b> (30s) — TEES đủ? Linking natural?</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Bước 3 quan trọng nhất — 1 phút scan: articles, S-V, tense, word form.\"</p></div>","p":1},{"id":"W9D1-S-04","l":31,"t":"S","st":"Structure","s":2,"tags":["grammar","articles","rules"],"f":"<p>Quy tắc nhanh dùng article (the / a-an / Ø) — 6 tình huống chính?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Lần đầu, chung chung</b> → <b>a/an</b> (\"A study was conducted...\")</li><li><b>Đã nhắc trước, hoặc cụ thể</b> → <b>the</b> (\"The study found that...\")</li><li><b>Số nhiều nói chung</b> → <b>Ø</b> (\"Students need education.\")</li><li><b>Không đếm được nói chung</b> → <b>Ø</b> (\"Education is important.\")</li><li><b>Cụ thể hóa bằng \"of\" phrase</b> → <b>the</b> (\"The education of children...\")</li><li><b>Duy nhất / Superlative</b> → <b>the</b> (\"The government\", \"The most important...\")</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Trước noun → hỏi: Chung chung hay cụ thể? Lần đầu hay đã nhắc? Đếm được không?\"</p></div>","p":1},{"id":"W9D1-S-05","l":31,"t":"S","st":"Structure","s":2,"tags":["grammar","tense","rules"],"f":"<p>Quy tắc chọn tense trong IELTS — Task 1 và Task 2 dùng tense gì?</p>","a":"","b":"<div class=\"sec\"><p><b>Task 1:</b></p><ul><li>Data quá khứ → <b>Past Simple</b> (in 2010, between X and Y)</li><li>Data hiện tại / general → <b>Present Simple</b> (currently, today)</li><li>Thay đổi đến nay → <b>Present Perfect</b> (since 2010, has increased)</li></ul><p><b>Task 2:</b></p><ul><li>Quan điểm chung → <b>Present Simple</b> (I believe, it is argued)</li><li>Ví dụ quá khứ → <b>Past Simple</b> (in the 20th century)</li><li>Dự đoán tương lai → <b>Will / May / Could</b> (in the future)</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Task 1 = theo data (Past/Present/Perfect). Task 2 = theo ngữ cảnh argument.\"</p></div>","p":1},{"id":"W9D1-S-06","l":31,"t":"S","st":"Structure","s":2,"tags":["grammar","word-form","rules"],"f":"<p>Mẹo nhận biết word form: trước noun cần gì? Trước verb/adj cần gì? Sau \"the...of\" cần gì?</p>","a":"","b":"<div class=\"sec\"><ul><li>Trước <b>noun</b> → cần <b>adjective</b> (economic growth, environmental problem)</li><li>Trước <b>verb / adjective</b> → cần <b>adverb</b> (significantly improve, increasingly difficult)</li><li>Sau <b>\"the...of\"</b> → cần <b>noun</b> (the importance of, the development of)</li><li>Sau <b>\"is / are / was\"</b> → cần <b>adjective</b> hoặc <b>noun</b> (it is important, she is a teacher)</li></ul></div><div class=\"sec\"><span class=\"lbl\">VD</span><ul><li class=\"bad\">❌ \"economy growth\" → ✅ \"economic growth\" (noun → adj trước noun)</li><li class=\"bad\">❌ \"significant improve\" → ✅ \"significantly improve\" (adj → adv trước verb)</li></ul></div>","p":1},{"id":"W9D1-S-07","l":31,"t":"S","st":"Structure","s":2,"tags":["technique","self-correction"],"f":"<p>3 kỹ thuật Self-Correction khi tự review bài viết ở nhà?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Color-Coded Highlighting</b> — 4 màu (🔴 GRA, 🟡 LR, 🔵 CC, 🟢 TA) → thấy ngay weak point #1</li><li><b>\"Exact Match\" Search</b> — Google cụm từ trong ngoặc kép → &lt;1000 kết quả = không tự nhiên</li><li><b>Read-Aloud</b> — Đọc to bài viết → chỗ nào nghe \"kỳ\" hoặc phải dừng = có lỗi</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Trong phòng thi dùng 'đọc thầm chậm' — mental read-aloud, hiệu quả tương tự.\"</p></div>","p":1},{"id":"W9D1-S-08","l":31,"t":"S","st":"Structure","s":2,"tags":["technique","classify"],"f":"<p>Phân biệt lỗi LR vs GRA: \"economy growth\" là lỗi LR hay GRA? Quy tắc phân biệt?</p>","a":"","b":"<div class=\"sec\"><p><b>\"economy growth\" = lỗi GRA</b> (word form error — dùng noun thay vì adjective \"economic\")</p><p><b>Quy tắc phân biệt:</b></p><ul><li>Nếu lỗi liên quan đến <b>cấu trúc câu</b> (agreement, tense, word form, articles) → <b>GRA</b></li><li>Nếu lỗi liên quan đến <b>chọn từ</b> (wrong word, collocation, repetition) → <b>LR</b></li></ul></div><div class=\"sec\"><span class=\"lbl\">VD</span><ul><li>\"economy growth\" (noun thay adj) → <b>GRA</b> (word form)</li><li>dùng \"economic\" khi cần \"economical\" (tiết kiệm) → <b>LR</b> (wrong word choice)</li></ul></div>","p":1},{"id":"W9D1-P-01","l":31,"t":"P","st":"Phrase","s":2,"tags":["collocation","upgrade"],"f":"<p>This is a ______ (rất quan trọng, cấp bách) issue. [thay \"very important problem\"]</p>","a":"<b>pressing</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"This is a pressing issue that demands immediate governmental attention.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"paramount\" | \"crucial\" | \"critical\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi cần nhấn mạnh tầm quan trọng (thay \"very important\")</p></div>","p":1},{"id":"W9D1-P-02","l":31,"t":"P","st":"Phrase","s":2,"tags":["collocation","upgrade"],"f":"<p>Pollution has a ______ (ảnh hưởng có hại) on public health. [thay \"big effect\"]</p>","a":"<b>detrimental effect</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Industrial emissions have a detrimental effect on the respiratory health of urban populations.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"profound impact\" | \"adverse effect\" | \"damaging impact\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi mô tả tác động tiêu cực (thay \"big/bad effect\")</p></div>","p":1},{"id":"W9D1-P-03","l":31,"t":"P","st":"Phrase","s":2,"tags":["collocation","correct"],"f":"<p>The government should ______ (thực hiện) further research. [thay \"do research\"]</p>","a":"<b>conduct</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The government should conduct further research into the long-term effects of air pollution.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"carry out\" | \"undertake\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Khi nói về nghiên cứu — KHÔNG BAO GIỜ dùng \"do a research\" (research không đếm được)</p></div>","p":1},{"id":"W9D1-P-04","l":31,"t":"P","st":"Phrase","s":2,"tags":["collocation","correct"],"f":"<p>Young offenders who ______ (phạm tội) should receive rehabilitation. [thay \"do a crime\"]</p>","a":"<b>commit a crime</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Individuals who commit crimes at a young age often lack stable family environments.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"perpetrate an offence\" (formal) | \"engage in criminal activity\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Crime/punishment topics — \"commit\" là collocation chuẩn, KHÔNG dùng \"do/make\"</p></div>","p":1},{"id":"W9D1-P-05","l":31,"t":"P","st":"Phrase","s":2,"tags":["paraphrase","upgrade"],"f":"<p>Authorities should ______ (phân bổ thêm kinh phí) to mass transit systems. [thay \"spend more money on public transport\"]</p>","a":"<b>allocate greater funding</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"It is often argued that authorities should allocate greater funding to mass transit systems.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"devote more resources to\" | \"increase investment in\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Introduction paraphrase — \"spend more money\" → \"allocate greater funding\" (3 elements)</p></div>","p":1},{"id":"W9D1-P-06","l":31,"t":"P","st":"Phrase","s":2,"tags":["collocation","upgrade"],"f":"<p>Technology has ______ (cách mạng hóa) the way people communicate. [thay \"changed\"]</p>","a":"<b>revolutionised</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Digital technology has revolutionised how people connect across borders.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"transformed\" | \"fundamentally altered\" | \"reshaped\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — khi mô tả thay đổi LỚN (mạnh hơn \"changed\")</p></div>","p":1},{"id":"W9D1-P-07","l":31,"t":"P","st":"Phrase","s":2,"tags":["collocation","academic"],"f":"<p>E-learning platforms have ______ (dân chủ hóa quyền tiếp cận) education. [academic phrase]</p>","a":"<b>democratised access to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Online platforms have democratised access to education, allowing students in remote areas to access world-class content.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"widened access to\" | \"made... accessible to a broader audience\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Education/technology topics — nhấn mạnh equality of access</p></div>","p":1},{"id":"W9D1-P-08","l":31,"t":"P","st":"Phrase","s":2,"tags":["collocation","academic"],"f":"<p>When harnessed responsibly, digital innovation can serve as a ______ (chất xúc tác mạnh mẽ cho) social progress.</p>","a":"<b>powerful catalyst for</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"These examples illustrate that digital innovation can serve as a powerful catalyst for social progress.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"driving force behind\" | \"key enabler of\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Summary sentence — khi kết luận positive impact</p></div>","p":1},{"id":"W9D1-P-09","l":31,"t":"P","st":"Phrase","s":2,"tags":["collocation","introduction"],"f":"<p>The question of whether school uniforms should be mandatory has ______ (gây ra tranh luận đáng kể).</p>","a":"<b>sparked considerable debate</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The question of whether school uniforms should be mandatory has sparked considerable debate among educators and parents alike.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"generated significant discussion\" | \"provoked heated debate\" | \"attracted widespread attention\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Introduction câu 1 — mở đầu discussion essay</p></div>","p":1},{"id":"W9D1-P-10","l":31,"t":"P","st":"Phrase","s":2,"tags":["collocation","solution"],"f":"<p>One viable solution is the ______ (triển khai) stricter environmental legislation.</p>","a":"<b>implementation of</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"One viable solution is the implementation of stricter environmental legislation to curb industrial emissions.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"introduction of\" | \"enforcement of\" | \"adoption of\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Problem-Solution body paragraph — khi đề xuất giải pháp cụ thể</p></div>","p":1},{"id":"W9D1-P-11","l":31,"t":"P","st":"Phrase","s":2,"tags":["collocation","upgrade"],"f":"<p>Air pollution ______ (đại diện cho) one of the most pressing environmental challenges. [thay \"is\"]</p>","a":"<b>represents</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Air pollution represents one of the most pressing environmental challenges facing urban areas today.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"constitutes\" | \"remains\" | \"stands as\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Topic sentence — động từ mạnh thay \"is\" (academic tone)</p></div>","p":1},{"id":"W9D1-P-12","l":31,"t":"P","st":"Phrase","s":2,"tags":["linking","natural"],"f":"<p>Kể 3 natural linking phrases thay thế \"Firstly, Secondly, Thirdly\" (mechanical linking)?</p>","a":"<ol><li><b>One significant advantage...</b> (thay Firstly)</li><li><b>Beyond this, ...</b> (thay Secondly/Moreover)</li><li><b>Perhaps most importantly, ...</b> (thay Thirdly/Furthermore)</li></ol>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"One significant advantage of technology is its impact on education. Beyond this, digital tools have transformed communication. Perhaps most importantly, the tech sector has emerged as a major driver of employment.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraphs — LUÔN dùng natural linking thay mechanical (Band 7 vs Band 5.5)</p></div>","p":1},{"id":"W9D1-E-01","l":31,"t":"E","st":"Error","s":3,"tags":["mistake","articles","GRA"],"f":"<p><i>\"Government should invest in education.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Thiếu article \"the\" trước \"government\" — government là entity cụ thể (của 1 nước).</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"<b>The</b> government should invest in education.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Danh từ chỉ tổ chức/thể chế cụ thể (the government, the internet, the environment) luôn cần \"the\".</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA — thiếu articles lặp lại = systematic error → cap Band 5.5</p></div>","p":0},{"id":"W9D1-E-02","l":31,"t":"E","st":"Error","s":3,"tags":["mistake","articles","GRA"],"f":"<p><i>\"Internet has changed the way people communicate.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Thiếu \"the\" trước \"internet\" — internet là thứ duy nhất trên thế giới.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"<b>The</b> internet has changed the way people communicate.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Danh từ duy nhất (the sun, the internet, the 21st century) luôn cần \"the\".</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA — article error</p></div>","p":0},{"id":"W9D1-E-03","l":31,"t":"E","st":"Error","s":3,"tags":["mistake","SV-agreement","GRA"],"f":"<p><i>\"The number of students have increased significantly.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"The number of\" = singular → verb phải là \"has\", không phải \"have\".</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The number of students <b>has</b> increased significantly.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>\"The number of\" = singular (has). \"A number of\" = plural/many (have). Đây là cặp hay nhầm nhất.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA — S-V agreement error</p></div>","p":0},{"id":"W9D1-E-04","l":31,"t":"E","st":"Error","s":3,"tags":["mistake","word-form","GRA"],"f":"<p><i>\"Many develop countries face this problem.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"develop\" là verb, trước noun \"countries\" cần adjective.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Many <b>developed</b> countries face this problem.\" (past participle → adjective)</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Trước noun → cần adjective. develop → developed/developing. Cũng hay sai: economy → economic, environment → environmental.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA — word form error</p></div>","p":0},{"id":"W9D1-E-05","l":31,"t":"E","st":"Error","s":3,"tags":["mistake","word-form","GRA"],"f":"<p><i>\"The important of education cannot be denied.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"important\" là adjective, sau \"the...of\" cần noun.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The <b>importance</b> of education cannot be denied.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Sau \"the ___ of\" → cần NOUN: the importance of, the development of, the establishment of.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA — word form error (adjective thay noun)</p></div>","p":0},{"id":"W9D1-E-06","l":31,"t":"E","st":"Error","s":3,"tags":["mistake","run-on","GRA"],"f":"<p><i>\"Technology is useful, it helps people communicate, it creates jobs.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Comma splice (run-on sentence) — nối 3 independent clauses bằng dấu phẩy.</p></div><div class=\"sec\"><span class=\"lbl\">✅ Đúng</span><p>3 cách sửa:</p><ol><li>Tách: \"Technology is useful. It helps people communicate.\"</li><li>Conjunction: \"Technology is useful <b>because</b> it helps people communicate <b>and</b> creates jobs.\"</li><li>Semicolon: \"Technology is useful<b>;</b> it facilitates communication and creates employment.\"</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Tiếng Việt cho phép câu dài nối phẩy. English YÊU CẦU conjunction (and/because/so) hoặc dấu chấm.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA — run-on sentence = moderate error, lặp lại → urgent</p></div>","p":0},{"id":"W9D1-E-07","l":31,"t":"E","st":"Error","s":3,"tags":["mistake","tense","GRA"],"f":"<p><i>\"In the past, people travel by horse. Then cars are invented. Now, people drove cars.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Tense inconsistency — trộn lẫn present/past/passive không theo logic thời gian.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"In the past, people <b>travelled</b> by horse. Subsequently, the automobile <b>was invented</b> in the late 19th century. Today, private cars <b>remain</b> the dominant mode of transport.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Giữ tense nhất quán theo ngữ cảnh: quá khứ → Past Simple, hiện tại → Present Simple. KHÔNG đổi tense giữa chừng.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA — tense inconsistency = moderate error</p></div>","p":0},{"id":"W9D1-E-08","l":31,"t":"E","st":"Error","s":3,"tags":["mistake","mechanical-linking","CC"],"f":"<p><i>\"Firstly, technology improves education. Secondly, technology helps communication. Thirdly, technology creates jobs. Moreover, technology is useful for healthcare. Furthermore, technology helps the economy.\"</i> — Mất điểm gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Mechanical linking — \"Firstly, Secondly, Thirdly, Moreover, Furthermore\" máy móc + cùng nghĩa.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"One <b>significant</b> advantage... <b>Beyond this</b>, digital tools have <b>fundamentally transformed</b>... <b>Perhaps most importantly</b>, the technology sector has emerged as...\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Band 7 = linking qua MEANING (ý dẫn sang ý), xen kẽ vị trí (đầu/giữa câu), dùng pronoun reference. Band 5.5 = list linking words ở đầu MỌI câu.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC — \"formulaic\" cohesive devices = cap Band 5.5 CC</p></div>","p":0},{"id":"W9D1-E-09","l":31,"t":"E","st":"Error","s":3,"tags":["mistake","under-addressing","TA"],"f":"<p>Đề: <i>\"What are the reasons for online shopping? Is this positive or negative?\"</i> — Bài viết chỉ nêu reasons, kết luận \"online shopping is increasing because of many reasons.\" — Mất điểm gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>HOÀN TOÀN BỎ QUA phần 2 (\"Is this positive or negative?\") → under-addressing.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Body 1: Reasons (convenience + variety + pricing). Body 2: Evaluation (largely positive — accessibility; caveat — impact on local retailers).</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Two-Part Question = PHẢI trả lời CẢ 2 parts. Mỗi part ít nhất 1 body paragraph.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA ≤ 5.0 — \"only partially addresses the task\"</p></div>","p":0},{"id":"W9D1-E-10","l":31,"t":"E","st":"Error","s":3,"tags":["mistake","repetition","LR"],"f":"<p>Bài viết dùng \"technology\" 5 lần, \"important\" 4 lần. — Mất điểm gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Repetition — dùng cùng content word 3+ lần → examiner ghi \"limited range of vocabulary.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Thay \"technology\" bằng: \"digital tools\", \"these innovations\", \"it\", \"digital innovation\". Thay \"important\" bằng: \"crucial\", \"essential\", \"pivotal\", \"significant\".</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Mỗi content word (noun/verb/adj) dùng tối đa 2 lần/essay. Lần 3+ → dùng synonym hoặc pronoun.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR — repetition = cap Band 5.5 LR</p></div>","p":0},{"id":"W9D1-E-11","l":31,"t":"E","st":"Error","s":3,"tags":["mistake","paraphrase","LR","TA"],"f":"<p>Đề: <i>\"The government should spend more money on public transport.\"</i> — Intro viết nguyên: <i>\"Some people believe that the government should spend more money on public transport. I agree.\"</i> — Mất điểm gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Copy nguyên đề vào intro = examiner thấy bạn không có vocab + không paraphrase được.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"It is often argued that <b>authorities</b> should <b>allocate greater funding</b> to <b>mass transit systems</b>.\" (paraphrase 3 elements: government→authorities, spend more money→allocate greater funding, public transport→mass transit systems)</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Paraphrase ≥3 elements từ đề: đổi verb + noun + cấu trúc. KHÔNG BAO GIỜ copy nguyên.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR + TA — lặp từ đề = Band 5 LR; examiner nghĩ bạn không hiểu đề</p></div>","p":0},{"id":"W9D1-E-12","l":31,"t":"E","st":"Error","s":2,"tags":["mistake","collocation","LR"],"f":"<p><i>\"Pollution has a big effect on people's health.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"big effect\" — \"big\" quá informal cho academic writing.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Pollution has a <b>significant/profound effect</b> on people's health.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Academic collocations: significant/profound/detrimental + effect/impact. KHÔNG dùng big/good/bad trong formal writing.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR — informal collocation → giảm academic tone</p></div>","p":0},{"id":"W9D1-E-13","l":31,"t":"E","st":"Error","s":2,"tags":["mistake","collocation","LR"],"f":"<p><i>\"The company needs to make a research before launching the product.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"make a research\" — 2 lỗi: (1) \"make\" không đi với \"research\", (2) \"research\" KHÔNG đếm được → không dùng \"a\".</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The company needs to <b>conduct research</b> before launching the product.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>research + conduct/carry out/undertake. Research = uncountable → KHÔNG có \"a\". Nếu muốn đếm: \"a research <b>study</b>\" hoặc \"a piece of research\".</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR — collocation error + article error</p></div>","p":0},{"id":"W9D1-E-14","l":31,"t":"E","st":"Error","s":2,"tags":["mistake","paragraph-unity","CC"],"f":"<p>1 body paragraph viết về air pollution, animal extinction, VÀ water pollution. — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>3 ý khác nhau trong 1 paragraph → vi phạm paragraph unity → examiner ghi \"a lack of clear progression.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>1 body paragraph = 1 main idea, phát triển sâu bằng TEES. Ví dụ: Chỉ viết về air pollution → explain sources (vehicle emissions, industrial waste) → example (Delhi, Beijing) → summary.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>1 paragraph = 1 main idea + TEES. Nếu có 3 ý → chia 3 paragraphs hoặc chọn 1 ý phát triển sâu.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC ≤ 5.5 — \"a lack of clear progression\"</p></div>","p":0},{"id":"W9D1-E-15","l":31,"t":"E","st":"Error","s":2,"tags":["mistake","over-generalisation","TA"],"f":"<p>Body paragraph: <i>\"Technology is useful for education. Students can learn many things from the internet. It helps them study better.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Over-generalisation — ý quá chung, \"đúng nhưng KHÔNG CÓ GÌ MỚI\", không có specific example.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Digital technology has <b>revolutionised</b> access to educational resources. For instance, <b>Massive Open Online Courses (MOOCs)</b> offered by platforms such as <b>Coursera and edX</b> have enabled students in <b>remote areas of Southeast Asia</b> to access <b>university-level content</b> from institutions like MIT and Stanford.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Band 7 cần TÊN CỤ THỂ (Coursera, MIT), VÙNG CỤ THỂ (Southeast Asia), IMPACT CỤ THỂ (educational inequality). Band 5 = ý chung chung.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA ≤ 6.0 — \"ideas are not fully developed\"</p></div>","p":0},{"id":"W9D2-S-01","l":32,"t":"S","st":"Structure","s":3,"tags":["exam-strategy","time-management","20-40-rule"],"f":"<p>\"20-40 Rule\" là gì? Phân bổ cụ thể cho từng task trong 60 phút?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Task 1 (20 phút)</b>: 2' planning → 15' viết → 3' review</li><li><b>Task 2 (40 phút)</b>: 5' planning → 30' viết → 5' review (3' Error Prevention Checklist + 2' polish)</li><li>Task 2 chiếm <b>2/3 tổng điểm Writing</b> → KHÔNG tốn quá 20' cho Task 1</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Đặt timer thật. SAU 20 PHÚT → DỪNG Task 1 → chuyển Task 2 dù chưa hoàn hảo. Task 1 viết 30' = Task 2 chỉ còn 30' = mất điểm nhiều hơn.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"20-40\" = Task 1 chiếm 1/3 thời gian, Task 2 chiếm 2/3 — giống tỷ lệ điểm.</p></div>","p":1},{"id":"W9D2-S-02","l":32,"t":"S","st":"Structure","s":3,"tags":["error-prevention","checklist","pre-submission"],"f":"<p>Error Prevention Checklist gồm <b>5 bước</b> gì? Tổng bao lâu?</p>","a":"","b":"<div class=\"sec\"><p>5 bước trong <b>3 phút</b>:</p><ol><li><b>WORD COUNT</b> (30s): Task 1 ≥ 150? Task 2 ≥ 250?</li><li><b>TA CHECK</b> (30s): Trả lời đủ parts? Task 1 có overview?</li><li><b>GRAMMAR SCAN</b> (1'): articles → S-V agreement → tense → word form</li><li><b>LR SCAN</b> (30s): Từ lặp 3+? Paraphrase đề?</li><li><b>CC SCAN</b> (30s): Mỗi body có TEES? Linking natural?</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>3 phút cuối Test → scan GRA phát hiện \"The students is...\" → sửa → cứu 0.5 band GRA.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Thứ tự nhớ: <b>W-T-G-L-C</b> (Word count → TA → GRA → LR → CC).</p></div>","p":1},{"id":"W9D2-S-03","l":32,"t":"S","st":"Structure","s":3,"tags":["phase-3","completion-criteria","readiness"],"f":"<p>Phase 3 Completion Criteria có <b>3 levels</b> — kể từng level + điều kiện + hành động?</p>","a":"","b":"<div class=\"sec\"><ul><li class=\"good\">✅ <b>PASS</b>: Overall <b>6.0-6.5 ổn định</b> (≥2/3 tests) + không lỗi GRA lặp + đã viết 4 essay types → <b>Sang Phase 4</b></li><li>⚠️ <b>CONDITIONAL</b>: 1 tiêu chí <b>dưới 6.0</b> hoặc lỗi GRA lặp &gt;3 lần/bài → <b>Drill thêm 2-3 ngày</b> → test lại</li><li class=\"bad\">❌ <b>REPEAT</b>: Overall <b>&lt; 6.0</b> hoặc 2+ tiêu chí dưới 5.5 → <b>Lặp Week 8-9</b></li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Test 1: 6.0, Test 2: 6.5, Test 3: 5.5 → 2/3 tests ≥ 6.0 → PASS.</p></div>","p":1},{"id":"W9D2-S-04","l":32,"t":"S","st":"Structure","s":3,"tags":["band-comparison","time-pressure","performance"],"f":"<p><b>3 điểm khác biệt lớn nhất</b> giữa Band 5 và Band 7 khi viết dưới áp lực thời gian?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Planning</b>: Band 5 viết ngay, không outline → Band 7 dành 3-5' planning, outline rõ</li><li><b>Error check</b>: Band 5 viết xong nộp ngay → Band 7 dùng Error Prevention Checklist 3' cuối</li><li><b>Recovery</b>: Band 5 hoảng khi gặp đề lạ, viết lan man → Band 7 bình tĩnh, outline generic, adapt</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Gặp đề Process (ít gặp) → Band 5: hoảng, viết active voice, lộn xộn → Band 7: bình tĩnh, áp dụng passive voice template, sequencing language.</p></div>","p":1},{"id":"W9D2-P-01","l":32,"t":"P","st":"Phrase","s":3,"tags":["collocation","task-1","strong-increase"],"f":"<p>International student numbers more than doubled, ______ (tăng vọt từ) 1,200 in 2015 ______ 2,800 in 2023.</p>","a":"<b>surging from</b> ... <b>to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Online retail sales grew dramatically, surging from $500 million to $2.3 billion in just three years.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"soaring from X to Y\" | \"rocketing from X to Y\" | \"jumping from X to Y\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body paragraph — mô tả strong increase với số liệu cụ thể (participle clause)</p></div>","p":1},{"id":"W9D2-P-02","l":32,"t":"P","st":"Phrase","s":2,"tags":["collocation","task-1","small-increase"],"f":"<p>Medicine showed only a marginal increase, with numbers ______ (tăng nhích từ) 600 ______ 680.</p>","a":"<b>edging up from</b> ... <b>to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Spending on public transport edged up from $12 billion to $13.5 billion, a relatively modest rise.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"inching up from X to Y\" | \"creeping up from X to Y\" | \"rising slightly from X to Y\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Body paragraph — mô tả very small increase, contrast với large increase</p></div>","p":1},{"id":"W9D2-P-03","l":32,"t":"P","st":"Phrase","s":3,"tags":["collocation","education","social-equality"],"f":"<p>Free university education would ______ (thúc đẩy dịch chuyển xã hội) and ensure equal access to higher learning.</p>","a":"<b>promote social mobility</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Scholarship programmes have played a crucial role in promoting social mobility among disadvantaged communities.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"enhance social mobility\" | \"foster upward mobility\" | \"improve social equity\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — education, equality, government policy topics</p></div>","p":1},{"id":"W9D2-P-04","l":32,"t":"P","st":"Phrase","s":3,"tags":["collocation","government","financial-burden"],"f":"<p>Making university entirely free would place ______ (gánh nặng không bền vững lên) public finances.</p>","a":"<b>an unsustainable burden on</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Rapid population growth has placed an unsustainable burden on the country's healthcare system.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"an excessive strain on\" | \"an unbearable pressure on\" | \"an overwhelming demand on\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — government spending, public services, resource allocation topics</p></div>","p":1},{"id":"W9D2-P-05","l":32,"t":"P","st":"Phrase","s":3,"tags":["collocation","conclusion","balanced-position"],"f":"<p>A hybrid model would ______ (đạt sự cân bằng đúng giữa) accessibility and fiscal responsibility.</p>","a":"<b>strike the right balance between</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Effective environmental policy must strike the right balance between economic growth and ecological preservation.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"achieve the right balance between\" | \"find the optimal equilibrium between\" | \"maintain a balance between\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Conclusion — khi đưa ra balanced/hybrid position trong Discussion essay</p></div>","p":1},{"id":"W9D2-P-06","l":32,"t":"P","st":"Phrase","s":3,"tags":["collocation","introduction","cause-effect"],"f":"<p>Rapid urbanisation inevitably ______ (dẫn đến / tạo ra) a range of serious challenges.</p>","a":"<b>gives rise to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The widespread use of social media has given rise to concerns about privacy and mental health among young people.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"leads to\" | \"results in\" | \"brings about\" | \"triggers\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Introduction / Body paragraph — academic way to express cause → effect</p></div>","p":1},{"id":"W9D2-P-07","l":32,"t":"P","st":"Phrase","s":2,"tags":["collocation","housing","demand-supply"],"f":"<p>Demand for affordable accommodation ______ (vượt xa nguồn cung), leading to soaring property prices.</p>","a":"<b>far outstrips supply</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"In major cities, the demand for affordable childcare far outstrips the available supply, leaving many parents without options.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"greatly exceeds supply\" | \"significantly surpasses supply\" | \"overwhelms available supply\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — housing, resources, healthcare, education — khi demand &gt; supply</p></div>","p":1},{"id":"W9D2-P-08","l":32,"t":"P","st":"Phrase","s":3,"tags":["collocation","solution","multi-solution"],"f":"<p>To mitigate these challenges, governments should adopt ______ (cách tiếp cận đa chiều).</p>","a":"<b>a multi-pronged approach</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Tackling youth unemployment requires a multi-pronged approach, combining education reform with job creation incentives.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"a comprehensive strategy\" | \"a multifaceted approach\" | \"a holistic strategy\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph (Solutions) — khi giới thiệu nhiều giải pháp cùng lúc</p></div>","p":1},{"id":"W9D2-P-09","l":32,"t":"P","st":"Phrase","s":3,"tags":["collocation","process","overview"],"f":"<p>The process involves nine sequential stages, ______ (bắt đầu từ) the collection of waste paper and ______ (kết thúc bằng) the production of finished paper.</p>","a":"<b>beginning with</b> ... <b>and culminating in</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The manufacturing process involves five stages, beginning with raw material extraction and culminating in the packaging of finished goods.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"starting with... and ending with...\" | \"commencing with... and concluding with...\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Overview — Process diagram — tóm tắt start point + end point</p></div>","p":1},{"id":"W9D2-E-01","l":32,"t":"E","st":"Error","s":3,"tags":["mistake","time-management","task-1-trap"],"f":"<p><i>Thí sinh viết Task 1 rất kỹ, tốn 35 phút. Task 2 chỉ còn 25 phút, viết vội 220 từ.</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Task 1 chiếm 35/60 phút → Task 2 (chiếm 2/3 tổng điểm) chỉ còn 25 phút → thiếu word count + thiếu development → TA + CC giảm ít nhất 1 band.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"20-40 Rule\" nghiêm ngặt. SAU 20 PHÚT → DỪNG Task 1 → chuyển Task 2 dù chưa hoàn hảo. Task 1 hoàn hảo nhưng Task 2 yếu = điểm tổng THẤP hơn.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Task 2 quan trọng gấp đôi Task 1 → luôn đảm bảo 40 phút cho Task 2. Đặt timer thật.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + CC (Task 2)</p></div>","p":0},{"id":"W9D2-E-02","l":32,"t":"E","st":"Error","s":3,"tags":["mistake","process","active-voice"],"f":"<p><i>\"Workers collect waste paper from homes. Then they sort the paper by type. Then they shred it.\"</i> (Process diagram) — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>(1) Dùng active voice cho process diagram — không academic, không phù hợp (process tập trung vào QUÁ TRÌNH, không phải NGƯỜI thực hiện). (2) Lặp \"then\" 2 lần — sequencing nghèo nàn.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Waste paper is collected from homes and offices. Subsequently, the collected paper is sorted by type at a recycling facility. Once sorted, the paper is shredded into small pieces.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Process/Map = PASSIVE VOICE nhất quán (is collected, is sorted, is shredded). Sequencing = đa dạng (Subsequently, Once..., Following..., In the final stages).</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA + LR</p></div>","p":0},{"id":"W9D2-E-03","l":32,"t":"E","st":"Error","s":3,"tags":["mistake","no-planning","time-pressure"],"f":"<p><i>Thí sinh sợ hết giờ → bắt đầu viết ngay từ câu đầu tiên, không plan, không outline. Kết quả: paragraph lộn xộn, thiếu 1 part câu hỏi.</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Không planning → viết tới đâu nghĩ tới đó → paragraph lộn xộn, ý trùng lặp, thiếu parts, kết bài không khớp mở bài. Thực tế MẤT THỜI GIAN HƠN vì phải sửa/xoá.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Task 1: 2' planning (identify type → spot trends → group data → note figures). Task 2: 5' planning (analyse question → position → outline 4 đoạn → vocabulary brainstorm).</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Planning 3-5 phút TIẾT KIỆM thời gian sửa bài 10-15 phút. Không plan = plan để thất bại.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + CC</p></div>","p":0},{"id":"W9D2-E-04","l":32,"t":"E","st":"Error","s":3,"tags":["mistake","skip-review","error-prevention"],"f":"<p><i>Thí sinh viết xong 1 phút trước giờ → nộp ngay, không review. Bài có 4 lỗi articles và 2 lỗi S-V agreement.</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Bỏ Error Prevention Checklist 3 phút cuối → 6 lỗi GRA có thể phát hiện + sửa trong 1 phút scan → mất 0.5 band GRA.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Dành 3' cuối cho 5-Step Review: Word Count → TA Check → Grammar Scan (articles → S-V → tense → word form) → LR Scan → CC Scan. Phát hiện + sửa 80% lỗi cơ bản.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>3 phút review cứu 0.5 band. Viết 247 từ + review &gt; Viết 280 từ + không review.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA</p></div>","p":0},{"id":"W10D1-S-01","l":33,"t":"S","st":"Structure","s":3,"tags":["band7","TA","descriptors"],"f":"<p>Band 7 TA yêu cầu 2 keyword quan trọng gì mà Band 6 không có?</p>","a":"","b":"<div class=\"sec\"><p><b>2 keywords:</b></p><ol><li><b>\"ALL parts\"</b> — trả lời ĐẦY ĐỦ mọi phần của đề (không bỏ sót)</li><li><b>\"clear position THROUGHOUT\"</b> — quan điểm rõ ràng xuyên suốt (không thay đổi, không mâu thuẫn)</li></ol><p><b>Band 6</b> chỉ yêu cầu: \"addresses all parts but some parts may be more fully covered than others\"</p></div><div class=\"sec\"><span class=\"lbl\">VD</span><ul><li>Band 6 TA: Viết 2 body về \"longer prison sentences\" → quên \"better ways\" → chỉ cover 1/2</li><li>Band 7 TA: Body 1 = view 1 (+ explanation + example), Body 2 = view 2, Conclusion = clear position</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"ALL + THROUGHOUT = đầy đủ + nhất quán. Gạch chân mọi phần đề trước khi viết.\"</p></div>","p":1},{"id":"W10D1-S-02","l":33,"t":"S","st":"Structure","s":3,"tags":["band7","CC","descriptors"],"f":"<p>Band 7 CC yêu cầu 2 keyword quan trọng gì mà Band 6 không có?</p>","a":"","b":"<div class=\"sec\"><p><b>2 keywords:</b></p><ol><li><b>\"range of cohesive devices appropriately\"</b> — linking devices đa dạng VÀ tự nhiên (không lặp, không máy móc)</li><li><b>\"clear central topic within each paragraph\"</b> — mỗi paragraph = 1 central topic duy nhất</li></ol><p><b>Band 6</b> vấn đề: \"cohesion may be faulty or mechanical\" — dùng cohesive devices nhưng máy móc (Firstly... Secondly... Moreover...)</p></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Band 7 dùng 6+ loại linking: reference (\"This shift\"), participle (\"thereby creating\"), contrast (\"However\"), cause-effect (\"As a result\"), concession (\"regardless of\")</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"RANGE + CENTRAL TOPIC = đa dạng linking + 1 ý/paragraph.\"</p></div>","p":1},{"id":"W10D1-S-03","l":33,"t":"S","st":"Structure","s":3,"tags":["band7","LR","descriptors"],"f":"<p>Band 7 LR yêu cầu 2 keyword quan trọng gì? Nguyên tắc vàng của Band 7 LR là gì?</p>","a":"","b":"<div class=\"sec\"><p><b>2 keywords:</b></p><ol><li><b>\"flexibility and precision\"</b> — từ vựng linh hoạt VÀ chính xác</li><li><b>\"awareness of style and collocation\"</b> — less common vocab phải đúng style VÀ đúng collocation</li></ol><p><b>Nguyên tắc vàng: \"Precision over Complexity\"</b></p><p>Band 7 KHÔNG yêu cầu từ khó nhất. Mà yêu cầu từ ĐÚNG NHẤT.</p></div><div class=\"sec\"><span class=\"lbl\">VD</span><ul><li class=\"bad\">❌ \"eradicate unemployment\" (eradicate dùng cho bệnh/virus → collocation mismatch)</li><li class=\"good\">✅ \"address the growing issue of unemployment\" (academic collocation chính xác)</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"PRECISION &gt; COMPLEXITY. 1 collocation đúng &gt; 1 từ khó sai context.\"</p></div>","p":1},{"id":"W10D1-S-04","l":33,"t":"S","st":"Structure","s":3,"tags":["band7","GRA","descriptors"],"f":"<p>Band 7 GRA yêu cầu 2 keyword quan trọng gì? \"One-trick pony\" là gì?</p>","a":"","b":"<div class=\"sec\"><p><b>2 keywords:</b></p><ol><li><b>\"variety of complex structures\"</b> — nhiều LOẠI câu complex khác nhau (relative, participle, conditional, concessive, cleft, passive)</li><li><b>\"frequent error-free sentences\"</b> — đa số câu KHÔNG có lỗi</li></ol><p><b>\"One-trick pony\"</b> = chỉ dùng 1-2 loại complex sentence lặp lại:</p><ul><li class=\"bad\">❌ \"Although X, Y. Although A, B. Although P, Q.\" (3 câu Although = zero variety = Band 6)</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Band 7 paragraph cần 3+ loại: While (concessive) + who (relative) + having been deprived of (participle) + despite (preposition) + rather than (comparative)</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"VARIETY + ERROR-FREE. Nhiều loại câu + ít lỗi. 1 câu complex đúng &gt; 3 câu complex sai.\"</p></div>","p":1},{"id":"W10D1-S-05","l":33,"t":"S","st":"Structure","s":3,"tags":["checklist","pre-submission","exam-strategy"],"f":"<p>Band 7 Pre-Submission Checklist gồm 5 bước (5 phút). Kể tên từng bước + thời gian?</p>","a":"","b":"<div class=\"sec\"><p><b>5 bước × 1 phút/bước:</b></p><ol><li><b>TA Check</b> — Mọi part đề có paragraph? Position nhất quán intro + conclusion? Mỗi idea có explanation + example?</li><li><b>CC Check</b> — Topic sentence rõ? 1 topic/paragraph? ≥3 LOẠI linking? Có reference words?</li><li><b>LR Check</b> — Đã paraphrase keywords đề? ≥3-4 collocations? Không memorized clichés?</li><li><b>GRA Check</b> — ≥3-4 câu complex (variety)? Đọc ngược tìm lỗi? Check pet mistakes?</li><li><b>Format + Word Count</b> — T1 ≥150 từ? T2 ≥250 từ? 4 paragraphs? Có conclusion?</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"5 phút cuối = 5 bước checklist. SỬA LỖI hiệu quả hơn VIẾT THÊM Ý.\"</p></div>","p":1},{"id":"W10D1-S-06","l":33,"t":"S","st":"Structure","s":2,"tags":["examiner-perspective","self-assessment"],"f":"<p>3 kỹ thuật \"Examiner Perspective\" để tự đánh giá bài viết là gì?</p>","a":"","b":"<div class=\"sec\"><p><b>3 kỹ thuật:</b></p><ol><li><b>Backwards Reading</b> — đọc từ paragraph cuối → đầu, câu cuối → câu đầu. Mục đích: phá \"mental flow\" → phát hiện lỗi grammar, spelling, collocation</li><li><b>Topic Sentence Test</b> — che body, chỉ đọc topic sentences. Hỏi: \"Examiner có hiểu bài nói gì không?\" Nếu KHÔNG → CC Band 6</li><li><b>Detach and Re-read</b> — đợi 2-3 phút, quay lại đọc như bài của NGƯỜI KHÁC. Hỏi: \"Bài này có cần đọc lại 2 lần không?\"</li></ol></div><div class=\"sec\"><span class=\"lbl\">VD</span><ul><li class=\"bad\">❌ \"There are many reasons for this.\" → examiner KHÔNG biết bài nói gì</li><li class=\"good\">✅ \"The primary argument in favour of longer prison sentences is their potential deterrent effect.\" → hiểu ngay</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"3 kỹ thuật: Đọc NGƯỢC + Test TOPIC SENTENCE + Đọc như NGƯỜI KHÁC.\"</p></div>","p":1},{"id":"W10D1-S-07","l":33,"t":"S","st":"Structure","s":2,"tags":["TA-drill","prompt-deconstruction"],"f":"<p>\"Prompt Deconstruction\" drill gồm 3 bước gì? Mục đích?</p>","a":"","b":"<div class=\"sec\"><p><b>Mục đích:</b> Đảm bảo address ALL parts (Band 7 TA)</p><p><b>3 bước:</b></p><ol><li><b>Gạch chân</b> mọi thành phần cần trả lời trong đề</li><li><b>Viết outline</b> — mỗi thành phần → paragraph nào?</li><li><b>Viết 2 câu</b> cho MỖI thành phần (topic sentence + 1 supporting sentence)</li></ol></div><div class=\"sec\"><span class=\"lbl\">VD</span><p>Đề hỏi \"causes + measures\" →</p><ul><li>Gạch chân: ①causes ②measures → Loại essay: Problem-Solution</li><li>Outline: Body 1 = 2 causes, Body 2 = 2 solutions</li><li>Viết 2 câu/phần → TA self-check: all parts addressed? ✅</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"GẠCH CHÂN → OUTLINE → 2 CÂU/PHẦN. Không bỏ sót part nào.\"</p></div>","p":1},{"id":"W10D1-S-08","l":33,"t":"S","st":"Structure","s":3,"tags":["GRA","complex-structures","band7"],"f":"<p>Kể tên 6 loại complex structure cần dùng cho Band 7 GRA? Cho formula mỗi loại.</p>","a":"","b":"<div class=\"sec\"><div class=\"tw\"><table><thead><tr><th>#</th><th>Structure</th><th>Formula</th></tr></thead><tbody><tr><td>1</td><td><b>Relative clause</b></td><td>noun + who/which/that + verb</td></tr><tr><td>2</td><td><b>Participle clause</b></td><td>V-ing / Having V-ed, S + V</td></tr><tr><td>3</td><td><b>Conditional</b></td><td>If S + V (past), S + would + V</td></tr><tr><td>4</td><td><b>Concessive</b></td><td>Although/While/Despite + noun/-ing</td></tr><tr><td>5</td><td><b>Cleft sentence</b></td><td>It is [noun/adj] that...</td></tr><tr><td>6</td><td><b>Passive + by-agent</b></td><td>S + be + V-ed + by...</td></tr></tbody></table></div></div><div class=\"sec\"><span class=\"lbl\">VD</span><ul><li>Relative: \"Students <b>who lack access to</b> digital resources...\"</li><li>Participle: \"<b>Having examined</b> both perspectives, I am inclined to...\"</li><li>Cleft: \"<b>It is the lack of</b> affordable healthcare <b>that</b> contributes most...\"</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"6 loại: REL + PART + COND + CONC + CLEFT + PASSIVE. Dùng ≥3 loại/bài.\"</p></div>","p":1},{"id":"W10D1-S-09","l":33,"t":"S","st":"Structure","s":2,"tags":["idea-development","TEES","band7"],"f":"<p>Viết ý như thế nào để được Band 7 TA? \"Listing vs Developing\" khác nhau sao?</p>","a":"","b":"<div class=\"sec\"><p><b>Band 7 = DEVELOPING (TEES), không phải LISTING</b></p><ul><li class=\"bad\">❌ <b>Listing</b> (Band 6): 5 ý × 1 câu = liệt kê, không phát triển</li><li class=\"good\">✅ <b>Developing</b> (Band 7): 2-3 ý × 4-6 câu = phát triển kỹ mỗi ý</li></ul><p><b>TEES Framework:</b></p><ol><li><b>T</b>opic sentence — nêu main idea</li><li><b>E</b>xplanation — giải thích tại sao</li><li><b>E</b>xample/Evidence — ví dụ cụ thể (tên nước, năm, số liệu)</li><li><b>S</b>ummary — kết luận/link back to topic</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"Germany, for example, eliminated tuition fees in 2014, resulting in a measurable increase in enrolment rates among students from lower socioeconomic backgrounds.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"2 ý phát triển kỹ &gt; 5 ý liệt kê. Mỗi body = 1 main idea × 4-6 câu TEES.\"</p></div>","p":1},{"id":"W10D1-S-10","l":33,"t":"S","st":"Structure","s":2,"tags":["hedging","academic-language","band7"],"f":"<p>\"Hedging language\" là gì? Kể 7 công cụ hedging cho Band 7?</p>","a":"","b":"<div class=\"sec\"><p><b>Hedging</b> = ngôn ngữ hàn lâm thể hiện sự cân nhắc, tránh khẳng định tuyệt đối (over-generalisation)</p><p><b>7 hedging tools:</b></p><ol><li><b>may/might/could</b> — \"Technology <b>may</b> contribute to obesity\"</li><li><b>tend to</b> — \"Students <b>tend to</b> perform better online\"</li><li><b>arguably</b> — \"This is <b>arguably</b> the most effective approach\"</li><li><b>it is generally believed that</b> — mở đầu ý kiến chung</li><li><b>a significant proportion of</b> — thay \"all/every\"</li><li><b>in many cases</b> — thay \"always\"</li><li><b>can contribute to</b> — thay \"causes/leads to\"</li></ol></div><div class=\"sec\"><span class=\"lbl\">VD</span><ul><li class=\"bad\">❌ \"Technology <b>always causes</b> problems\" → over-generalised = TA Band 6</li><li class=\"good\">✅ \"Technology <b>can contribute to</b> certain challenges\" → hedged = Band 7</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Tuyệt đối = Band 6. Cân nhắc = Band 7. may/tend to/arguably là bạn thân.\"</p></div>","p":1},{"id":"W10D1-P-01","l":33,"t":"P","st":"Phrase","s":2,"tags":["collocation","government","LR-upgrade"],"f":"<p>The government should ______ ______ ______ to curb industrial pollution. (thực thi quy định nghiêm ngặt)</p>","a":"<b>implement stringent regulations</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The government should implement stringent regulations to curb industrial pollution and protect public health.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"enforce strict policies\" | \"introduce rigorous measures\" | \"enact comprehensive legislation\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Khi viết về government action, policy solutions — thay cho \"do something\" hoặc \"make rules\"</p></div>","p":1},{"id":"W10D1-P-02","l":33,"t":"P","st":"Phrase","s":2,"tags":["collocation","resources","LR-upgrade"],"f":"<p>By ______ ______ ______ to police forces, governments aim to create a stronger deterrent. (phân bổ thêm nguồn lực)</p>","a":"<b>allocating additional resources</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"By allocating additional resources to police forces and imposing harsher sentences on convicted criminals, governments aim to create a stronger deterrent against criminal activity.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"channelling more funding\" | \"directing increased investment\" | \"dedicating greater resources\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Khi viết về giải pháp cần đầu tư — thay cho \"give more money\"</p></div>","p":1},{"id":"W10D1-P-03","l":33,"t":"P","st":"Phrase","s":2,"tags":["collocation","crime","LR-upgrade"],"f":"<p>Governments should consider ______ ______ ______ on convicted criminals. (áp đặt mức án nặng hơn)</p>","a":"<b>imposing harsher sentences</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Rather than imposing harsher sentences, governments should invest in community-based rehabilitation programmes.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"introducing stricter penalties\" | \"handing down more severe punishments\" | \"enforcing tougher sanctions\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Khi viết về crime/punishment — thay cho \"make the punishment harder\"</p></div>","p":1},{"id":"W10D1-P-04","l":33,"t":"P","st":"Phrase","s":2,"tags":["collocation","evaluation","LR-upgrade"],"f":"<p>Alternative approaches to crime prevention ______ more ______ ______. (mang lại kết quả bền vững hơn)</p>","a":"<b>yield sustainable results</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"There is compelling evidence to suggest that alternative approaches to crime prevention yield more sustainable results than punitive measures.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"produce lasting outcomes\" | \"deliver long-term benefits\" | \"generate enduring improvements\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Khi đánh giá hiệu quả giải pháp — thay cho \"work well\" hoặc \"have good results\"</p></div>","p":1},{"id":"W10D1-P-05","l":33,"t":"P","st":"Phrase","s":2,"tags":["collocation","attitude","LR-upgrade"],"f":"<p>An increasing proportion of young people ______ a ______ ______ to pursue academic studies. (thể hiện sự miễn cưỡng rõ rệt)</p>","a":"<b>display a marked reluctance</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"An increasing proportion of young people display a marked reluctance to pursue academic studies, opting instead for vocational training.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"exhibit a growing disinclination\" | \"show considerable unwillingness\" | \"demonstrate increasing resistance\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Khi mô tả thái độ tiêu cực/miễn cưỡng — thay cho \"don't want to\"</p></div>","p":1},{"id":"W10D1-P-06","l":33,"t":"P","st":"Phrase","s":3,"tags":["collocation","argument","LR-upgrade"],"f":"<p>There is ______ ______ to ______ that rehabilitation reduces recidivism. (bằng chứng thuyết phục cho thấy)</p>","a":"<b>compelling evidence to suggest</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"There is compelling evidence to suggest that community-based rehabilitation programmes reduce recidivism rates more effectively than extended incarceration.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"strong evidence to indicate\" | \"substantial data to support the claim\" | \"convincing research to demonstrate\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Khi đưa ra bằng chứng ủng hộ lập luận — thay cho \"studies show that\"</p></div>","p":1},{"id":"W10D1-P-07","l":33,"t":"P","st":"Phrase","s":2,"tags":["collocation","solutions","LR-upgrade"],"f":"<p>______ ______ to crime prevention yield more sustainable results. (cách tiếp cận thay thế cho)</p>","a":"<b>alternative approaches to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Alternative approaches to crime prevention, such as education and rehabilitation, have proven more effective than incarceration in several Nordic countries.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"other methods of\" | \"different strategies for\" | \"supplementary measures for\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Khi giới thiệu giải pháp khác — thay cho \"other ways to\"</p></div>","p":1},{"id":"W10D1-P-08","l":33,"t":"P","st":"Phrase","s":2,"tags":["collocation","safety","LR-upgrade"],"f":"<p>Such measures could ______ to ______ ______ ______. (góp phần nâng cao an toàn công cộng)</p>","a":"<b>contribute to enhanced public safety</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Such measures could, in theory, contribute to enhanced public safety and a more secure living environment for all citizens.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"promote greater community security\" | \"foster a safer living environment\" | \"strengthen public protection\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Khi viết về kết quả tích cực cho xã hội — thay cho \"make society safer\"</p></div>","p":1},{"id":"W10D1-P-09","l":33,"t":"P","st":"Phrase","s":2,"tags":["collocation","problem-solving","LR-upgrade"],"f":"<p>The government should implement targeted policies to ______ the growing ______ of unemployment. (giải quyết vấn đề)</p>","a":"<b>address the issue</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The government should implement targeted policies to address the growing issue of unemployment in rural areas.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"tackle the problem\" | \"confront the challenge\" | \"deal with the matter\" | \"mitigate the impact\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Khi viết về giải pháp cho vấn đề — thay cho \"solve the problem\" (overused)</p></div>","p":1},{"id":"W10D1-P-10","l":33,"t":"P","st":"Phrase","s":2,"tags":["collocation","impact","LR-upgrade"],"f":"<p>Technology ______ ______ a ______ ______ ______ on modern education delivery. (đã có tác động tích cực sâu sắc)</p>","a":"<b>has had a profoundly positive impact</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Technology has had a profoundly positive impact on modern education delivery, enabling students to access resources from anywhere in the world.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"has exerted a transformative influence\" | \"has played a pivotal role in shaping\" | \"has substantially enhanced\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Khi đánh giá tác động tích cực — thay cho \"is good for\" hoặc \"helps a lot\"</p></div>","p":1},{"id":"W10D1-E-01","l":33,"t":"E","st":"Error","s":3,"tags":["CC-trap","mechanical-linking","band6"],"f":"<p>Paragraph viết: <i>\"Firstly, technology improves education. Secondly, it makes learning accessible. Moreover, it reduces costs. Furthermore, students can learn at their own pace. In addition, online courses are flexible.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>5 câu liệt kê, linked bằng \"Firstly/Secondly/Moreover/Furthermore/In addition\" = <b>mechanical listing</b>. Cả 3 từ Moreover/Furthermore/In addition đều thuộc nhóm \"addition\" → KHÔNG có range.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Dùng 3+ LOẠI linking khác nhau: reference (\"This shift\"), participle (\"thereby creating\"), contrast (\"However\"), cause-effect (\"As a result\"), concession (\"regardless of\") — VÀ mỗi câu phải DEVELOP câu trước, không chỉ liệt kê.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Band 7 CC = range of cohesive devices appropriately. Dùng 3+ LOẠI khác nhau (addition, contrast, cause-effect, reference, sequence, concession). KHÔNG dùng 3 từ cùng nhóm liên tiếp.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC — mechanical linking = Band 6 CC</p></div>","p":0},{"id":"W10D1-E-02","l":33,"t":"E","st":"Error","s":3,"tags":["LR-trap","memorized-language","band6"],"f":"<p>Introduction viết: <i>\"It is an undeniable fact that in this day and age, with the rapid development of science and technology...\"</i> — Examiner đánh giá thế nào?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Examiner nhận ra ngay đây là <b>memorized template</b>, không phải ngôn ngữ tự nhiên của thí sinh → LR Band 6.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Bỏ template → bắt đầu bằng content luôn: \"Technology has transformed education delivery.\" — đơn giản, chính xác, KHÔNG memorized.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>8 clichés cần tránh: \"It is an undeniable fact that...\" | \"In this day and age...\" | \"double-edged sword\" | \"In a nutshell\" | \"Every coin has two sides\" | \"Last but not least\" | \"Pros and cons\" | \"With the development of science and technology...\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR — memorized language = Band 6 LR maximum</p></div>","p":0},{"id":"W10D1-E-03","l":33,"t":"E","st":"Error","s":3,"tags":["collocation-error","crime","LR"],"f":"<p>Câu viết: <i>\"When punishment is very hard, people will not do crimes.\"</i> — Có mấy lỗi collocation?</p>","a":"","b":"<div class=\"sec\"><span class=\"lbl\">❌ Sai</span><p>2 lỗi collocation:</p><ol><li><del>\"do crimes\"</del> → <b>commit crimes</b> (fixed collocation)</li><li><del>\"very hard punishment\"</del> → <b>severe penalties</b> (academic register)</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"When potential offenders face severe penalties, they are arguably less inclined to engage in illegal behaviour.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Common collocation mistakes của Vietnamese speakers: <del>do a crime</del> → commit a crime | <del>big problem</del> → significant problem | <del>get knowledge</del> → acquire knowledge | <del>affect to</del> → affect sth (transitive, no \"to\") | <del>depend of</del> → depend on</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR — collocation inaccuracy = Band 6 LR</p></div>","p":0},{"id":"W10D1-E-04","l":33,"t":"E","st":"Error","s":3,"tags":["GRA-trap","one-trick-pony","band6"],"f":"<p>Paragraph viết 5 câu: <i>\"Although technology is beneficial, it can cause problems. Although education is important, not everyone has access. Although governments try, pollution is still increasing...\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Dùng \"Although\" 5 lần = <b>zero variety</b> = \"one-trick pony\". Band 7 GRA yêu cầu variety of complex structures.</p></div><div class=\"sec\"><span class=\"lbl\">✅ Đúng</span><p>Thay mỗi câu bằng loại complex structure khác nhau:</p><ol><li><b>While</b> online learning offers advantages... (concessive)</li><li>Students <b>who study remotely</b> often report... (relative clause)</li><li><b>Despite the decreasing cost</b>... (despite + noun phrase)</li><li><b>Having been deprived of</b> social interactions... (perfect participle)</li><li><b>Rather than replacing</b> conventional education... (comparative participle)</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Band 7 GRA cần ≥3 loại complex structure/bài: relative + participle + conditional + concessive + cleft + passive. Không lặp cùng 1 pattern.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA — no variety = Band 6 GRA</p></div>","p":0},{"id":"W10D1-E-05","l":33,"t":"E","st":"Error","s":3,"tags":["TA-trap","underdeveloped","band6"],"f":"<p>Body paragraph có 5 ý, mỗi ý chỉ 1 câu: <i>\"Firstly, tech helps education. Secondly, it makes learning fun. Thirdly, it helps teachers. Moreover, courses are flexible. Furthermore, it saves time.\"</i> — Tại sao chỉ được Band 6?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>5 ý × 1 câu = <b>listing, not developing</b>. Không có explanation, không có specific example. Examiner: \"Ideas are relevant but not fully extended\" → TA Band 6.</p></div><div class=\"sec\"><span class=\"lbl\">✅ Đúng</span><p>Viết 2-3 ý thôi, nhưng develop kỹ mỗi ý theo TEES:</p><ul><li><b>T</b>opic sentence → <b>E</b>xplanation → <b>E</b>xample (tên nước, số liệu) → <b>S</b>ummary</li><li>Mỗi body paragraph = 1 main idea × 4-6 câu</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Band 7 TA = fewer ideas, deeper development. 2 ý phát triển kỹ &gt; 5 ý liệt kê. Mỗi ý cần explanation + specific evidence.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA — underdeveloped ideas = Band 6 TA</p></div>","p":0},{"id":"W10D1-E-06","l":33,"t":"E","st":"Error","s":2,"tags":["TA-trap","over-generalisation","hedging"],"f":"<p>Câu viết: <i>\"Technology always causes problems for society.\"</i> và <i>\"All students should study abroad.\"</i> — Examiner nghĩ gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Khẳng định tuyệt đối (\"always\", \"all\", \"never\", \"the only solution\") = <b>over-generalisation</b> → thiếu nuance → TA Band 6.</p></div><div class=\"sec\"><span class=\"lbl\">✅ Đúng</span><p>Dùng hedging language:</p><ul><li>\"Technology <b>can contribute to</b> certain societal challenges.\"</li><li>\"<b>Many</b> students <b>may benefit from</b> studying abroad.\"</li><li>\"This is <b>arguably</b> the most effective approach.\"</li><li>\"Students <b>tend to</b> perform better in online environments.\"</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Academic writing cần hedging: may/might/could, tend to, arguably, a significant proportion of, in many cases, can contribute to. Tuyệt đối = Band 6, cân nhắc = Band 7.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA — over-generalised claims without nuance = Band 6 TA</p></div>","p":0},{"id":"W10D1-E-07","l":33,"t":"E","st":"Error","s":2,"tags":["CC-trap","dead-weight","band6"],"f":"<p>Paragraph viết: <i>\"Education is important. It is very important for people. Everyone knows that education matters. Without education, life is difficult.\"</i> — Examiner gọi hiện tượng này là gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>4 câu nói CÙNG 1 Ý = <b>\"dead weight\" sentences</b>. Lặp ý đã nói, không đẩy argument đi tiếp. Examiner: \"Repeats without extending\" → CC Band 6 (no progression).</p></div><div class=\"sec\"><span class=\"lbl\">✅ Đúng</span><p>Mỗi câu phải đẩy argument tiến 1 bước:</p><ul><li>\"Education <b>equips individuals with</b> critical thinking skills.\"</li><li>\"<b>These competencies enable</b> graduates to <b>navigate complex professional challenges</b> and <b>contribute meaningfully</b> to economic growth.\"</li></ul><p>→ 2 câu = 2 ý khác nhau, câu 2 develop câu 1.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Test: che câu đó đi — bài có mất thông tin gì không? Nếu KHÔNG → đó là dead weight → xoá.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC — no progression, repetition = Band 6 CC</p></div>","p":0},{"id":"W10D1-E-08","l":33,"t":"E","st":"Error","s":2,"tags":["collocation-error","LR","style-mismatch"],"f":"<p>Câu viết: <i>\"The government should implement stringent measures to eradicate the problem of unemployment.\"</i> — Collocation nào sai?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span><del>\"eradicate unemployment\"</del> — \"eradicate\" thường dùng cho <b>bệnh/virus</b> (eradicate smallpox, eradicate polio), không tự nhiên với \"unemployment\" → <b>collocation mismatch</b>, thiếu style awareness.</p></div><div class=\"sec\"><span class=\"lbl\">✅ Đúng</span><p>\"The government should implement <b>targeted policies</b> to <b>address</b> the growing issue of unemployment.\"</p><ul><li>\"targeted policies\" = academic collocation chính xác</li><li>\"address the issue\" = phù hợp context hơn \"eradicate\"</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Band 7 LR = awareness of style and collocation. Không chỉ biết từ \"khó\" — phải biết từ đó dùng trong context nào, đi với từ nào. Precision &gt; Complexity.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>LR — collocation mismatch / style unawareness = Band 6 LR</p></div>","p":0},{"id":"W10D2-S-01","l":34,"t":"S","st":"Structure","s":3,"tags":["time-management","exam-strategy"],"f":"<p>\"20-40 Rule\" — Phân bổ 60 phút như thế nào cho Task 1 và Task 2? Nêu chi tiết từng giai đoạn.</p>","a":"","b":"<div class=\"sec\"><p><b>Task 1: 20 phút (STRICT)</b></p><ol><li><b>Planning:</b> 2-3 phút (đọc + xác định trend/feature + outline)</li><li><b>Writing:</b> 12-15 phút (viết 4 đoạn: Intro + Overview + Detail 1 + Detail 2)</li><li><b>Review:</b> 2-3 phút (check GRA + word count ≥ 150)</li></ol><p><b>Task 2: 40 phút (CORE)</b></p><ol><li><b>Planning:</b> 5 phút (highlight prompt parts + outline 4 đoạn + keywords)</li><li><b>Writing:</b> 30-32 phút (viết 4 đoạn: Intro + Body 1 + Body 2 + Conclusion)</li><li><b>Review:</b> 3-5 phút (Band 7 Checklist + backwards reading)</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Task 1 = 20' STRICT, không lấn sang Task 2. Task 2 = 40' CORE — nơi kiếm điểm chính.\"</p></div>","p":1},{"id":"W10D2-S-02","l":34,"t":"S","st":"Structure","s":3,"tags":["planning","task2"],"f":"<p>\"5-Minute Planning\" cho Task 2 gồm 5 bước — kể tên và thời gian từng bước?</p>","a":"","b":"<div class=\"sec\"><p><b>5 bước trong 5 phút:</b></p><ol><li><b>HIGHLIGHT</b> parts (30s) — gạch chân từng part của prompt</li><li><b>POSITION</b> (30s) — quyết định quan điểm rõ ràng</li><li><b>OUTLINE</b> 4 đoạn (2 phút) — Intro + Body 1 + Body 2 + Conclusion</li><li><b>KEYWORDS</b> (1 phút) — ghi 3-5 collocations muốn dùng</li><li><b>GRA targets</b> (1 phút) — chọn 2-3 complex structures sẽ dùng</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"① Highlight (30s) → ② Position (30s) → ③ Outline (2') → ④ Keywords (1') → ⑤ GRA (1')\"</p></div>","p":1},{"id":"W10D2-S-03","l":34,"t":"S","st":"Structure","s":2,"tags":["task2-first","exam-strategy"],"f":"<p>Khi nào nên dùng chiến lược \"Task 2 First\"? Nêu 3 điều kiện NÊN và 3 điều kiện KHÔNG NÊN.</p>","a":"","b":"<div class=\"sec\"><p><b>✅ Dùng \"Task 2 First\" khi:</b></p><ol><li>Bạn hay viết Task 1 quá dài (&gt; 200 từ, &gt; 25 phút)</li><li>Task 2 là essay type bạn yếu (cần thời gian suy nghĩ)</li><li>Task 1 data đơn giản (line graph, bar chart quen thuộc)</li></ol><p><b>❌ KHÔNG dùng khi:</b></p><ol><li>Task 1 là dạng lạ (map, process) → cần xử lý khi đầu còn tỉnh</li><li>Bạn chưa quen → dễ hoảng loạn</li><li>Thi lần đầu → giữ thứ tự an toàn</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Task 2 = 2/3 điểm Writing → ưu tiên trước KHI Task 1 đơn giản.\"</p></div>","p":1},{"id":"W10D2-S-04","l":34,"t":"S","st":"Structure","s":3,"tags":["self-assessment","band7-checklist"],"f":"<p>Band 7 Pre-Submission Checklist có 5 mục — kể tên?</p>","a":"","b":"<div class=\"sec\"><p><b>5 mục kiểm tra:</b></p><ol><li><b>TA:</b> Trả lời ĐẦY ĐỦ mọi part của prompt? Position rõ ràng THROUGHOUT?</li><li><b>CC:</b> Mỗi paragraph = 1 central topic? Linking devices NATURAL?</li><li><b>LR:</b> Có ≥3 less common collocations? KHÔNG có memorized clichés?</li><li><b>GRA:</b> Có ≥3 complex structures khác nhau? Majority sentences error-free?</li><li><b>FORMAT:</b> Task 1 ≥ 150 từ? Task 2 ≥ 250 từ? 4 paragraphs?</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"TA → CC → LR → GRA → FORMAT. 5 bước, dành 5 phút sau mỗi test.\"</p></div>","p":1},{"id":"W10D2-S-05","l":34,"t":"S","st":"Structure","s":3,"tags":["examiner-perspective","self-assessment"],"f":"<p>\"Examiner Perspective Technique\" gồm 3 bước — mô tả?</p>","a":"","b":"<div class=\"sec\"><p><b>3 bước:</b></p><ol><li><b>DETACH</b> — Đợi 2-3 phút (uống nước, hít thở) trước khi đọc lại</li><li><b>BACKWARDS READING</b> — Đọc từ conclusion → body 2 → body 1 → intro → phát hiện lỗi GRA tốt hơn vì không bị cuốn theo nghĩa</li><li><b>TOPIC SENTENCE TEST</b> — Đọc CHỈ câu đầu mỗi paragraph → ghép thành mini-essay → nếu hợp lý = CC tốt</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"DETACH → BACKWARDS → TOPIC TEST. Đọc ngược = thấy lỗi GRA rõ hơn.\"</p></div>","p":1},{"id":"W10D2-S-06","l":34,"t":"S","st":"Structure","s":2,"tags":["proofreading","review"],"f":"<p>\"Proofreading 3-Focus Technique\" — 3 focus nào khi review trong 2-3 phút cuối?</p>","a":"","b":"<div class=\"sec\"><p><b>3 focus duy nhất:</b></p><ol><li><b>REPEATED VOCABULARY</b> — scan nhanh → thấy từ lặp &gt; 2 lần → thay synonym</li><li><b>VERB TENSE</b> — kiểm tra consistency (Task 1: past/present tùy data, Task 2: present tense chủ đạo)</li><li><b>BASIC GRAMMAR</b> — 3 lỗi phổ biến nhất:</li></ol><ul><li>① Articles (the/a/an — đặc biệt \"the government\", \"the environment\")<div>② Subject-Verb agreement (\"the number of... HAS\", \"a number of... HAVE\")</div><div>③ Plural/Singular (\"informations\" ❌ → \"information\" ✅)</div></li></ul></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Mỗi lần review, chọn 1 trong 3 focus đọc riêng — KHÔNG cố đọc cả 3 cùng lúc.\"</p></div>","p":1},{"id":"W10D2-S-07","l":34,"t":"S","st":"Structure","s":2,"tags":["clock-checking","time-management"],"f":"<p>Clock-checking habit — kiểm tra đồng hồ ở 5 mốc nào?</p>","a":"","b":"<div class=\"sec\"><p><b>5 mốc kiểm tra:</b></p><ol><li><b>10 phút</b> → Task 1: planning xong, đang viết body (KHÔNG còn loay hoay đọc đề)</li><li><b>20 phút</b> → PHẢI chuyển sang Task 2 (dù Task 1 chưa hoàn hảo)</li><li><b>35 phút</b> → Task 2 Body 1 xong, bắt đầu Body 2</li><li><b>50 phút</b> → Bắt đầu Conclusion (dù Body 2 chưa hoàn hảo)</li><li><b>55 phút</b> → Review time — chạy Proofreading 3-Focus</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Nếu sắp hết giờ: LUÔN viết conclusion (dù chỉ 1-2 câu). Thiếu conclusion → CC bị ảnh hưởng nặng.\"</p></div>","p":1},{"id":"W10D2-S-08","l":34,"t":"S","st":"Structure","s":3,"tags":["map-writing","task1","tense"],"f":"<p>Map Writing — Chọn thì theo 3 loại timeline nào?</p>","a":"","b":"<div class=\"sec\"><p><b>3 loại timeline:</b></p><ol><li><b>Past → Past</b> (VD: 1950 vs 1990) → dùng <b>Past Simple</b> passive: \"The factory <b>was demolished</b> in 1990.\"</li><li><b>Past → Present</b> (VD: 1980 vs today) → dùng <b>Present Perfect</b> passive: \"The forest <b>has been converted into</b> a park.\"</li><li><b>Present → Future</b> (VD: now vs 2035 plan) → dùng <b>Future</b> forms: \"A new hospital <b>is planned to be built</b>.\"</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Map so sánh 1980 vs present → \"The farmland <b>has been replaced by</b> a sports centre.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Past→Past = Simple Past | Past→Present = Present Perfect | Present→Future = Future\"</p></div>","p":1},{"id":"W10D2-S-09","l":34,"t":"S","st":"Structure","s":2,"tags":["map-writing","task1","rules"],"f":"<p>Map Writing — 5 quy tắc quan trọng nhất?</p>","a":"","b":"<div class=\"sec\"><p><b>5 quy tắc:</b></p><ol><li>Dùng <b>present perfect passive</b>: \"has been replaced by\", \"has been converted into\"</li><li>Dùng <b>spatial language</b>: \"To the north/south\", \"on the western side\", \"nearby\"</li><li><b>KHÔNG</b> dùng số liệu cụ thể — Map không có data → mô tả THAY ĐỔI</li><li><b>PHẢI</b> có overview: \"Overall, the town has undergone...\"</li><li><b>Nhóm theo vị trí</b> (north/south) hoặc loại thay đổi (developed/unchanged)</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Map = passive + spatial + overview + nhóm theo vị trí. KHÔNG liệt kê số liệu.\"</p></div>","p":1},{"id":"W10D2-S-10","l":34,"t":"S","st":"Structure","s":2,"tags":["midpoint-assessment","progress"],"f":"<p>Phase 4 Midpoint Assessment — 3 levels đánh giá (PASS / CONDITIONAL / REPEAT) và tiêu chí?</p>","a":"","b":"<div class=\"sec\"><p><b>3 levels:</b></p><ol><li><b>✅ PASS:</b> Overall ≥ 6.5 cả 2 tests + không có tiêu chí nào &lt; 6.0 → Tiếp tục W11</li><li><b>⚠️ CONDITIONAL:</b> Overall 6.0-6.5 HOẶC có 1 tiêu chí &lt; 6.0 → W11 + thêm targeted drill</li><li><b>❌ REPEAT:</b> Overall &lt; 6.0 cả 2 tests HOẶC có ≥ 2 tiêu chí &lt; 5.5 → Quay lại W10D1 drills</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"PASS = 6.5+ toàn bộ. CONDITIONAL = có điểm yếu → drill thêm. REPEAT = dưới 6.0 → lặp lại.\"</p></div>","p":1},{"id":"W10D2-P-01","l":34,"t":"P","st":"Phrase","s":2,"tags":["line-graph","task1","trend"],"f":"<p>South Korea ______ (bắt đầu giai đoạn với) the highest internet access at 73%.</p>","a":"<b>began the period with</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"South Korea began the period with the highest internet access at 73% in 2005.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"started the period at\" | \"opened the period with\" | \"recorded the highest initial rate of\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 — mô tả điểm bắt đầu của dữ liệu</p></div>","p":1},{"id":"W10D2-P-02","l":34,"t":"P","st":"Phrase","s":2,"tags":["line-graph","task1","comparison"],"f":"<p>By 2015, Germany ______ (thu hẹp khoảng cách) with South Korea to just 8 percentage points.</p>","a":"<b>had narrowed the gap</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"By 2015, Germany had narrowed the gap with South Korea to just 8 percentage points.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"had closed the gap\" | \"had reduced the difference\" | \"had bridged the divide\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 — so sánh sự thay đổi khoảng cách giữa 2 đối tượng</p></div>","p":1},{"id":"W10D2-P-03","l":34,"t":"P","st":"Phrase","s":2,"tags":["line-graph","task1","trend"],"f":"<p>Brazil ______ (thể hiện mức tăng trưởng ấn tượng nhất) in proportional terms.</p>","a":"<b>demonstrated the most dramatic growth</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Brazil demonstrated the most dramatic growth in proportional terms, increasing more than fivefold to 71% by 2020.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"exhibited the most remarkable increase\" | \"showed the most striking rise\" | \"experienced the sharpest growth\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 — mô tả đối tượng có mức tăng tương đối lớn nhất</p></div>","p":1},{"id":"W10D2-P-04","l":34,"t":"P","st":"Phrase","s":2,"tags":["line-graph","task1","comparison"],"f":"<p>Brazil still ______ (tụt lại phía sau) the other two nations by a considerable margin.</p>","a":"<b>lagged behind</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Despite this rapid expansion, Brazil still lagged behind the other two nations by a considerable margin at the end of the period.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"trailed behind\" | \"remained below\" | \"fell short of\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 — so sánh đối tượng thấp nhất với các đối tượng khác</p></div>","p":1},{"id":"W10D2-P-05","l":34,"t":"P","st":"Phrase","s":2,"tags":["discussion","task2","education"],"f":"<p>Universities should ______ (trang bị cho sinh viên) career-relevant knowledge.</p>","a":"<b>equip students with</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Those who argue that universities should equip students with career-relevant knowledge raise a valid point.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"provide students with\" | \"furnish students with\" | \"prepare students for\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 2 — education topic, bàn về mục đích của giáo dục</p></div>","p":1},{"id":"W10D2-P-06","l":34,"t":"P","st":"Phrase","s":2,"tags":["discussion","task2","career"],"f":"<p>Graduates are more likely to ______ (đảm bảo việc làm ổn định) upon graduation.</p>","a":"<b>secure stable employment</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Graduates who possess practical skills are more likely to secure stable employment upon graduation.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"obtain steady jobs\" | \"find reliable work\" | \"gain permanent positions\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 2 — career/education topic, bàn về kết quả việc làm</p></div>","p":1},{"id":"W10D2-P-07","l":34,"t":"P","st":"Phrase","s":3,"tags":["discussion","task2","criticism"],"f":"<p>Reducing university education to mere job preparation would be ______ (thiển cận về bản chất).</p>","a":"<b>fundamentally short-sighted</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Reducing university education to mere job preparation would be fundamentally short-sighted.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"inherently narrow-minded\" | \"profoundly misguided\" | \"deeply flawed\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 2 — strong criticism, phản bác quan điểm đối lập</p></div>","p":1},{"id":"W10D2-P-08","l":34,"t":"P","st":"Phrase","s":2,"tags":["discussion","task2","skills"],"f":"<p>Critical thinking and personal development ______ (nuôi dưỡng khả năng thích ứng).</p>","a":"<b>foster adaptability</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Critical thinking and personal development foster adaptability — a quality that is arguably more valuable in an era where career paths are no longer linear.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"cultivate resilience\" | \"develop flexibility\" | \"nurture versatility\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 2 — personal development, bàn về kỹ năng mềm</p></div>","p":1},{"id":"W10D2-P-09","l":34,"t":"P","st":"Phrase","s":3,"tags":["problem-solution","task2","cause"],"f":"<p>The escalating problem of traffic congestion ______ (có thể quy cho) several interrelated factors.</p>","a":"<b>can be attributed to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The escalating problem of traffic congestion can be attributed to several interrelated factors.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"is largely driven by\" | \"stems primarily from\" | \"is principally caused by\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 2 — problem-solution essay, giới thiệu nguyên nhân</p></div>","p":1},{"id":"W10D2-P-10","l":34,"t":"P","st":"Phrase","s":2,"tags":["problem-solution","task2","cause"],"f":"<p>Population density has ______ (vượt xa năng lực) of existing transport networks.</p>","a":"<b>far outstripped the capacity</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"In cities such as Jakarta and Manila, population density has far outstripped the capacity of existing transport networks.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"greatly exceeded the limits\" | \"overwhelmed the infrastructure\" | \"surpassed the capability\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 2 — problem-solution, mô tả sự mất cân đối demand vs supply</p></div>","p":1},{"id":"W10D2-P-11","l":34,"t":"P","st":"Phrase","s":2,"tags":["problem-solution","task2","solution"],"f":"<p>Bogotá's TransMilenio ______ (là mô hình thuyết phục) of how affordable public transport can alleviate urban gridlock.</p>","a":"<b>serves as a compelling model</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Bogotá's TransMilenio bus rapid transit system serves as a compelling model of how affordable public transport can alleviate urban gridlock.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"provides a successful example\" | \"offers a proven blueprint\" | \"stands as a testament to\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 2 — dùng ví dụ cụ thể để minh hoạ giải pháp</p></div>","p":1},{"id":"W10D2-P-12","l":34,"t":"P","st":"Phrase","s":2,"tags":["map","task1","change"],"f":"<p>Lakeside ______ (đã trải qua sự biến đổi đáng kể) from a small rural settlement to a more developed town.</p>","a":"<b>has undergone considerable transformation</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Overall, Lakeside has undergone considerable transformation from a small rural settlement to a more developed town.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"has experienced significant development\" | \"has been substantially transformed\" | \"has seen dramatic changes\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Map — overview, mô tả tổng quan thay đổi</p></div>","p":1},{"id":"W10D2-P-13","l":34,"t":"P","st":"Phrase","s":2,"tags":["map","task1","change"],"f":"<p>The eastern forest ______ (đã nhường chỗ cho) a hotel accompanied by a car park.</p>","a":"<b>has given way to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The eastern forest has given way to a hotel accompanied by a car park.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"has been replaced by\" | \"has been converted into\" | \"has made way for\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Map — mô tả khu vực cũ bị thay thế bởi công trình mới</p></div>","p":1},{"id":"W10D2-P-14","l":34,"t":"P","st":"Phrase","s":2,"tags":["map","task1","interpretation"],"f":"<p>These developments suggest ______ (sự chuyển dịch hướng tới) leisure and tourism.</p>","a":"<b>a shift towards</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"These developments suggest a shift towards leisure and tourism.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"a transition to\" | \"a move towards\" | \"a trend in the direction of\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Task 1 Map — câu kết thể hiện nhận xét tổng quan về hướng phát triển</p></div>","p":1},{"id":"W10D2-E-01","l":34,"t":"E","st":"Error","s":3,"tags":["mistake","planning","vietnamese-trap"],"f":"<p>Thí sinh Việt Nam thường \"nghĩ trong đầu rồi viết luôn\" — không outline trên giấy. Lỗi này ảnh hưởng gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Không viết outline trên giấy → viết được 150 từ thì hết ý → body paragraph underdeveloped</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>LUÔN viết outline trên giấy — dù chỉ 4 dòng gạch đầu dòng. Outline giúp phân bổ ý đều cho 2 body paragraphs.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Task 2 Planning = 5 phút bắt buộc. Outline trên giấy = bảo hiểm chống hết ý.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA + CC — body paragraph underdeveloped = TA/CC 5.5</p></div>","p":0},{"id":"W10D2-E-02","l":34,"t":"E","st":"Error","s":3,"tags":["mistake","map","passive"],"f":"<p>Viết trong bài Map: \"A change was taken place in the town centre.\" — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>\"take place\" là intransitive verb (không có object) → KHÔNG dùng passive</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"Several changes <b>have taken place</b> in the town centre.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Các động từ intransitive KHÔNG BAO GIỜ dùng passive: take place, occur, happen, appear, become, change</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA — lỗi cấu trúc cơ bản = GRA bị ảnh hưởng</p></div>","p":0},{"id":"W10D2-E-03","l":34,"t":"E","st":"Error","s":3,"tags":["mistake","conclusion","time-pressure"],"f":"<p>Hết 35 phút, Task 2 chưa xong. Thí sinh viết nhanh, bỏ conclusion. Mất điểm gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Bỏ conclusion → mất cấu trúc hoàn chỉnh → CC bị ảnh hưởng nặng</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>LUÔN viết conclusion (dù chỉ 1-2 câu ngắn). VD: \"In conclusion, I firmly believe that the benefits of X significantly outweigh its drawbacks.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Conclusion ngắn &gt; không có conclusion. Thiếu conclusion = CC bị cap ở Band 5-6.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC — thiếu conclusion = CC mất cấu trúc</p></div>","p":0},{"id":"W10D2-E-04","l":34,"t":"E","st":"Error","s":2,"tags":["mistake","task1","overview"],"f":"<p>Task 1: Thí sinh liệt kê mọi số liệu, viết 250+ từ nhưng không có overview. Mất điểm gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Liệt kê hết data + viết quá dài + thiếu overview → lạc focus, mất thời gian Task 2</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Chọn 3-4 key trends + overall → viết 160-180 từ, rõ ràng. Overview = 1-2 câu nêu trend CHUNG.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Task 1 cần chọn lọc data, KHÔNG mô tả tất cả. Overview là bắt buộc — thiếu overview → TA bị cap ở Band 5.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA — thiếu overview = TA bị cap Band 5</p></div>","p":0},{"id":"W10D2-E-05","l":34,"t":"E","st":"Error","s":2,"tags":["mistake","map","tense"],"f":"<p>Map so sánh 1980 vs hiện tại nhưng thí sinh dùng Simple Past: \"The forest was converted into a park.\" — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Dùng Simple Past cho map Past → Present. Simple Past chỉ phù hợp khi cả 2 mốc đều ở quá khứ.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>\"The forest <b>has been converted into</b> a park.\" (Present Perfect vì so sánh quá khứ → hiện tại)</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Past→Past = Simple Past passive. Past→Present = Present Perfect passive. Present→Future = Future forms.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA — dùng sai thì = GRA accuracy giảm</p></div>","p":0},{"id":"W10D2-E-06","l":34,"t":"E","st":"Error","s":2,"tags":["mistake","linking","cc"],"f":"<p>Thí sinh dùng linking devices máy móc: \"Firstly, ... Secondly, ... Thirdly, ... Finally, ...\" — Vấn đề gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Linking devices quá mechanical và decorative → CC không tự nhiên, giám khảo nhận ra ngay</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Dùng linking tự nhiên và đa dạng: \"On the one hand / From this perspective / Moreover / In parallel / Chief among these / Additionally\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Linking devices phải NATURAL, không phải decorative. Đa dạng hoá: cause-effect, contrast, addition, example markers.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC — linking mechanical = CC bị cap Band 6</p></div>","p":0},{"id":"W11D1-S-01","l":35,"t":"S","st":"Structure","s":3,"tags":["exam-strategy","automatic-checklist","review"],"f":"<p>\"Automatic Checklist\" gồm 2 bước gì? Tổng bao lâu? Dùng khi nào?</p>","a":"","b":"<div class=\"sec\"><p><b>2 bước trong 2 PHÚT</b> — dùng trong 2-3 phút cuối MỖI bài thi:</p><ol><li><b>Phút 1 — SCAN</b> (đọc lướt toàn bài):</li></ol><ul><li>Word count OK? (Task 1 ≥ 150, Task 2 ≥ 250)<div>4 paragraphs?</div><div>Position clear? (intro + conclusion trùng ý = OK)</div></li></ul><ol><li><b>Phút 2 — SPOT CHECK</b> (đọc ngẫu nhiên 3-4 câu):</li></ol><ul><li>Có ít nhất 1 complex sentence?<div>Linking device tự nhiên? (không \"Firstly... Secondly...\")</div><div>Articles OK? (\"the government\", không \"government\")</div></li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Test #8 mệt → vẫn chạy Automatic Checklist → phát hiện thiếu \"the\" trước \"government\" 2 chỗ → sửa → cứu 0.5 band GRA.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"SCAN rồi SPOT\" — Scan toàn bài trước, spot check chi tiết sau. Khác với Band 7 Checklist 5 bước (dùng khi self-assess SAU thi).</p></div>","p":1},{"id":"W11D1-S-02","l":35,"t":"S","st":"Structure","s":3,"tags":["exam-strategy","fatigue","endurance"],"f":"<p>Khi phải làm nhiều tests liên tiếp (hoặc sau Listening + Reading), nêu 4 chiến lược chống fatigue?</p>","a":"","b":"<div class=\"sec\"><ol><li><b>Trước Test 1</b>: Warm-up routine (hít thở + nhắc 3 điều) + uống nước</li><li><b>Giữa tests</b>: Đi lại 2' + uống nước + KHÔNG đọc lại bài cũ (tránh overthinking)</li><li><b>Trước test cuối</b>: Nhắm mắt 2' + stretch + ăn nhẹ (trái cây/chocolate = glucose cho não)</li><li><b>Trong test cuối</b>: Plan outline KỸ HƠN — <b>6-7 phút</b> thay vì 5 (khi mệt, outline cứu bạn)</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Test #3, mệt, hết ý Body 2 → nhờ outline chi tiết đã plan 7 phút → vẫn có keywords → viết được.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Mệt hơn → plan LÂU hơn, câu ĐƠN GIẢN hơn, review NGHIÊM hơn.\"</p></div>","p":1},{"id":"W11D1-S-03","l":35,"t":"S","st":"Structure","s":3,"tags":["exam-strategy","accuracy","grammar"],"f":"<p>Nguyên tắc \"Accuracy Over Complexity\" khi mệt là gì? Nêu 3 câu AN TOÀN vs 3 câu NÊN TRÁNH?</p>","a":"","b":"<div class=\"sec\"><p><b>Nguyên tắc:</b> Thà viết câu đơn giản mà ĐÚNG → hơn câu phức tạp mà SAI.</p><ul><li>70% câu đúng (dù đơn giản) = GRA 6.5</li><li>50% câu sai (dù phức tạp) = GRA 5.5</li></ul><p><b>✅ Câu an toàn (dùng khi mệt):</b></p><ul><li>Simple compound: \"X has increased, and Y has decreased.\"</li><li>Basic relative: \"Students who study abroad gain valuable experience.\"</li><li>Basic conditional: \"If governments invest in education, society benefits.\"</li></ul><p><b>❌ Tránh khi mệt (dễ sai):</b></p><ul><li>Inversion: \"Not only does...\" → dễ sai word order</li><li>Participle clause: \"Having considered...\" → dễ sai tense</li><li>Complex passive: \"It could be argued that...\" → dễ quên agreement</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>MIX: 2-3 câu phức tạp (đã \"tự động hoá\") + còn lại câu đơn giản chính xác.</p></div>","p":1},{"id":"W11D1-S-04","l":35,"t":"S","st":"Structure","s":2,"tags":["scoring","task-priority","time-management"],"f":"<p>Task 2 chiếm bao nhiêu phần trăm điểm Writing? Công thức tính? Hệ quả cho time management?</p>","a":"","b":"<div class=\"sec\"><p><b>Task 2 = 2/3 tổng điểm Writing.</b></p><ul><li>Công thức: <b>(Task 1 × 1 + Task 2 × 2) ÷ 3 = Overall Writing Band</b></li><li>Ví dụ: Task 1 = 6.0, Task 2 = 7.0 → (6 + 14) ÷ 3 = 6.67 → <b>Overall = 6.5</b></li></ul><p><b>Hệ quả:</b></p><ul><li>LUÔN ưu tiên Task 2 nếu hết giờ</li><li>Task 1 chưa xong sau 20' → CHUYỂN sang Task 2 ngay</li><li>Task 2 chưa xong → viết conclusion ngắn (1-2 câu) trong 1' cuối</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Task 2 gấp đôi → thời gian cũng gấp đôi: 20' vs 40'.\"</p></div>","p":1},{"id":"W11D1-S-05","l":35,"t":"S","st":"Structure","s":2,"tags":["word-count","strategy","target"],"f":"<p>Word count tối ưu cho Task 1 và Task 2? Tại sao không nên viết quá dài?</p>","a":"","b":"<div class=\"sec\"><div class=\"tw\"><table><thead><tr><th>Task</th><th>Minimum</th><th>Target tối ưu</th><th>Lý do</th></tr></thead><tbody><tr><td>Task 1</td><td>150 từ</td><td><b>170-190 từ</b></td><td>Đủ develop ideas mà không lấn giờ Task 2</td></tr><tr><td>Task 2</td><td>250 từ</td><td><b>270-290 từ</b></td><td>Đủ space cho examples + complex structures</td></tr></tbody></table></div><p><b>Rủi ro:</b></p><ul><li>Viết DƯỚI minimum → TA bị ảnh hưởng NẶNG (thiếu ideas + examples)</li><li>Viết QUÁ DÀI (&gt;350 từ) → hết giờ + nhiều lỗi hơn + mất focus</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"170-190 / 270-290 — đủ xài, không thừa.\"</p></div>","p":1},{"id":"W11D1-S-06","l":35,"t":"S","st":"Structure","s":3,"tags":["process-writing","task1","passive-voice"],"f":"<p>Viết Process Diagram (Task 1) có 5 quy tắc đặc biệt — kể tên?</p>","a":"","b":"<div class=\"sec\"><ol><li>Dùng <b>passive voice</b> chủ đạo: \"Fish are caught\", \"they are sorted\" (chủ ngữ nhận hành động)</li><li><b>Nhóm stages</b> thành 3-4 phases — KHÔNG liệt kê từng bước riêng lẻ</li><li>Dùng <b>sequencing language ĐA DẠNG</b>: \"Following this\", \"subsequently\", \"before being\", \"once cooled\"</li><li><b>KHÔNG</b> dùng bullet points — viết prose liên tục (paragraph form)</li><li><b>Overview</b> = chia phases + nêu đặc điểm chung: \"can be divided into three phases\"</li><li>Viết số bằng <b>CHỮ</b>: \"two to four hours\", KHÔNG \"2-4 hours\"</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>\"In the first phase, fish are caught from the sea by trawlers and subsequently transported to a port facility, where they are sorted by size.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Passive + Phases + Prose + Sequencing variety = Band 7 Process.\"</p></div>","p":1},{"id":"W11D1-P-01","l":35,"t":"P","st":"Phrase","s":2,"tags":["bar-chart","comparison","total"],"f":"<p>Australian households ______ (chi tiêu nhiều hơn tổng cộng) than their British counterparts.</p>","a":"<b>spent more in aggregate</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Overall, Australian households spent more in aggregate than their British counterparts, although the UK allocated a higher proportion of its budget to transport.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"had higher total expenditure\" | \"spent more collectively\" | \"recorded greater overall spending\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Bar chart — khi so sánh tổng số liệu giữa 2+ nhóm.</p></div>","p":1},{"id":"W11D1-P-02","l":35,"t":"P","st":"Phrase","s":2,"tags":["bar-chart","proportion","comparison"],"f":"<p>The UK ______ (phân bổ tỷ lệ cao hơn) of its budget to transport.</p>","a":"<b>allocated a higher proportion</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The UK allocated a higher proportion of its budget to transport, making it the only category where UK spending exceeded that of Australia.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"devoted a larger share\" | \"dedicated a greater percentage\" | \"assigned more of its budget\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Bar/Pie chart — khi so sánh tỷ lệ phân bổ giữa các nhóm.</p></div>","p":1},{"id":"W11D1-P-03","l":35,"t":"P","st":"Phrase","s":2,"tags":["bar-chart","comparison","margin"],"f":"<p>Total Australian spending ______ UK expenditure ______ (vượt qua... với biên độ) approximately £100.</p>","a":"<b>surpassed... by a margin of</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Total Australian household spending (£1,040) surpassed UK expenditure (£940) by a margin of approximately £100.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"exceeded... by roughly\" | \"outstripped... by around\" | \"was higher than... by approximately\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Mọi loại chart — khi nêu khoảng cách chênh lệch cụ thể giữa 2 số liệu.</p></div>","p":1},{"id":"W11D1-P-04","l":35,"t":"P","st":"Phrase","s":3,"tags":["inequality","cause-effect","society"],"f":"<p>Income inequality ______ (dẫn đến) several serious socioeconomic consequences.</p>","a":"<b>gives rise to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Income inequality gives rise to several serious socioeconomic consequences, most notably stratified access to education and healthcare.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"leads to\" | \"results in\" | \"engenders\" | \"precipitates\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Cause-effect — thay thế \"causes\" hoặc \"leads to\" (academic hơn, Band 7+).</p></div>","p":1},{"id":"W11D1-P-05","l":35,"t":"P","st":"Phrase","s":3,"tags":["inequality","education","mobility"],"f":"<p>Poor education limits children's ______ (triển vọng thăng tiến xã hội).</p>","a":"<b>prospects for upward social mobility</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Children from low-income households often attend under-resourced schools, which severely limits their prospects for upward social mobility.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"chances of social advancement\" | \"opportunities for socioeconomic progress\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Education / Equality / Poverty topics — khi nói về cơ hội thăng tiến.</p></div>","p":1},{"id":"W11D1-P-06","l":35,"t":"P","st":"Phrase","s":2,"tags":["inequality","society","cohesion"],"f":"<p>Stark economic disparities tend to ______ (xói mòn sự gắn kết xã hội).</p>","a":"<b>erode social cohesion</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Stark economic disparities tend to erode social cohesion, as resentment between different income brackets can fuel political instability.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"undermine community bonds\" | \"weaken the social fabric\" | \"fracture societal unity\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Society / Inequality topics — khi nói về tác động tiêu cực lên xã hội.</p></div>","p":1},{"id":"W11D1-P-07","l":35,"t":"P","st":"Phrase","s":3,"tags":["government","taxation","policy"],"f":"<p>Governments could address inequality by ______ (áp dụng thuế luỹ tiến).</p>","a":"<b>implementing progressive taxation</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Implementing progressive taxation — whereby higher earners contribute a larger share of their income — would generate revenue to fund social programmes.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"introducing a graduated tax system\" | \"adopting tiered taxation\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Government policy / Economics — khi đề xuất giải pháp thuế.</p></div>","p":1},{"id":"W11D1-P-08","l":35,"t":"P","st":"Phrase","s":2,"tags":["process","sequencing","overview"],"f":"<p>The process ______ (có thể chia thành ba giai đoạn chính): initial preparation, the smoking treatment, and final quality assurance.</p>","a":"<b>can be divided into three broad phases</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Overall, the process can be divided into three broad phases: initial preparation (catching to cleaning), the smoking treatment (brining to cooling), and final quality assurance (inspection to distribution).\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"consists of three main stages\" | \"comprises three distinct phases\" | \"encompasses three key stages\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Process diagram overview — khi nhóm các bước thành phases.</p></div>","p":1},{"id":"W11D1-P-09","l":35,"t":"P","st":"Phrase","s":2,"tags":["process","quality","inspection"],"f":"<p>Once cooled, the fish ______ (trải qua kiểm tra chất lượng) for colour, texture and smell.</p>","a":"<b>undergo quality inspection</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Once cooled to room temperature, the fish undergo quality inspection for colour, texture and smell.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"are subjected to quality control checks\" | \"pass through a quality assessment stage\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Process diagram — khi mô tả bước kiểm tra/đánh giá chất lượng.</p></div>","p":1},{"id":"W11D1-P-10","l":35,"t":"P","st":"Phrase","s":3,"tags":["work-from-home","advantage","commuting"],"f":"<p>The most compelling advantage of home-based work is the ______ (loại bỏ việc đi lại hàng ngày).</p>","a":"<b>elimination of daily commuting</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The most compelling advantage of home-based work is the elimination of daily commuting, which saves employees one to two hours per day.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"removal of the daily commute\" | \"freedom from commuting obligations\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Work from home / Transport / Lifestyle topics — khi nêu lợi ích chính.</p></div>","p":1},{"id":"W11D1-P-11","l":35,"t":"P","st":"Phrase","s":2,"tags":["work-from-home","disadvantage","isolation"],"f":"<p>Remote workers may experience ______ (sự cô lập nghề nghiệp) and miss out on spontaneous collaboration.</p>","a":"<b>professional isolation</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Chief among these disadvantages is the potential for professional isolation, as employees who work remotely may miss out on the spontaneous collaboration that an office naturally provides.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"workplace isolation\" | \"occupational solitude\" | \"career disconnection\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Work from home disadvantages / Workplace culture topics.</p></div>","p":1},{"id":"W11D1-P-12","l":35,"t":"P","st":"Phrase","s":2,"tags":["pie-chart","change","overview"],"f":"<p>There was ______ (sự chuyển dịch đáng chú ý từ... sang...) location-based factors towards career-oriented criteria.</p>","a":"<b>a notable shift from... towards...</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Overall, there was a notable shift from location-based factors towards career-oriented and technology-driven criteria over the 18-year period.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"a marked transition from... to...\" | \"a significant move away from... towards...\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Pie chart / Line graph overview — khi mô tả xu hướng thay đổi lớn theo thời gian.</p></div>","p":1},{"id":"W11D1-P-13","l":35,"t":"P","st":"Phrase","s":2,"tags":["pie-chart","change","new-category"],"f":"<p>Career prospects ______ (đã nổi lên như mối quan tâm hàng đầu) at 32%.</p>","a":"<b>had emerged as the foremost concern</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"By 2023, career prospects after graduation had emerged as the foremost concern at 32%, displacing academic reputation, which declined to 24%.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"had become the primary consideration\" | \"had risen to become the dominant factor\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Pie/Bar chart — khi một category mới vươn lên vị trí dẫn đầu.</p></div>","p":1},{"id":"W11D1-P-14","l":35,"t":"P","st":"Phrase","s":3,"tags":["transport","environment","investment"],"f":"<p>Building more roads tends to ______ (tạo ra thêm giao thông) rather than reduce congestion.</p>","a":"<b>induce additional traffic</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Simply building more roads tends to induce additional traffic rather than reduce congestion — a phenomenon well-documented in cities such as Los Angeles.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"generate further congestion\" | \"attract more vehicles\" | \"stimulate increased car usage\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Transport / Urban planning — khi phản bác ý tưởng xây thêm đường.</p></div>","p":1},{"id":"W11D1-P-15","l":35,"t":"P","st":"Phrase","s":2,"tags":["economics","investment","long-term"],"f":"<p>Public transport infrastructure ______ (mang lại lợi nhuận dài hạn vượt trội) on government expenditure.</p>","a":"<b>delivers superior long-term returns</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Public transport infrastructure delivers superior long-term returns on government expenditure, despite the considerable initial capital outlay.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"yields greater long-term dividends\" | \"offers better value over time\" | \"generates sustained economic benefits\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Economics / Government spending — khi so sánh hiệu quả đầu tư dài hạn.</p></div>","p":1},{"id":"W11D1-E-01","l":35,"t":"E","st":"Error","s":3,"tags":["mistake","fatigue","review"],"f":"<p>Sau 2-3 bài thi liên tiếp, nhiều thí sinh \"mệt quá\" nên bỏ review 2 phút cuối. — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Bỏ review khi mệt → bỏ lỡ 3-5 lỗi GRA dễ sửa (articles, S-V agreement, tense) → mất 0.5 band.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Automatic Checklist 2 phút PHẢI LÀM dù mệt. Set alarm 2 phút trước hết giờ. Phút 1: SCAN (word count, paragraphs, position). Phút 2: SPOT CHECK (complex sentence, linking, articles).</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Review 2 phút = ROI cao nhất trong bài thi. 2 phút đổi 0.5 band — KHÔNG có hoạt động nào khác hiệu quả bằng.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA — lỗi cơ bản không sửa = examiner thấy \"frequent errors\" → GRA 5.5</p></div>","p":0},{"id":"W11D1-E-02","l":35,"t":"E","st":"Error","s":3,"tags":["mistake","fatigue","complexity"],"f":"<p>Trong test cuối khi đã mệt, thí sinh cố viết: <i>\"Not only does technology provides benefits but also it creating problems.\"</i> — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Khi mệt, cố viết câu phức tạp (inversion, participle) → sai ngữ pháp → GRA GIẢM. Câu trên sai 2 chỗ: \"provides\" → \"provide\" (bare infinitive after does), \"it creating\" → \"it creates\".</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Viết câu đơn giản mà ĐÚNG: \"Technology provides significant benefits. However, it also creates certain problems.\" — 100% đúng ngữ pháp.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>\"Accuracy Over Complexity\" — 70% câu đúng (dù đơn giản) = GRA 6.5. 50% câu sai (dù phức tạp) = GRA 5.5. Khi mệt: MIX 2-3 câu phức đã thuộc + còn lại câu đơn giản chính xác.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA — \"frequent grammatical errors\" = GRA 5.0-5.5</p></div>","p":0},{"id":"W11D1-E-03","l":35,"t":"E","st":"Error","s":3,"tags":["mistake","fatigue","linking","coherence"],"f":"<p>Bài viết test thứ 3: <i>\"Firstly... Secondly... Thirdly... Finally...\"</i> — lặp lại ở cả 3 tests. Mất điểm gì?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Linking devices lặp = \"mechanical\" = CC 5.5. Examiner muốn thấy \"a range of cohesive devices\", không phải cùng 1 pattern.</p></div><div class=\"sec\"><span class=\"lbl\">✅ Đúng</span><p>Rotate linking devices:</p><ul><li>Thay \"Firstly\" → \"One key factor...\" / \"The most persuasive argument...\"</li><li>Thay \"Secondly\" → \"Additionally\" / \"A further consideration...\"</li><li>Thay \"Finally\" → \"Ultimately\" / \"In the final analysis...\"</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Chuẩn bị \"Linking Rotation Card\" — 3 options mỗi vị trí. Khi mệt, nhìn card → chọn option khác test trước.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>CC — \"overuse of certain cohesive devices\" = CC 5.5-6.0</p></div>","p":0},{"id":"W11D1-E-04","l":35,"t":"E","st":"Error","s":3,"tags":["mistake","time-management","task1"],"f":"<p>Thí sinh viết Task 1 mất 28 phút vì \"muốn hoàn hảo\", còn 32 phút cho Task 2. — Sai ở đâu?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Task 1 chiếm 28' → Task 2 chỉ còn 32' → không đủ develop ideas + examples → TA Task 2 giảm. Task 2 = 2/3 tổng điểm → mất nhiều hơn được.</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Task 1 MAX 20 phút. Sau 20' → DỪNG → chuyển Task 2 dù chưa hoàn hảo. Task 1 chưa xong → quay lại nếu còn thời gian cuối.</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Hết 20 phút Task 1 = CHUYỂN. Công thức: (Task 1 × 1 + Task 2 × 2) ÷ 3. Task 2 hoàn thiện = Overall cao hơn Task 1 hoàn thiện.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA (Task 2) — underdeveloped body paragraphs + missing/rushed conclusion = TA 5.5</p></div>","p":0},{"id":"W12D1-S-01","l":36,"t":"S","st":"Structure","s":3,"tags":["exam-strategy","time-management","time-allocation"],"f":"<p>3 Time Allocation Strategies cho 60 phút thi Writing là gì? Mỗi strategy phân bổ bao lâu cho Task 1 và Task 2?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>Standard 20-40</b>: Task 1 trước (20') → Task 2 sau (40') — phù hợp người viết Task 1 nhanh</li><li><b>Task 2 First 40-20</b>: Task 2 trước (40') → Task 1 sau (20') — phù hợp người hay frozen ở Task 2</li><li><b>Balanced 25-35</b>: Task 1 trước (25') → Task 2 sau (35') — phù hợp người viết Task 1 chậm (process/map)</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Chọn strategy đã drill nhiều nhất trong W8-W11. Exam day KHÔNG phải lúc thử nghiệm.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Chọn 1 → drill → dùng. KHÔNG thay đổi strategy trong phòng thi. Switching = mất 2-3 phút = mất 1 paragraph.</p></div>","p":1},{"id":"W12D1-S-02","l":36,"t":"S","st":"Structure","s":3,"tags":["exam-strategy","planning","task-1"],"f":"<p>Task 1 Planning Protocol gồm mấy bước? Tổng bao lâu? Kể từng bước.</p>","a":"","b":"<div class=\"sec\"><p><b>4 bước trong 3 phút:</b></p><ol><li><b>(30s)</b> Đọc đề → xác định TYPE (line/bar/pie/table/mixed/process/map)</li><li><b>(60s)</b> Tìm 2-3 MAIN TRENDS (tăng/giảm/lớn nhất/nhỏ nhất/ngoại lệ)</li><li><b>(30s)</b> Chọn DATA cụ thể cho mỗi trend (số liệu chính xác)</li><li><b>(60s)</b> Viết outline: Intro → Overview → Body 1 → Body 2</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Mixed chart → TYPE: table + bar → TRENDS: tất cả tăng enrollment, fees chênh lệch lớn → OUTLINE: Body 1 enrollment, Body 2 fees comparison.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Planning KHÔNG tốn thời gian — planning TIẾT KIỆM thời gian. Người có outline viết nhanh hơn vì không phải \"nghĩ tiếp\" giữa bài.</p></div>","p":1},{"id":"W12D1-S-03","l":36,"t":"S","st":"Structure","s":3,"tags":["exam-strategy","planning","task-2"],"f":"<p>Task 2 Planning Protocol gồm mấy bước? Tổng bao lâu? Kể từng bước.</p>","a":"","b":"<div class=\"sec\"><p><b>5 bước trong 5 phút:</b></p><ol><li><b>(60s)</b> Đọc đề → xác định TYPE (Opinion/Discussion/Problem-Solution/Two-Part)</li><li><b>(60s)</b> Brainstorm ideas — viết TẤT CẢ ra → chọn 2-3 mạnh nhất</li><li><b>(60s)</b> Chọn POSITION (agree/disagree/both views + own opinion)</li><li><b>(60s)</b> Viết outline 4 paragraphs: Intro → Body 1 → Body 2 → Conclusion</li><li><b>(60s)</b> Ghi nhanh KEY VOCAB cho mỗi paragraph (2-3 collocations)</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Discussion essay → Brainstorm cả 2 views → Chọn position → Outline + KEY VOCAB: \"sedentary lifestyle, holistic approach, preventive healthcare.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Bước 5 (ghi vocab trước) giúp tránh bị blank khi viết — từ đã sẵn trên giấy nháp.</p></div>","p":1},{"id":"W12D1-S-04","l":36,"t":"S","st":"Structure","s":3,"tags":["exam-strategy","contingency","brain-dump"],"f":"<p>\"Brain Dump\" technique gồm mấy bước? Dùng khi nào? Tại sao hiệu quả?</p>","a":"","b":"<div class=\"sec\"><p><b>3 bước — dùng khi bị blank/frozen:</b></p><ol><li><b>(2 phút)</b> Viết TẤT CẢ từ liên quan ra giấy nháp (không cần logic, chỉ cần từ/cụm)</li><li>Nhóm các từ thành <b>2-3 categories</b></li><li>Chọn <b>2 categories</b> → đó là 2 body paragraphs</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Đề \"public health\" → Brain dump: hospital, doctor, exercise, food, stress, pollution → Nhóm: Physical (exercise, food) / Mental (stress) / System (hospital, government) → Chọn 2 nhóm.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Khi panic, não \"đóng băng\" ở abstract thinking. Viết từ rời = \"hạ level\" xuống concrete → xây ngược lên ideas.</p></div>","p":1},{"id":"W12D1-S-05","l":36,"t":"S","st":"Structure","s":3,"tags":["exam-strategy","contingency","prioritize-conclusion","golden-rule"],"f":"<p>\"Prioritize Conclusion\" protocol — khi còn 5 phút mà chưa có conclusion Task 2, phải làm gì? Tại sao đây là QUY TẮC VÀNG?</p>","a":"","b":"<div class=\"sec\"><p><b>Protocol:</b></p><ol><li><b>DỪNG</b> viết body paragraph NGAY LẬP TỨC</li><li>Viết conclusion <b>NGAY</b> (2-3 câu, 1 phút): \"In conclusion, I firmly believe that [position]. While [acknowledge], [final statement].\"</li><li>NẾU CÒN thời gian: quay lại body paragraph bổ sung</li></ol><p><b>Tại sao = Quy tắc vàng:</b></p><ul><li>Task 2 KHÔNG có conclusion = TA tối đa <b>5.0</b> (\"response is incomplete\")</li><li>Task 2 CÓ conclusion ngắn = TA có thể đạt <b>6.5-7.0</b></li><li>1 phút viết conclusion = difference <b>1.5-2.0 band score</b></li></ul></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Set alarm ở phút 50 (Task 2) để remind bản thân. KHÔNG BAO GIỜ vi phạm quy tắc này.</p></div>","p":1},{"id":"W12D1-S-06","l":36,"t":"S","st":"Structure","s":3,"tags":["exam-strategy","contingency","frozen"],"f":"<p>Protocol khi bị blank/frozen trong phòng thi — 4 bước trong bao lâu?</p>","a":"","b":"<div class=\"sec\"><p><b>4 bước trong 3 phút:</b></p><ol><li><b>(30s)</b> Thở sâu 4-7-8 × 2 lần → hạ cortisol</li><li><b>(90s)</b> Brain Dump → viết TẤT CẢ từ liên quan ra giấy nháp</li><li><b>(30s)</b> Chọn 2 ideas từ brain dump</li><li><b>(30s)</b> Viết body paragraph TRƯỚC — intro viết SAU</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Gặp đề lạ → hoảng → thở 4-7-8 → brain dump → chọn 2 ideas → viết Body 1 trước → intro viết sau khi position đã rõ.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>\"Start Small\" = viết 1 câu bất kỳ → momentum tự đến. Intro cần biết position → viết body trước → position tự rõ.</p></div>","p":1},{"id":"W12D1-S-07","l":36,"t":"S","st":"Structure","s":3,"tags":["exam-strategy","contingency","salvage"],"f":"<p>\"Salvage Strategy\" — khi viết SAI approach giữa chừng, protocol gồm mấy bước?</p>","a":"","b":"<div class=\"sec\"><p><b>4 bước:</b></p><ol><li><b>ĐỪNG XOÁ</b> những gì đã viết (tốn thời gian + mất content)</li><li>Thêm 1 câu <b>TRANSITION</b>: \"However, a more nuanced perspective reveals that...\"</li><li><b>Chuyển hướng</b> trong body paragraph TIẾP THEO</li><li><b>Conclusion</b>: nêu position phù hợp với PHẦN SAU (examiner đọc kỹ conclusion nhất)</li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Viết Body 1 theo hướng agree → nhận ra nên discuss both views → thêm transition → Body 2 nêu opposing view → Conclusion: balanced position.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Examiner KHÔNG trừ điểm vì \"thay đổi ý kiến\". Họ trừ vì \"unclear position\" hoặc \"incomplete response\". Transition smooth → CC vẫn đạt 7.0.</p></div>","p":1},{"id":"W12D1-S-08","l":36,"t":"S","st":"Structure","s":2,"tags":["exam-strategy","clock-checking","checkpoints"],"f":"<p>Clock-Checking Protocol có mấy checkpoints? Kể 4 checkpoints cho strategy Standard 20-40.</p>","a":"","b":"<div class=\"sec\"><p><b>4 checkpoints</b> (nhìn đồng hồ tại mỗi checkpoint):</p><ul><li><b>CP1 — 5:00</b>: Task 1 planning done?</li><li><b>CP2 — 15:00</b>: Task 1 body done?</li><li><b>CP3 — 20:00</b>: Task 1 XONG → switch sang Task 2</li><li><b>CP4 — 55:00</b>: Task 2 XONG → proofread cả 2 bài</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Checkpoint 15:00 mà chưa xong body Task 1 → tăng tốc, bỏ bớt data → đảm bảo switch ở 20:00.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Dù chọn strategy nào, luôn có CP4 ở 55:00 = 5 phút proofread. KHÔNG viết thêm trừ khi thiếu conclusion.</p></div>","p":1},{"id":"W12D1-S-09","l":36,"t":"S","st":"Structure","s":2,"tags":["exam-strategy","error-shield","exam-day"],"f":"<p>\"Error Shield\" — viết 5 lỗi cần tránh ra giấy nháp trước khi bắt đầu viết. 5 items là gì?</p>","a":"","b":"<div class=\"sec\"><p>5 items viết ra góc giấy nháp:</p><ol><li><b>THE</b> + specific noun (articles)</li><li><b>Complex sentence</b> mỗi paragraph</li><li><b>Overview PHẢI CÓ</b> (Task 1)</li><li><b>Paraphrase đề</b> (≥3 từ khác)</li><li><b>Conclusion ≠ copy intro</b></li></ol></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Mỗi lần xong 1 paragraph → nhìn lại giấy nháp 5 giây → check. Tổng thêm ~30 giây/bài nhưng tránh được lỗi lặp.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Viết ra = visual reminder = ít lỗi hơn. Đừng nghĩ \"mình nhớ rồi\" — stress trong phòng thi làm quên.</p></div>","p":1},{"id":"W12D1-S-10","l":36,"t":"S","st":"Structure","s":2,"tags":["exam-strategy","breathing","stress-management"],"f":"<p>Kỹ thuật thở \"4-7-8\" — cụ thể làm gì? Lặp mấy lần? Tại sao hiệu quả?</p>","a":"","b":"<div class=\"sec\"><ul><li><b>HÍT VÀO</b> (4 giây): qua mũi, đếm chậm 1-2-3-4</li><li><b>GIỮ</b> (7 giây): không thở, đếm 1-2-3-4-5-6-7</li><li><b>THỞ RA</b> (8 giây): qua miệng, chậm, đếm 1-2-3-4-5-6-7-8</li><li>Lặp lại <b>3 lần</b> = tổng 57 giây</li><li>Cortisol (hormone stress) giảm rõ rệt sau 3 cycles</li></ul></div><div class=\"sec\"><p><span class=\"lbl\">VD</span>Dùng trước khi bắt đầu viết (Activation Routine) hoặc khi bắt đầu panic giữa bài.</p></div><div class=\"sec\"><p><span class=\"lbl\">💡 Mẹo</span>Practice TRƯỚC ngày thi — làm 4-7-8 mỗi tối trước khi ngủ trong 7 ngày → đến ngày thi, cơ thể tự động biết cách calm down.</p></div>","p":1},{"id":"W12D1-P-01","l":36,"t":"P","st":"Phrase","s":3,"tags":["collocation","discussion","introduction","model-answer"],"f":"<p>The question of how best to enhance public health has become ______ (chủ đề tranh luận đáng kể).</p>","a":"<b>a topic of considerable debate</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"The question of how best to enhance public health has become a topic of considerable debate.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"a matter of considerable debate\" | \"a subject of much discussion\" | \"a widely debated issue\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Introduction — mở bài Discussion/Opinion essay, nêu chủ đề đang được tranh luận</p></div>","p":1},{"id":"W12D1-P-02","l":36,"t":"P","st":"Phrase","s":3,"tags":["collocation","discussion","view-presentation","model-answer"],"f":"<p>Some ______ (ủng hộ việc mở rộng) sporting amenities to improve public health.</p>","a":"<b>advocate for the expansion of</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"While some advocate for the expansion of sporting amenities, others contend that alternative interventions would prove more effective.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"support the development of\" | \"call for greater investment in\" | \"push for the proliferation of\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — trình bày quan điểm của một nhóm người (View 1 trong Discussion essay)</p></div>","p":1},{"id":"W12D1-P-03","l":36,"t":"P","st":"Phrase","s":3,"tags":["collocation","health","cause-effect","model-answer"],"f":"<p>Sedentary lifestyles are ______ (nguyên nhân hàng đầu của) chronic diseases such as obesity.</p>","a":"<b>a leading contributor to</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Sedentary lifestyles are a leading contributor to chronic diseases such as obesity and cardiovascular conditions.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"a major cause of\" | \"a primary driver of\" | \"a significant factor in\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — giải thích nguyên nhân của vấn đề (Explanation trong TEES)</p></div>","p":1},{"id":"W12D1-P-04","l":36,"t":"P","st":"Phrase","s":3,"tags":["collocation","example","correlation","model-answer"],"f":"<p>Singapore's investment in fitness centres ______ (trùng với sự giảm đáng kể) its national obesity rate.</p>","a":"<b>coincided with a measurable decline in</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Singapore's investment in publicly accessible fitness centres in the 2010s coincided with a measurable decline in its national obesity rate.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"was accompanied by a notable reduction in\" | \"corresponded with a significant drop in\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — nêu ví dụ cụ thể + kết quả (Example trong TEES), tránh nói \"caused\" khi chỉ là correlation</p></div>","p":1},{"id":"W12D1-P-05","l":36,"t":"P","st":"Phrase","s":3,"tags":["collocation","concession","acknowledge","model-answer"],"f":"<p>Therefore, ______ (sẽ không chính xác nếu bác bỏ) the potential benefits of such infrastructure entirely.</p>","a":"<b>it would be inaccurate to dismiss</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Therefore, it would be inaccurate to dismiss the potential benefits of such infrastructure entirely.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"it would be unreasonable to overlook\" | \"it would be misguided to ignore\" | \"one cannot simply disregard\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Summary sentence cuối Body 1 trong Discussion essay — công nhận quan điểm đối lập trước khi chuyển sang view 2</p></div>","p":1},{"id":"W12D1-P-06","l":36,"t":"P","st":"Phrase","s":2,"tags":["collocation","comparison","equal-importance","model-answer"],"f":"<p>Factors such as dietary habits and mental well-being ______ (đóng vai trò quan trọng ngang nhau).</p>","a":"<b>play equally, if not more, significant roles</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Factors such as dietary habits, mental well-being, and access to affordable healthcare play equally, if not more, significant roles.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"are of equal, if not greater, importance\" | \"carry comparable weight\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body 2 — so sánh tầm quan trọng giữa các yếu tố, đặc biệt khi muốn nâng view 2 lên ngang/hơn view 1</p></div>","p":1},{"id":"W12D1-P-07","l":36,"t":"P","st":"Phrase","s":3,"tags":["collocation","example","achievement","model-answer"],"f":"<p>Japan's school lunch programme ______ (được ghi nhận là) instilling nutritional awareness from an early age.</p>","a":"<b>has been credited with</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"A compelling illustration is Japan's school lunch programme, which has been credited with instilling nutritional awareness from an early age.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"has been recognised for\" | \"has been praised for\" | \"is widely acknowledged for\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — nêu ví dụ cụ thể + thành tựu/kết quả (Example trong TEES)</p></div>","p":1},{"id":"W12D1-P-08","l":36,"t":"P","st":"Phrase","s":2,"tags":["collocation","result","improvement","model-answer"],"f":"<p>Public health campaigns targeting smoking cessation have been shown to ______ (mang lại cải thiện đáng kể).</p>","a":"<b>yield substantial improvements</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"Public health campaigns targeting smoking cessation and alcohol moderation have been shown to yield substantial improvements without requiring any physical infrastructure.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"produce significant results\" | \"deliver meaningful outcomes\" | \"generate considerable benefits\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Body paragraph — nói về kết quả/hiệu quả của giải pháp (kết hợp với \"have been shown to\" = evidence-based)</p></div>","p":1},{"id":"W12D1-P-09","l":36,"t":"P","st":"Phrase","s":3,"tags":["collocation","conclusion","holistic","model-answer"],"f":"<p>I firmly believe that ______ (chiến lược toàn diện bao gồm) dietary education, mental health support, and preventive healthcare is far more likely to bring about lasting improvements.</p>","a":"<b>a holistic strategy encompassing</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"I firmly believe that a holistic strategy — encompassing dietary education, mental health support, and preventive healthcare — is far more likely to bring about lasting improvements in public health.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"a comprehensive approach incorporating\" | \"a multifaceted strategy involving\" | \"an integrated plan covering\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Conclusion — tổng kết bằng cách nhấn mạnh cần nhiều giải pháp kết hợp (rất phù hợp Discussion essay)</p></div>","p":1},{"id":"W12D1-P-10","l":36,"t":"P","st":"Phrase","s":3,"tags":["collocation","conclusion","forward-looking","model-answer"],"f":"<p>A holistic strategy is far more likely to ______ (tạo ra cải thiện lâu dài) in public health.</p>","a":"<b>bring about lasting improvements in</b>","b":"<div class=\"sec\"><p><span class=\"lbl\">Câu mẫu</span>\"A holistic strategy is far more likely to bring about lasting improvements in public health.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Synonyms</span>\"lead to sustainable progress in\" | \"result in long-term gains in\" | \"generate enduring benefits for\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Khi nào</span>Conclusion — câu cuối forward-looking, nhấn mạnh tác động lâu dài (thay vì chỉ \"In conclusion, I agree\")</p></div>","p":1},{"id":"W12D1-E-01","l":36,"t":"E","st":"Error","s":3,"tags":["exam-mistake","conclusion","task-achievement"],"f":"<p>Sắp hết giờ Task 2 mà chưa có conclusion — lỗi này ảnh hưởng band score thế nào?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Tiếp tục viết body paragraph, hy vọng kịp → hết giờ, không có conclusion</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>DỪNG body ngay → viết conclusion 2-3 câu (1 phút): \"In conclusion, I firmly believe that [position]. While [acknowledge], [final statement].\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Task 2 KHÔNG có conclusion = TA tối đa 5.0 (\"response is incomplete\"). Có conclusion ngắn = TA có thể đạt 6.5-7.0. <b>1 phút viết conclusion = difference 1.5-2.0 band.</b></p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA -1.5 đến -2.0 band (từ 7.0 xuống 5.0-5.5)</p></div>","p":0},{"id":"W12D1-E-02","l":36,"t":"E","st":"Error","s":3,"tags":["exam-mistake","planning","off-topic"],"f":"<p>~30% thí sinh mắc lỗi gì khi nhận đề thi? So sánh Band 5 vs Band 7 behaviour.</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Đọc đề qua → viết ngay không planning → viết 200 từ → nhận ra off-topic → xoá → viết lại → hết giờ, thiếu conclusion</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Đọc kỹ → <b>3-5 phút planning</b> (outline 4 paragraphs) → viết liên tục → đủ thời gian proofread</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Planning KHÔNG tốn thời gian — planning TIẾT KIỆM thời gian. Người có outline viết nhanh hơn vì không phải \"nghĩ tiếp\" giữa bài.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA -0.5 đến -1.0 (off-topic hoặc under-developed) + CC -0.5 (incoherent structure)</p></div>","p":0},{"id":"W12D1-E-03","l":36,"t":"E","st":"Error","s":3,"tags":["exam-mistake","time-management","task-1-overtime"],"f":"<p>~20% thí sinh mắc lỗi phân bổ thời gian sai — cụ thể là gì? Hậu quả?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Viết Task 1 quá lâu (25-30 phút) vì muốn hoàn hảo → Task 2 chỉ còn 30-35 phút → Task 2 under-developed hoặc thiếu conclusion</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Strict 20 phút cho Task 1. Nếu chưa xong → viết 1 câu overview (QUAN TRỌNG NHẤT) → chuyển sang Task 2 NGAY</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Task 2 chiếm <b>2/3 điểm Writing</b>. Task 2 hoàn chỉnh Band 7 + Task 1 thiếu data = overall ~6.5. Nhưng Task 2 thiếu conclusion = overall ~5.5. <b>Luôn ưu tiên Task 2.</b></p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA -1.0 (Task 2 incomplete) — nghiêm trọng hơn Task 1 thiếu data</p></div>","p":0},{"id":"W12D1-E-04","l":36,"t":"E","st":"Error","s":2,"tags":["exam-mistake","proofread","grammar"],"f":"<p>~40% thí sinh mắc lỗi gì ở bước cuối cùng? Ảnh hưởng thế nào đến band score?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Viết đến giây cuối cùng, không proofread → lỗi grammar cơ bản (articles, tenses, S-V agreement) vẫn nằm trong bài</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Dành <b>2-5 phút cuối</b> proofread. Ưu tiên scan: <b>articles → tenses → spelling → word count</b>. Ưu tiên sửa lỗi LỚN (thiếu \"the\" × 5 = impact lớn hơn 1 lỗi spelling)</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>2 phút proofread = sửa 3-5 lỗi = +0.5 GRA band. Band 7 cho phép \"a few\" lỗi nhỏ nhưng KHÔNG chấp nhận lỗi hệ thống lặp lại.</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>GRA -0.5 (lỗi cơ bản lặp lại nhiều lần)</p></div>","p":0},{"id":"W12D1-E-05","l":36,"t":"E","st":"Error","s":2,"tags":["exam-mistake","strategy-switching","panic"],"f":"<p>Tại sao KHÔNG NÊN thay đổi time allocation strategy trong phòng thi?</p>","a":"","b":"<div class=\"sec\"><p><span class=\"lbl\">❌ Sai</span>Bắt đầu bằng Standard 20-40 → giữa chừng hoảng → đổi sang Task 2 First → mất 2-3 phút điều chỉnh, rối loạn</p></div><div class=\"sec\"><p><span class=\"lbl\">✅ Đúng</span>Chọn 1 strategy trước ngày thi (dựa trên drill W8-W11) → dùng strategy đó FIXED → theo đúng kế hoạch đã drill</p></div><div class=\"sec\"><p><span class=\"lbl\">Rule</span>Switching strategy giữa chừng = mất 2-3 phút điều chỉnh = mất 1 paragraph. Exam day KHÔNG phải lúc thử nghiệm. Consistency quan trọng hơn \"strategy tối ưu.\"</p></div><div class=\"sec\"><p><span class=\"lbl\">Mất điểm</span>TA -0.5 + CC -0.5 (bài viết lộn xộn, thiếu thời gian cho 1 task)</p></div>","p":0}]};window.WCARDS.build="99f40dfda0";
